function runAuthoringCheckpointExecution(input: {
  root: string;
  draftSourcePath: string;
  paths: PreConfirmationPaths;
  recordId: string;
  requirementSetId: string;
  implementationAttemptId: string;
  routeDecision: string;
  sourceDocumentHash: string;
  implementationConfirmationHash: string;
  semanticBinding: SemanticCheckpointBinding;
  createdAt: string;
  forceRefresh?: boolean;
  allowDeferredCriticalAuditorBlockers?: boolean;
}): { ok: true } | { ok: false; issues: PreConfirmationDrilldownIssue[] } {
  const runners = [
    runCp00SemanticKernel,
    runCp01MustDecompositionPacket,
    runCp02AtomicDecompositionLoopConvergence,
    runCp03PacketToSourceMaterialization,
    runCp04IdFreeze,
    runCp05ImplementationConfirmationCore,
    runCp06Projections,
    runCp07HumanReadableViews,
    runCp08Reconciliation,
  ];
  const resumeStartIndex =
    input.forceRefresh === true ? 0 : resolveCheckpointResumeStartIndex(input);
  if (resumeStartIndex > 0) {
    const nextCheckpoint =
      AUTHORING_REPAIR_CHECKPOINTS[resumeStartIndex]?.id ?? 'checkpoint-persistence-summary';
    process.stderr.write(
      `[requirements-contract-authoring] checkpoint resume progress=${toRootRelativePath(input.root, input.paths.progress)} completed=${resumeStartIndex} next=${nextCheckpoint}\n`
    );
  }
  for (const [offset, runner] of runners.slice(resumeStartIndex).entries()) {
    const checkpointIndex = resumeStartIndex + offset;
    const checkpoint = AUTHORING_REPAIR_CHECKPOINTS[checkpointIndex];
    const result = runner(input);
    if (!result.ok) {
      const receipt = readJsonIfExists(checkpointReceiptPath(input.paths, checkpoint));
      if (
        input.allowDeferredCriticalAuditorBlockers === true &&
        isCurrentDeferredCriticalAuditorCheckpointReceipt({
          root: input.root,
          receipt,
          checkpoint,
          recordId: input.recordId,
          requirementSetId: input.requirementSetId,
          implementationAttemptId: input.implementationAttemptId,
          sourceDocumentHash: input.sourceDocumentHash,
          implementationConfirmationHash: input.implementationConfirmationHash,
          semanticBinding: input.semanticBinding,
          draftSourcePath: input.draftSourcePath,
          paths: input.paths,
        })
      ) {
        removeCheckpointReceiptsAfter(input.paths, checkpointIndex);
        writeCheckpointProgressFromReceipts(input);
        return { ok: true };
      }
      writeCheckpointProgressFromReceipts(input);
      return { ok: false, issues: [result.issue] };
    }
  }
  writeCheckpointProgressFromReceipts(input);
  return { ok: true };
}

function buildCheckpointPersistenceEvidenceFromReceipts(input: {
  root: string;
  draftSourcePath: string;
  paths: PreConfirmationPaths;
  routeDecision: Record<string, unknown> | null;
  recordId: string;
  requirementSetId: string;
  implementationAttemptId: string;
  sourceDocumentHash: string;
  implementationConfirmationHash: string;
  semanticBinding: SemanticCheckpointBinding;
  createdAt: string;
  allowDeferredCriticalAuditorBlockers?: boolean;
}): Record<string, unknown> {
  const routeDecisionHash = normalizeText(input.routeDecision?.routeDecisionHash);
  const progress = checkpointProgressFromReceipts({
    root: input.root,
    draftSourcePath: input.draftSourcePath,
    paths: input.paths,
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    implementationAttemptId: input.implementationAttemptId,
    routeDecision: normalizeText(input.routeDecision?.decision),
    sourceDocumentHash: input.sourceDocumentHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    semanticBinding: input.semanticBinding,
    createdAt: input.createdAt,
  });
  const checkpointReceiptRefs = asRecordArray(progress.checkpoints).map((checkpoint) => ({
    checkpointId: normalizeText(checkpoint.id),
    path: normalizeText(checkpoint.receiptPath),
    hash: checkpoint.receiptHash ?? null,
    status: normalizeText(checkpoint.status),
    persistenceStatus: normalizeText(checkpoint.persistenceStatus),
    semanticValidationStatus: normalizeText(checkpoint.semanticValidationStatus),
  }));
  const completedCheckpointIds = asStringArray(
    recordObject(progress.resumeLedger).completedCheckpointIds
  );
  const preRenderMustGate = readJsonIfExists(input.paths.preRenderMustGate);
  const preRenderGlobalConsistency = readJsonIfExists(input.paths.preRenderGlobalConsistency);
  const reconciliationReport = readJsonIfExists(input.paths.reconciliationReport);
  const mustGateIssues = asRecordArray(preRenderMustGate?.blockingIssues);
  const globalGateIssues = asRecordArray(preRenderGlobalConsistency?.issues);
  const checkpointIssues = checkpointReceiptRefs.flatMap((checkpoint) => {
    const receiptPath = resolveRootRelativePath(input.root, checkpoint.path);
    return asRecordArray(readJsonIfExists(receiptPath)?.blockers);
  });
  const mustGateVerdict = normalizeText(preRenderMustGate?.verdict).toLowerCase();
  const globalGateVerdict = normalizeText(preRenderGlobalConsistency?.verdict).toLowerCase();
  const reconciliationVerdict = normalizeText(reconciliationReport?.verdict).toLowerCase();
  const deferredCriticalAuditorBlockers = input.allowDeferredCriticalAuditorBlockers
    ? Array.from(
        new Map(
          [...mustGateIssues, ...globalGateIssues, ...checkpointIssues]
            .filter((issue) =>
              CRITICAL_AUDITOR_DEFERRED_CHECKPOINT_BLOCKER_CODES.has(normalizeText(issue.code))
            )
            .map((issue) => [
              `${normalizeText(issue.code)}\n${asStringArray(issue.refs).join('\n')}`,
              issue,
            ])
        ).values()
      )
    : [];
  const nonDeferredMustGateIssues = mustGateIssues.filter(
    (issue) =>
      !input.allowDeferredCriticalAuditorBlockers ||
      !CRITICAL_AUDITOR_DEFERRED_CHECKPOINT_BLOCKER_CODES.has(normalizeText(issue.code))
  );
  const nonDeferredGlobalGateIssues = globalGateIssues.filter(
    (issue) =>
      !input.allowDeferredCriticalAuditorBlockers ||
      !CRITICAL_AUDITOR_DEFERRED_CHECKPOINT_BLOCKER_CODES.has(normalizeText(issue.code))
  );
  const mustGateStructurallyPassed =
    mustGateVerdict === 'pass' ||
    (mustGateVerdict === 'fail' &&
      nonDeferredMustGateIssues.length === 0 &&
      reconciliationVerdict === 'pass');
  const globalGateStructurallyPassed =
    globalGateVerdict === 'pass' ||
    (globalGateVerdict === 'fail' && nonDeferredGlobalGateIssues.length === 0);
  const structuralGateSatisfied = mustGateStructurallyPassed && globalGateStructurallyPassed;
  const checkpointPersistenceSatisfiedCandidate =
    AUTHORING_REPAIR_CHECKPOINT_IDS.every((id) => completedCheckpointIds.includes(id)) &&
    fs.existsSync(input.paths.progress) &&
    structuralGateSatisfied &&
    reconciliationVerdict === 'pass';
  const evidence = {
    schemaVersion: 'semantic-checkpoint-persistence-evidence/v1',
    checkpointPersistenceSatisfiedCandidate,
    checkpointPersistenceStage: 'checkpoint_driven_execution_summary',
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    implementationAttemptId: input.implementationAttemptId,
    source: toRootRelativePath(input.root, input.draftSourcePath),
    sourceDocumentHash: input.sourceDocumentHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    semanticModelHash: input.semanticBinding.semanticModelHash,
    semanticConservationManifestHash: input.semanticBinding.semanticConservationManifestHash,
    checkpointPersistenceRef: {
      routeDecisionHash,
      requirementSetId: input.requirementSetId,
      implementationAttemptId: input.implementationAttemptId,
      semanticModelHash: input.semanticBinding.semanticModelHash,
      semanticConservationManifestHash: input.semanticBinding.semanticConservationManifestHash,
      progressPath: toRootRelativePath(input.root, input.paths.progress),
      progressHash: fs.existsSync(input.paths.progress) ? sha256File(input.paths.progress) : null,
      checkpointReceiptRefs,
      completedCheckpointIds,
      preRenderMustDecompositionGateHash: fs.existsSync(input.paths.preRenderMustGate)
        ? sha256File(input.paths.preRenderMustGate)
        : null,
      preRenderGlobalConsistencyHash: fs.existsSync(input.paths.preRenderGlobalConsistency)
        ? sha256File(input.paths.preRenderGlobalConsistency)
        : null,
      packetSourceReconciliationHash: fs.existsSync(input.paths.reconciliationReport)
        ? sha256File(input.paths.reconciliationReport)
        : null,
      preRenderGatePolicy: {
        mode: input.allowDeferredCriticalAuditorBlockers
          ? 'source_gap_fix_materialization'
          : 'final_pre_render',
        structuralGateSatisfied,
        auditorConvergenceDeferredToNextRound: deferredCriticalAuditorBlockers.length > 0,
        deferredCriticalAuditorBlockers: deferredCriticalAuditorBlockers.map((issue) => ({
          code: normalizeText(issue.code),
          refs: asStringArray(issue.refs),
        })),
      },
    },
    completedAt: input.createdAt,
    createdBy:
      'main_agent_orchestration.requirement_confirmation.authoring.checkpoint_persistence_summary',
  };
  return {
    ...evidence,
    evidenceHash: sha256Json(evidence),
  };
}

function prepareAuthoringRepairCheckpointPersistenceEvidence(input: {
  root: string;
  repairDraftPath: string;
  paths: PreConfirmationPaths;
  recordId: string;
  requirementSetId?: string;
  implementationAttemptId?: string;
  sourceDocumentHash: string;
  implementationConfirmationHash: string;
  createdAt: string;
  routeDecision: Record<string, unknown> | null;
  forceRefresh?: boolean;
}): { ok: true } | { ok: false; issue: PreConfirmationDrilldownIssue } {
  const routeDecisionText = normalizeText(input.routeDecision?.decision);
  if (!['checkpoint_required', 'checkpoint_required_with_amendment'].includes(routeDecisionText)) {
    return { ok: true };
  }
  const requirementSetId = normalizeText(input.requirementSetId);
  const implementationAttemptId = normalizeText(input.implementationAttemptId);
  if (!requirementSetId || !implementationAttemptId) {
    return {
      ok: false,
      issue: preConfirmationIssue(
        'checkpoint_current_attempt_binding_missing',
        'Checkpoint execution requires explicit requirementSetId and implementationAttemptId bindings.',
        [input.recordId, requirementSetId, implementationAttemptId].filter(Boolean),
        'requirements_contract_authoring_checkpoint_semantic_validation'
      ),
    };
  }
  const semanticBinding = semanticCheckpointBindingFromPaths(input.paths);
  if (!semanticBinding) {
    return {
      ok: false,
      issue: preConfirmationIssue(
        'semantic_checkpoint_binding_missing',
        'Checkpoint execution requires the current Canonical Semantic IR and Semantic Conservation Manifest hashes.',
        [
          toRootRelativePath(input.root, input.paths.semanticIr),
          toRootRelativePath(input.root, input.paths.semanticConservationManifest),
        ],
        'requirements_contract_authoring_checkpoint_driven_execution'
      ),
    };
  }

  const checkpointScript = resolveSkillScript(input.root, 'run_semantic_checkpoints.js');
  const combinedGate = runNodeJson(
    checkpointScript,
    [
      '--source',
      input.repairDraftPath,
      '--progress',
      input.paths.progress,
      '--mode',
      'pre-render-gate',
      '--json',
    ],
    input.root
  );
  const combinedReport = combinedGate.json;
  if (!combinedReport && !fs.existsSync(input.paths.preRenderGlobalConsistency)) {
    return {
      ok: false,
      issue: commandFailureIssue(
        'authoring_repair_checkpoint_global_gate_report_missing',
        checkpointScript,
        combinedGate
      ),
    };
  }
  if (!fs.existsSync(input.paths.preRenderMustGate)) {
    return {
      ok: false,
      issue: sourceMaterializationGateIssue(
        'authoring_repair_checkpoint_must_gate_report_missing',
        'Authoring repair checkpoint persistence requires a current pre-render MUST gate report hash before promotion.',
        [toRootRelativePath(input.root, input.paths.preRenderMustGate)]
      ),
    };
  }
  if (!fs.existsSync(input.paths.preRenderGlobalConsistency)) {
    const globalGate = recordObject(combinedReport?.globalConsistencyGate);
    if (Object.keys(globalGate).length > 0) {
      writeJsonUtf8(input.paths.preRenderGlobalConsistency, globalGate);
    }
  }
  if (!fs.existsSync(input.paths.preRenderGlobalConsistency)) {
    return {
      ok: false,
      issue: sourceMaterializationGateIssue(
        'authoring_repair_checkpoint_global_gate_report_missing',
        'Authoring repair checkpoint persistence requires a current pre-render global consistency report hash before promotion.',
        [toRootRelativePath(input.root, input.paths.preRenderGlobalConsistency)]
      ),
    };
  }
  if (!fs.existsSync(input.paths.reconciliationReport)) {
    return {
      ok: false,
      issue: sourceMaterializationGateIssue(
        'authoring_repair_checkpoint_reconciliation_missing',
        'Authoring repair checkpoint persistence requires packet/source reconciliation evidence before promotion.',
        [toRootRelativePath(input.root, input.paths.reconciliationReport)]
      ),
    };
  }

  const checkpointRun = runAuthoringCheckpointExecution({
    root: input.root,
    draftSourcePath: input.repairDraftPath,
    paths: input.paths,
    recordId: input.recordId,
    requirementSetId,
    implementationAttemptId,
    routeDecision: routeDecisionText,
    sourceDocumentHash: input.sourceDocumentHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    semanticBinding,
    createdAt: input.createdAt,
    forceRefresh: input.forceRefresh,
    allowDeferredCriticalAuditorBlockers: true,
  });
  if (!checkpointRun.ok) {
    return { ok: false, issue: checkpointRun.issues[0] };
  }
  const evidence = buildCheckpointPersistenceEvidenceFromReceipts({
    root: input.root,
    draftSourcePath: input.repairDraftPath,
    paths: input.paths,
    routeDecision: input.routeDecision,
    recordId: input.recordId,
    requirementSetId,
    implementationAttemptId,
    sourceDocumentHash: input.sourceDocumentHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    semanticBinding,
    createdAt: input.createdAt,
    allowDeferredCriticalAuditorBlockers: true,
  });
  writeJsonUtf8(input.paths.checkpointPersistenceEvidence, evidence);
  const validationIssues = validateCheckpointPersistenceEvidence({
    root: input.root,
    sourcePath: input.repairDraftPath,
    paths: input.paths,
    evidencePath: input.paths.checkpointPersistenceEvidence,
    routeDecision: input.routeDecision,
    recordId: input.recordId,
    requirementSetId,
    implementationAttemptId,
    sourceDocumentHash: input.sourceDocumentHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    allowDeferredCriticalAuditorBlockers: true,
  });
  if (validationIssues.length > 0) {
    return { ok: false, issue: validationIssues[0] };
  }
  return { ok: true };
}

export function refreshCurrentSourceCheckpointPersistence(
  root: string,
  options: {
    source: string;
    recordId: string;
    requirementSetId: string;
    implementationAttemptId: string;
    sourceDocumentHash: string;
    implementationConfirmationHash: string;
    createdAt?: string;
    routeDecision?: Record<string, unknown> | null;
    forceRefresh?: boolean;
  }
): { ok: true } | { ok: false; issue: PreConfirmationDrilldownIssue } {
  const recordId = normalizeText(options.recordId);
  const requirementSetId = normalizeText(options.requirementSetId);
  const implementationAttemptId = normalizeText(options.implementationAttemptId);
  const sourceDocumentHash = normalizeText(options.sourceDocumentHash);
  const implementationConfirmationHash = normalizeText(options.implementationConfirmationHash);
  const source = normalizeText(options.source);
  const sourcePath = resolveRootRelativePath(root, source);
  if (
    !source ||
    !recordId ||
    !requirementSetId ||
    !implementationAttemptId ||
    !sourceDocumentHash ||
    !implementationConfirmationHash ||
    !fs.existsSync(sourcePath)
  ) {
    return {
      ok: false,
      issue: preConfirmationIssue(
        'checkpoint_current_source_refresh_binding_missing',
        'Current-source checkpoint refresh requires explicit current source, requirement, attempt, and semantic hash bindings.',
        [
          recordId,
          requirementSetId,
          implementationAttemptId,
          sourceDocumentHash,
          implementationConfirmationHash,
          source,
        ].filter(Boolean),
        'requirements_contract_authoring_checkpoint_semantic_validation'
      ),
    };
  }
  const paths = preConfirmationPaths(root, recordId, requirementSetId);
  const routeDecision =
    options.routeDecision ??
    authoringCheckpointRouteDecisionForPersistence(
      readJsonIfExists(paths.scaleRoutingDecision),
      paths
    );
  return prepareAuthoringRepairCheckpointPersistenceEvidence({
    root,
    repairDraftPath: sourcePath,
    paths,
    recordId,
    requirementSetId,
    implementationAttemptId,
    sourceDocumentHash,
    implementationConfirmationHash,
    createdAt: normalizeText(options.createdAt) || new Date().toISOString(),
    routeDecision,
    forceRefresh: options.forceRefresh ?? true,
  });
}

function ensureCheckpointPersistenceForAuthoring(input: {
  root: string;
  draftSourcePath: string;
  paths: PreConfirmationPaths;
  routeDecision: Record<string, unknown> | null;
  recordId: string;
  requirementSetId: string;
  implementationAttemptId: string;
  sourceDocumentHash: string;
  implementationConfirmationHash: string;
  createdAt: string;
}): { ok: true } | { ok: false; issues: PreConfirmationDrilldownIssue[] } {
  const routeDecisionText = normalizeText(input.routeDecision?.decision);
  if (!['checkpoint_required', 'checkpoint_required_with_amendment'].includes(routeDecisionText)) {
    return { ok: true };
  }
  const requirementSetId = normalizeText(input.requirementSetId);
  const implementationAttemptId = normalizeText(input.implementationAttemptId);
  if (!requirementSetId || !implementationAttemptId) {
    return {
      ok: false,
      issues: [
        preConfirmationIssue(
          'checkpoint_current_attempt_binding_missing',
          'Checkpoint execution requires explicit requirementSetId and implementationAttemptId bindings.',
          [input.recordId, requirementSetId, implementationAttemptId].filter(Boolean),
          'requirements_contract_authoring_checkpoint_semantic_validation'
        ),
      ],
    };
  }
  const semanticBinding = semanticCheckpointBindingFromPaths(input.paths);
  if (!semanticBinding) {
    return {
      ok: false,
      issues: [
        preConfirmationIssue(
          'semantic_checkpoint_binding_missing',
          'Checkpoint execution requires the current Canonical Semantic IR and Semantic Conservation Manifest hashes.',
          [
            toRootRelativePath(input.root, input.paths.semanticIr),
            toRootRelativePath(input.root, input.paths.semanticConservationManifest),
          ],
          'requirements_contract_authoring_checkpoint_driven_execution'
        ),
      ],
    };
  }

  const checkpointRun = runAuthoringCheckpointExecution({
    root: input.root,
    draftSourcePath: input.draftSourcePath,
    paths: input.paths,
    recordId: input.recordId,
    requirementSetId,
    implementationAttemptId,
    routeDecision: routeDecisionText,
    sourceDocumentHash: input.sourceDocumentHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    semanticBinding,
    createdAt: input.createdAt,
  });
  if (!checkpointRun.ok) {
    return checkpointRun;
  }
  const evidence = buildCheckpointPersistenceEvidenceFromReceipts({
    root: input.root,
    draftSourcePath: input.draftSourcePath,
    paths: input.paths,
    routeDecision: input.routeDecision,
    recordId: input.recordId,
    requirementSetId,
    implementationAttemptId,
    sourceDocumentHash: input.sourceDocumentHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    semanticBinding,
    createdAt: input.createdAt,
  });
  writeJsonUtf8(input.paths.checkpointPersistenceEvidence, evidence);

  const validationIssues = validateCheckpointPersistenceEvidence({
    root: input.root,
    sourcePath: input.draftSourcePath,
    paths: input.paths,
    evidencePath: input.paths.checkpointPersistenceEvidence,
    routeDecision: input.routeDecision,
    recordId: input.recordId,
    requirementSetId,
    implementationAttemptId,
    sourceDocumentHash: input.sourceDocumentHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
  });
  const completedIds = asStringArray(
    recordObject(evidence.checkpointPersistenceRef).completedCheckpointIds
  );
  emitAuthoringCheckpointTrace({
    root: input.root,
    draftSourcePath: input.draftSourcePath,
    paths: input.paths,
    recordId: input.recordId,
    routeDecision: routeDecisionText,
    evidence,
  });
  const missingCheckpoints = AUTHORING_REPAIR_CHECKPOINT_IDS.filter(
    (id) => !completedIds.includes(id)
  );
  if (missingCheckpoints.length > 0) {
    validationIssues.push(
      preConfirmationIssue(
        'checkpoint_persistence_evidence_incomplete',
        `Checkpoint persistence evidence is missing completed checkpoint IDs: ${missingCheckpoints.join(', ')}.`,
        [toRootRelativePath(input.root, input.paths.checkpointPersistenceEvidence)],
        'requirements_contract_authoring_scale_routing'
      )
    );
  }
  if (normalizeText(evidence.schemaVersion) !== 'semantic-checkpoint-persistence-evidence/v1') {
    validationIssues.push(
      preConfirmationIssue(
        'checkpoint_persistence_evidence_schema_invalid',
        'Checkpoint persistence evidence schemaVersion must equal semantic-checkpoint-persistence-evidence/v1.',
        [toRootRelativePath(input.root, input.paths.checkpointPersistenceEvidence)],
        'requirements_contract_authoring_scale_routing'
      )
    );
  }
  if (validationIssues.length > 0) {
    return { ok: false, issues: validationIssues };
  }
  return { ok: true };
}

function materializeCriticalAuditorGapFix(input: {
  root: string;
  sourcePath: string;
  paths: PreConfirmationPaths;
  recordId: string;
  requirementSetId: string;
  implementationAttemptId: string;
  confirmation: Record<string, unknown>;
  previousSourceDocumentHash: string;
  response: CriticalAuditorRoundResult;
  createdAt: string;
  promotionReceiptPath?: string;
}):
  | {
      ok: true;
      materialized: ReturnType<typeof readMaterializedConfirmation>;
      receipt: Record<string, unknown> | null;
      receiptPath: string;
    }
  | { ok: false; issue: PreConfirmationDrilldownIssue } {
  const sourceText = fs.readFileSync(input.sourcePath, 'utf8');
  const sourcePath = toRootRelativePath(input.root, input.sourcePath);
  let materializedSourceText = sourceText;
  const splitSourceBindings = new Map<string, SplitMustSourceBinding[]>();
  const splitActions = asRecordArray(input.response.validatedGaps)
    .flatMap((gap) => asRecordArray(gap.repairActions))
    .filter((action) => normalizeText(action.type) === 'split_must')
    .sort(
      (left, right) =>
        Number(recordObject(right.sourceSpan).startLine) -
        Number(recordObject(left.sourceSpan).startLine)
    );
  for (const action of splitActions) {
    const value = recordObject(action.newValue);
    const splitSource = materializeSplitMustSourceRows({
      sourceText: materializedSourceText,
      sourcePath,
      sourceMustRef: normalizeText(value.sourceMustRef),
      replacements: asRecordArray(value.replacements).map((replacement) => ({
        id: normalizeText(replacement.id),
        text: normalizeText(replacement.text),
      })),
      sourceSpan: recordObject(action.sourceSpan) as {
        startLine: number;
        endLine: number;
      },
      expectedSourceText: normalizeText(action.sourceText),
    });
    materializedSourceText = splitSource.sourceText;
    splitSourceBindings.set(normalizeText(action.actionId), splitSource.bindings);
  }
  const sourceAuthoritySnapshot = createRegisteredSourceAuthoritySnapshot({
    sourcePath,
    sourceText: materializedSourceText,
  });
  const semanticBeforeHash = implementationConfirmationHashForPreConfirmation(input.confirmation);
  const appliedActions: Record<string, unknown>[] = [];
  const changedTargetFields = new Set<string>();
  const repairRefs = {
    mustIds: new Set<string>(),
    negIds: new Set<string>(),
    outIds: new Set<string>(),
    evidenceIds: new Set<string>(),
    traceIds: new Set<string>(),
    acceptanceIds: new Set<string>(),
    e2eIds: new Set<string>(),
    commandIds: new Set<string>(),
  };
  const repairBackRef = (
    action: CriticalAuditorRepairAction,
    materializedId: string
  ): Record<string, unknown> => ({
    derivedFromMustRef:
      normalizeText(
        action.type === 'add_must' || action.type === 'split_must' ? materializedId : ''
      ) ||
      asStringArray(action.mustRefs)[0] ||
      materializedId,
    projectionStatus: 'synchronized',
  });
  const appendRow = (
    confirmation: Record<string, unknown>,
    field: string,
    action: CriticalAuditorRepairAction,
    defaultPrefix: string,
    extra: Record<string, unknown> = {}
  ) => {
    const rows = asRecordArray(confirmation[field]);
    const value = recordObject(action.newValue);
    const id =
      normalizeText(value.id ?? value.commandId) ||
      `${defaultPrefix}-${String(rows.length + 1).padStart(3, '0')}`;
    confirmation[field] = [
      ...rows,
      {
        id,
        ...value,
        ...repairBackRef(action, id),
        text: normalizeText(value.text) || action.sourceText,
        sourceSpan: action.sourceSpan,
        sourceText: action.sourceText,
        sourceRequirementIds: action.requirementIds,
        repairActionId: action.actionId,
        repairReason: action.reason,
        ...extra,
      },
    ];
    changedTargetFields.add(field);
    return id;
  };
  const appendRows = (
    confirmation: Record<string, unknown>,
    fields: string[],
    action: CriticalAuditorRepairAction,
    defaultPrefix: string,
    extra: Record<string, unknown> = {}
  ) => {
    let primaryId = '';
    for (const field of fields) {
      const appendedId = appendRow(confirmation, field, action, defaultPrefix, extra);
      primaryId = primaryId || appendedId;
      if (primaryId) {
        const rows = asRecordArray(confirmation[field]);
        const last = rows[rows.length - 1];
        if (last && normalizeText(last.id) !== primaryId) {
          last.id = primaryId;
        }
      }
    }
    return primaryId;
  };
  const replaceRows = (
    confirmation: Record<string, unknown>,
    field: string,
    action: CriticalAuditorRepairAction,
    matchKeys: string[]
  ) => {
    const rows = asRecordArray(confirmation[field]);
    const value = recordObject(action.newValue);
    const nextRows = rows.filter((row) =>
      matchKeys.every((key) => {
        const replacementValue = normalizeText(value[key]);
        return !replacementValue || normalizeText(row[key]) !== replacementValue;
      })
    );
    const id =
      normalizeText(value.id ?? value.commandId) ||
      `${field === 'requiredCommands' ? 'CMD' : 'TARGET-MOD'}-${String(nextRows.length + 1).padStart(3, '0')}`;
    confirmation[field] = [
      ...nextRows,
      {
        id,
        ...value,
        ...repairBackRef(action, id),
        sourceSpan: action.sourceSpan,
        sourceText: action.sourceText,
        sourceRequirementIds: action.requirementIds,
        repairActionId: action.actionId,
        repairReason: action.reason,
      },
    ];
    changedTargetFields.add(field);
    return id;
  };
  let nextConfirmation: Record<string, unknown> = {
    ...input.confirmation,
  };
  const appendRepairRows = (
    confirmation: Record<string, unknown>,
    fields: string[],
    action: CriticalAuditorRepairAction,
    defaultPrefix: string,
    extra: Record<string, unknown> = {}
  ) => {
    const createdIds: string[] = [];
    for (const field of fields) {
      createdIds.push(appendRow(confirmation, field, action, defaultPrefix, extra));
    }
    return createdIds;
  };
  for (const gap of asRecordArray(input.response.validatedGaps)) {
    const repairActions = asRecordArray(
      gap.repairActions
    ) as unknown as CriticalAuditorRepairAction[];
    for (const action of repairActions) {
      const targetField = normalizeText(action.targetField);
      const allowedTargetFields = criticalAuditorRepairActionTargetFields(action.type);
      if (allowedTargetFields.length > 0 && !allowedTargetFields.includes(targetField)) {
        return {
          ok: false,
          issue: sourceMaterializationGateIssue(
            'critical_auditor_repair_action_target_field_mismatch',
            `Critical Auditor repair action ${action.actionId} targets ${targetField || '<missing>'}, which cannot be materialized by action type ${action.type}.`,
            [action.actionId, action.type, targetField || '<missing>', ...allowedTargetFields]
          ),
        };
      }
      let materializedRef = '';
      let materializedRefs: string[] = [];
      switch (action.type) {
        case 'add_must':
          materializedRef = appendRow(nextConfirmation, 'must', action, 'MUST', {
            source: 'critical_auditor_validated_gap',
            sourcePath,
            sourceDocumentHash: sourceAuthoritySnapshot.sourceHash,
            sourceRequirementId:
              asStringArray(action.requirementIds)[0] ||
              asStringArray(action.mustRefs)[0] ||
              action.actionId,
          });
          materializedRefs = [materializedRef];
          break;
        case 'split_must': {
          const value = recordObject(action.newValue);
          const sourceMustRef = normalizeText(value.sourceMustRef);
          const replacements = asRecordArray(value.replacements);
          const currentMustRows = asRecordArray(nextConfirmation.must);
          const sourceIndex = currentMustRows.findIndex(
            (row) => normalizeText(row.id) === sourceMustRef
          );
          if (sourceIndex < 0) {
            return {
              ok: false,
              issue: sourceMaterializationGateIssue(
                'critical_auditor_split_must_source_missing',
                `Critical Auditor split_must action ${action.actionId} cannot find source MUST ${sourceMustRef}.`,
                [action.actionId, sourceMustRef]
              ),
            };
          }
          const sourceRow = currentMustRows[sourceIndex];
          const sourceBindings = splitSourceBindings.get(normalizeText(action.actionId));
          if (!sourceBindings || sourceBindings.length === 0) {
            return {
              ok: false,
              issue: sourceMaterializationGateIssue(
                'critical_auditor_split_must_source_binding_missing',
                `Critical Auditor split_must action ${action.actionId} has no source-level materialization binding.`,
                [action.actionId, sourceMustRef]
              ),
            };
          }
          const replacementRows = sourceBindings.map((binding) => {
            const replacement = replacements.find(
              (candidate) =>
                normalizeText(candidate.id).toUpperCase() === binding.modelReplacementId
            );
            return {
              ...sourceRow,
              ...(replacement ?? {}),
              id: binding.mustId,
              text: binding.text,
              source: 'critical_auditor_validated_gap',
              sourcePath,
              sourceDocumentHash: sourceAuthoritySnapshot.sourceHash,
              sourceRequirementId: binding.sourceRequirementId,
              derivedFromMustRef: sourceMustRef,
              projectionStatus: 'synchronized',
              sourceSpan: binding.sourceSpan,
              sourceText: binding.sourceText,
              sourceRequirementIds: [binding.sourceRequirementId],
              repairActionId: action.actionId,
              repairReason: action.reason,
            };
          });
          nextConfirmation.must = [
            ...currentMustRows.slice(0, sourceIndex),
            ...replacementRows,
            ...currentMustRows.slice(sourceIndex + 1),
          ];
          changedTargetFields.add('must');
          materializedRefs = replacementRows.map((row) => normalizeText(row.id));
          materializedRef = materializedRefs[0] ?? '';
          break;
        }
        case 'add_neg':
          materializedRef = appendRows(
            nextConfirmation,
            ['notDone', 'negativeRequirements'],
            action,
            'NEG',
            {
              negativeAssertionRequired: true,
            }
          );
          break;
        case 'add_out':
          {
            const outRefs = appendRepairRows(
              nextConfirmation,
              ['mustNot', 'outOfScope'],
              action,
              'OUT',
              {
                userApprovalRequiredIfChanged: true,
                boundaryType: 'non_goal_scope_boundary',
                conflictResolution: 'out_of_scope_boundary_only',
                covers: [],
                linkedMustRefs: asStringArray(action.mustRefs),
              }
            );
            materializedRef = outRefs[0] ?? '';
          }
          break;
        case 'add_evidence':
          materializedRef = appendRow(nextConfirmation, 'evidence', action, 'EVD');
          break;
        case 'add_trace':
          materializedRef = appendRow(nextConfirmation, 'traceRows', action, 'TRACE');
          break;
        case 'upsert_trace':
          materializedRef = replaceRows(nextConfirmation, 'traceRows', action, ['id']);
          break;
        case 'upsert_failure_path':
          materializedRef = replaceRows(nextConfirmation, 'failurePaths', action, ['id']);
          break;
        case 'upsert_edge_case':
          materializedRef = replaceRows(nextConfirmation, 'edgeCases', action, ['id']);
          break;
        case 'add_acc':
          {
            const acceptanceRefs = appendRepairRows(
              nextConfirmation,
              ['acceptanceTests', 'acceptanceCriteria'],
              action,
              'ACC'
            );
            materializedRef = acceptanceRefs[0] ?? '';
          }
          break;
        case 'add_e2e':
          {
            const e2eRefs = appendRepairRows(
              nextConfirmation,
              ['e2eSuites', 'e2eScenarios'],
              action,
              'E2E'
            );
            materializedRef = e2eRefs[0] ?? '';
          }
          break;
        case 'add_business_view':
          materializedRef = appendRow(nextConfirmation, 'businessViews', action, 'BUSINESS-VIEW');
          break;
        case 'add_business_visual': {
          const visualField = targetField.includes('sequenceViews')
            ? 'sequenceViews'
            : targetField.includes('flowViews')
              ? 'flowViews'
              : 'businessVisuals';
          materializedRef = appendRow(nextConfirmation, visualField, action, 'BUSINESS-VISUAL', {
            scope: 'business',
          });
          break;
        }
        case 'replace_target_path':
          materializedRef = replaceRows(nextConfirmation, 'targetModificationPaths', action, [
            'path',
          ]);
          break;
        case 'replace_validation_command':
          materializedRef = replaceRows(nextConfirmation, 'requiredCommands', action, ['command']);
          break;
        default: {
          const unknownActionType = normalizeText(recordObject(action).type);
          return {
            ok: false,
            issue: sourceMaterializationGateIssue(
              'critical_auditor_repair_action_type_unknown',
              `Critical Auditor repair action type ${unknownActionType} cannot be materialized.`,
              [unknownActionType]
            ),
          };
        }
      }
      appliedActions.push({
        actionId: action.actionId,
        type: action.type,
        targetField: action.targetField,
        materializedRef,
        materializedRefs,
        requirementIds: action.requirementIds,
        mustRefs: action.mustRefs,
      });
      if (materializedRef || materializedRefs.length > 0) {
        if (action.type === 'add_must') {
          repairRefs.mustIds.add(materializedRef);
        }
        if (action.type === 'split_must') {
          for (const replacementRef of materializedRefs) {
            repairRefs.mustIds.add(replacementRef);
          }
        }
        if (action.type === 'add_neg') repairRefs.negIds.add(materializedRef);
        if (action.type === 'add_out') repairRefs.outIds.add(materializedRef);
        if (action.type === 'add_evidence') repairRefs.evidenceIds.add(materializedRef);
        if (action.type === 'add_trace' || action.type === 'upsert_trace') {
          repairRefs.traceIds.add(materializedRef);
        }
        if (action.type === 'add_acc') repairRefs.acceptanceIds.add(materializedRef);
        if (action.type === 'add_e2e') repairRefs.e2eIds.add(materializedRef);
        if (action.type === 'replace_validation_command')
          repairRefs.commandIds.add(materializedRef);
      }
    }
  }
  if (appliedActions.length === 0) {
    return {
      ok: false,
      issue: sourceMaterializationGateIssue(
        'critical_auditor_repair_action_field_missing',
        'Validated Critical Auditor gaps require at least one materializable repair action.',
        ['validatedGaps.repairActions']
      ),
    };
  }
  const repairClosure = closeCriticalAuditorRepairProjectionRefs(nextConfirmation, repairRefs);
  if (repairClosure.changed) {
    nextConfirmation = repairClosure.confirmation;
    for (const field of repairClosure.changedFields) changedTargetFields.add(field);
  }
  let semanticAfterHash = implementationConfirmationHashForPreConfirmation(nextConfirmation);
  if (semanticAfterHash === semanticBeforeHash) {
    return {
      ok: false,
      issue: sourceMaterializationGateIssue(
        'source_gap_fix_semantic_hash_unchanged',
        'Validated Critical Auditor repair actions must change implementationConfirmation semantic fields, not only repair receipts.',
        appliedActions.map((action) => normalizeText(action.actionId))
      ),
    };
  }
  const resyncedRepair = resyncExistingBusinessVisualProofClosure(nextConfirmation, {
    root: input.root,
    sourcePath: input.sourcePath,
    sourceText: materializedSourceText,
    packetHash: normalizeText(
      recordObject(
        recordObject(nextConfirmation.preConfirmationDrilldown).mustDecompositionPacketRef
      ).hash
    ),
    forceCurrentTargetMapRebuild: true,
  });
  if (resyncedRepair.changed) {
    nextConfirmation = resyncedRepair.confirmation;
    for (const viewId of resyncedRepair.changedViewIds) changedTargetFields.add(viewId);
    semanticAfterHash = implementationConfirmationHashForPreConfirmation(nextConfirmation);
  }
  const existingRows = asRecordArray(input.confirmation.sourceGapFixes);
  Object.assign(nextConfirmation, {
    sourceGapFixes: [
      ...existingRows,
      {
        id: `GAP-FIX-${String(existingRows.length + 1).padStart(3, '0')}`,
        source: 'critical_auditor_validated_gap',
        status: 'materialized',
        validatedGapRefs: asRecordArray(input.response.validatedGaps).map((gap, index) =>
          normalizeText(gap.id ?? gap.code ?? `validated-gap-${index + 1}`)
        ),
        verdict: input.response.verdict,
        materializedAt: input.createdAt,
        appliedActions,
        targetFieldsChanged: Array.from(changedTargetFields).sort(),
        semanticHashBefore: semanticBeforeHash,
        semanticHashAfter: semanticAfterHash,
      },
    ],
    preConfirmationDrilldown: {
      ...recordObject(input.confirmation.preConfirmationDrilldown),
      criticalAuditor: {
        ...recordObject(recordObject(input.confirmation.preConfirmationDrilldown).criticalAuditor),
        consecutiveNoNewGapRounds: 0,
        convergenceVerdict: 'blocked_by_validated_gap_fix',
      },
    },
  });
  if (normalizeText(input.confirmation.status) === 'user_confirmed') {
    nextConfirmation.status = 'reconfirm_required';
  }
  const reconfirmation = buildControlledAuthoringReconfirmationRequest({
    previousConfirmation: input.confirmation,
    nextConfirmation,
    appliedActions,
    changedTargetFields,
  });
  if (reconfirmation.issue) {
    return { ok: false, issue: reconfirmation.issue };
  }
  if (reconfirmation.request) {
    nextConfirmation.reconfirmationRequest = reconfirmation.request;
  }
  const repairDraftPath = path.join(input.paths.authoringDir, 'authoring-repair-draft-source.md');
  fs.writeFileSync(
    repairDraftPath,
    materializeImplementationConfirmationText(materializedSourceText, nextConfirmation),
    'utf8'
  );
  const encodingGate = runEncodingIntegrityGate({
    root: input.root,
    paths: input.paths,
    targetPaths: [repairDraftPath],
  });
  if (encodingGate.issues.length > 0) {
    return { ok: false, issue: encodingGate.issues[0] };
  }
  const normalizedRepairDraft = normalizeImplementationConfirmationDraftForPromotion({
    root: input.root,
    draftPath: repairDraftPath,
    paths: input.paths,
    blockingStage: 'source_gap_fix_materialization_required',
  });
  if (!normalizedRepairDraft.ok) {
    return { ok: false, issue: normalizedRepairDraft.issues[0] };
  }
  const repairScaleAssessment = runPreConfirmationScaleAssessment({
    root: input.root,
    sourcePath: repairDraftPath,
    paths: input.paths,
    phase: 'initial_assessment',
  });
  if (repairScaleAssessment.issues.length > 0) {
    return { ok: false, issue: repairScaleAssessment.issues[0] };
  }
  const repairDraftText = fs.readFileSync(repairDraftPath, 'utf8');
  const repairDraftExtraction = extractImplementationConfirmationBlock(repairDraftText);
  if (!repairDraftExtraction) {
    return {
      ok: false,
      issue: sourceMaterializationGateIssue(
        'source_gap_fix_draft_missing_implementation_confirmation',
        'Validated Critical Auditor repair actions must produce a staging draft with implementationConfirmation before promotion.',
        [toRootRelativePath(input.root, repairDraftPath)]
      ),
    };
  }
  const rebuiltArtifacts = buildPreserveExistingAuthoringArtifacts({
    root: input.root,
    sourcePath: repairDraftPath,
    paths: input.paths,
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    createdAt: input.createdAt,
    sourceText: repairDraftText,
    extraction: repairDraftExtraction,
    consecutiveNoNewGapRounds: 0,
  });
  if (!rebuiltArtifacts.ok) {
    return { ok: false, issue: rebuiltArtifacts.issue };
  }
  const repairPostPacketScaleAssessment = runPreConfirmationScaleAssessment({
    root: input.root,
    sourcePath: repairDraftPath,
    paths: input.paths,
    phase: 'post_packet_assessment',
  });
  if (repairPostPacketScaleAssessment.issues.length > 0) {
    return { ok: false, issue: repairPostPacketScaleAssessment.issues[0] };
  }
  const mustGateScript = resolveSkillScript(input.root, 'pre_render_must_decomposition_gate.js');
  const mustGate = runNodeJson(
    mustGateScript,
    [
      '--source',
      repairDraftPath,
      '--authoring-dir',
      input.paths.authoringDir,
      '--semantic-kernel',
      input.paths.semanticKernel,
      '--must-decomposition-packet',
      input.paths.mustDecompositionPacket,
      '--out',
      input.paths.preRenderMustGate,
      '--receipt',
      input.paths.mustDecompositionReceipt,
      '--reconciliation-report',
      input.paths.reconciliationReport,
      '--json',
    ],
    input.root
  );
  if (!mustGate.json && !fs.existsSync(input.paths.reconciliationReport)) {
    return {
      ok: false,
      issue: commandFailureIssue(
        'source_gap_fix_reconciliation_report_missing',
        mustGateScript,
        mustGate
      ),
    };
  }
  const repairPostMaterializationScaleAssessment = runPreConfirmationScaleAssessment({
    root: input.root,
    sourcePath: repairDraftPath,
    paths: input.paths,
    phase: 'post_materialization_assessment',
  });
  if (repairPostMaterializationScaleAssessment.issues.length > 0) {
    return { ok: false, issue: repairPostMaterializationScaleAssessment.issues[0] };
  }
  const repairRouteDecision = repairPostMaterializationScaleAssessment.routingDecision;
  const repairDraftSourceDocumentHash = sourceDocumentHashForPreConfirmation(
    repairDraftText,
    repairDraftExtraction.blockText,
    repairDraftExtraction.confirmation
  );
  const repairDraftImplementationConfirmationHash =
    implementationConfirmationHashForPreConfirmation(repairDraftExtraction.confirmation);
  const preflightCheckpoints = runCriticalAuditorPreflightCheckpoints({
    root: input.root,
    sourcePath: repairDraftPath,
    paths: input.paths,
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    implementationAttemptId: input.implementationAttemptId,
    sourceDocumentHash: repairDraftSourceDocumentHash,
    implementationConfirmationHash: repairDraftImplementationConfirmationHash,
    createdAt: input.createdAt,
  });
  if (!preflightCheckpoints.ok) {
    return { ok: false, issue: preflightCheckpoints.issue };
  }
  const checkpointPersistence = prepareAuthoringRepairCheckpointPersistenceEvidence({
    root: input.root,
    repairDraftPath,
    paths: input.paths,
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    implementationAttemptId: input.implementationAttemptId,
    sourceDocumentHash: repairDraftSourceDocumentHash,
    implementationConfirmationHash: repairDraftImplementationConfirmationHash,
    createdAt: input.createdAt,
    routeDecision:
      repairRouteDecision ??
      repairPostPacketScaleAssessment.routingDecision ??
      repairScaleAssessment.routingDecision,
    forceRefresh: true,
  });
  if (!checkpointPersistence.ok) {
    return { ok: false, issue: checkpointPersistence.issue };
  }
  const currentTargetHash = fs.existsSync(input.sourcePath)
    ? sha256File(input.sourcePath)
    : 'absent';
  const repairDraftSemanticSourceHash = repairDraftSourceDocumentHash;
  writeSourceMutationDecision({
    root: input.root,
    sourcePath: input.sourcePath,
    paths: input.paths,
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    createdAt: input.createdAt,
    sourceDocumentExistedBefore: fs.existsSync(input.sourcePath),
    sourceHashBefore: currentTargetHash,
    sourceHashAfter: normalizedRepairDraft.draftHash,
    targetRawHashBefore: currentTargetHash,
    targetRawHashAfter: normalizedRepairDraft.draftHash,
    semanticSourceHashBefore: input.previousSourceDocumentHash,
    semanticSourceHashAfter: repairDraftSemanticSourceHash,
    issues: [],
    coverageDecision: 'pass',
    targetAuthorityDecision: 'pass',
    validationAuthorityDecision: 'pass',
    projectionSanityDecision: 'pass',
    auditEvidenceDecision: 'pass',
    scaleRoutingDecision:
      normalizeText(repairRouteDecision?.decision) ||
      normalizeText(repairPostPacketScaleAssessment.routingDecision?.decision) ||
      normalizeText(repairScaleAssessment.routingDecision?.decision) ||
      'authoring_repair_preserve_existing',
    reverseAuditDraftValidationDecision: 'pass',
    sourceMutationPerformed: false,
  });
  const promotionPaths = input.promotionReceiptPath
    ? { ...input.paths, promotionReceipt: input.promotionReceiptPath }
    : input.paths;
  const promotion = promoteImplementationConfirmationDraftWithReceipt({
    root: input.root,
    sourcePath: input.sourcePath,
    draftPath: repairDraftPath,
    paths: promotionPaths,
  });
  if (!promotion.ok) {
    return { ok: false, issue: promotion.issues[0] };
  }
  const materialized = readMaterializedConfirmation(input.sourcePath);
  if (materialized.sourceDocumentHash === input.previousSourceDocumentHash) {
    return {
      ok: false,
      issue: sourceMaterializationGateIssue(
        'source_gap_fix_hash_unchanged',
        'Validated Critical Auditor gaps require a source document materialization that changes sourceDocumentHashAfter before the next audit round.',
        [input.previousSourceDocumentHash]
      ),
    };
  }
  return {
    ok: true,
    materialized,
    receipt: promotion.receipt,
    receiptPath: promotionPaths.promotionReceipt,
  };
}

type PreserveExistingAuthoringArtifactsResult =
  | {
      ok: true;
      sourceDocumentHash: string;
      semanticModelHash: string;
      implementationConfirmationHash: string;
      semanticKernelHash: string;
      packetHash: string;
      mustRequirements: SourceMustRequirement[];
      packet: Record<string, unknown>;
      effectivePacket: Record<string, unknown>;
      auditInputHash: string;
    }
  | {
      ok: false;
      issue: PreConfirmationDrilldownIssue;
    };

function buildPreserveExistingAuthoringArtifacts(input: {
  root: string;
  sourcePath: string;
  paths: PreConfirmationPaths;
  recordId: string;
  requirementSetId: string;
  createdAt: string;
  sourceText: string;
  extraction: NonNullable<ReturnType<typeof extractImplementationConfirmationBlock>>;
  consecutiveNoNewGapRounds: number;
}): PreserveExistingAuthoringArtifactsResult {
  const mustRequirements = extractInlineMustRequirements(input.extraction.confirmation, {
    extraction: input.extraction,
    sourcePath: toRootRelativePath(input.root, input.sourcePath),
    sourceDocumentHash: sha256Text(input.sourceText),
  });
  if (mustRequirements.length === 0) {
    return {
      ok: false,
      issue: preConfirmationIssue(
        'controlled_must_candidates_missing',
        'No inline implementationConfirmation.must[] entries were found; preserve-existing artifact generation does not synthesize default MUST candidates.',
        ['implementationConfirmation.must'],
        'semantic_kernel_authoring'
      ),
    };
  }
  const sourceDocumentHash = sourceDocumentHashForPreConfirmation(
    input.sourceText,
    input.extraction.blockText,
    input.extraction.confirmation
  );
  const implementationConfirmationHash = implementationConfirmationHashForPreConfirmation(
    input.extraction.confirmation
  );
  const packetHash = sha256Json({
    recordId: input.recordId,
    sourceDocumentHash,
    implementationConfirmationHash,
    mode: 'preserve-existing',
    mustRefs: mustRequirements.map((requirement) => requirement.id),
  });
  const sourceSnapshot = readCanonicalUtf8Source(input.sourcePath);
  const intakeAuthority = materializeFileEntryIntake({
    projectRoot: input.root,
    requirementSetId: input.requirementSetId,
    entrySource: 'source_prd_draft',
    source: sourceSnapshot,
    capturedAt: input.createdAt,
    intakeReceiptPath: input.paths.intakeReceipt,
  });
  const structuredBlocks = extractStructuredSourceBlocks(
    input.root,
    input.sourcePath,
    input.sourceText
  );
  const groundedMustRequirements = groundSourceMustRequirements(mustRequirements, structuredBlocks);
  const sourceTargetRecords = extractTargetAuthorityFromSource({
    root: input.root,
    sourceText: input.sourceText,
    blocks: structuredBlocks,
  });
  const targetAuthority = resolveTargetAuthority({
    root: input.root,
    sourceText: input.sourceText,
    explicitTargetPaths: [],
    sourceRecords: sourceTargetRecords,
  });
  const validationAuthority = buildValidationAuthority({
    root: input.root,
    sourceText: input.sourceText,
    blocks: structuredBlocks,
    explicitCommands: [],
    targetRecords: targetAuthority.accepted,
  });
  const projectionTargetAuthorityRecords = validationAuthority.acceptedTargetRecords;
  const lineageWitnesses = planProductionSemanticSourceRootLineageWitnesses({
    root: input.root,
    sourcePath: input.sourcePath,
    sourceText: input.sourceText,
    packetHash,
    mustRequirements: groundedMustRequirements,
    structuredBlocks,
    targetAuthorityRecords: projectionTargetAuthorityRecords,
    validationAuthorityRecords: validationAuthority.accepted,
  });
  const intentLineageLedger = materializeEntryLineage({
    projectRoot: input.root,
    authority: intakeAuthority,
    sourceRoots: lineageWitnesses,
    lineageLedgerPath: input.paths.intentLineageLedger,
  });
  const semanticSourceRootCandidates = planProductionSemanticSourceRootCandidates({
    root: input.root,
    sourcePath: input.sourcePath,
    sourceText: input.sourceText,
    packetHash,
    mustRequirements: groundedMustRequirements,
    structuredBlocks,
    targetAuthorityRecords: projectionTargetAuthorityRecords,
    validationAuthorityRecords: validationAuthority.accepted,
    invocationAuthority: null,
  });
  assertProductionSemanticSourceRootCandidateLineageParity({
    witnesses: lineageWitnesses,
    candidates: semanticSourceRootCandidates,
  });
  const semanticPipeline = runRequirementsContractProductionSemanticPipeline({
    projectRoot: input.root,
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    intakeReceiptPath: input.paths.intakeReceipt,
    intakeReceipt: recordObject(intakeAuthority.intakeReceipt),
    intentLineageLedgerPath: input.paths.intentLineageLedger,
    intentLineageLedger: recordObject(intentLineageLedger),
    sourceRootCandidates: semanticSourceRootCandidates,
    semanticIrPath: input.paths.semanticIr,
    semanticResolutionDir: input.paths.semanticResolutionDir,
    interactionResolutionPath: input.paths.interactionResolution,
    semanticConservationManifestPath: input.paths.semanticConservationManifest,
  });
  const semanticModelHash = semanticPipeline.semanticIr.semanticModelHash;
  const kernel = buildSemanticKernel({
    root: input.root,
    sourcePath: input.sourcePath,
    recordId: input.recordId,
    sourceDocumentHash,
    semanticModelHash,
    implementationConfirmationHash,
    createdAt: input.createdAt,
    mustRequirements,
  });
  kernel.kernelHash = sha256Json({
    schemaVersion: kernel.schemaVersion,
    recordId: kernel.recordId,
    sourceDocumentHash,
    semanticModelHash,
    implementationConfirmationHash,
    mustCandidates: kernel.mustCandidates,
    sourceRequirementTexts: kernel.sourceRequirementTexts,
    mode: 'preserve-existing',
  });
  kernel.contentHash = kernel.kernelHash;
  writeJsonUtf8(input.paths.semanticKernel, { semanticKernel: kernel });
  const semanticKernelHash = normalizeText(kernel.kernelHash);
  const packet = buildPreserveExistingMustDecompositionPacket({
    root: input.root,
    sourcePath: input.sourcePath,
    paths: input.paths,
    recordId: input.recordId,
    sourceDocumentHash,
    semanticModelHash,
    implementationConfirmationHash,
    semanticKernelHash,
    packetHash,
    createdAt: input.createdAt,
    mustRequirements,
    confirmation: input.extraction.confirmation,
    consecutiveNoNewGapRounds: input.consecutiveNoNewGapRounds,
  });
  writeJsonUtf8(input.paths.mustDecompositionPacket, { must_decomposition_packet: packet });
  const canonicalCompilerInput = buildCanonicalPreCheckpointCompilerInput({
    semanticIr: semanticPipeline.semanticIr,
    semanticConservationManifest: semanticPipeline.semanticConservationManifest,
    sourceRoots: semanticPipeline.sourceRoots,
  });
  const compiledModel = compileCanonicalSemanticRequirementContractModel(canonicalCompilerInput);
  writeRequirementContractModelArtifacts({
    authoringDir: input.paths.authoringDir,
    model: compiledModel,
    canonicalInputAuthority: canonicalCompilerInput.authority,
  });
  if (compiledModel.invariantClosure.terminalState === 'blocked') {
    const issueSummary = compiledModel.invariantClosure.issues
      .slice(0, 10)
      .map((issue) => `${issue.code}:${issue.message}`)
      .join(' | ');
    throw new Error(
      `Preserve-existing semantic compiler closure blocked with ${compiledModel.invariantClosure.remainingIssueCount} unresolved issue(s): ${issueSummary}`
    );
  }
  const roundTripReport = runSourcePrdSemanticRoundTrip({
    root: input.root,
    parsedSourcePath: input.sourcePath,
    authoritySourcePath: input.sourcePath,
    sourceText: input.sourceText,
    reportPath: input.paths.renderRoundTripReport,
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    packetHash,
    explicitTargetPaths: [],
    explicitRequiredCommands: [],
    invocationAuthority: null,
    baseline: semanticPipeline,
    paths: input.paths,
  });
  if (roundTripReport.decision !== 'pass') {
    throw new Error(
      'Preserve-existing semantic round-trip did not conserve the Source Root inventory'
    );
  }
  const preserveExistingCandidates: ControlledMustCandidate[] = mustRequirements.map(
    (requirement, index) => {
      const sourceLine = requirement.sourceLine ?? 1;
      return {
        candidateId: requirement.candidateId ?? `PRESERVE-${requirementOrdinal(index)}`,
        sourcePath: requirement.sourcePath ?? toRootRelativePath(input.root, input.sourcePath),
        sourceHash: sha256Text(input.sourceText),
        sourceDocumentHash: requirement.sourceDocumentHash ?? sourceDocumentHash,
        sourceSpan: requirement.sourceSpan ?? { startLine: sourceLine, endLine: sourceLine },
        headingPath: Array.isArray(requirement.headingPath) ? requirement.headingPath : [],
        blockKind: 'paragraph',
        requirementType: 'positive',
        coverageDecision: 'mapped_to_must',
        coverageReason: 'preserve-existing repair retained this requirement for checkpoint handoff',
        confidence: 1,
        tableContext: null,
        groupId: requirement.id,
        originalText: requirement.text,
        normalizedRequirement: requirement.text,
        decision: 'accepted_for_draft',
        decisionReason: 'preserve-existing repair retained requirement as controlled candidate',
        requiresHumanReview: false,
      };
    }
  );
  writeControlledMustCandidateArtifacts({
    root: input.root,
    sourcePath: input.sourcePath,
    paths: input.paths,
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    createdAt: input.createdAt,
    sourceText: input.sourceText,
    candidates: preserveExistingCandidates,
    mustRequirements,
    draftConfirmation: input.extraction.confirmation,
    decision: 'draft_materialization_allowed',
  });
  const auditInputHash = sha256Json({
    sourceDocumentHash,
    semanticModelHash,
    implementationConfirmationHash,
    semanticKernelHash,
    packetHash,
  });
  const effectivePacket = {
    ...packet,
    consecutiveNoNewValidGapRounds: input.consecutiveNoNewGapRounds,
    authorClaims: asRecordArray(packet.authorClaims).map((claim) => ({
      ...claim,
      criticDisposition:
        input.consecutiveNoNewGapRounds >= 3
          ? 'accepted_no_new_valid_gap'
          : 'pending_critical_auditor_response',
    })),
    mustPackets: asRecordArray(packet.mustPackets).map((mustPacket) => ({
      ...mustPacket,
      authorClaims: asRecordArray(mustPacket.authorClaims).map((claim) => ({
        ...claim,
        criticDisposition:
          input.consecutiveNoNewGapRounds >= 3
            ? 'accepted_no_new_valid_gap'
            : 'pending_critical_auditor_response',
      })),
    })),
  };
  return {
    ok: true,
    sourceDocumentHash,
    semanticModelHash,
    implementationConfirmationHash,
    semanticKernelHash,
    packetHash,
    mustRequirements,
    packet,
    effectivePacket,
    auditInputHash,
  };
}

function readMaterializedConfirmation(sourcePath: string): {
  sourceText: string;
  extraction: ImplementationConfirmationExtraction;
  sourceDocumentHash: string;
  implementationConfirmationHash: string;
} {
  const sourceText = fs.readFileSync(sourcePath, 'utf8');
  const extraction = extractImplementationConfirmationBlock(sourceText);
  if (!extraction) {
    throw new Error(
      `implementationConfirmation block missing after materialization: ${sourcePath}`
    );
  }
  return {
    sourceText,
    extraction,
    sourceDocumentHash: sourceDocumentHashForPreConfirmation(
      sourceText,
      extraction.blockText,
      extraction.confirmation
    ),
    implementationConfirmationHash: implementationConfirmationHashForPreConfirmation(
      extraction.confirmation
    ),
  };
}

function buildSemanticKernel(input: {
  root: string;
  sourcePath: string;
  recordId: string;
  sourceDocumentHash: string;
  semanticModelHash: string;
  implementationConfirmationHash: string;
  createdAt: string;
  mustRequirements: SourceMustRequirement[];
}): Record<string, unknown> {
  const mustRefs = input.mustRequirements.map((requirement) => requirement.id);
  const payload: Record<string, unknown> = {
    schemaVersion: 'semantic-kernel/v1',
    recordId: input.recordId,
    sourceDocument: toRootRelativePath(input.root, input.sourcePath),
    sourceDocumentHash: input.sourceDocumentHash,
    semanticModelHash: input.semanticModelHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    goal: 'Prepare requirement scope confirmation through semantic drilldown without proving implementation completion.',
    currentState: input.mustRequirements.map(
      (requirement) =>
        `${requirement.id} is an authored source requirement awaiting packet-backed drilldown.`
    ),
    targetState: [
      'User-confirmable requirement confirmation page is rendered after atomic decomposition and gates pass.',
    ],
    nonGoals: [
      'No delivery readiness claim.',
      'No seventh mental model.',
      'No standalone orchestrator authority.',
    ],
    mustCandidates: mustRefs,
    sourceRequirementTexts: input.mustRequirements.map((requirement) => requirement.text),
    sourceRequirementMap: input.mustRequirements.map((requirement) => ({
      id: requirement.id,
      text: requirement.text,
      source: requirement.source,
      sourceLine: requirement.sourceLine,
      sourcePath: requirement.sourcePath,
      sourceDocumentHash: requirement.sourceDocumentHash,
      sourceSpan: requirement.sourceSpan,
      headingPath: requirement.headingPath,
      candidateId: requirement.candidateId,
    })),
    createdBy: 'main_agent_orchestration.requirement_confirmation.pre_confirmation_drilldown',
    createdAt: input.createdAt,
    inputRefs: [toRootRelativePath(input.root, input.sourcePath)],
  };
  const { createdAt: _createdAt, ...semanticAuthority } = payload;
  payload.kernelHash = sha256Json({ ...semanticAuthority, kernelHash: null });
  payload.contentHash = payload.kernelHash;
  return payload;
}

function buildMustDecompositionPacket(input: {
  root: string;
  sourcePath: string;
  paths: PreConfirmationPaths;
  recordId: string;
  sourceDocumentHash: string;
  semanticModelHash: string;
  implementationConfirmationHash: string;
  semanticKernelHash: string;
  packetHash: string;
  createdAt: string;
  mustRequirements: SourceMustRequirement[];
  structuredBlocks?: StructuredSourceBlock[];
  targetAuthorityRecords?: TargetAuthorityRecord[];
  validationAuthorityRecords?: ValidationAuthorityRecord[];
  confirmation: Record<string, unknown>;
  consecutiveNoNewGapRounds?: number;
}): Record<string, unknown> {
  const rel = (filePath: string) => toRootRelativePath(input.root, filePath);
  const materialized = (target: string) => [target];
  const mustRefs = input.mustRequirements.map((requirement) => requirement.id);
  const mustTexts = input.mustRequirements.map((requirement) => requirement.text);
  const totalMusts = input.mustRequirements.length;
  const sourceBusinessFailureRows = buildBusinessFailurePathRows({
    blocks: input.structuredBlocks ?? [],
    mustRequirements: input.mustRequirements,
  });
  const sourceMustRefsForAuthorityRow = (
    section: string,
    sourceId: string,
    fields: string[]
  ): string[] => {
    const block = (input.structuredBlocks ?? []).find(
      (candidate) =>
        candidate.blockKind === 'table_row' &&
        headingPathContainsExactSection(candidate.headingPath, section) &&
        normalizeText(tableContextRowValue(candidate.tableContext, ['ID'])).toUpperCase() ===
          sourceId
    );
    return block
      ? sourceRefsToMustRefs(sourceRefsFromTableField(block, fields), input.mustRequirements)
      : [];
  };
  const negativeTraceOwnersByTrace = new Map<string, string[]>();
  const negativeAcceptanceRefsByMust = new Map<string, string[]>();
  const negativeE2eRefsByMust = new Map<string, string[]>();
  for (const block of input.structuredBlocks ?? []) {
    if (
      block.blockKind !== 'table_row' ||
      !headingPathContainsExactSection(block.headingPath, 'Trace Matrix Source')
    ) {
      continue;
    }
    const traceId = normalizeText(tableContextRowValue(block.tableContext, ['ID'])).toUpperCase();
    if (!/^TRACE-\d{1,3}$/u.test(traceId)) continue;
    const negativeRefs = sourceRefsFromTableField(block, ['Covers', 'Requirement']).filter((ref) =>
      /^NEG-\d{1,3}$/u.test(ref)
    );
    if (negativeRefs.length === 0) continue;
    const sourceAcceptanceRefs = sourceReferenceIds(sourceTableRowText(block)).filter((ref) =>
      /^ACC-\d{1,3}$/u.test(ref)
    );
    const sourceE2eRefs = sourceReferenceIds(sourceTableRowText(block)).filter((ref) =>
      /^E2E-\d{1,3}$/u.test(ref)
    );
    const acceptanceOwners = sourceAcceptanceRefs.flatMap((ref) =>
      sourceMustRefsForAuthorityRow('Acceptance Evidence', ref, ['Covers', 'Requirement refs'])
    );
    const failureOwners = sourceBusinessFailureRows
      .filter((row) => row.sourceTraceRefs.includes(traceId))
      .flatMap((row) => row.ownerMustRefs);
    const ownerMustRefs = uniqueNonEmpty([...acceptanceOwners, ...failureOwners]);
    if (ownerMustRefs.length === 0) continue;
    negativeTraceOwnersByTrace.set(traceId, ownerMustRefs);
    for (const mustRef of ownerMustRefs) {
      negativeAcceptanceRefsByMust.set(
        mustRef,
        uniqueNonEmpty([
          ...(negativeAcceptanceRefsByMust.get(mustRef) ?? []),
          ...sourceAcceptanceRefs,
        ])
      );
      negativeE2eRefsByMust.set(
        mustRef,
        uniqueNonEmpty([...(negativeE2eRefsByMust.get(mustRef) ?? []), ...sourceE2eRefs])
      );
    }
  }
  const targetAuthorityRecords = input.targetAuthorityRecords ?? [];
  const validationAuthorityRecords = input.validationAuthorityRecords ?? [];
  const sourceProjectionAuthority = buildSourceMustProjectionAuthority({
    blocks: input.structuredBlocks ?? [],
    mustRequirements: input.mustRequirements,
    validationAuthorityRecords,
  });
  const sourceMappedTargetPaths = new Set(
    [...sourceProjectionAuthority.values()]
      .flatMap((authority) => authority.targetFiles)
      .map((targetPath) => targetPath.replace(/\\/g, '/'))
  );
  const commandIds = assignedValidationAuthorityCommandIds(validationAuthorityRecords);
  const commandIdSet = new Set(commandIds);
  const negativeAcceptanceOwnersByRef = new Map<string, string[]>();
  for (const [mustRef, acceptanceRefs] of negativeAcceptanceRefsByMust) {
    for (const acceptanceRef of acceptanceRefs) {
      negativeAcceptanceOwnersByRef.set(
        acceptanceRef,
        uniqueNonEmpty([...(negativeAcceptanceOwnersByRef.get(acceptanceRef) ?? []), mustRef])
      );
    }
  }
  const commandIdsForMust = (mustRef: string): string[] => {
    const authority = sourceProjectionAuthority.get(mustRef);
    const refs = uniqueNonEmpty([
      ...(authority?.contractCommandRefs ?? []),
      ...(authority?.deliveryCommandRefs ?? []),
    ]).filter((ref) => commandIdSet.has(ref));
    const negativeClosureCommandIds = validationAuthorityRecords
      .map((record, recordIndex) => {
        const ownerMustRefs = uniqueNonEmpty([
          ...(record.sourceTraceRefs ?? []).flatMap(
            (traceRef) => negativeTraceOwnersByTrace.get(traceRef) ?? []
          ),
          ...(record.sourceAcceptanceRefs ?? []).flatMap(
            (acceptanceRef) => negativeAcceptanceOwnersByRef.get(acceptanceRef) ?? []
          ),
        ]);
        return ownerMustRefs.includes(mustRef) ? commandIds[recordIndex] : '';
      })
      .filter((ref) => commandIdSet.has(ref));
    const explicitCommandIds = validationAuthorityRecords
      .map((record, recordIndex) =>
        record.source === 'explicit_option' ? commandIds[recordIndex] : ''
      )
      .filter((ref) => commandIdSet.has(ref));
    return uniqueNonEmpty([...refs, ...negativeClosureCommandIds, ...explicitCommandIds]);
  };
  const commandMustRefsForTargetPath = (targetPath: string): string[] =>
    input.mustRequirements
      .filter((requirement) =>
        validationAuthorityRecords.some((record, recordIndex) => {
          const commandTargetPaths = uniqueNonEmpty([
            ...record.commandFileRefs,
            ...(record.sourceTargetFiles ?? []),
          ]).map((candidatePath) => candidatePath.replace(/\\/g, '/'));
          return (
            commandTargetPaths.includes(targetPath) &&
            commandIdsForMust(requirement.id).includes(commandIds[recordIndex])
          );
        })
      )
      .map((requirement) => requirement.id);
  const projectedTargetAuthorityRecords =
    sourceMappedTargetPaths.size > 0
      ? targetAuthorityRecords.filter(
          (record) =>
            record.explicit ||
            record.coverageRole === 'validation_only' ||
            sourceMappedTargetPaths.has(record.path.replace(/\\/g, '/'))
        )
      : targetAuthorityRecords;
  const targetPathRows = projectedTargetAuthorityRecords.map((record, index) => {
    const normalizedTargetPath = record.path.replace(/\\/g, '/');
    const sourceMappedRequirementRefs = uniqueNonEmpty([
      ...(record.sourceMustRefs ?? []),
      ...commandMustRefsForTargetPath(normalizedTargetPath),
      ...input.mustRequirements
        .filter((requirement) =>
          sourceProjectionAuthority.get(requirement.id)?.targetFiles.includes(normalizedTargetPath)
        )
        .map((requirement) => requirement.id),
    ]);
    return {
      id: `TARGET-MOD-${requirementOrdinal(index)}`,
      path: record.path,
      changeType:
        record.coverageRole === 'validation_only' || record.pathKind === 'test'
          ? 'validation_only'
          : 'modify',
      coverageRole:
        record.coverageRole === 'validation_only' || record.pathKind === 'test'
          ? 'validation_only'
          : 'modify',
      requirementRefs:
        sourceMappedRequirementRefs.length > 0
          ? sourceMappedRequirementRefs
          : record.explicit && record.coverageRole !== 'validation_only'
            ? mustRefs
            : totalMusts === 1
            ? mustRefs
            : [],
    };
  });
  targetPathRows.push(
    {
      id: `TARGET-MOD-${requirementOrdinal(projectedTargetAuthorityRecords.length)}`,
      path: rel(input.paths.preRenderMustGate),
      changeType: 'generated_output',
      coverageRole: 'generated_output',
      requirementRefs: mustRefs,
    },
    {
      id: `TARGET-MOD-${requirementOrdinal(projectedTargetAuthorityRecords.length + 1)}`,
      path: rel(input.paths.confirmationHtml),
      changeType: 'generated_output',
      coverageRole: 'generated_output',
      requirementRefs: mustRefs,
    }
  );
  const targetPathIdsForMust = (mustRef: string): string[] => {
    const refs = targetPathRows
      .filter((row) => row.requirementRefs.includes(mustRef))
      .map((row) => row.id);
    return refs;
  };
  const payload: Record<string, unknown> = {
    schemaVersion: 'must-decomposition-packet/v1',
    recordId: input.recordId,
    sourceDocument: rel(input.sourcePath),
    sourceDocumentHash: input.sourceDocumentHash,
    semanticModelHash: input.semanticModelHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    semanticKernelHash: input.semanticKernelHash,
    packetHash: input.packetHash,
    status: 'synchronized',
    generatedBy: 'main_agent_orchestration.requirement_confirmation.pre_confirmation_drilldown',
    createdBy: 'main_agent_orchestration.requirement_confirmation.pre_confirmation_drilldown',
    createdAt: input.createdAt,
    inputRefs: [rel(input.sourcePath), rel(input.paths.semanticKernel)],
    materializationTarget: 'implementationConfirmation',
    lifecycle: {
      currentMentalModel: 'requirement_confirmation',
      lane: 'pre_confirmation_drilldown',
      atomicDecompositionLoopEnteredBeforeMaterialization: true,
      materializationStartedAfterAtomicLoop: true,
      singlePassBypassPrevented: true,
      materializedAfterStatus: 'synchronized',
      controlledIngestRequiredBeforeMentalModelProgression: true,
    },
    consecutiveNoNewValidGapRounds: input.consecutiveNoNewGapRounds ?? 0,
    mustRefs,
    sourceRequirementTexts: mustTexts,
    topLevelProjectionInventory: projectionInventoryFromConfirmation(input.confirmation),
    authorClaims: [
      {
        id: 'CLAIM-001',
        claim: `Pre-confirmation packet is source-derived scope-quality evidence only, not implementation completion evidence, for ${mustRefs.join(', ')}.`,
        criticDisposition:
          (input.consecutiveNoNewGapRounds ?? 0) >= 3
            ? 'accepted_no_new_valid_gap'
            : 'pending_critical_auditor_response',
      },
    ],
    mustPackets: input.mustRequirements.map((requirement, index) => {
      const matrixId = mdmIdForMust(index, totalMusts);
      const sourceAuthority = sourceProjectionAuthority.get(requirement.id);
      const ids = sourceAuthorizedProjectionIdsForMust({
        index,
        total: totalMusts,
        mustRef: requirement.id,
        sourceAuthority,
        sourceBusinessFailureRows,
      });
      const productTargetFiles = sourceAuthority?.targetFiles.length
        ? sourceAuthority.targetFiles
        : [];
      const productTestFiles =
        sourceAuthority && sourceAuthority.testFiles.length > 0
          ? sourceAuthority.testFiles
          : productTargetFiles.filter(isExecutableTestPath);
      const oracle = sourceAuthority?.oracle || requirement.text;
      const atomicUnits = fullyDecomposedAtomicBehaviorOracleUnits(requirement.text, oracle);
      const taskIds = atomicTaskIdsForMust(index, totalMusts, atomicUnits.length);
      const taskRows = atomicUnits.map((unit, unitIndex) => ({
        id: taskIds[unitIndex],
        targetFiles: targetFilesForAtomicUnit(
          unit,
          productTargetFiles.length > 0
            ? productTargetFiles
            : productTestFiles.length > 0
              ? productTestFiles
              : []
        ),
        redProofPlan: `Current-attempt validation remains red until it independently proves: ${unit}`,
        primaryObservableBehaviors: [unit],
        primaryAcceptanceOracles: [unit],
        atomicUnitIndex: unitIndex + 1,
        atomicUnitCount: atomicUnits.length,
        derivedFromMustRef: requirement.id,
        materializedTo: materialized(
          `implementationConfirmation.atomicImplementationTaskList[${taskIds[unitIndex]}]`
        ),
      }));
      const negativeTraceRefs = [...negativeTraceOwnersByTrace.entries()]
        .filter(([, owners]) => owners.includes(requirement.id))
        .map(([traceId]) => traceId);
      const traceProjectionRefs = uniqueNonEmpty([
        ...(sourceAuthority?.traceRefs ?? []),
        ids.traceId,
        ...negativeTraceRefs,
      ]);
      const acceptanceProjectionRefs = uniqueNonEmpty([
        ...(sourceAuthority?.acceptanceRefs ?? []),
        ...(negativeAcceptanceRefsByMust.get(requirement.id) ?? []),
        ids.acceptanceId,
      ]).filter((ref) => /^ACC-\d{1,3}$/u.test(ref));
      const e2eProjectionRefs = uniqueNonEmpty([
        ...(sourceAuthority?.e2eRefs ?? []),
        ...(negativeE2eRefsByMust.get(requirement.id) ?? []),
        ids.e2eId,
      ]).filter((ref) => /^E2E-\d{1,3}$/u.test(ref));
      return {
        mustRef: requirement.id,
        mustIntent: requirement.text,
        sourceRequirementText: requirement.text,
        sourceRequirementLine: requirement.sourceLine,
        sourceRequirementAuthority: requirement.source,
        sourceLine: requirement.sourceLine,
        sourcePath: requirement.sourcePath,
        sourceDocumentHash: requirement.sourceDocumentHash,
        sourceSpan: requirement.sourceSpan,
        headingPath: requirement.headingPath,
        candidateId: requirement.candidateId,
        decompositionBasis: {
          observableBehaviors: atomicUnits,
          targetSurfaces: productTargetFiles,
        },
        atomicityDrivers: {
          behaviorSurfaceOracleUnits: atomicUnits,
          oneTaskPerIndependentBehaviorSurfaceOracle: true,
        },
        questionCoverage: {
          requiredCategories: [
            'scope_boundary',
            'atomicity',
            'projection',
            'confirmation_surface',
            'mental_model_progression',
          ],
          answeredCategories: [
            'scope_boundary',
            'atomicity',
            'projection',
            'confirmation_surface',
            'mental_model_progression',
          ],
          missingCategories: [],
          coverageVerdict: 'complete',
          questions: [
            `How many independently confirmable behavior-surface-oracle units does ${requirement.id} contain? ${atomicUnits.length}`,
            `Which entry points, failure outcomes, or state transitions require separate tasks for ${requirement.id}? ${atomicUnits.join(' | ')}`,
            `Does ${requirement.id} overlap another controlled MUST, and what distinct oracle prevents double counting? Review ${mustRefs.filter((mustRef) => mustRef !== requirement.id).join(', ')}`,
            `Which source-authorized product targets implement ${requirement.id}? ${productTargetFiles.join(', ')}`,
            `Which source oracle closes ${requirement.id}? ${oracle}`,
            `Which validation commands prove ${requirement.id}? ${commandIdsForMust(requirement.id).join(', ')}`,
          ],
        },
        atomicityCompleteness: {
          splitRule: 'one_task_per_independent_behavior_surface_oracle',
          completenessVerdict: 'complete',
          expectedTaskCount: atomicUnits.length,
          actualTaskCount: taskRows.length,
        },
        authorClaims: [
          {
            id: `CLAIM-${requirement.id}`,
            claim: `${requirement.id} is split into ${atomicUnits.length} source-oracle atomic behavior unit(s).`,
            criticDisposition:
              (input.consecutiveNoNewGapRounds ?? 0) >= 3
                ? 'accepted_no_new_valid_gap'
                : 'pending_critical_auditor_response',
          },
        ],
        mustExecutionDecompositionMatrix: [
          {
            id: matrixId,
            mustRef: requirement.id,
            atomicTaskRefs: taskIds,
            materializedTo: taskIds.flatMap((taskId) =>
              materialized(`implementationConfirmation.implementationTasks[${taskId}]`)
            ),
          },
        ],
        mustAtomicTasks: taskRows,
        mustEvidenceProjection: [
          {
            id: ids.evidenceId,
            materializedTo: materialized(`implementationConfirmation.evidence[${ids.evidenceId}]`),
          },
        ],
        mustTraceProjection: traceProjectionRefs.map((id) => ({
          id,
          materializedTo: materialized(`implementationConfirmation.traceRows[${id}]`),
        })),
        mustAcceptanceProjection: [
          ...acceptanceProjectionRefs.map((id) => ({
            id,
            materializedTo: materialized(
              `implementationConfirmation.acceptanceTests[${id}]`
            ),
          })),
          ...e2eProjectionRefs.map((id) => ({
            id,
            materializedTo: materialized(`implementationConfirmation.e2eSuites[${id}]`),
          })),
        ],
        mustFailureEdgeProjection: [
          ...ids.failureIds.map((failureId) => ({
            id: failureId,
            materializedTo: materialized(`implementationConfirmation.failurePaths[${failureId}]`),
          })),
          {
            id: ids.edgeId,
            materializedTo: materialized(`implementationConfirmation.edgeCases[${ids.edgeId}]`),
          },
        ],
        mustTargetPathProjection: targetPathIdsForMust(requirement.id).map((id) => ({
          id,
          materializedTo: materialized(`implementationConfirmation.targetModificationPaths[${id}]`),
        })),
        mustCurrentTargetProjection: [
          {
            id: `CT-MUST-${requirementOrdinal(index)}`,
            materializedTo: materialized('implementationConfirmation.currentTargetMap'),
          },
        ],
        mustAiTddManifestProjection: [
          {
            id: 'AI-TDD-001',
            materializedTo: materialized(
              'implementationConfirmation.aiTddContractExecutionManifestProjection'
            ),
          },
        ],
        mustArtifactProjection: [
          {
            id: 'ART-001',
            materializedTo: materialized(
              'implementationConfirmation.artifactAutomationPlan[ART-001]'
            ),
          },
          {
            id: 'ART-002',
            materializedTo: materialized(
              'implementationConfirmation.artifactAutomationPlan[ART-002]'
            ),
          },
        ],
        mustCommandProjection: commandIdsForMust(requirement.id).map((id) => ({
          id,
          materializedTo: materialized(`implementationConfirmation.requiredCommands[${id}]`),
        })),
        mustCloseoutBoundaryProjection: [
          {
            id: 'CLOSEOUT-BOUNDARY-001',
            materializedTo: materialized('implementationConfirmation.closeoutReadinessPreview'),
          },
        ],
      };
    }),
    mustDerivedProjectionMap: input.mustRequirements.map((requirement) => ({
      mustRef: requirement.id,
      materializedTo: [
        'implementationConfirmation.currentTargetMap',
        'implementationConfirmation.aiTddContractExecutionManifestProjection',
        'implementationConfirmation.closeoutReadinessPreview',
        'implementationConfirmation.mustToAtomicTaskMap',
        'implementationConfirmation.atomicTaskToTraceMap',
        'implementationConfirmation.atomicTaskToAcceptanceMap',
        'implementationConfirmation.atomicTaskToEvidenceMap',
        'implementationConfirmation.atomicTaskToTargetPathMap',
        'implementationConfirmation.atomicTaskToCommandMap',
      ],
    })),
  };
  payload.contentHash = input.packetHash;
  return payload;
}

function asRecordArray(value: unknown): Record<string, unknown>[] {
  return Array.isArray(value)
    ? value.filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === 'object' && !Array.isArray(item)
      )
    : [];
}

function asStringArray(value: unknown): string[] {
  return Array.isArray(value) ? value.map((item) => String(item)) : [];
}

function uniqueStrings(values: unknown[]): string[] {
  return [...new Set(values.map((value) => normalizeText(value)).filter(Boolean))];
}

function appendUniqueStrings(existing: unknown, additions: string[]): string[] {
  return uniqueStrings([...asStringArray(existing), ...additions]);
}

function areAuthoringCheckpointReceiptsCurrent(input: {
  root: string;
  draftSourcePath: string;
  paths: PreConfirmationPaths;
  recordId: string;
  requirementSetId: string;
  implementationAttemptId: string;
  sourceDocumentHash: string;
  implementationConfirmationHash: string;
}): boolean {
  const semanticBinding = semanticCheckpointBindingFromPaths(input.paths);
  if (!semanticBinding) return false;
  return AUTHORING_REPAIR_CHECKPOINTS.every((checkpoint) =>
    isCurrentCheckpointReceipt({
      root: input.root,
      receipt: readJsonIfExists(checkpointReceiptPath(input.paths, checkpoint)),
      checkpoint,
      recordId: input.recordId,
      requirementSetId: input.requirementSetId,
      implementationAttemptId: input.implementationAttemptId,
      sourceDocumentHash: input.sourceDocumentHash,
      implementationConfirmationHash: input.implementationConfirmationHash,
      semanticBinding,
      draftSourcePath: input.draftSourcePath,
      paths: input.paths,
    })
  );
}

function authoringCheckpointRouteDecisionForPersistence(
  routeDecision: Record<string, unknown> | null,
  paths: PreConfirmationPaths
): Record<string, unknown> | null {
  const decision = normalizeText(routeDecision?.decision);
  if (['checkpoint_required', 'checkpoint_required_with_amendment'].includes(decision)) {
    return routeDecision;
  }
  if (hasAnyAuthoringCheckpointReceipt(paths)) {
    return {
      ...(routeDecision ?? {}),
      decision: 'checkpoint_required_with_amendment',
      decisionSource:
        normalizeText(routeDecision?.decisionSource) || 'existing_checkpoint_receipts',
    };
  }
  return routeDecision;
}

function firstAvailableRef(...sets: Array<Set<string>>): string {
  for (const set of sets) {
    const first = [...set][0];
    if (first) return first;
  }
  return '';
}

function closeCriticalAuditorRepairProjectionRefs(
  confirmation: Record<string, unknown>,
  refs: {
    mustIds: Set<string>;
    negIds: Set<string>;
    outIds: Set<string>;
    evidenceIds: Set<string>;
    traceIds: Set<string>;
    acceptanceIds: Set<string>;
    e2eIds: Set<string>;
    commandIds: Set<string>;
  }
): { confirmation: Record<string, unknown>; changed: boolean; changedFields: string[] } {
  const mustIds = [...refs.mustIds];
  const negIds = [...refs.negIds];
  const requirementIds = [...mustIds, ...negIds];
  if (requirementIds.length === 0) {
    return { confirmation, changed: false, changedFields: [] };
  }
  const next: Record<string, unknown> = { ...confirmation };
  const changedFields = new Set<string>();
  const evidenceIds = [...refs.evidenceIds];
  const traceIds = [...refs.traceIds];
  const acceptanceIds = [...refs.acceptanceIds];
  const e2eIds = [...refs.e2eIds];
  const effectiveAcceptanceIds = acceptanceIds;
  const effectiveE2eIds = e2eIds;
  const commandId =
    firstAvailableRef(refs.commandIds) ||
    normalizeText(asRecordArray(next.requiredCommands)[0]?.id) ||
    normalizeText(asRecordArray(next.requiredCommands)[0]?.commandId);
  const failurePathIdsByNeg = new Map<string, string[]>();
  for (const failurePath of asRecordArray(next.failurePaths)) {
    const failurePathId = normalizeText(failurePath.id);
    for (const negId of asStringArray(failurePath.linkedNegIds)) {
      failurePathIdsByNeg.set(
        negId,
        appendUniqueStrings(failurePathIdsByNeg.get(negId), [failurePathId])
      );
    }
  }

  const updateRows = (
    field: string,
    shouldUpdate: (row: Record<string, unknown>) => boolean,
    update: (row: Record<string, unknown>) => Record<string, unknown>
  ) => {
    const rows = asRecordArray(next[field]);
    if (rows.length === 0) return;
    let changed = false;
    const nextRows = rows.map((row) => {
      if (!shouldUpdate(row)) return row;
      const updated = update({ ...row });
      if (stableStringify(updated) !== stableStringify(row)) changed = true;
      return updated;
    });
    if (changed) {
      next[field] = nextRows;
      changedFields.add(field);
    }
  };

  updateRows(
    'must',
    (row) => mustIds.includes(normalizeText(row.id)),
    (row) => ({
      ...row,
      evidenceRefs: appendUniqueStrings(row.evidenceRefs, evidenceIds),
      coveredByTraceRows: appendUniqueStrings(row.coveredByTraceRows, traceIds),
      acceptanceRefs: appendUniqueStrings(row.acceptanceRefs, [
        ...effectiveAcceptanceIds,
        ...effectiveE2eIds,
      ]),
    })
  );

  updateRows(
    'notDone',
    (row) => negIds.includes(normalizeText(row.id)),
    (row) => ({
      ...row,
      evidenceRefs: appendUniqueStrings(row.evidenceRefs, evidenceIds),
      coveredByTraceRows: appendUniqueStrings(row.coveredByTraceRows, traceIds),
      coveredByFailurePath: appendUniqueStrings(
        row.coveredByFailurePath,
        failurePathIdsByNeg.get(normalizeText(row.id)) ?? []
      ),
      negativeAssertionRequired: row.negativeAssertionRequired ?? true,
    })
  );

  updateRows(
    'negativeRequirements',
    (row) => negIds.includes(normalizeText(row.id)),
    (row) => ({
      ...row,
      evidenceRefs: appendUniqueStrings(row.evidenceRefs, evidenceIds),
      coveredByTraceRows: appendUniqueStrings(row.coveredByTraceRows, traceIds),
      coveredByFailurePath: appendUniqueStrings(
        row.coveredByFailurePath,
        failurePathIdsByNeg.get(normalizeText(row.id)) ?? []
      ),
      negativeAssertionRequired: row.negativeAssertionRequired ?? true,
    })
  );

  updateRows(
    'evidence',
    (row) => evidenceIds.includes(normalizeText(row.id)),
    (row) => ({
      ...row,
      mustRefs: appendUniqueStrings(row.mustRefs, mustIds),
      covers: appendUniqueStrings(row.covers, requirementIds),
      gate:
        normalizeText(row.gate) ||
        'Critical Auditor repair evidence must be verified by the requirement command.',
      oracle:
        normalizeText(row.oracle) ||
        `Repair evidence proves ${mustIds.join(', ')} without relying on shared all-MUST closure.`,
      requiredCommandRefs: commandId
        ? appendUniqueStrings(row.requiredCommandRefs, [commandId])
        : asStringArray(row.requiredCommandRefs),
      perMustAssertions: {
        ...recordObject(row.perMustAssertions),
        ...Object.fromEntries(
          requirementIds.map((requirementId) => [
            requirementId,
            `Evidence ${normalizeText(row.id)} independently proves ${requirementId}.`,
          ])
        ),
      },
    })
  );

  updateRows(
    'traceRows',
    (row) => traceIds.includes(normalizeText(row.id)),
    (row) => ({
      ...row,
      covers: appendUniqueStrings(row.covers, requirementIds).filter(
        (ref) => ref.startsWith('MUST-') || ref.startsWith('NEG-')
      ),
      boundaryRefs: appendUniqueStrings(row.boundaryRefs, [...refs.outIds]),
      evidenceRefs: appendUniqueStrings(row.evidenceRefs, evidenceIds),
      contractValidationCommandRefs: commandId
        ? appendUniqueStrings(row.contractValidationCommandRefs, [commandId])
        : asStringArray(row.contractValidationCommandRefs),
      deliveryEvidenceCommandRefs: commandId
        ? appendUniqueStrings(row.deliveryEvidenceCommandRefs, [commandId])
        : asStringArray(row.deliveryEvidenceCommandRefs),
      perMustAssertions: {
        ...recordObject(row.perMustAssertions),
        ...Object.fromEntries(
          requirementIds.map((requirementId) => [
            requirementId,
            `Trace ${normalizeText(row.id)} independently closes ${requirementId}.`,
          ])
        ),
      },
    })
  );

  const closeAcceptanceRows = (field: string, ids: string[]) => {
    updateRows(
      field,
      (row) => ids.includes(normalizeText(row.id)),
      (row) => ({
        ...row,
        covers: appendUniqueStrings(row.covers, mustIds),
        traceRows: appendUniqueStrings(row.traceRows ?? row.traceRefs, traceIds),
        evidenceRefs: appendUniqueStrings(row.evidenceRefs, evidenceIds),
        perMustAssertions: {
          ...recordObject(row.perMustAssertions),
          ...Object.fromEntries(
            mustIds.map((mustId) => [
              mustId,
              `Acceptance ${normalizeText(row.id)} independently verifies ${mustId}.`,
            ])
          ),
        },
      })
    );
  };
  closeAcceptanceRows('acceptanceTests', effectiveAcceptanceIds);
  closeAcceptanceRows('acceptanceCriteria', effectiveAcceptanceIds);
  closeAcceptanceRows('e2eSuites', effectiveE2eIds);
  closeAcceptanceRows('e2eScenarios', effectiveE2eIds);

  return {
    confirmation: next,
    changed: changedFields.size > 0,
    changedFields: [...changedFields].sort(),
  };
}

function normalizeVisualKindForProofClosure(value: unknown): string {
  const normalized = normalizeText(value)
    .toLowerCase()
    .replace(/[\s_-]+/gu, '');
  if (!normalized) return '';
  if (['happy', 'happypath', 'positive', 'success'].includes(normalized)) return 'happy';
  if (['failure', 'failurepath', 'negative', 'negativepath', 'rollback'].includes(normalized))
    return 'failure';
  if (['state', 'stateview', 'statediagram', 'stateflow'].includes(normalized)) return 'state';
  if (['flow', 'flowview', 'flowchart', 'process'].includes(normalized)) return 'flow';
  if (['edge', 'edgecase', 'edgecaseview'].includes(normalized)) return 'edge';
  if (['boundary', 'scopeboundary', 'out'].includes(normalized)) return 'boundary';
  return '';
}

function hasLegacyGovernanceCurrentTargetMap(value: unknown): boolean {
  const text = stableStringify(value);
  return [
    'Pre-confirmation drilldown remains inside requirement_confirmation',
    'Draft requirement',
    'User-confirmable requirement',
    'requirement_confirmation draft',
    'requirement_confirmation user_confirmable',
  ].some((token) => text.includes(token));
}

function hasStaleProductCurrentTargetMap(value: unknown, sourceText: string): boolean {
  const text = stableStringify(value);
  if (!text || text === '{}') return false;
  const currentTargetMap = recordObject(value);
  const sourceAuthorityText = sourceAuthorityTextWithoutInlineConfirmation(sourceText);
  const sourceHasStructuredDefaultRows =
    collectMarkdownDefaultVisibilityRowsForCurrentTargetMap(sourceAuthorityText).length > 0;
  if (
    sourceHasStructuredDefaultRows &&
    Object.keys(recordObject(currentTargetMap.sourceDefaultVisibility)).length === 0
  ) {
    return true;
  }
  const sourceStateProjection = currentTargetMapSourceStateProjection(sourceAuthorityText);
  if (
    sourceStateProjection.mode === 'source_current_target_sections' &&
    normalizeText(recordObject(currentTargetMap.sourceStateProjection).mode) !==
      'source_current_target_sections'
  ) {
    return true;
  }
  if (sourceStateProjection.mode === 'source_current_target_sections') {
    const existingProjection = recordObject(currentTargetMap.sourceStateProjection);
    const existingCurrentRows = asRecordArray(existingProjection.currentRows).map((row) =>
      normalizeText(row.text)
    );
    const existingTargetRows = asRecordArray(existingProjection.targetRows).map((row) =>
      normalizeText(row.text)
    );
    const expectedCurrentRows = sourceStateProjection.currentRows.map((row) =>
      normalizeText(row.text)
    );
    const expectedTargetRows = sourceStateProjection.targetRows.map((row) =>
      normalizeText(row.text)
    );
    if (
      stableStringify(existingCurrentRows) !== stableStringify(expectedCurrentRows) ||
      stableStringify(existingTargetRows) !== stableStringify(expectedTargetRows)
    ) {
      return true;
    }
  }
  if (
    /Current source anchors for default\/visibility behavior include/iu.test(text) ||
    /Target source-defined periods \(/iu.test(text)
  ) {
    return true;
  }
  if (
    /(?:reconfirm_required|req-trace|controlled confirm-scope ingest|source document hash|sourceDocumentHash|implementation readiness|本文档当前状态|用户精确确认|重新渲染确认页)/iu.test(
      text
    )
  ) {
    return true;
  }
  return false;
}

function shouldRebuildExistingCurrentTargetMap(value: unknown, sourceText: string): boolean {
  return (
    hasLegacyGovernanceCurrentTargetMap(value) || hasStaleProductCurrentTargetMap(value, sourceText)
  );
}

function inferredTargetModificationPathClassification(pathValue: unknown): string {
  const normalized = normalizeText(pathValue).replace(/\\/g, '/').toLowerCase();
  if (!normalized) return 'modify';
  if (isGeneratedRequirementArtifactPath(normalized)) return 'generated_output';
  if (
    /(?:^|\/)(?:tests?|e2e)\//iu.test(normalized) ||
    /\.(?:test|spec)\.[cm]?[jt]sx?$/iu.test(normalized)
  ) {
    return 'validation_only';
  }
  return 'modify';
}

function normalizedTargetModificationPathClassification(row: Record<string, unknown>): string {
  const existing = normalizeText(
    row.coverageRole ??
      row.changeType ??
      row.targetPathRole ??
      row.pathRole ??
      row.classification ??
      row.artifactType
  )
    .toLowerCase()
    .replace(/-/gu, '_');
  if (existing === 'validate' || existing === 'validation') return 'validation_only';
  if (existing === 'generated' || existing === 'output' || existing === 'generated_output')
    return 'generated_output';
  if (existing === 'runtime' || existing === 'runtime_output') return 'runtime_output';
  if (['modify', 'add', 'create', 'delete', 'remove', 'update', 'replace'].includes(existing)) {
    return 'modify';
  }
  if (['validation_only', 'generated_output', 'runtime_output'].includes(existing)) return existing;
  return inferredTargetModificationPathClassification(row.path);
}

function resyncTargetModificationPathClassifications(confirmation: Record<string, unknown>): {
  rows: Record<string, unknown>[];
  changed: boolean;
} {
  const rows = asRecordArray(confirmation.targetModificationPaths);
  let changed = false;
  const nextRows = rows.map((row) => {
    const classification = normalizedTargetModificationPathClassification(row);
    const nextRow: Record<string, unknown> = { ...row };
    const before = stableStringify(nextRow);
    nextRow.changeType = classification;
    nextRow.coverageRole = classification;
    if (stableStringify(nextRow) !== before) changed = true;
    return nextRow;
  });
  return { rows: nextRows, changed };
}

function existingProductTargetPaths(confirmation: Record<string, unknown>): string[] {
  return uniqueStrings(
    asRecordArray(confirmation.targetModificationPaths)
      .filter((row) => normalizedTargetModificationPathClassification(row) === 'modify')
      .map((row) => normalizeText(row.path).replace(/\\/g, '/').replace(/\/+$/u, ''))
      .filter(Boolean)
  );
}

function resyncExistingRequiredCommandTargetFiles(confirmation: Record<string, unknown>): {
  rows: Record<string, unknown>[];
  changed: boolean;
} {
  const productTargetPaths = existingProductTargetPaths(confirmation);
  const rows = asRecordArray(confirmation.requiredCommands);
  let changed = false;
  const nextRows = rows.map((row) => {
    const existingTargetFiles = asStringArray(row.targetFiles).map((targetPath) =>
      targetPath.replace(/\\/g, '/').replace(/\/+$/u, '')
    );
    const declaredTargets = uniqueStrings([
      ...existingTargetFiles,
      ...extractDeclaredTargetPaths(normalizeText(row.command)),
    ]);
    const resolvedTargetFiles = uniqueStrings(
      declaredTargets.flatMap((declaredTarget) => {
        const matchingProductTargets = productTargetPaths.filter(
          (targetPath) =>
            targetPath === declaredTarget || targetPath.startsWith(`${declaredTarget}/`)
        );
        if (matchingProductTargets.length > 0) return matchingProductTargets;
        if (
          existingTargetFiles.includes(declaredTarget) ||
          /\.[A-Za-z0-9]+$/u.test(declaredTarget)
        ) {
          return [declaredTarget];
        }
        return [];
      })
    );
    if (
      resolvedTargetFiles.length === 0 ||
      stableStringify(resolvedTargetFiles) === stableStringify(existingTargetFiles)
    ) {
      return row;
    }
    changed = true;
    return { ...row, targetFiles: resolvedTargetFiles };
  });
  return { rows: nextRows, changed };
}

function buildCurrentTargetMapFromExistingConfirmation(input: {
  root: string;
  sourcePath: string;
  sourceText?: string;
  packetHash?: string;
  confirmation: Record<string, unknown>;
  traceIds: string[];
  evidenceIds: string[];
  mustIds: string[];
}): CurrentTargetMapBuildResult {
  const mustRequirements: SourceMustRequirement[] = asRecordArray(input.confirmation.must)
    .filter((row) => input.mustIds.includes(normalizeText(row.id)))
    .map((row, index) => ({
      id: normalizeText(row.id) || normalizeMustRef(row.id, index),
      text: normalizeText(row.text) || normalizeText(row.description) || normalizeText(row.title),
      textZh: normalizeText(row.textZh) || undefined,
      source: 'inline_implementation_confirmation',
      sourceLine: typeof row.sourceLine === 'number' ? row.sourceLine : null,
      sourcePath: normalizeText(row.sourcePath) || undefined,
      sourceDocumentHash: normalizeText(row.sourceDocumentHash) || undefined,
      sourceSpan:
        recordObject(row.sourceSpan).startLine || recordObject(row.sourceSpan).endLine
          ? {
              startLine: Number(recordObject(row.sourceSpan).startLine ?? 1),
              endLine: Number(
                recordObject(row.sourceSpan).endLine ?? recordObject(row.sourceSpan).startLine ?? 1
              ),
            }
          : undefined,
      headingPath: asStringArray(row.headingPath),
    }));
  return buildSourceSpecificCurrentTargetMap({
    root: input.root,
    sourcePath: input.sourcePath,
    sourceText: input.sourceText,
    packetHash: normalizeText(input.packetHash) || undefined,
    mustRequirements,
    businessRows: asRecordArray(input.confirmation.businessViews),
    outOfScopeRows: [
      ...asRecordArray(input.confirmation.outOfScope),
      ...asRecordArray(input.confirmation.mustNot),
    ],
    targetPathRows: asRecordArray(input.confirmation.targetModificationPaths),
    commandRows: asRecordArray(input.confirmation.requiredCommands),
    allTraceIds: input.traceIds,
    allEvidenceIds: input.evidenceIds,
    mustRefs: input.mustIds,
  });
}

function defaultFailurePathRequiredAssertions(row: Record<string, unknown>): string[] {
  const failureId = normalizeText(row.id) || 'failure-path';
  const trigger = normalizeText(row.trigger) || 'failure trigger occurs';
  const expected =
    normalizeText(row.expectedBehavior) || 'expected fail-closed behavior is enforced';
  const forbidden = normalizeText(row.forbiddenBehavior) || 'forbidden behavior is rejected';
  return [`${failureId}: ${trigger}`, `${failureId}: ${expected}`, `${failureId}: ${forbidden}`];
}

function splitAtomicTaskIds(
  originalId: string,
  atomicUnits: string[],
  usedIdOracleKeys: Map<string, string>
): string[] {
  const ids = [originalId];
  for (const unit of atomicUnits.slice(1)) {
    const oracleKey = normalizedAtomicTaskOracleText(unit);
    const suffix = sha256Text(oracleKey)
      .replace(/^sha256:/u, '')
      .slice(0, 12)
      .toUpperCase();
    const baseCandidate = `${originalId}-A${suffix}`;
    let candidate = baseCandidate;
    let collisionOrdinal = 2;
    while (usedIdOracleKeys.has(candidate) && usedIdOracleKeys.get(candidate) !== oracleKey) {
      candidate = `${baseCandidate}-${collisionOrdinal}`;
      collisionOrdinal += 1;
    }
    ids.push(candidate);
    usedIdOracleKeys.set(candidate, oracleKey);
  }
  return ids;
}

function expandAtomicTaskRefs(values: unknown, replacements: Map<string, string[]>): string[] {
  return uniqueStrings(
    asStringArray(values).flatMap((value) => replacements.get(value) ?? [value])
  );
}

function normalizeExpandedAtomicTaskRefs(
  values: unknown,
  replacements: Map<string, string[]>,
  orderedTaskIds: string[]
): string[] {
  const originalRefs = asStringArray(values);
  const referencedIds = new Set([
    ...originalRefs,
    ...expandAtomicTaskRefs(originalRefs, replacements),
  ]);
  return orderedTaskIds.filter((taskId) => referencedIds.has(taskId));
}

function expandAtomicTaskKeyedMap(
  value: unknown,
  replacements: Map<string, string[]>,
  orderedTaskIds: string[] = []
): Record<string, unknown> {
  const source = recordObject(value);
  const next: Record<string, unknown> = {};
  const mergeEntry = (key: string, entry: unknown): void => {
    const expandedEntry = Array.isArray(entry) ? expandAtomicTaskRefs(entry, replacements) : entry;
    const existing = next[key];
    next[key] =
      Array.isArray(existing) && Array.isArray(expandedEntry)
        ? uniqueStrings([...existing, ...expandedEntry])
        : existing === undefined
          ? expandedEntry
          : existing;
  };
  for (const [key, entry] of Object.entries(source)) {
    const replacementIds = replacements.get(key);
    if (!replacementIds) {
      mergeEntry(key, entry);
      continue;
    }
    if (orderedTaskIds.includes(key)) {
      mergeEntry(key, entry);
    }
    for (const replacementId of replacementIds) {
      mergeEntry(replacementId, entry);
    }
  }
  if (orderedTaskIds.length === 0) return next;
  return Object.fromEntries([
    ...orderedTaskIds
      .filter((taskId) => next[taskId] !== undefined)
      .map((taskId) => [taskId, next[taskId]]),
    ...Object.entries(next).filter(([taskId]) => !orderedTaskIds.includes(taskId)),
  ]);
}

function normalizedAtomicTaskOracleText(value: unknown): string {
  return normalizeText(value)
    .normalize('NFKC')
    .toLocaleLowerCase('en-US')
    .replace(/\s+/gu, ' ')
    .replace(/[.!?。！？]+$/gu, '');
}

function normalizedAtomicTaskOracleKey(row: Record<string, unknown>): string {
  return normalizedAtomicTaskOracleText(
    asStringArray(row.primaryAcceptanceOracles)[0] ||
      asStringArray(row.primaryObservableBehaviors)[0] ||
      normalizeText(row.text)
  );
}

function canonicalizeAtomicTaskRows(
  taskRows: Record<string, unknown>[],
  replacements: Map<string, string[]>,
  generatedTaskIds: Set<string>
): { taskRows: Record<string, unknown>[]; changed: boolean } {
  const canonicalRows: Record<string, unknown>[] = [];
  const canonicalIndexByKey = new Map<string, number>();
  const duplicateToCanonical = new Map<string, string>();
  let changed = false;
  const mergeTaskRows = (
    canonicalRow: Record<string, unknown>,
    duplicateRow: Record<string, unknown>
  ): Record<string, unknown> => ({
    ...canonicalRow,
    targetFiles: uniqueNonEmpty([
      ...asStringArray(canonicalRow.targetFiles),
      ...asStringArray(duplicateRow.targetFiles),
    ]).slice(0, 6),
    acceptanceRefs: uniqueNonEmpty([
      ...asStringArray(canonicalRow.acceptanceRefs),
      ...asStringArray(duplicateRow.acceptanceRefs),
    ]),
    traceRows: uniqueNonEmpty([
      ...asStringArray(canonicalRow.traceRows),
      ...asStringArray(duplicateRow.traceRows),
    ]),
    evidenceRefs: uniqueNonEmpty([
      ...asStringArray(canonicalRow.evidenceRefs),
      ...asStringArray(duplicateRow.evidenceRefs),
    ]),
  });

  for (const row of taskRows) {
    const taskId = normalizeText(row.id);
    const mustRef = normalizeText(row.derivedFromMustRef || row.mustRef);
    const oracleKey = normalizedAtomicTaskOracleKey(row);
    if (!taskId || !mustRef || !oracleKey) {
      canonicalRows.push(row);
      continue;
    }
    const key = `${mustRef}\u0000${oracleKey}`;
    const canonicalIndex = canonicalIndexByKey.get(key);
    if (canonicalIndex === undefined) {
      canonicalIndexByKey.set(key, canonicalRows.length);
      canonicalRows.push(row);
      continue;
    }

    const canonicalRow = canonicalRows[canonicalIndex];
    const canonicalId = normalizeText(canonicalRow.id);
    if (taskId === canonicalId) {
      canonicalRows[canonicalIndex] = mergeTaskRows(canonicalRow, row);
      changed = true;
      continue;
    }
    if (generatedTaskIds.has(canonicalId) && !generatedTaskIds.has(taskId)) {
      duplicateToCanonical.set(canonicalId, taskId);
      canonicalRows[canonicalIndex] = mergeTaskRows(row, canonicalRow);
    } else {
      duplicateToCanonical.set(taskId, canonicalId);
      canonicalRows[canonicalIndex] = mergeTaskRows(canonicalRow, row);
    }
    changed = true;
  }

  if (duplicateToCanonical.size > 0) {
    const resolveCanonicalId = (taskId: string): string => {
      const seen = new Set<string>();
      let current = taskId;
      while (duplicateToCanonical.has(current) && !seen.has(current)) {
        seen.add(current);
        current = duplicateToCanonical.get(current) ?? current;
      }
      return current;
    };
    for (const [sourceId, replacementIds] of replacements.entries()) {
      replacements.set(
        sourceId,
        uniqueNonEmpty(replacementIds.map((replacementId) => resolveCanonicalId(replacementId)))
      );
    }
    for (const duplicateId of duplicateToCanonical.keys()) {
      replacements.set(duplicateId, [resolveCanonicalId(duplicateId)]);
    }
  }
  if (duplicateToCanonical.size === 0 && replacements.size === 0) {
    return { taskRows: canonicalRows, changed };
  }

  const taskCountByMust = new Map<string, number>();
  for (const row of canonicalRows) {
    const mustRef = normalizeText(row.derivedFromMustRef || row.mustRef);
    if (mustRef) {
      taskCountByMust.set(mustRef, (taskCountByMust.get(mustRef) ?? 0) + 1);
    }
  }
  const nextIndexByMust = new Map<string, number>();
  const reindexedRows = canonicalRows.map((row) => {
    const mustRef = normalizeText(row.derivedFromMustRef || row.mustRef);
    const oracle =
      asStringArray(row.primaryAcceptanceOracles)[0] ||
      asStringArray(row.primaryObservableBehaviors)[0];
    if (!mustRef || !oracle) return row;
    const atomicUnitIndex = (nextIndexByMust.get(mustRef) ?? 0) + 1;
    const atomicUnitCount = taskCountByMust.get(mustRef) ?? 1;
    nextIndexByMust.set(mustRef, atomicUnitIndex);
    const nextRow = {
      ...row,
      text: `Implement and prove ${mustRef} atomic behavior ${atomicUnitIndex}: ${oracle}`,
      redProofPlan: `Current-attempt validation remains red until it independently proves: ${oracle}`,
      primaryObservableBehaviors: [oracle],
      primaryAcceptanceOracles: [oracle],
      atomicUnitIndex,
      atomicUnitCount,
    };
    if (stableStringify(nextRow) !== stableStringify(row)) changed = true;
    return nextRow;
  });

  return { taskRows: reindexedRows, changed };
}

function resyncExistingAtomicTaskDecomposition(confirmation: Record<string, unknown>): {
  confirmation: Record<string, unknown>;
  changed: boolean;
} {
  const taskRows = asRecordArray(confirmation.atomicImplementationTaskList);
  if (taskRows.length === 0) return { confirmation, changed: false };
  const authorityTargetsByMust = new Map<string, string[]>();
  const modificationTargetsByMust = new Map<string, string[]>();
  const addAuthorityTargets = (row: Record<string, unknown>, targets: string[]): void => {
    const mustRefs = uniqueNonEmpty([
      normalizeText(row.derivedFromMustRef || row.mustRef),
      ...asStringArray(row.covers),
      ...asStringArray(row.requirementRefs),
      ...asRecordArray(row.perMustRows).map((entry) => normalizeText(entry.mustRef)),
    ]).filter((ref) => ref.startsWith('MUST-'));
    for (const mustRef of mustRefs) {
      authorityTargetsByMust.set(
        mustRef,
        uniqueNonEmpty([...(authorityTargetsByMust.get(mustRef) ?? []), ...targets])
      );
    }
  };
  for (const row of asRecordArray(confirmation.targetModificationPaths)) {
    addAuthorityTargets(row, [normalizeText(row.path)]);
    if (
      !['validation_only', 'generated_output'].includes(normalizeText(row.coverageRole)) &&
      normalizeText(row.changeType) !== 'validation_only'
    ) {
      const mustRefs = uniqueNonEmpty([
        normalizeText(row.derivedFromMustRef || row.mustRef),
        ...asStringArray(row.requirementRefs),
      ]).filter((ref) => ref.startsWith('MUST-'));
      for (const mustRef of mustRefs) {
        modificationTargetsByMust.set(
          mustRef,
          uniqueNonEmpty([
            ...(modificationTargetsByMust.get(mustRef) ?? []),
            normalizeText(row.path),
          ])
        );
      }
    }
  }
  for (const row of asRecordArray(confirmation.requiredCommands)) {
    addAuthorityTargets(row, asStringArray(row.targetFiles));
  }
  for (const row of [
    ...asRecordArray(confirmation.acceptanceTests),
    ...asRecordArray(confirmation.e2eSuites),
  ]) {
    addAuthorityTargets(row, [normalizeText(row.file)]);
  }
  const mustTextByRef = new Map(
    asRecordArray(confirmation.must)
      .map((row) => [normalizeText(row.id), normalizeText(row.text)] as const)
      .filter(([mustRef, text]) => mustRef && text)
  );
  const taskCountByMust = new Map<string, number>();
  for (const row of taskRows) {
    const mustRef = normalizeText(row.derivedFromMustRef || row.mustRef);
    if (mustRef) {
      taskCountByMust.set(mustRef, (taskCountByMust.get(mustRef) ?? 0) + 1);
    }
  }
  const usedIdOracleKeys = new Map(
    taskRows
      .map((row) => [normalizeText(row.id), normalizedAtomicTaskOracleKey(row)] as const)
      .filter(([taskId, oracleKey]) => taskId && oracleKey)
  );
  const replacements = new Map<string, string[]>();
  const generatedTaskIds = new Set<string>();
  let taskTargetsChanged = false;
  const expandedTaskRows = taskRows.flatMap((row) => {
    const originalId = normalizeText(row.id);
    const mustRef = normalizeText(row.derivedFromMustRef || row.mustRef);
    const primaryOracles = asStringArray(row.primaryAcceptanceOracles);
    const primaryBehaviors = asStringArray(row.primaryObservableBehaviors);
    const oracleSources =
      primaryOracles.length > 0
        ? primaryOracles
        : primaryBehaviors.length > 0
          ? primaryBehaviors
          : [normalizeText(row.text)].filter(Boolean);
    const oracleAtomicUnits = uniqueStrings(
      oracleSources.flatMap((oracle) => fullyDecomposedAtomicBehaviorOracleUnits('', oracle))
    );
    const requirementAtomicUnits = fullyDecomposedAtomicBehaviorOracleUnits(
      '',
      controlledMustBehaviorText(mustTextByRef.get(mustRef) ?? '')
    );
    let atomicUnits =
      taskCountByMust.get(mustRef) === 1 && requirementAtomicUnits.length > oracleAtomicUnits.length
        ? requirementAtomicUnits
        : oracleAtomicUnits;
    if (!originalId || !mustRef || atomicUnits.length === 0) return [row];
    const originalOracleKey = normalizedAtomicTaskOracleText(
      primaryOracles[0] || primaryBehaviors[0] || normalizeText(row.text)
    );
    const originalOracleUnitIndex = atomicUnits.findIndex(
      (unit) => normalizedAtomicTaskOracleText(unit) === originalOracleKey
    );
    if (originalOracleUnitIndex > 0) {
      atomicUnits = [
        atomicUnits[originalOracleUnitIndex],
        ...atomicUnits.filter((_, index) => index !== originalOracleUnitIndex),
      ];
    }
    const sourceTargets = asStringArray(row.targetFiles);
    const authorityTargets = authorityTargetsByMust.get(mustRef) ?? [];
    const authorityTargetSet = new Set(
      authorityTargets.map((target) => target.replace(/\\/g, '/'))
    );
    const authorityScopedSourceTargets = sourceTargets.filter((target) =>
      authorityTargetSet.has(target.replace(/\\/g, '/'))
    );
    const fallbackTargets =
      authorityScopedSourceTargets.length > 0
        ? authorityScopedSourceTargets
        : sourceTargets.length > 0
          ? sourceTargets
          : authorityTargets;
    const targetCandidates = uniqueNonEmpty([...sourceTargets, ...authorityTargets]);
    if (atomicUnits.length === 1) {
      const targetFiles = targetFilesForAtomicUnit(
        atomicUnits[0],
        targetCandidates,
        fallbackTargets
      );
      if (stableStringify(targetFiles) === stableStringify(sourceTargets)) return [row];
      taskTargetsChanged = true;
      return [{ ...row, targetFiles }];
    }
    const taskIds = splitAtomicTaskIds(originalId, atomicUnits, usedIdOracleKeys);
    for (const generatedTaskId of taskIds.slice(1)) {
      generatedTaskIds.add(generatedTaskId);
    }
    replacements.set(originalId, taskIds);
    return atomicUnits.map((unit, index) => ({
      ...row,
      id: taskIds[index],
      text: `Implement and prove ${mustRef} atomic behavior ${index + 1}: ${unit}`,
      targetFiles: targetFilesForAtomicUnit(unit, targetCandidates, fallbackTargets),
      redProofPlan: `Current-attempt validation remains red until it independently proves: ${unit}`,
      primaryObservableBehaviors: [unit],
      primaryAcceptanceOracles: [unit],
      atomicUnitIndex: index + 1,
      atomicUnitCount: atomicUnits.length,
    }));
  });
  const canonicalized = canonicalizeAtomicTaskRows(
    expandedTaskRows,
    replacements,
    generatedTaskIds
  );
  const authorityCoverage = ensureAtomicTaskModificationAuthorityCoverage(
    canonicalized.taskRows,
    modificationTargetsByMust
  );
  if (authorityCoverage.changed) {
    taskTargetsChanged = true;
  }
  const nextTaskRows = authorityCoverage.taskRows;
  const orderedTaskIds = nextTaskRows.map((row) => normalizeText(row.id)).filter(Boolean);
  const taskRowsById = new Map(
    nextTaskRows
      .map((row) => [normalizeText(row.id), row] as const)
      .filter(([taskId]) => Boolean(taskId))
  );
  const orderedTaskIdsByMust = new Map<string, string[]>();
  for (const row of nextTaskRows) {
    const taskId = normalizeText(row.id);
    const mustRef = normalizeText(row.derivedFromMustRef || row.mustRef);
    if (!taskId || !mustRef) continue;
    orderedTaskIdsByMust.set(mustRef, [...(orderedTaskIdsByMust.get(mustRef) ?? []), taskId]);
  }
  if (replacements.size === 0 && !taskTargetsChanged && !canonicalized.changed) {
    return { confirmation, changed: false };
  }

  const nextConfirmation: Record<string, unknown> = {
    ...confirmation,
    atomicImplementationTaskList: nextTaskRows,
  };
  if (replacements.size === 0) {
    const changed = stableStringify(nextConfirmation) !== stableStringify(confirmation);
    return { confirmation: changed ? nextConfirmation : confirmation, changed };
  }
  for (const field of [
    'mustExecutionDecompositionMatrix',
    'traceRows',
    'acceptanceTests',
    'e2eSuites',
    'evidence',
  ]) {
    nextConfirmation[field] = asRecordArray(confirmation[field]).map((row) => {
      const nextRow = { ...row };
      const rowId = normalizeText(row.id);
      const rowMustRef = normalizeText(row.mustRef || row.derivedFromMustRef);
      const directlyLinkedTaskIds =
        field === 'mustExecutionDecompositionMatrix'
          ? (orderedTaskIdsByMust.get(rowMustRef) ?? [])
          : orderedTaskIds.filter((taskId) => {
              const taskRow = taskRowsById.get(taskId);
              if (!taskRow || !rowId) return false;
              if (field === 'traceRows') return asStringArray(taskRow.traceRows).includes(rowId);
              if (field === 'evidence') return asStringArray(taskRow.evidenceRefs).includes(rowId);
              return asStringArray(taskRow.acceptanceRefs).includes(rowId);
            });
      for (const refField of ['taskRefs', 'atomicTaskRefs']) {
        if (Array.isArray(row[refField])) {
          const normalizedRefs = normalizeExpandedAtomicTaskRefs(
            row[refField],
            replacements,
            orderedTaskIds
          );
          const includedRefs = new Set([...normalizedRefs, ...directlyLinkedTaskIds]);
          nextRow[refField] = orderedTaskIds.filter((taskId) => includedRefs.has(taskId));
        }
      }
      return nextRow;
    });
  }
  const mustToAtomicTaskMap = recordObject(confirmation.mustToAtomicTaskMap);
  if (Object.keys(mustToAtomicTaskMap).length > 0) {
    nextConfirmation.mustToAtomicTaskMap = Object.fromEntries(
      Object.entries(mustToAtomicTaskMap).map(([mustRef, refs]) => [
        mustRef,
        orderedTaskIdsByMust.get(mustRef) ??
          normalizeExpandedAtomicTaskRefs(refs, replacements, orderedTaskIds),
      ])
    );
  }
  const completeAtomicTaskKeyedMap = (
    value: unknown,
    directRefField?: 'traceRows' | 'acceptanceRefs' | 'evidenceRefs'
  ): Record<string, unknown> => {
    const expanded = expandAtomicTaskKeyedMap(value, replacements, orderedTaskIds);
    const refsByMust = new Map<string, string[]>();
    for (const [taskId, entry] of Object.entries(expanded)) {
      const taskRow = taskRowsById.get(taskId);
      const mustRef = normalizeText(taskRow?.derivedFromMustRef || taskRow?.mustRef);
      if (!mustRef || !Array.isArray(entry)) continue;
      refsByMust.set(mustRef, uniqueNonEmpty([...(refsByMust.get(mustRef) ?? []), ...entry]));
    }
    return Object.fromEntries(
      orderedTaskIds.flatMap((taskId) => {
        const taskRow = taskRowsById.get(taskId);
        if (!taskRow) return [];
        const mustRef = normalizeText(taskRow.derivedFromMustRef || taskRow.mustRef);
        const directRefs = directRefField ? asStringArray(taskRow[directRefField]) : [];
        const taskSpecificRefs = uniqueNonEmpty([
          ...asStringArray(expanded[taskId]),
          ...directRefs,
        ]);
        const refs =
          taskSpecificRefs.length > 0 ? taskSpecificRefs : (refsByMust.get(mustRef) ?? []);
        return refs.length > 0 ? [[taskId, refs] as const] : [];
      })
    );
  };
  const keyedMapDirectRefFields: Record<
    string,
    'traceRows' | 'acceptanceRefs' | 'evidenceRefs' | undefined
  > = {
    atomicTaskToTraceMap: 'traceRows',
    atomicTaskToAcceptanceMap: 'acceptanceRefs',
    atomicTaskToEvidenceMap: 'evidenceRefs',
    atomicTaskToTargetPathMap: undefined,
    atomicTaskToCommandMap: undefined,
  };
  for (const field of [
    'atomicTaskToTraceMap',
    'atomicTaskToAcceptanceMap',
    'atomicTaskToEvidenceMap',
    'atomicTaskToTargetPathMap',
    'atomicTaskToCommandMap',
  ]) {
    if (Object.keys(recordObject(confirmation[field])).length > 0) {
      nextConfirmation[field] = completeAtomicTaskKeyedMap(
        confirmation[field],
        keyedMapDirectRefFields[field]
      );
    }
  }
  const manifest = recordObject(confirmation.aiTddContractExecutionManifestProjection);
  const lineage = recordObject(manifest.atomicImplementationTaskLineage);
  if (Object.keys(lineage).length > 0) {
    const nextLineage: Record<string, unknown> = { ...lineage };
    const lineageMustMap = recordObject(lineage.mustToAtomicTaskMap);
    if (Object.keys(lineageMustMap).length > 0) {
      nextLineage.mustToAtomicTaskMap = Object.fromEntries(
        Object.entries(lineageMustMap).map(([mustRef, refs]) => [
          mustRef,
          orderedTaskIdsByMust.get(mustRef) ??
            normalizeExpandedAtomicTaskRefs(refs, replacements, orderedTaskIds),
        ])
      );
    }
    for (const field of [
      'atomicTaskToTraceMap',
      'atomicTaskToAcceptanceMap',
      'atomicTaskToEvidenceMap',
      'atomicTaskToTargetPathMap',
      'atomicTaskToCommandMap',
    ]) {
      if (Object.keys(recordObject(lineage[field])).length > 0) {
        nextLineage[field] = completeAtomicTaskKeyedMap(
          lineage[field],
          keyedMapDirectRefFields[field]
        );
      }
    }
    nextConfirmation.aiTddContractExecutionManifestProjection = {
      ...manifest,
      atomicImplementationTaskLineage: nextLineage,
    };
  }
  const changed = stableStringify(nextConfirmation) !== stableStringify(confirmation);
  return { confirmation: changed ? nextConfirmation : confirmation, changed };
}

function semanticProjectionOwnershipText(row: Record<string, unknown>): string {
  return uniqueNonEmpty([
    normalizeText(row.title),
    normalizeText(row.text),
    normalizeText(row.trigger),
    normalizeText(row.condition),
    normalizeText(row.expectedBehavior),
    normalizeText(row.forbiddenBehavior),
    normalizeText(row.oracle),
    ...asStringArray(row.primaryObservableBehaviors),
    ...asStringArray(row.primaryAcceptanceOracles),
  ]).join(' ');
}

function semanticProjectionOwnershipScore(projectionText: string, requirementText: string): number {
  const projectionTokens = new Set(semanticBusinessTokens(projectionText));
  return semanticBusinessTokens(requirementText).reduce((score, token) => {
    if (projectionTokens.has(token)) return score + token.length;
    const partialMatch = [...projectionTokens].some(
      (projectionToken) =>
        projectionToken.length >= 4 &&
        token.length >= 4 &&
        (projectionToken.includes(token) || token.includes(projectionToken))
    );
    return score + (partialMatch ? Math.min(token.length, 6) : 0);
  }, 0);
}

function uniquelyDominantSemanticMustRef(input: {
  row: Record<string, unknown>;
  candidateMustRefs: string[];
  mustRowsById: Map<string, Record<string, unknown>>;
}): string {
  const projectionText = semanticProjectionOwnershipText(input.row);
  const scored = uniqueStrings(input.candidateMustRefs)
    .map((mustRef) => ({
      mustRef,
      score: semanticProjectionOwnershipScore(
        projectionText,
        normalizeText(input.mustRowsById.get(mustRef)?.text)
      ),
    }))
    .sort((left, right) => right.score - left.score || left.mustRef.localeCompare(right.mustRef));
  if (scored.length === 0 || scored[0].score <= 0 || scored[0].score === scored[1]?.score) {
    return '';
  }
  return scored[0].mustRef;
}

function canonicalImplementationTasksForResync(
  confirmation: Record<string, unknown>
): Record<string, unknown>[] {
  const existingTasks = asRecordArray(confirmation.implementationTasks);
  if (existingTasks.length > 0) return existingTasks;

  const mustRowsById = new Map(
    asRecordArray(confirmation.must)
      .map((row) => [normalizeText(row.id), row] as const)
      .filter(([mustRef]) => Boolean(mustRef))
  );
  const legacyTasksById = new Map(
    asRecordArray(confirmation.atomicImplementationTaskList)
      .map((row) => [normalizeText(row.id), row] as const)
      .filter(([taskId]) => Boolean(taskId))
  );
  const traceRows = asRecordArray(confirmation.traceRows);
  const taskIds = uniqueNonEmpty([
    ...legacyTasksById.keys(),
    ...traceRows.flatMap((row) => [
      ...asStringArray(row.taskRefs),
      ...asStringArray(row.atomicTaskRefs),
    ]),
  ]);
  const targetRows = asRecordArray(confirmation.targetModificationPaths);
  const commandRows = asRecordArray(confirmation.requiredCommands);
  const acceptanceRows = [
    ...asRecordArray(confirmation.acceptanceTests),
    ...asRecordArray(confirmation.e2eSuites),
  ];

  return taskIds.map((taskId) => {
    const legacyTask = legacyTasksById.get(taskId) ?? {};
    const owningTraces = traceRows.filter((row) =>
      [...asStringArray(row.taskRefs), ...asStringArray(row.atomicTaskRefs)].includes(taskId)
    );
    const traceRefs = uniqueNonEmpty([
      ...asStringArray(legacyTask.traceRefs),
      ...asStringArray(legacyTask.traceRows),
      ...owningTraces.map((row) => normalizeText(row.id)),
    ]);
    const evidenceRefs = uniqueNonEmpty([
      ...asStringArray(legacyTask.evidenceRefs),
      ...owningTraces.flatMap((row) => asStringArray(row.evidenceRefs)),
    ]);
    const requirementRefs = uniqueNonEmpty([
      ...asStringArray(legacyTask.requirementRefs),
      normalizeText(legacyTask.derivedFromMustRef || legacyTask.mustRef),
      ...owningTraces.flatMap((row) => asStringArray(row.covers)),
    ]).filter((mustRef) => mustRowsById.has(mustRef));
    const rowBelongsToTask = (row: Record<string, unknown>): boolean => {
      const rowMustRefs = uniqueNonEmpty([
        normalizeText(row.derivedFromMustRef || row.mustRef),
        ...asStringArray(row.requirementRefs),
        ...asStringArray(row.covers),
      ]);
      const rowTraceRefs = uniqueNonEmpty([
        ...asStringArray(row.traceRefs),
        ...asStringArray(row.traceRows),
      ]);
      const rowEvidenceRefs = asStringArray(row.evidenceRefs);
      return (
        rowMustRefs.some((mustRef) => requirementRefs.includes(mustRef)) ||
        rowTraceRefs.some((traceRef) => traceRefs.includes(traceRef)) ||
        rowEvidenceRefs.some((evidenceRef) => evidenceRefs.includes(evidenceRef))
      );
    };
    const targetPaths = uniqueNonEmpty([
      ...asStringArray(legacyTask.targetPaths),
      ...asStringArray(legacyTask.targetFiles),
      ...targetRows.filter(rowBelongsToTask).map((row) => normalizeText(row.path)),
      ...commandRows.filter(rowBelongsToTask).flatMap((row) => asStringArray(row.targetFiles)),
      ...acceptanceRows.filter(rowBelongsToTask).map((row) => normalizeText(row.file)),
    ]);
    const requirementTitles = requirementRefs
      .map((mustRef) => normalizeText(mustRowsById.get(mustRef)?.text))
      .filter(Boolean);
    return {
      id: taskId,
      title:
        normalizeText(legacyTask.title) ||
        normalizeText(legacyTask.text) ||
        requirementTitles.join(' | ') ||
        taskId,
      requirementRefs,
      targetPaths,
      traceRefs,
      evidenceRefs,
    };
  });
}

function resyncExistingBusinessVisualProofClosure(
  confirmation: Record<string, unknown>,
  context?: {
    root: string;
    sourcePath: string;
    sourceText: string;
    packetHash?: string;
    forceCurrentTargetMapRebuild?: boolean;
  },
  options: {
    resetCriticalAuditor?: boolean;
  } = {}
): { confirmation: Record<string, unknown>; changed: boolean; changedViewIds: string[] } {
  const traceRows = asRecordArray(confirmation.traceRows);
  const traceIds = traceRows.map((row) => normalizeText(row.id)).filter(Boolean);
  const evidenceIds = asRecordArray(confirmation.evidence)
    .map((row) => normalizeText(row.id))
    .filter(Boolean);
  const acceptanceIds = [
    ...asRecordArray(confirmation.acceptanceTests),
    ...asRecordArray(confirmation.e2eSuites),
  ]
    .map((row) => normalizeText(row.id))
    .filter(Boolean);
  const failurePathIds = asRecordArray(confirmation.failurePaths)
    .map((row) => normalizeText(row.id))
    .filter(Boolean);
  const edgeCaseIds = asRecordArray(confirmation.edgeCases)
    .map((row) => normalizeText(row.id))
    .filter(Boolean);
  const mustIds = asRecordArray(confirmation.must)
    .map((row) => normalizeText(row.id))
    .filter(Boolean);
  if (
    traceIds.length === 0 ||
    evidenceIds.length === 0 ||
    acceptanceIds.length === 0 ||
    mustIds.length === 0
  ) {
    return { confirmation, changed: false, changedViewIds: [] };
  }

  let nextConfirmation: Record<string, unknown> = { ...confirmation };
  const changedViewIds = new Set<string>();
  let changed = false;
  const canonicalImplementationTasks = canonicalImplementationTasksForResync(nextConfirmation);
  if (
    canonicalImplementationTasks.length > 0 &&
    stableStringify(canonicalImplementationTasks) !==
      stableStringify(asRecordArray(nextConfirmation.implementationTasks))
  ) {
    nextConfirmation.implementationTasks = canonicalImplementationTasks;
    changed = true;
    changedViewIds.add('implementationTasks');
  }
  const atomicTaskResync = resyncExistingAtomicTaskDecomposition(nextConfirmation);
  if (atomicTaskResync.changed) {
    nextConfirmation = atomicTaskResync.confirmation;
    changed = true;
    changedViewIds.add('atomicImplementationTaskList');
    changedViewIds.add('mustExecutionDecompositionMatrix');
    changedViewIds.add('traceRows');
    changedViewIds.add('aiTddContractExecutionManifestProjection');
  }
  const preConfirmationDrilldown = recordObject(nextConfirmation.preConfirmationDrilldown);
  const criticalAuditor = recordObject(preConfirmationDrilldown.criticalAuditor);
  if (
    options.resetCriticalAuditor !== false &&
    Object.keys(criticalAuditor).length > 0 &&
    (Number(criticalAuditor.consecutiveNoNewGapRounds ?? 0) !== 0 ||
      criticalAuditor.latestReceiptHash !== null ||
      normalizeText(criticalAuditor.convergenceVerdict) !== 'audit_not_run')
  ) {
    nextConfirmation.preConfirmationDrilldown = {
      ...preConfirmationDrilldown,
      criticalAuditor: {
        ...criticalAuditor,
        consecutiveNoNewGapRounds: 0,
        latestReceiptHash: null,
        convergenceVerdict: 'audit_not_run',
      },
    };
    changed = true;
    changedViewIds.add('preConfirmationDrilldown');
  }
  const targetPathClassificationResync =
    resyncTargetModificationPathClassifications(nextConfirmation);
  let shouldForceCurrentTargetMapRebuild = context?.forceCurrentTargetMapRebuild === true;
  if (targetPathClassificationResync.changed) {
    nextConfirmation.targetModificationPaths = targetPathClassificationResync.rows;
    changed = true;
    shouldForceCurrentTargetMapRebuild = true;
    changedViewIds.add('targetModificationPaths');
  }
  const requiredCommandTargetResync = resyncExistingRequiredCommandTargetFiles(nextConfirmation);
  if (requiredCommandTargetResync.changed) {
    nextConfirmation.requiredCommands = requiredCommandTargetResync.rows;
    changed = true;
    shouldForceCurrentTargetMapRebuild = true;
    changedViewIds.add('requiredCommands');
  }
  const nextFailurePaths = asRecordArray(confirmation.failurePaths).map((row) => {
    if (asStringArray(row.requiredAssertions).length > 0) return row;
    changed = true;
    shouldForceCurrentTargetMapRebuild = true;
    changedViewIds.add('failurePaths');
    return {
      ...row,
      requiredAssertions: defaultFailurePathRequiredAssertions(row),
    };
  });
  if (nextFailurePaths.length > 0) {
    nextConfirmation.failurePaths = nextFailurePaths;
  }
  const mustRowsById = new Map(
    asRecordArray(nextConfirmation.must)
      .map((row) => [normalizeText(row.id), row] as const)
      .filter(([id]) => Boolean(id))
  );
  const knownMustIds = new Set(mustRowsById.keys());
  let semanticFailureOwnershipChanged = false;
  const semanticallyOwnedFailurePaths = asRecordArray(nextConfirmation.failurePaths).map((row) => {
    const candidateMustRefs = uniqueStrings([
      ...asStringArray(row.ownerMustRefs),
      normalizeText(row.derivedFromMustRef),
    ]).filter((ref) => knownMustIds.has(ref));
    if (candidateMustRefs.length <= 1) return row;
    const semanticOwner = uniquelyDominantSemanticMustRef({
      row,
      candidateMustRefs,
      mustRowsById,
    });
    if (!semanticOwner) return row;
    const nextRow = {
      ...row,
      ownerMustRefs: [semanticOwner],
      derivedFromMustRef: semanticOwner,
    };
    if (stableStringify(nextRow) === stableStringify(row)) return row;
    semanticFailureOwnershipChanged = true;
    return nextRow;
  });
  if (semanticFailureOwnershipChanged) {
    nextConfirmation.failurePaths = semanticallyOwnedFailurePaths;
    changed = true;
    shouldForceCurrentTargetMapRebuild = true;
    changedViewIds.add('failurePaths');
  }
  const viewRefsByTraceField: Record<string, Set<string>> = {
    sequenceViewRefs: new Set<string>(),
    flowViewRefs: new Set<string>(),
    edgeCaseViewRefs: new Set<string>(),
  };
  const businessViewIdsByTraceField: Record<string, Set<string>> = {
    sequenceViewRefs: new Set<string>(),
    flowViewRefs: new Set<string>(),
    edgeCaseViewRefs: new Set<string>(),
  };
  const notDoneRowsById = new Map(
    asRecordArray(confirmation.notDone)
      .map((row) => [normalizeText(row.id), row] as const)
      .filter(([id]) => Boolean(id))
  );
  const acceptanceRows = [
    ...asRecordArray(nextConfirmation.acceptanceTests),
    ...asRecordArray(nextConfirmation.e2eSuites),
  ];
  const failurePathRows = asRecordArray(nextConfirmation.failurePaths);
  const edgeCaseRows = asRecordArray(nextConfirmation.edgeCases);
  const knownNegIds = new Set(notDoneRowsById.keys());
  const knownRequirementIds = new Set([...mustIds, ...notDoneRowsById.keys()]);

  const proofClosureForRequirements = (requirementRefs: string[]) => {
    const requirementSet = new Set(
      uniqueStrings(requirementRefs).filter((ref) => knownRequirementIds.has(ref))
    );
    const relevantTraceRows = traceRows.filter((traceRow) =>
      asStringArray(traceRow.covers).some((ref) => requirementSet.has(ref))
    );
    const relevantTraceIds = relevantTraceRows
      .map((traceRow) => normalizeText(traceRow.id))
      .filter(Boolean);
    const relevantTraceIdSet = new Set(relevantTraceIds);
    const relevantEvidenceIds = uniqueStrings([
      ...relevantTraceRows.flatMap((traceRow) => asStringArray(traceRow.evidenceRefs)),
      ...[...requirementSet].flatMap((requirementRef) => [
        ...asStringArray(mustRowsById.get(requirementRef)?.evidenceRefs),
        ...asStringArray(notDoneRowsById.get(requirementRef)?.evidenceRefs),
      ]),
    ]).filter((ref) => evidenceIds.includes(ref));
    const relevantAcceptanceIds = uniqueStrings([
      ...relevantTraceRows.flatMap((traceRow) => asStringArray(traceRow.acceptanceRefs)),
      ...acceptanceRows
        .filter((acceptanceRow) =>
          asStringArray(acceptanceRow.covers).some((ref) => requirementSet.has(ref))
        )
        .map((acceptanceRow) => normalizeText(acceptanceRow.id)),
    ]).filter((ref) => acceptanceIds.includes(ref));
    const relevantFailurePathIds = failurePathRows
      .filter(
        (failurePath) =>
          requirementSet.has(normalizeText(failurePath.derivedFromMustRef)) ||
          asStringArray(failurePath.ownerMustRefs).some((ref) => requirementSet.has(ref)) ||
          asStringArray(failurePath.linkedNegIds).some((ref) => requirementSet.has(ref)) ||
          asStringArray(failurePath.traceRows).some((ref) => relevantTraceIdSet.has(ref))
      )
      .map((failurePath) => normalizeText(failurePath.id))
      .filter((ref) => failurePathIds.includes(ref));
    const relevantFailurePathIdSet = new Set(relevantFailurePathIds);
    const relevantEdgeCaseIds = edgeCaseRows
      .filter(
        (edgeCase) =>
          requirementSet.has(normalizeText(edgeCase.derivedFromMustRef)) ||
          asStringArray(edgeCase.ownerMustRefs).some((ref) => requirementSet.has(ref)) ||
          asStringArray(edgeCase.linkedNegIds).some((ref) => requirementSet.has(ref)) ||
          asStringArray(edgeCase.traceRows).some((ref) => relevantTraceIdSet.has(ref)) ||
          asStringArray(edgeCase.linkedFailurePathIds).some((ref) =>
            relevantFailurePathIdSet.has(ref)
          )
      )
      .map((edgeCase) => normalizeText(edgeCase.id))
      .filter((ref) => edgeCaseIds.includes(ref));
    return {
      requirementRefs: [...requirementSet],
      traceRows: relevantTraceIds,
      evidenceRefs: relevantEvidenceIds,
      acceptanceRefs: relevantAcceptanceIds,
      failurePathRefs: relevantFailurePathIds,
      edgeCaseRefs: relevantEdgeCaseIds,
    };
  };

  const mustRefsByNegId = new Map<string, string[]>();
  for (const failurePath of failurePathRows) {
    const ownerMustRefs = uniqueStrings([
      ...asStringArray(failurePath.ownerMustRefs),
      normalizeText(failurePath.derivedFromMustRef),
    ]).filter((ref) => knownMustIds.has(ref));
    if (ownerMustRefs.length === 0) continue;
    for (const negId of asStringArray(failurePath.linkedNegIds)) {
      if (!knownNegIds.has(negId)) continue;
      mustRefsByNegId.set(
        negId,
        uniqueStrings([...(mustRefsByNegId.get(negId) ?? []), ...ownerMustRefs])
      );
    }
  }
  const mustRefsForRequirementRefs = (refs: string[]): string[] =>
    uniqueStrings(
      refs.flatMap((ref) => {
        if (knownMustIds.has(ref)) return [ref];
        return mustRefsByNegId.get(ref) ?? [];
      })
    );
  const traceMustRefsById = new Map(
    traceRows
      .map(
        (row) =>
          [normalizeText(row.id), mustRefsForRequirementRefs(asStringArray(row.covers))] as const
      )
      .filter(([traceId]) => Boolean(traceId))
  );
  const projectionMustRefs = (row: Record<string, unknown>): string[] => {
    const directRefs = mustRefsForRequirementRefs(
      uniqueStrings([
        ...asStringArray(row.ownerMustRefs),
        ...asStringArray(row.requirementRefs),
        ...asStringArray(row.mustRefs),
        ...asStringArray(row.covers),
        ...asStringArray(row.linkedRequirements),
        ...asRecordArray(row.perMustRows).map((entry) => normalizeText(entry.mustRef)),
      ])
    );
    const traceRefs = uniqueStrings([
      ...asStringArray(row.traceRows),
      ...asStringArray(row.traceRefs),
    ]);
    return uniqueStrings([
      ...directRefs,
      ...traceRefs.flatMap((traceRef) => traceMustRefsById.get(traceRef) ?? []),
    ]);
  };
  for (const field of ['acceptanceTests', 'acceptanceCriteria', 'e2eSuites', 'e2eScenarios']) {
    const rows = asRecordArray(nextConfirmation[field]);
    if (rows.length === 0) continue;
    let fieldChanged = false;
    const nextRows = rows.map((row) => {
      const closure = proofClosureForRequirements(projectionMustRefs(row));
      const nextRow = {
        ...row,
        failurePathRefs: closure.failurePathRefs,
        edgeCaseRefs: closure.edgeCaseRefs,
      };
      if (stableStringify(nextRow) !== stableStringify(row)) fieldChanged = true;
      return nextRow;
    });
    if (fieldChanged) {
      nextConfirmation[field] = nextRows;
      changed = true;
      changedViewIds.add(field);
    }
  }
  const commandMustRefsByTargetPath = new Map<string, string[]>();
  for (const command of asRecordArray(nextConfirmation.requiredCommands)) {
    const commandMustRefs = projectionMustRefs(command);
    if (commandMustRefs.length === 0) continue;
    for (const targetFile of asStringArray(command.targetFiles)) {
      const normalizedTargetFile = normalizeText(targetFile).replace(/\\/g, '/');
      if (!normalizedTargetFile) continue;
      commandMustRefsByTargetPath.set(
        normalizedTargetFile,
        uniqueStrings([
          ...(commandMustRefsByTargetPath.get(normalizedTargetFile) ?? []),
          ...commandMustRefs,
        ])
      );
    }
  }
  const resolveExistingProjectionMustRef = (row: Record<string, unknown>): string => {
    const directOrTraceRef = projectionMustRefs(row)[0];
    if (directOrTraceRef) return directOrTraceRef;
    const rowPath = normalizeText(row.path).replace(/\\/g, '/');
    return rowPath ? (commandMustRefsByTargetPath.get(rowPath)?.[0] ?? '') : '';
  };
  for (const field of [
    'atomicImplementationTaskList',
    'mustExecutionDecompositionMatrix',
    'evidence',
    'traceRows',
    'acceptanceTests',
    'e2eSuites',
    'failurePaths',
    'edgeCases',
    'targetModificationPaths',
    'artifactAutomationPlan',
    'requiredCommands',
  ]) {
    const rows = asRecordArray(nextConfirmation[field]);
    if (rows.length === 0) continue;
    let fieldChanged = false;
    const nextRows = rows.map((row) => {
      const declaredRequirementRefs = uniqueStrings([
        ...repairProjectionDeclaredRequirementRefs(row),
        ...(field === 'failurePaths' ? asStringArray(row.linkedNegIds) : []),
      ]);
      const declaredMustRefs = declaredRequirementRefs.filter((ref) => knownMustIds.has(ref));
      const declaredNegRefs = declaredRequirementRefs.filter((ref) => knownNegIds.has(ref));
      if (declaredMustRefs.length === 0 && declaredNegRefs.length > 0) {
        const ownerMustRefs = uniqueStrings(
          declaredNegRefs.flatMap((negRef) => mustRefsByNegId.get(negRef) ?? [])
        );
        const nextRow = { ...row };
        let rowChanged = false;
        if (
          declaredNegRefs.length === 1 &&
          normalizeText(row.derivedFromRequirementRef) !== declaredNegRefs[0]
        ) {
          nextRow.derivedFromRequirementRef = declaredNegRefs[0];
          rowChanged = true;
        }
        if (ownerMustRefs.length === 1) {
          if (normalizeText(row.derivedFromMustRef) !== ownerMustRefs[0]) {
            nextRow.derivedFromMustRef = ownerMustRefs[0];
            rowChanged = true;
          }
        } else {
          if (row.derivedFromMustRef !== undefined) {
            delete nextRow.derivedFromMustRef;
            rowChanged = true;
          }
        }
        if (!rowChanged) return row;
        fieldChanged = true;
        return nextRow;
      }
      if (declaredRequirementRefs.length > 0 && declaredMustRefs.length === 0) {
        return row;
      }
      if (
        field === 'failurePaths' &&
        asStringArray(row.ownerMustRefs).length === 0 &&
        !knownMustIds.has(normalizeText(row.derivedFromMustRef))
      ) {
        return row;
      }
      if (knownMustIds.has(normalizeText(row.derivedFromMustRef))) return row;
      const derivedFromMustRef = resolveExistingProjectionMustRef(row);
      if (!derivedFromMustRef) return row;
      fieldChanged = true;
      return {
        ...row,
        derivedFromMustRef,
        projectionStatus: 'synchronized',
      };
    });
    if (fieldChanged) {
      nextConfirmation[field] = nextRows;
      changed = true;
      changedViewIds.add(field);
    }
  }

  const syncViewRows = (field: string, traceRefField: string): void => {
    const rows = asRecordArray(confirmation[field]);
    if (!rows.length) return;
    const nextRows = rows.map((row) => {
      const viewId = normalizeText(row.id);
      const scope = normalizeText(row.scope).toLowerCase();
      const visualKind = normalizeVisualKindForProofClosure(row.visualKind);
      if (!viewId || scope !== 'business' || !visualKind) return row;
      const nextRow: Record<string, unknown> = { ...row };
      const before = stableStringify(nextRow);
      const requirementRefs = uniqueStrings([
        ...asStringArray(nextRow.covers),
        ...asRecordArray(nextRow.perMustRows).map((entry) => normalizeText(entry.mustRef)),
      ]);
      const closure = proofClosureForRequirements(requirementRefs);
      nextRow.traceRows = closure.traceRows;
      nextRow.evidenceRefs = closure.evidenceRefs;
      nextRow.acceptanceRefs = closure.acceptanceRefs;
      const businessEdgePattern =
        /^\s*(?:[A-Za-z0-9_()[\]\s-]+(?:->>|-->>|->|-->|-\)|-\]|\)|\])|[A-Za-z0-9_()[\]\s-]+--[A-Za-z0-9_()[\]\s-]+:|[A-Za-z0-9_()[\]\s-]+-->|[A-Za-z0-9_()[\]\s-]+:)\s*(.+)$/u;
      const requirementIdPattern = /\b(?:MUST|NEG|OUT)-[A-Za-z0-9_.:-]+\b/u;
      const mermaidRequirementRefs = closure.requirementRefs.filter((ref) =>
        knownRequirementIds.has(ref)
      );
      if (normalizeText(nextRow.mermaid) && mermaidRequirementRefs.length > 0) {
        const requirementSuffix = mermaidRequirementRefs.map((ref) => `[${ref}]`).join('');
        nextRow.mermaid = String(nextRow.mermaid)
          .split(/\r?\n/u)
          .map((line) => {
            const trimmed = line.trim();
            if (!businessEdgePattern.test(trimmed) || requirementIdPattern.test(trimmed)) {
              return line;
            }
            return `${line} ${requirementSuffix}`;
          })
          .join('\n');
      }
      const existingPerMustRows = asRecordArray(nextRow.perMustRows);
      const existingPerMustRowsById = new Map(
        existingPerMustRows
          .map((entry) => [normalizeText(entry.mustRef), entry] as const)
          .filter(([mustRef]) => Boolean(mustRef))
      );
      nextRow.perMustRows = closure.requirementRefs
        .filter((requirementRef) => knownMustIds.has(requirementRef))
        .map((mustRef) => {
          const mustClosure = proofClosureForRequirements([mustRef]);
          const existing = existingPerMustRowsById.get(mustRef) ?? {};
          return {
            ...existing,
            mustRef,
            traceRows: mustClosure.traceRows,
            evidenceRefs: mustClosure.evidenceRefs,
            acceptanceRefs: mustClosure.acceptanceRefs,
            failurePathRefs: mustClosure.failurePathRefs,
            edgeCaseRefs: mustClosure.edgeCaseRefs,
            assertion:
              normalizeText(existing.assertion) ||
              `${mustRef} remains independently visible through the business visual proof chain.`,
          };
        });
      if (visualKind === 'failure') {
        nextRow.failurePathRefs = closure.failurePathRefs;
      }
      if (visualKind === 'edge') {
        nextRow.edgeCaseRefs = closure.edgeCaseRefs;
      }
      if (stableStringify(nextRow) !== before) {
        changed = true;
        changedViewIds.add(viewId);
      }
      businessViewIdsByTraceField[traceRefField].add(viewId);
      for (const traceId of closure.traceRows) {
        viewRefsByTraceField[traceRefField].add(`${traceId}\u0000${viewId}`);
      }
      return nextRow;
    });
    nextConfirmation[field] = nextRows;
  };

  syncViewRows('sequenceViews', 'sequenceViewRefs');
  syncViewRows('flowViews', 'flowViewRefs');
  syncViewRows('edgeCaseViews', 'edgeCaseViewRefs');

  if (
    context &&
    (shouldForceCurrentTargetMapRebuild ||
      shouldRebuildExistingCurrentTargetMap(nextConfirmation.currentTargetMap, context.sourceText))
  ) {
    const before = stableStringify({
      currentTargetMap: nextConfirmation.currentTargetMap,
      aiTddContractExecutionManifestProjection:
        nextConfirmation.aiTddContractExecutionManifestProjection,
    });
    const rebuiltCurrentTargetMap = buildCurrentTargetMapFromExistingConfirmation({
      root: context.root,
      sourcePath: context.sourcePath,
      sourceText: context.sourceText,
      packetHash: context.packetHash,
      confirmation: nextConfirmation,
      traceIds,
      evidenceIds,
      mustIds,
    });
    nextConfirmation.currentTargetMap = rebuiltCurrentTargetMap.map;
    const manifest = recordObject(nextConfirmation.aiTddContractExecutionManifestProjection);
    if (Object.keys(manifest).length > 0) {
      nextConfirmation.aiTddContractExecutionManifestProjection = {
        ...manifest,
        currentTargetMap: { rows: rebuiltCurrentTargetMap.diffRowIds },
        canonicalSurfaces: rebuiltCurrentTargetMap.canonicalArtifactIds,
        canonicalSurfaceReconciliation: {
          ...recordObject(manifest.canonicalSurfaceReconciliation),
          canonicalArtifacts: rebuiltCurrentTargetMap.canonicalArtifactIds,
          traceRows: appendUniqueStrings(
            recordObject(manifest.canonicalSurfaceReconciliation).traceRows,
            traceIds
          ),
          evidenceRefs: appendUniqueStrings(
            recordObject(manifest.canonicalSurfaceReconciliation).evidenceRefs,
            evidenceIds
          ),
        },
        legacyDenial: rebuiltCurrentTargetMap.legacyArtifactIds,
      };
    }
    const after = stableStringify({
      currentTargetMap: nextConfirmation.currentTargetMap,
      aiTddContractExecutionManifestProjection:
        nextConfirmation.aiTddContractExecutionManifestProjection,
    });
    if (after !== before) {
      changed = true;
      changedViewIds.add('currentTargetMap');
    }
  }

  const nextTraceRows = asRecordArray(nextConfirmation.traceRows).map((row) => {
    const traceId = normalizeText(row.id);
    if (!traceId || !traceIds.includes(traceId)) return row;
    const nextRow: Record<string, unknown> = { ...row };
    const before = stableStringify(nextRow);
    for (const [field, refs] of Object.entries(viewRefsByTraceField)) {
      const businessViewIds = businessViewIdsByTraceField[field];
      const preservedRefs = asStringArray(nextRow[field]).filter(
        (ref) => !businessViewIds.has(ref)
      );
      const exactRefs = [...refs]
        .filter((entry) => entry.startsWith(`${traceId}\u0000`))
        .map((entry) => entry.slice(traceId.length + 1));
      nextRow[field] = uniqueStrings([...preservedRefs, ...exactRefs]);
    }
    return stableStringify(nextRow) !== before ? ((changed = true), nextRow) : row;
  });
  nextConfirmation.traceRows = nextTraceRows;

  return { confirmation: nextConfirmation, changed, changedViewIds: [...changedViewIds].sort() };
}

function buildControlledAuthoringReconfirmationRequest(input: {
  previousConfirmation: Record<string, unknown>;
  nextConfirmation: Record<string, unknown>;
  appliedActions: Record<string, unknown>[];
  changedTargetFields: Set<string>;
}): {
  request: Record<string, unknown> | null;
  issue: PreConfirmationDrilldownIssue | null;
} {
  const previousStatus = normalizeText(input.previousConfirmation.status);
  const previouslyConfirmed =
    previousStatus === 'user_confirmed' ||
    previousStatus === 'reconfirm_required' ||
    Boolean(normalizeText(input.previousConfirmation.confirmedAt)) ||
    Boolean(normalizeText(input.previousConfirmation.confirmedBy));
  if (!previouslyConfirmed) {
    return { request: null, issue: null };
  }

  const impactedIds = uniqueStrings(
    input.appliedActions.flatMap((action) => [
      ...asStringArray(action.requirementIds),
      ...asStringArray(action.mustRefs),
      normalizeText(action.materializedRef),
    ])
  ).filter((ref) => /^(?:MUST|NEG|OUT|EVD|TRACE|ACC|E2E|FAIL|EDGE)-/u.test(ref));
  const impactedRequirementIds = impactedIds.filter((ref) => /^(?:MUST|NEG|OUT)-/u.test(ref));
  const impactedTraceRows = uniqueStrings([
    ...impactedIds.filter((ref) => ref.startsWith('TRACE-')),
    ...asRecordArray(input.nextConfirmation.traceRows)
      .filter((row) =>
        asStringArray(row.covers).some((ref) => impactedRequirementIds.includes(ref))
      )
      .map((row) => normalizeText(row.id)),
  ]);
  const proofRefs = uniqueStrings([
    ...impactedIds.filter((ref) => /^(?:EVD|TRACE|ACC|E2E)-/u.test(ref)),
    ...asRecordArray(input.nextConfirmation.traceRows)
      .filter((row) => impactedTraceRows.includes(normalizeText(row.id)))
      .flatMap((row) => [
        normalizeText(row.id),
        ...asStringArray(row.evidenceRefs),
        ...asStringArray(row.acceptanceRefs),
        ...asStringArray(row.contractValidationCommandRefs),
        ...asStringArray(row.deliveryEvidenceCommandRefs),
      ]),
  ]);
  const sourceRefs =
    impactedRequirementIds.length > 0
      ? impactedRequirementIds
      : impactedIds.filter(Boolean).slice(0, 8);
  if (sourceRefs.length === 0) {
    return {
      request: null,
      issue: sourceMaterializationGateIssue(
        'controlled_authoring_reconfirmation_source_refs_missing',
        'Confirmed-scope authoring repair requires authoritative source requirement references before reconfirmation evidence can be materialized.',
        input.appliedActions
          .flatMap((action) => [
            normalizeText(action.actionId),
            ...asStringArray(action.requirementIds),
            ...asStringArray(action.mustRefs),
            normalizeText(action.materializedRef),
          ])
          .filter(Boolean)
      ),
    };
  }
  const actionIds = input.appliedActions
    .map((action) => normalizeText(action.actionId))
    .filter(Boolean);
  const changedFields = [...input.changedTargetFields].sort();

  return {
    request: {
      required: true,
      reasonCode: 'controlled_authoring_repair_changed_confirmed_scope',
      reason: 'implementationConfirmationHash_changed',
      userFacingTitle: '需要重新确认受控需求修复',
      userFacingSummary:
        'Critical Auditor 已将确认后的语义缺口修复到需求源文档；修复后的范围、失败路径和验证闭环必须由用户重新确认。',
      persuasiveRationale: {
        whyReconfirmNow: '当前实现确认语义已不同于上次确认版本，历史确认不能授权修复后的需求范围。',
        riskIfSkipped:
          '若跳过重新确认，实施链可能把用户未确认的失败路径、验收绑定或范围修复误当作既有授权。',
        whyEvidenceIsSufficient:
          '受控修复动作、受影响需求 ID、TRACE/EVD/ACC/E2E 证明引用和重新执行的预渲染门禁共同界定了本次变化。',
      },
      evidenceBundle: {
        sufficiencyVerdict: 'sufficient',
        items: [
          {
            kind: 'controlled_authoring_repair',
            title: 'Critical Auditor 受控语义修复',
            summary: `已执行 ${actionIds.length} 个受控修复动作，并同步 ${changedFields.length} 个确认投影视图。`,
            sourceRefs,
            proofRefs,
          },
        ],
      },
      previousSourceDocumentHash:
        normalizeText(input.previousConfirmation.sourceDocumentHash) || null,
      previousImplementationConfirmationHash:
        normalizeText(input.previousConfirmation.implementationConfirmationHash) || null,
      diffSummary: [
        {
          summary: `Critical Auditor 修复动作：${actionIds.join(', ') || 'controlled semantic repair'}。`,
        },
        {
          summary: `同步确认投影：${changedFields.join(', ') || 'implementationConfirmation'}。`,
        },
      ],
      affectedRequirementIds: impactedRequirementIds,
      affectedTraceRows: impactedTraceRows,
      impactedIds,
      impactedTraceRows,
      impactedArtifacts: ['sourceGapFixes', 'must_decomposition_packet.json'],
      impactedGatesOrCommands: ['pre_render_must_decomposition_gate'],
      allowedUserActions: [
        'confirm_current_version',
        'reject_current_changes_restore_last_confirmed',
        'accept_partial_changes_create_followup',
        'regenerate_confirmation_view',
      ],
    },
    issue: null,
  };
}

function packetWithCriticalAuditorConvergence(
  packet: Record<string, unknown>,
  consecutiveNoNewGapRounds: number
): Record<string, unknown> {
  const criticDisposition =
    consecutiveNoNewGapRounds >= 3
      ? 'accepted_no_new_valid_gap'
      : 'pending_critical_auditor_response';
  return {
    ...packet,
    consecutiveNoNewValidGapRounds: consecutiveNoNewGapRounds,
    authorClaims: asRecordArray(packet.authorClaims).map((claim) => ({
      ...claim,
      criticDisposition,
    })),
    mustPackets: asRecordArray(packet.mustPackets).map((mustPacket) => ({
      ...mustPacket,
      authorClaims: asRecordArray(mustPacket.authorClaims).map((claim) => ({
        ...claim,
        criticDisposition,
      })),
    })),
  };
}

function projectionBackRefForRepair(packetHash: string, mustRef: string): Record<string, unknown> {
  return {
    derivedFromMustRef: mustRef,
    derivedFromPacketHash: packetHash,
    projectionStatus: 'synchronized',
  };
}

function sourceRowsForRepairProjection(
  confirmation: Record<string, unknown>,
  key: string
): Record<string, unknown>[] {
  if (key === 'atomicImplementationTaskList' && !Array.isArray(confirmation[key])) {
    return asRecordArray(confirmation.implementationTasks).map((row) => {
      const task = recordObject(row);
      const requirementRefs = asStringArray(task.requirementRefs);
      return {
        ...task,
        derivedFromMustRef: requirementRefs.length === 1 ? requirementRefs[0] : undefined,
        targetFiles: asStringArray(task.targetPaths),
        traceRows: asStringArray(task.traceRefs),
        evidenceRefs: asStringArray(task.evidenceRefs),
        text: normalizeText(task.title) || normalizeText(task.text),
      };
    });
  }
  if (key === 'currentTargetMap') {
    const currentTargetMap = recordObject(confirmation.currentTargetMap);
    return [
      ...asRecordArray(currentTargetMap.currentSummary),
      ...asRecordArray(currentTargetMap.targetSummary),
      ...asRecordArray(currentTargetMap.diffRows),
      ...asRecordArray(currentTargetMap.process),
      ...asRecordArray(currentTargetMap.artifactPaths),
      ...asRecordArray(currentTargetMap.canonicalArtifacts),
      ...asRecordArray(currentTargetMap.existingArtifacts),
    ];
  }
  if (key === 'aiTddContractExecutionManifestProjection') {
    const manifest = recordObject(confirmation.aiTddContractExecutionManifestProjection);
    return Object.keys(manifest).length
      ? [{ id: normalizeText(manifest.id) || 'AI-TDD-001', ...manifest }]
      : [];
  }
  if (key === 'closeoutReadinessPreview') {
    const closeout = recordObject(confirmation.closeoutReadinessPreview);
    return Object.keys(closeout).length ? [{ id: 'closeoutReadinessPreview', ...closeout }] : [];
  }
  return asRecordArray(confirmation[key]);
}

function rowIdForRepair(row: Record<string, unknown>, fallback: string): string {
  return normalizeText(
    row.id ?? row.taskId ?? row.commandId ?? row.artifactId ?? row.path ?? fallback
  );
}

function selectExistingRowIds(
  confirmation: Record<string, unknown>,
  keys: string[],
  fallbackIds: string[]
): string[] {
  const ids = keys
    .flatMap((key) => sourceRowsForRepairProjection(confirmation, key))
    .map((row, index) => rowIdForRepair(row, String(index)))
    .filter(Boolean);
  return ids.length > 0 ? ids : fallbackIds;
}

function repairProjectionMustRefsFromValue(value: unknown, depth = 0): string[] {
  if (depth > 4 || value === null || value === undefined) return [];
  if (typeof value === 'string') {
    const normalized = normalizeText(value);
    return normalized.startsWith('MUST-') ? [normalized] : [];
  }
  if (Array.isArray(value)) {
    return uniqueStrings(
      value.flatMap((item) => repairProjectionMustRefsFromValue(item, depth + 1))
    );
  }
  if (typeof value !== 'object') return [];
  const row = value as Record<string, unknown>;
  return uniqueStrings([
    ...Object.keys(row).filter((key) => key.startsWith('MUST-')),
    ...[
      'derivedFromMustRef',
      'mustRef',
      'mustId',
      'requirementRef',
      'requirementId',
      'covers',
      'ownerMustRefs',
      'requirementRefs',
      'mustRefs',
    ].flatMap((key) => repairProjectionMustRefsFromValue(row[key], depth + 1)),
  ]);
}

function repairProjectionMustRefs(row: Record<string, unknown>): string[] {
  return uniqueStrings([
    ...repairProjectionMustRefsFromValue(row.derivedFromMustRef),
    ...repairProjectionMustRefsFromValue(row.mustRef),
    ...repairProjectionMustRefsFromValue(row.mustId),
    ...repairProjectionMustRefsFromValue(row.requirementRef),
    ...repairProjectionMustRefsFromValue(row.requirementId),
    ...repairProjectionMustRefsFromValue(row.covers),
    ...repairProjectionMustRefsFromValue(row.ownerMustRefs),
    ...repairProjectionMustRefsFromValue(row.requirementRefs),
    ...repairProjectionMustRefsFromValue(row.mustRefs),
    ...[
      'perMustRows',
      'perMustAssertions',
      'perMustOracles',
      'perMustResponsibilities',
      'responsibilityMapping',
    ].flatMap((key) => repairProjectionMustRefsFromValue(row[key])),
  ]).filter((ref) => ref.startsWith('MUST-'));
}

function repairProjectionSpecificMustRefs(row: Record<string, unknown>): string[] {
  const singularArrayRefs = ['covers', 'requirementRefs', 'mustRefs'].flatMap((key) => {
    const refs = repairProjectionMustRefsFromValue(row[key]);
    return refs.length === 1 ? refs : [];
  });
  return uniqueStrings([
    ...repairProjectionMustRefsFromValue(row.derivedFromMustRef),
    ...repairProjectionMustRefsFromValue(row.mustRef),
    ...repairProjectionMustRefsFromValue(row.mustId),
    ...repairProjectionMustRefsFromValue(row.requirementRef),
    ...repairProjectionMustRefsFromValue(row.requirementId),
    ...singularArrayRefs,
    ...[
      'perMustRows',
      'perMustAssertions',
      'perMustOracles',
      'perMustResponsibilities',
      'responsibilityMapping',
    ].flatMap((key) => repairProjectionMustRefsFromValue(row[key])),
  ]).filter((ref) => ref.startsWith('MUST-'));
}

function repairProjectionDeclaredRequirementRefs(row: Record<string, unknown>): string[] {
  return uniqueStrings([
    normalizeText(row.derivedFromRequirementRef),
    ...asStringArray(row.ownerMustRefs),
    ...asStringArray(row.requirementRefs),
    ...asStringArray(row.mustRefs),
    ...asStringArray(row.covers),
    ...asStringArray(row.linkedRequirements),
  ]).filter((ref) => ref.startsWith('MUST-') || ref.startsWith('NEG-') || ref.startsWith('OUT-'));
}

function repairProjectionRowsForMust(
  rows: Record<string, unknown>[],
  mustRef: string,
  linkedRefs: Set<string>[] = []
): Record<string, unknown>[] {
  return rows.filter((row) => {
    const declaredRequirementRefs = repairProjectionDeclaredRequirementRefs(row);
    const declaredMustRefs = declaredRequirementRefs.filter((ref) => ref.startsWith('MUST-'));
    if (declaredRequirementRefs.length > 0 && declaredMustRefs.length === 0) return false;
    const explicitMustRefs = repairProjectionMustRefs(row);
    if (explicitMustRefs.includes(mustRef)) return true;
    if (explicitMustRefs.length > 0) return false;
    const rowLinks = [
      ...asStringArray(row.traceRows),
      ...asStringArray(row.traceRefs),
      ...asStringArray(row.evidenceRefs),
      ...asStringArray(row.linkedEvidenceIds),
      ...asStringArray(row.acceptanceRefs),
      ...asStringArray(row.failurePathRefs),
      ...asStringArray(row.linkedFailurePathIds),
    ];
    return linkedRefs.some((refs) => rowLinks.some((ref) => refs.has(ref)));
  });
}

function buildPreserveExistingMustDecompositionPacket(input: {
  root: string;
  sourcePath: string;
  paths: PreConfirmationPaths;
  recordId: string;
  sourceDocumentHash: string;
  semanticModelHash: string;
  implementationConfirmationHash: string;
  semanticKernelHash: string;
  packetHash: string;
  createdAt: string;
  mustRequirements: SourceMustRequirement[];
  confirmation: Record<string, unknown>;
  consecutiveNoNewGapRounds: number;
}): Record<string, unknown> {
  const rel = (filePath: string) => toRootRelativePath(input.root, filePath);
  const mustRefs = input.mustRequirements.map((requirement) => requirement.id);
  const mustTexts = input.mustRequirements.map((requirement) => requirement.text);
  const existingTaskRows = sourceRowsForRepairProjection(
    input.confirmation,
    'atomicImplementationTaskList'
  );
  const existingMatrixRows = sourceRowsForRepairProjection(
    input.confirmation,
    'mustExecutionDecompositionMatrix'
  );
  const evidenceRows = sourceRowsForRepairProjection(input.confirmation, 'evidence');
  const traceRows = sourceRowsForRepairProjection(input.confirmation, 'traceRows');
  const acceptanceRows = sourceRowsForRepairProjection(input.confirmation, 'acceptanceTests');
  const e2eRows = sourceRowsForRepairProjection(input.confirmation, 'e2eSuites');
  const failureRows = sourceRowsForRepairProjection(input.confirmation, 'failurePaths');
  const edgeRows = sourceRowsForRepairProjection(input.confirmation, 'edgeCases');
  const targetRows = sourceRowsForRepairProjection(input.confirmation, 'targetModificationPaths');
  const artifactRows = sourceRowsForRepairProjection(input.confirmation, 'artifactAutomationPlan');
  const commandRows = sourceRowsForRepairProjection(input.confirmation, 'requiredCommands');
  const currentTargetRows = sourceRowsForRepairProjection(input.confirmation, 'currentTargetMap');
  const aiTddRows = sourceRowsForRepairProjection(
    input.confirmation,
    'aiTddContractExecutionManifestProjection'
  );
  const closeoutRows = sourceRowsForRepairProjection(
    input.confirmation,
    'closeoutReadinessPreview'
  );
  const projection = (id: string, target: string, mustRef: string) => ({
    id,
    mustRef,
    materializedTo: [target],
    ...projectionBackRefForRepair(input.packetHash, mustRef),
  });
  const payload: Record<string, unknown> = {
    schemaVersion: 'must-decomposition-packet/v1',
    recordId: input.recordId,
    sourceDocument: rel(input.sourcePath),
    sourceDocumentHash: input.sourceDocumentHash,
    semanticModelHash: input.semanticModelHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    semanticKernelHash: input.semanticKernelHash,
    packetHash: input.packetHash,
    status: 'synchronized',
    generatedBy:
      'main_agent_orchestration.requirement_confirmation.authoring_repair.preserve_existing',
    createdBy:
      'main_agent_orchestration.requirement_confirmation.authoring_repair.preserve_existing',
    createdAt: input.createdAt,
    inputRefs: [rel(input.sourcePath), rel(input.paths.semanticKernel)],
    materializationTarget: 'implementationConfirmation',
    lifecycle: {
      currentMentalModel: 'requirement_confirmation',
      lane: 'authoring_repair',
      mode: 'preserve-existing',
      atomicDecompositionLoopEnteredBeforeMaterialization: true,
      materializationStartedAfterAtomicLoop: false,
      singlePassBypassPrevented: true,
      materializedAfterStatus: 'synchronized',
      controlledIngestRequiredBeforeMentalModelProgression: true,
    },
    consecutiveNoNewValidGapRounds: input.consecutiveNoNewGapRounds,
    mustRefs,
    sourceRequirementTexts: mustTexts,
    topLevelProjectionInventory: projectionInventoryFromConfirmation(input.confirmation),
    authorClaims: [
      {
        id: 'CLAIM-PRESERVE-EXISTING',
        claim:
          'Preserve-existing authoring repair synchronizes artifacts without replacing the rich source contract.',
        criticDisposition:
          input.consecutiveNoNewGapRounds >= 3
            ? 'accepted_no_new_valid_gap'
            : 'pending_critical_auditor_response',
      },
    ],
    mustPackets: input.mustRequirements.map((requirement, index) => {
      const sourceTaskRows = repairProjectionRowsForMust(existingTaskRows, requirement.id);
      const fallbackTaskId = atomicTaskIdsForMust(index, input.mustRequirements.length)[0];
      const taskRows =
        sourceTaskRows.length > 0
          ? sourceTaskRows.map((row) => ({ ...row }))
          : input.mustRequirements.length === 1
            ? [
                {
                  id: fallbackTaskId,
                  targetFiles: [
                    rel(input.paths.semanticKernel),
                    rel(input.paths.mustDecompositionPacket),
                    rel(input.paths.preRenderMustGate),
                  ],
                  redProofPlan: `Repair blocks if ${requirement.id} lacks synchronized authoring artifacts.`,
                  primaryObservableBehaviors: [
                    `${requirement.id} authoring repair artifact synchronization`,
                  ],
                  primaryAcceptanceOracles: [
                    `${requirement.id} appears in semantic kernel and packet`,
                  ],
                },
              ]
            : [];
      const taskIds = taskRows
        .map((row, taskIndex) => rowIdForRepair(row, `${fallbackTaskId}-${taskIndex + 1}`))
        .filter(Boolean);
      const taskIdSet = new Set(taskIds);
      const sourceMatrixRows = repairProjectionRowsForMust(existingMatrixRows, requirement.id);
      const matrixRows =
        sourceMatrixRows.length > 0
          ? sourceMatrixRows
          : input.mustRequirements.length === 1
            ? [
                {
                  id: mdmIdForMust(index, input.mustRequirements.length),
                  mustRef: requirement.id,
                  atomicTaskRefs: taskIds,
                },
              ]
            : [];
      const mustEvidenceRows = repairProjectionRowsForMust(evidenceRows, requirement.id);
      const evidenceIdSet = new Set(
        mustEvidenceRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex)))
      );
      const mustTraceRows = repairProjectionRowsForMust(traceRows, requirement.id, [evidenceIdSet]);
      const traceIdSet = new Set(
        mustTraceRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex)))
      );
      const mustAcceptanceRows = repairProjectionRowsForMust(acceptanceRows, requirement.id, [
        traceIdSet,
        evidenceIdSet,
      ]);
      const acceptanceIdSet = new Set(
        mustAcceptanceRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex)))
      );
      const mustE2eRows = repairProjectionRowsForMust(e2eRows, requirement.id, [
        traceIdSet,
        evidenceIdSet,
      ]);
      const e2eIdSet = new Set(
        mustE2eRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex)))
      );
      const mustFailureRows = repairProjectionRowsForMust(failureRows, requirement.id, [
        traceIdSet,
        evidenceIdSet,
      ]);
      const failureIdSet = new Set(
        mustFailureRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex)))
      );
      const mustEdgeRows = repairProjectionRowsForMust(edgeRows, requirement.id, [
        traceIdSet,
        evidenceIdSet,
        failureIdSet,
      ]);
      const baseTargetRows = repairProjectionRowsForMust(targetRows, requirement.id, [
        traceIdSet,
        evidenceIdSet,
      ]);
      const baseTargetPaths = new Set(
        baseTargetRows.map((row) => normalizeText(row.path).replace(/\\/g, '/')).filter(Boolean)
      );
      const commandBelongsToMust = (row: Record<string, unknown>): boolean => {
        const declaredRequirementRefs = repairProjectionDeclaredRequirementRefs(row);
        const declaredMustRefs = declaredRequirementRefs.filter((ref) => ref.startsWith('MUST-'));
        if (declaredRequirementRefs.length > 0 && declaredMustRefs.length === 0) {
          return false;
        }
        const explicitMustRefs = repairProjectionMustRefs(row);
        if (explicitMustRefs.length > 0) {
          return explicitMustRefs.includes(requirement.id);
        }
        return (
          asStringArray(row.traceRows).some((ref) => traceIdSet.has(ref)) ||
          asStringArray(row.traceRefs).some((ref) => traceIdSet.has(ref)) ||
          asStringArray(row.evidenceRefs).some((ref) => evidenceIdSet.has(ref)) ||
          asStringArray(row.targetFiles)
            .map((targetPath) => targetPath.replace(/\\/g, '/'))
            .some((targetPath) => baseTargetPaths.has(targetPath))
        );
      };
      const mustCommandRows = commandRows.filter(commandBelongsToMust);
      const commandTargetPaths = new Set(
        mustCommandRows
          .flatMap((row) => asStringArray(row.targetFiles))
          .map((targetPath) => targetPath.replace(/\\/g, '/'))
      );
      const mustTargetRows = targetRows.filter((row) => {
        if (baseTargetRows.includes(row)) return true;
        if (repairProjectionMustRefs(row).length > 0) return false;
        return commandTargetPaths.has(normalizeText(row.path).replace(/\\/g, '/'));
      });
      const mustArtifactRows = repairProjectionRowsForMust(artifactRows, requirement.id, [
        traceIdSet,
        evidenceIdSet,
      ]);
      const specificCurrentTargetRows = currentTargetRows.filter((row) =>
        repairProjectionSpecificMustRefs(row).includes(requirement.id)
      );
      const mustCurrentTargetRows =
        specificCurrentTargetRows.length > 0
          ? specificCurrentTargetRows
          : repairProjectionRowsForMust(currentTargetRows, requirement.id, [
              traceIdSet,
              evidenceIdSet,
            ]);
      const mustAiTddRows = aiTddRows;
      const mustCloseoutRows = closeoutRows;
      const observableBehaviors = uniqueStrings(
        taskRows.flatMap((row) => [
          ...asStringArray(row.primaryObservableBehaviors),
          normalizeText(row.text),
        ])
      );
      const acceptanceOracles = uniqueStrings(
        taskRows.flatMap((row) => [
          ...asStringArray(row.primaryAcceptanceOracles),
          normalizeText(row.redProofPlan),
        ])
      );
      const targetSurfaces = uniqueStrings(
        taskRows.flatMap((row) => asStringArray(row.targetFiles))
      );
      const declaredTaskRefs = uniqueStrings(
        matrixRows.flatMap((row) => asStringArray(row.atomicTaskRefs))
      ).filter((taskRef) => taskIdSet.has(taskRef));
      const expectedTaskCount = declaredTaskRefs.length || taskIds.length;
      const questionEvidenceRefs = [...evidenceIdSet];
      const requiredQuestionCategories = [
        'scope_boundary',
        'atomicity',
        'projection',
        'confirmation_surface',
        'mental_model_progression',
      ];
      const questionAnswerAvailability: Record<string, boolean> = {
        scope_boundary: Boolean(requirement.text),
        atomicity: taskIds.length > 0 && matrixRows.length > 0,
        projection:
          mustEvidenceRows.length > 0 &&
          mustTraceRows.length > 0 &&
          mustAcceptanceRows.length + mustE2eRows.length > 0,
        confirmation_surface: mustCurrentTargetRows.length > 0 && mustAiTddRows.length > 0,
        mental_model_progression: mustCloseoutRows.length > 0,
      };
      const questionAnswers = [
        {
          id: `Q-${requirementOrdinal(index)}-SCOPE`,
          category: 'scope_boundary',
          question: `Which controlled source boundary prevents ${requirement.id} from expanding beyond its authored behavior?`,
          answer: `${requirement.id} is limited to its source requirement text and explicitly linked failure or negative boundaries; unrelated rows are not proof.`,
          evidenceRefs: questionEvidenceRefs,
          sourceRefs: uniqueStrings([requirement.id, ...failureIdSet]),
        },
        {
          id: `Q-${requirementOrdinal(index)}-ATOMICITY`,
          category: 'atomicity',
          question: `Which independently confirmable behavior-surface-oracle units decompose ${requirement.id}?`,
          answer:
            taskRows.length > 0
              ? taskRows
                  .map(
                    (row, taskIndex) =>
                      `${taskIds[taskIndex]}: ${asStringArray(row.primaryObservableBehaviors)[0] || normalizeText(row.text)}`
                  )
                  .join(' | ')
              : 'No source-owned atomic task is bound.',
          evidenceRefs: questionEvidenceRefs,
          sourceRefs: taskIds,
        },
        {
          id: `Q-${requirementOrdinal(index)}-PROJECTION`,
          category: 'projection',
          question: `Which source rows prove ${requirement.id} without relabeling unrelated rows?`,
          answer: uniqueStrings([
            ...evidenceIdSet,
            ...traceIdSet,
            ...acceptanceIdSet,
            ...e2eIdSet,
            ...failureIdSet,
          ]).join(', '),
          evidenceRefs: questionEvidenceRefs,
          sourceRefs: uniqueStrings([
            ...traceIdSet,
            ...acceptanceIdSet,
            ...e2eIdSet,
            ...failureIdSet,
          ]),
        },
        {
          id: `Q-${requirementOrdinal(index)}-TARGETS`,
          category: 'confirmation_surface',
          question: `Which source-authorized targets and commands implement and verify ${requirement.id}?`,
          answer: uniqueStrings([
            ...mustTargetRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex))),
            ...mustCommandRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex))),
          ]).join(', '),
          evidenceRefs: questionEvidenceRefs,
          sourceRefs: targetSurfaces,
        },
        {
          id: `Q-${requirementOrdinal(index)}-PROGRESSION`,
          category: 'mental_model_progression',
          question: `Which current-target and closeout rows keep ${requirement.id} in requirement confirmation until controlled implementation evidence exists?`,
          answer: uniqueStrings([
            ...mustCurrentTargetRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex))),
            ...mustCloseoutRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex))),
          ]).join(', '),
          evidenceRefs: questionEvidenceRefs,
          sourceRefs: uniqueStrings([
            ...mustCurrentTargetRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex))),
            ...mustCloseoutRows.map((row, rowIndex) => rowIdForRepair(row, String(rowIndex))),
          ]),
        },
      ].filter((row) => questionAnswerAvailability[row.category]);
      const answeredCategories = uniqueStrings(questionAnswers.map((row) => row.category));
      const missingCategories = requiredQuestionCategories.filter(
        (category) => !answeredCategories.includes(category)
      );
      return {
        mustRef: requirement.id,
        mustIntent: requirement.text,
        sourceRequirementText: requirement.text,
        sourceRequirementLine: requirement.sourceLine,
        sourceRequirementAuthority: requirement.source,
        sourceLine: requirement.sourceLine,
        sourcePath: requirement.sourcePath,
        sourceDocumentHash: requirement.sourceDocumentHash,
        sourceSpan: requirement.sourceSpan,
        headingPath: requirement.headingPath,
        candidateId: requirement.candidateId,
        decompositionBasis: {
          observableBehaviors:
            observableBehaviors.length > 0 ? observableBehaviors : [requirement.text],
          targetSurfaces,
        },
        atomicityDrivers: {
          behaviorSurfaceOracleUnits:
            acceptanceOracles.length > 0 ? acceptanceOracles : observableBehaviors,
          oneTaskPerIndependentBehaviorSurfaceOracle: true,
        },
        questionCoverage: {
          requiredCategories: requiredQuestionCategories,
          answeredCategories,
          missingCategories,
          coverageVerdict: missingCategories.length === 0 ? 'complete' : 'incomplete',
          questions: questionAnswers.map(
            (row) => `${row.question} ${row.answer || 'No source-derived answer.'}`
          ),
          answers: questionAnswers,
        },
        atomicityCompleteness: {
          splitRule: 'one_task_per_independent_behavior_surface_oracle',
          completenessVerdict:
            expectedTaskCount > 0 && expectedTaskCount === taskIds.length
              ? 'complete'
              : 'incomplete',
          expectedTaskCount,
          actualTaskCount: taskIds.length,
        },
        authorClaims: [
          {
            id: `CLAIM-${requirement.id}`,
            claim: `${requirement.id} reuses ${taskIds.length} source-owned atomic task(s) and explicitly linked projections.`,
            criticDisposition:
              input.consecutiveNoNewGapRounds >= 3
                ? 'accepted_no_new_valid_gap'
                : 'pending_critical_auditor_response',
          },
        ],
        mustExecutionDecompositionMatrix: matrixRows.map((row, rowIndex) => {
          const id = rowIdForRepair(row, String(rowIndex));
          const taskRefs = asStringArray(row.atomicTaskRefs).filter((ref) =>
            taskIdSet.has(ref)
          );
          return {
            ...row,
            id,
            mustRef: requirement.id,
            atomicTaskRefs: taskRefs,
            materializedTo: existingMatrixRows.includes(row)
              ? taskRefs.map(
                  (taskRef) => `implementationConfirmation.implementationTasks[${taskRef}]`
                )
              : [
                  `implementationConfirmation.implementationTasks[${
                    taskIds[0] || fallbackTaskId
                  }]`,
                ],
            derivedFromMustRef: requirement.id,
            ...projectionBackRefForRepair(input.packetHash, requirement.id),
          };
        }),
        mustAtomicTasks: taskRows.map((row, taskIndex) => {
          const id = taskIds[taskIndex];
          return {
            ...row,
            id,
            targetFiles: asStringArray(row.targetFiles),
            redProofPlan:
              normalizeText(row.redProofPlan) ||
              `Current-attempt evidence must independently prove ${requirement.id}.`,
            primaryObservableBehaviors:
              asStringArray(row.primaryObservableBehaviors).length > 0
                ? asStringArray(row.primaryObservableBehaviors)
                : uniqueStrings([normalizeText(row.text), requirement.text]),
            primaryAcceptanceOracles:
              asStringArray(row.primaryAcceptanceOracles).length > 0
                ? asStringArray(row.primaryAcceptanceOracles)
                : uniqueStrings([normalizeText(row.redProofPlan), requirement.text]),
            atomicUnitIndex: Number(row.atomicUnitIndex) || taskIndex + 1,
            atomicUnitCount: Number(row.atomicUnitCount) || taskRows.length,
            materializedTo: [`implementationConfirmation.implementationTasks[${id}]`],
            ...projectionBackRefForRepair(input.packetHash, requirement.id),
          };
        }),
        mustEvidenceProjection: mustEvidenceRows.map((row, rowIndex) => {
          const id = rowIdForRepair(row, String(rowIndex));
          return projection(id, `implementationConfirmation.evidence[${id}]`, requirement.id);
        }),
        mustTraceProjection: mustTraceRows.map((row, rowIndex) => {
          const id = rowIdForRepair(row, String(rowIndex));
          return projection(id, `implementationConfirmation.traceRows[${id}]`, requirement.id);
        }),
        mustAcceptanceProjection: [
          ...mustAcceptanceRows.map((row, rowIndex) => {
            const id = rowIdForRepair(row, String(rowIndex));
            return projection(
              id,
              `implementationConfirmation.acceptanceTests[${id}]`,
              requirement.id
            );
          }),
          ...mustE2eRows.map((row, rowIndex) => {
            const id = rowIdForRepair(row, String(rowIndex));
            return projection(id, `implementationConfirmation.e2eSuites[${id}]`, requirement.id);
          }),
        ],
        mustFailureEdgeProjection: [
          ...mustFailureRows.map((row, rowIndex) => {
            const id = rowIdForRepair(row, String(rowIndex));
            return projection(id, `implementationConfirmation.failurePaths[${id}]`, requirement.id);
          }),
          ...mustEdgeRows.map((row, rowIndex) => {
            const id = rowIdForRepair(row, String(rowIndex));
            return projection(id, `implementationConfirmation.edgeCases[${id}]`, requirement.id);
          }),
        ],
        mustTargetPathProjection: mustTargetRows.map((row, rowIndex) => {
          const id = rowIdForRepair(row, String(rowIndex));
          return projection(
            id,
            `implementationConfirmation.targetModificationPaths[${id}]`,
            requirement.id
          );
        }),
        mustCurrentTargetProjection: mustCurrentTargetRows.map((row, rowIndex) => {
          const id = rowIdForRepair(row, String(rowIndex));
          return projection(
            id,
            'implementationConfirmation.currentTargetMap',
            requirement.id
          );
        }),
        mustAiTddManifestProjection: mustAiTddRows.map((row, rowIndex) =>
          projection(
            rowIdForRepair(row, String(rowIndex)),
            'implementationConfirmation.aiTddContractExecutionManifestProjection',
            requirement.id
          )
        ),
        mustArtifactProjection: mustArtifactRows.map((row, rowIndex) => {
          const id = rowIdForRepair(row, String(rowIndex));
          return projection(
            id,
            `implementationConfirmation.artifactAutomationPlan[${id}]`,
            requirement.id
          );
        }),
        mustCommandProjection: mustCommandRows.map((row, rowIndex) => {
          const id = rowIdForRepair(row, String(rowIndex));
          return projection(
            id,
            `implementationConfirmation.requiredCommands[${id}]`,
            requirement.id
          );
        }),
        mustCloseoutBoundaryProjection: mustCloseoutRows.map((row, rowIndex) =>
          projection(
            rowIdForRepair(row, String(rowIndex)),
            'implementationConfirmation.closeoutReadinessPreview',
            requirement.id
          )
        ),
      };
    }),
    mustDerivedProjectionMap: mustRefs.map((mustRef) => {
      const currentTargetIds = repairProjectionRowsForMust(currentTargetRows, mustRef).map(
        (row, rowIndex) => rowIdForRepair(row, String(rowIndex))
      );
      return {
        mustRef,
        materializedTo: [
          ...currentTargetIds.map((id) => `implementationConfirmation.currentTargetMap[${id}]`),
          ...(aiTddRows.length > 0
            ? ['implementationConfirmation.aiTddContractExecutionManifestProjection']
            : []),
          ...(closeoutRows.length > 0
            ? ['implementationConfirmation.closeoutReadinessPreview']
            : []),
        ],
      };
    }),
  };
  payload.contentHash = input.packetHash;
  return payload;
}

export const CRITICAL_AUDITOR_RECEIPT_BINDING_ISSUE_CODES = [
  'critical_auditor_receipt_missing',
  'critical_auditor_response_artifact_missing',
  'critical_auditor_receipt_hash_missing',
  'critical_auditor_receipt_hash_mismatch',
  'critical_auditor_receipt_schema_version_mismatch',
  'critical_auditor_receipt_round_index_mismatch',
  'critical_auditor_receipt_transaction_id_mismatch',
  'critical_auditor_receipt_namespace_version_mismatch',
  'critical_auditor_receipt_record_id_mismatch',
  'critical_auditor_receipt_input_hash_mismatch',
  'critical_auditor_receipt_source_document_hash_mismatch',
  'critical_auditor_receipt_source_bytes_hash_mismatch',
  'critical_auditor_receipt_semantic_model_hash_mismatch',
  'critical_auditor_receipt_implementation_confirmation_hash_mismatch',
  'critical_auditor_receipt_packet_hash_mismatch',
  'critical_auditor_receipt_content_hash_mismatch',
  'critical_auditor_receipt_projection_set_hash_mismatch',
  'critical_auditor_receipt_request_hash_mismatch',
  'critical_auditor_receipt_gate_dry_run_hash_mismatch',
  'critical_auditor_receipt_response_hash_missing',
  'critical_auditor_receipt_response_hash_mismatch',
  'critical_auditor_response_schema_version_mismatch',
  'critical_auditor_response_round_index_mismatch',
  'critical_auditor_response_transaction_id_mismatch',
  'critical_auditor_response_namespace_version_mismatch',
  'critical_auditor_response_request_hash_mismatch',
  'critical_auditor_response_gate_dry_run_hash_mismatch',
  'critical_auditor_response_source_document_hash_mismatch',
  'critical_auditor_response_source_bytes_hash_mismatch',
  'critical_auditor_response_semantic_model_hash_mismatch',
  'critical_auditor_response_implementation_confirmation_hash_mismatch',
  'critical_auditor_response_packet_hash_mismatch',
  'critical_auditor_response_projection_set_hash_mismatch',
  'critical_auditor_cross_round_replay_detected',
] as const;

export type CriticalAuditorReceiptBindingIssueCode =
  (typeof CRITICAL_AUDITOR_RECEIPT_BINDING_ISSUE_CODES)[number];

export interface CriticalAuditorReceiptBindingExpectation {
  roundIndex: number;
  transactionId: string;
  namespaceVersion: string;
  auditInputHash: string;
  recordId: string;
  sourceDocumentHash: string;
  sourceBytesHash: string;
  semanticModelHash: string;
  implementationConfirmationHash: string;
  packetHash: string;
  projectionSetHash: string;
  requestHash: string;
  gateDryRunHash: string;
}

export interface CriticalAuditorReceiptBindingValidation {
  ok: boolean;
  issueCodes: CriticalAuditorReceiptBindingIssueCode[];
  responseHash: string | null;
}

export interface CriticalAuditorReceiptBindingRound {
  expectation: CriticalAuditorReceiptBindingExpectation;
  receipt: Record<string, unknown> | null;
  response: Record<string, unknown> | null;
}

export function validateCriticalAuditorReceiptBinding(
  input: CriticalAuditorReceiptBindingRound
): CriticalAuditorReceiptBindingValidation {
  const issueCodes: CriticalAuditorReceiptBindingIssueCode[] = [];
  const receipt = input.receipt;
  const response = input.response;
  const expected = input.expectation;
  const compare = (
    actual: unknown,
    expectedValue: string | number,
    issueCode: CriticalAuditorReceiptBindingIssueCode
  ) => {
    const matches =
      typeof expectedValue === 'number'
        ? Number(actual) === expectedValue
        : normalizeText(actual) === expectedValue;
    if (!matches) {
      issueCodes.push(issueCode);
    }
  };

  if (!receipt) {
    issueCodes.push('critical_auditor_receipt_missing');
  } else {
    const receiptHash = normalizeText(receipt.receiptHash);
    const receiptForHash = { ...receipt };
    delete receiptForHash.receiptHash;
    if (!receiptHash) {
      issueCodes.push('critical_auditor_receipt_hash_missing');
    } else if (receiptHash !== sha256Json(receiptForHash)) {
      issueCodes.push('critical_auditor_receipt_hash_mismatch');
    }
    compare(
      receipt.schemaVersion,
      'critical-auditor-receipt/v1',
      'critical_auditor_receipt_schema_version_mismatch'
    );
    compare(
      receipt.roundIndex,
      expected.roundIndex,
      'critical_auditor_receipt_round_index_mismatch'
    );
    compare(
      receipt.transactionId,
      expected.transactionId,
      'critical_auditor_receipt_transaction_id_mismatch'
    );
    compare(
      receipt.namespaceVersion,
      expected.namespaceVersion,
      'critical_auditor_receipt_namespace_version_mismatch'
    );
    compare(receipt.recordId, expected.recordId, 'critical_auditor_receipt_record_id_mismatch');
    compare(
      receipt.inputHash,
      expected.auditInputHash,
      'critical_auditor_receipt_input_hash_mismatch'
    );
    compare(
      receipt.sourceDocumentHash,
      expected.sourceDocumentHash,
      'critical_auditor_receipt_source_document_hash_mismatch'
    );
    compare(
      receipt.sourceBytesHash,
      expected.sourceBytesHash,
      'critical_auditor_receipt_source_bytes_hash_mismatch'
    );
    compare(
      receipt.semanticModelHash,
      expected.semanticModelHash,
      'critical_auditor_receipt_semantic_model_hash_mismatch'
    );
    compare(
      receipt.implementationConfirmationHash,
      expected.implementationConfirmationHash,
      'critical_auditor_receipt_implementation_confirmation_hash_mismatch'
    );
    compare(
      receipt.packetHash,
      expected.packetHash,
      'critical_auditor_receipt_packet_hash_mismatch'
    );
    compare(
      receipt.contentHash,
      expected.packetHash,
      'critical_auditor_receipt_content_hash_mismatch'
    );
    compare(
      receipt.projectionSetHash,
      expected.projectionSetHash,
      'critical_auditor_receipt_projection_set_hash_mismatch'
    );
    compare(
      receipt.requestHash,
      expected.requestHash,
      'critical_auditor_receipt_request_hash_mismatch'
    );
    compare(
      receipt.gateDryRunHash,
      expected.gateDryRunHash,
      'critical_auditor_receipt_gate_dry_run_hash_mismatch'
    );
  }

  const responseHash = response ? sha256Json(response) : null;
  if (!response) {
    issueCodes.push('critical_auditor_response_artifact_missing');
  } else {
    compare(
      response.schemaVersion,
      'critical-auditor-round-response/v1',
      'critical_auditor_response_schema_version_mismatch'
    );
    compare(
      response.roundIndex,
      expected.roundIndex,
      'critical_auditor_response_round_index_mismatch'
    );
    compare(
      response.transactionId,
      expected.transactionId,
      'critical_auditor_response_transaction_id_mismatch'
    );
    compare(
      response.namespaceVersion,
      expected.namespaceVersion,
      'critical_auditor_response_namespace_version_mismatch'
    );
    compare(
      response.requestHash,
      expected.requestHash,
      'critical_auditor_response_request_hash_mismatch'
    );
    compare(
      response.gateDryRunHash,
      expected.gateDryRunHash,
      'critical_auditor_response_gate_dry_run_hash_mismatch'
    );
    compare(
      response.sourceDocumentHash,
      expected.sourceDocumentHash,
      'critical_auditor_response_source_document_hash_mismatch'
    );
    compare(
      response.sourceBytesHash,
      expected.sourceBytesHash,
      'critical_auditor_response_source_bytes_hash_mismatch'
    );
    compare(
      response.semanticModelHash,
      expected.semanticModelHash,
      'critical_auditor_response_semantic_model_hash_mismatch'
    );
    compare(
      response.implementationConfirmationHash,
      expected.implementationConfirmationHash,
      'critical_auditor_response_implementation_confirmation_hash_mismatch'
    );
    compare(
      response.packetHash,
      expected.packetHash,
      'critical_auditor_response_packet_hash_mismatch'
    );
    compare(
      response.projectionSetHash,
      expected.projectionSetHash,
      'critical_auditor_response_projection_set_hash_mismatch'
    );
  }

  if (receipt) {
    const storedResponseHash = normalizeText(receipt.responseHash);
    if (!storedResponseHash) {
      issueCodes.push('critical_auditor_receipt_response_hash_missing');
    } else if (responseHash && storedResponseHash !== responseHash) {
      issueCodes.push('critical_auditor_receipt_response_hash_mismatch');
    }
  }

  const uniqueIssueCodes = [...new Set(issueCodes)];
  return {
    ok: uniqueIssueCodes.length === 0,
    issueCodes: uniqueIssueCodes,
    responseHash,
  };
}

export function evaluateCriticalAuditorReceiptBindingSequence(
  rounds: readonly CriticalAuditorReceiptBindingRound[]
): {
  ok: boolean;
  consecutiveValidNoNewGapRounds: number;
  latestReceiptHash: string | null;
  issueCodes: CriticalAuditorReceiptBindingIssueCode[];
} {
  const issueCodes: CriticalAuditorReceiptBindingIssueCode[] = [];
  let consecutiveValidNoNewGapRounds = 0;
  let latestReceiptHash: string | null = null;
  const seenProviderRunIds = new Set<string>();
  const seenRequestHashes = new Set<string>();
  const seenReceiptHashes = new Set<string>();
  for (const round of rounds) {
    const validation = validateCriticalAuditorReceiptBinding(round);
    if (!validation.ok) {
      issueCodes.push(...validation.issueCodes);
      consecutiveValidNoNewGapRounds = 0;
      latestReceiptHash = null;
      continue;
    }
    const receipt = recordObject(round.receipt);
    const providerRunId = normalizeText(
      recordObject(receipt.independentProviderEvidence).providerRunId
    );
    const requestHash = normalizeText(receipt.requestHash);
    const receiptHash = normalizeText(receipt.receiptHash);
    if (
      (providerRunId && seenProviderRunIds.has(providerRunId)) ||
      (requestHash && seenRequestHashes.has(requestHash)) ||
      (receiptHash && seenReceiptHashes.has(receiptHash))
    ) {
      issueCodes.push('critical_auditor_cross_round_replay_detected');
    }
    if (providerRunId) seenProviderRunIds.add(providerRunId);
    if (requestHash) seenRequestHashes.add(requestHash);
    if (receiptHash) seenReceiptHashes.add(receiptHash);
    const verdict = normalizeText(recordObject(round.receipt?.convergenceDecision).verdict);
    consecutiveValidNoNewGapRounds = isNoNewGapVerdict(verdict as CriticalAuditorVerdict)
      ? consecutiveValidNoNewGapRounds + 1
      : 0;
    latestReceiptHash = normalizeText(round.receipt?.receiptHash) || null;
  }
  const uniqueIssueCodes = [...new Set(issueCodes)];
  return {
    ok: uniqueIssueCodes.length === 0,
    consecutiveValidNoNewGapRounds,
    latestReceiptHash,
    issueCodes: uniqueIssueCodes,
  };
}

function buildCriticalAuditorResponseArtifact(input: {
  roundIndex: number;
  transaction: CriticalAuditorStagingTransaction;
  requestHash: string;
  sourceDocumentHash: string;
  sourceBytesHash: string;
  semanticModelHash: string;
  implementationConfirmationHash: string;
  packetHash: string;
  projectionSetHash: string;
  gateDryRunHash: string;
  auditResult: CriticalAuditorRoundResult;
}): Record<string, unknown> {
  const {
    providerInvocationReceiptRef: _providerInvocationReceiptRef,
    judgeAdapterHostExecution: _judgeAdapterHostExecution,
    ...semanticAuditResult
  } = input.auditResult;
  return {
    schemaVersion: 'critical-auditor-round-response/v1',
    roundIndex: input.roundIndex,
    transactionId: input.transaction.transactionId,
    namespaceVersion: input.transaction.namespaceVersion,
    requestHash: input.requestHash,
    sourceHash: input.sourceDocumentHash,
    sourceDocumentHash: input.sourceDocumentHash,
    sourceBytesHash: input.sourceBytesHash,
    semanticModelHash: input.semanticModelHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    packetHash: input.packetHash,
    projectionSetHash: input.projectionSetHash,
    gateDryRunHash: input.gateDryRunHash,
    ...semanticAuditResult,
  };
}

function criticalAuditorResponseArtifactMatchesExpectation(
  response: Record<string, unknown> | null,
  expectation: Pick<
    CriticalAuditorReceiptBindingExpectation,
    | 'roundIndex'
    | 'transactionId'
    | 'namespaceVersion'
    | 'sourceDocumentHash'
    | 'sourceBytesHash'
    | 'semanticModelHash'
    | 'implementationConfirmationHash'
    | 'packetHash'
    | 'projectionSetHash'
    | 'requestHash'
    | 'gateDryRunHash'
  >
): response is Record<string, unknown> {
  return (
    Boolean(response) &&
    normalizeText(response?.schemaVersion) === 'critical-auditor-round-response/v1' &&
    Number(response?.roundIndex) === expectation.roundIndex &&
    normalizeText(response?.transactionId) === expectation.transactionId &&
    normalizeText(response?.namespaceVersion) === expectation.namespaceVersion &&
    normalizeText(response?.sourceDocumentHash) === expectation.sourceDocumentHash &&
    normalizeText(response?.sourceBytesHash) === expectation.sourceBytesHash &&
    normalizeText(response?.semanticModelHash) === expectation.semanticModelHash &&
    normalizeText(response?.implementationConfirmationHash) ===
      expectation.implementationConfirmationHash &&
    normalizeText(response?.packetHash) === expectation.packetHash &&
    normalizeText(response?.projectionSetHash) === expectation.projectionSetHash &&
    normalizeText(response?.requestHash) === expectation.requestHash &&
    normalizeText(response?.gateDryRunHash) === expectation.gateDryRunHash
  );
}

function buildCriticalAuditorReceipt(input: {
  roundIndex: number;
  transactionId?: string;
  namespaceVersion?: string;
  requestHash?: string;
  gateDryRunHash?: string;
  responseHash: string;
  auditInputHash: string;
  recordId: string;
  sourceDocumentHash: string;
  sourceBytesHash: string;
  semanticModelHash: string;
  implementationConfirmationHash: string;
  packetHash: string;
  projectionSetHash?: string;
  independentProviderExpectation?: CriticalAuditorIndependentProviderExpectation;
  createdAt: string;
  auditResult?: CriticalAuditorRoundResult;
}): Record<string, unknown> {
  const auditResult = input.auditResult ?? { verdict: 'no_new_valid_gap' as const };
  const isClean =
    auditResult.verdict === 'no_new_valid_gap' ||
    auditResult.verdict === 'no_new_confirmation_blocking_gap';
  const receipt: Record<string, unknown> = {
    schemaVersion: 'critical-auditor-receipt/v1',
    recordId: input.recordId,
    roundIndex: input.roundIndex,
    transactionId: input.transactionId,
    namespaceVersion: input.namespaceVersion,
    requestHash: input.requestHash,
    inputHash: input.auditInputHash,
    sourceHash: input.sourceDocumentHash,
    sourceDocumentHash: input.sourceDocumentHash,
    sourceBytesHash: input.sourceBytesHash,
    semanticModelHash: input.semanticModelHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    packetHash: input.packetHash,
    projectionSetHash: input.projectionSetHash ?? null,
    contentHash: input.packetHash,
    createdBy: 'critical_auditor.requirement_confirmation.pre_confirmation_drilldown',
    createdAt: input.createdAt,
    inputRefs: [
      'semantic-kernel.json',
      'must_decomposition_packet.json',
      'implementationConfirmation',
    ],
    attackVectors: ['under_split_task', 'missing_projection', 'source_row_independently_invented'],
    gapCandidates: auditResult.gapCandidates ?? [],
    validatedGaps: auditResult.validatedGaps ?? [],
    rejectedGapCandidates:
      auditResult.rejectedGapCandidates ??
      (isClean ? [{ id: `REJ-${input.roundIndex}`, reason: 'no new valid gap detected' }] : []),
    mutationPressureFindings: auditResult.mutationPressureFindings ?? [],
    overBroadTaskFindings: auditResult.overBroadTaskFindings ?? [],
    missingProjectionFindings: auditResult.missingProjectionFindings ?? [],
    invalidProofFindings: auditResult.invalidProofFindings ?? [],
    legacyBypassFindings: auditResult.legacyBypassFindings ?? [],
    sourceMaterializationFindings: auditResult.sourceMaterializationFindings ?? [],
    reviewedProjectionRefs: auditResult.reviewedProjectionRefs ?? [],
    reviewedMustRefs: auditResult.reviewedMustRefs ?? [],
    gateDryRunHash: input.gateDryRunHash ?? auditResult.gateDryRunHash ?? null,
    responseHash: input.responseHash,
    independentProviderExpectation: input.independentProviderExpectation ?? null,
    independentProviderEvidence: auditResult.independentProviderEvidence ?? null,
    providerInvocationReceiptRef: auditResult.providerInvocationReceiptRef ?? null,
    judgeAdapterHostExecution: auditResult.judgeAdapterHostExecution ?? null,
    reconciliationIssueCount: auditResult.reconciliationIssueCount ?? null,
    checkedProjectionGroups: auditResult.checkedProjectionGroups ?? [],
    checkedProjectionQualityRuleCodes: auditResult.checkedProjectionQualityRuleCodes ?? [],
    priorFindingsDisposition: auditResult.priorFindingsDisposition ?? [],
    falsePositiveProofs: auditResult.falsePositiveProofs ?? [],
    noNewGapRationale:
      auditResult.rationale ??
      (isClean
        ? 'No new valid gap in this bounded audit round.'
        : 'Critical Auditor found a new gap; convergence counter resets.'),
    convergenceDecision: {
      verdict: auditResult.verdict,
      resetsConvergenceCounter: !isClean,
    },
  };
  const persistedReceipt = JSON.parse(JSON.stringify(receipt)) as Record<string, unknown>;
  persistedReceipt.receiptHash = sha256Json(persistedReceipt);
  return persistedReceipt;
}

function criticalAuditorReceiptMatchesCurrent(input: {
  projectRoot: string;
  receipt: Record<string, unknown> | null;
  response: Record<string, unknown> | null;
  roundIndex: number;
  transaction: CriticalAuditorStagingTransaction;
  auditInputHash: string;
  recordId: string;
  sourceDocumentHash: string;
  sourceBytesHash: string;
  semanticModelHash: string;
  implementationConfirmationHash: string;
  packetHash: string;
  projectionSetHash: string;
  requestHash: string;
  gateDryRunHash: string;
}): boolean {
  const receipt = input.receipt;
  const bindingValidation = validateCriticalAuditorReceiptBinding({
    receipt,
    response: input.response,
    expectation: {
      roundIndex: input.roundIndex,
      transactionId: input.transaction.transactionId,
      namespaceVersion: input.transaction.namespaceVersion,
      auditInputHash: input.auditInputHash,
      recordId: input.recordId,
      sourceDocumentHash: input.sourceDocumentHash,
      sourceBytesHash: input.sourceBytesHash,
      semanticModelHash: input.semanticModelHash,
      implementationConfirmationHash: input.implementationConfirmationHash,
      packetHash: input.packetHash,
      projectionSetHash: input.projectionSetHash,
      requestHash: input.requestHash,
      gateDryRunHash: input.gateDryRunHash,
    },
  });
  if (!bindingValidation.ok || !receipt) return false;
  try {
    const expectation = recordObject(receipt.independentProviderExpectation);
    if (
      normalizeText(expectation.requestHash) !== input.requestHash ||
      normalizeText(expectation.sourceDocumentHash) !== input.sourceDocumentHash ||
      normalizeText(expectation.semanticModelHash) !== input.semanticModelHash ||
      normalizeText(expectation.projectionSetHash) !== input.projectionSetHash
    ) {
      return false;
    }
    const providerValidation = validateCriticalAuditorIndependentProviderEvidence({
      expected: expectation as unknown as CriticalAuditorIndependentProviderExpectation,
      evidence: receipt.independentProviderEvidence,
    });
    if (!providerValidation.ok) return false;
    const providerRunId = normalizeText(
      recordObject(receipt.independentProviderEvidence).providerRunId
    );
    if (!providerRunId) return false;
    validateCriticalAuditorProviderInvocationReceipt({
      projectRoot: input.projectRoot,
      receiptRef: receipt.providerInvocationReceiptRef,
      requestHash: input.requestHash,
      sourceDocumentHash: input.sourceDocumentHash,
      sourceBytesHash: input.sourceBytesHash,
      semanticModelHash: input.semanticModelHash,
      projectionSetHash: input.projectionSetHash,
      providerRunId,
      expectedProviderBinding:
        expectation as unknown as CriticalAuditorJudgeRuntimeBinding,
    });
    validateCriticalAuditorJudgeHostExecution(
      input.projectRoot,
      receipt.judgeAdapterHostExecution,
      receipt.providerInvocationReceiptRef
    );
  } catch {
    return false;
  }
  return true;
}

function writeCriticalAuditorReceiptMirror(input: {
  rootReceiptPath: string;
  mirrorPath: string;
  transaction: CriticalAuditorStagingTransaction;
  authoringDir: string;
  receipt: Record<string, unknown>;
}): void {
  const payload = { criticalAuditorReceipt: input.receipt };
  const existingRoot = readJsonIfExists(input.rootReceiptPath);
  if (sha256Json(existingRoot ?? {}) !== sha256Json(payload)) {
    writeJsonUtf8(input.rootReceiptPath, payload);
  }
  const mirrorPayload = {
    criticalAuditorReceipt: input.receipt,
    transactionMirror: {
      transactionId: input.transaction.transactionId,
      sourcePath: path.relative(input.authoringDir, input.rootReceiptPath).replace(/\\/g, '/'),
    },
  };
  const existingMirror = readJsonIfExists(input.mirrorPath);
  if (sha256Json(existingMirror ?? {}) !== sha256Json(mirrorPayload)) {
    writeJsonUtf8(input.mirrorPath, mirrorPayload);
  }
}

function publishCriticalAuditorTransactionEvidence(input: {
  root: string;
  transaction: CriticalAuditorStagingTransaction;
  stagingPaths: PreConfirmationPaths;
  publishedPaths: PreConfirmationPaths;
  receiptCount: number;
}): string[] {
  const published: string[] = [];
  const publishFile = (sourcePath: string, targetPath: string): void => {
    if (!fs.existsSync(sourcePath)) {
      throw new Error(
        `critical_auditor_transaction_evidence_missing:${toRootRelativePath(input.root, sourcePath)}`
      );
    }
    fs.mkdirSync(path.dirname(targetPath), { recursive: true });
    if (fs.existsSync(targetPath) && sha256File(targetPath) !== sha256File(sourcePath)) {
      throw new Error(
        `critical_auditor_published_evidence_conflict:${toRootRelativePath(input.root, targetPath)}`
      );
    }
    if (!fs.existsSync(targetPath)) {
      fs.copyFileSync(sourcePath, targetPath);
    }
    published.push(targetPath);
  };
  for (let roundIndex = 1; roundIndex <= input.receiptCount; roundIndex += 1) {
    publishFile(
      criticalAuditorRequestPath(input.transaction, roundIndex),
      findCriticalAuditorRequestPath(input.publishedPaths.authoringDir, roundIndex)
    );
    publishFile(
      criticalAuditorResponsePath(input.transaction, roundIndex),
      path.join(
        input.publishedPaths.authoringDir,
        `critical-auditor-round-response-${roundIndex}.json`
      )
    );
    publishFile(
      criticalAuditorReceiptPath(input.transaction, roundIndex),
      path.join(
        input.publishedPaths.authoringDir,
        `critical-auditor-receipt-round-${roundIndex}.json`
      )
    );
  }
  publishFile(input.stagingPaths.criticalAuditorOutcome, input.publishedPaths.criticalAuditorOutcome);
  return published;
}

function isNoNewGapVerdict(verdict: CriticalAuditorVerdict): boolean {
  return verdict === 'no_new_valid_gap' || verdict === 'no_new_confirmation_blocking_gap';
}

const CRITICAL_AUDITOR_PROJECTION_GROUPS = [
  'mustAtomicTasks',
  'mustExecutionDecompositionMatrix',
  'mustEvidenceProjection',
  'mustTraceProjection',
  'mustAcceptanceProjection',
  'mustFailureEdgeProjection',
  'mustTargetPathProjection',
  'mustCurrentTargetProjection',
  'mustAiTddManifestProjection',
  'mustArtifactProjection',
  'mustCommandProjection',
  'mustCloseoutBoundaryProjection',
];

const PROJECTION_QUALITY_RULE_CODES = AUDIT_PROJECTION_QUALITY_RULE_CODES;

const CRITICAL_AUDITOR_ACTIONABLE_DRY_RUN_EXCLUSIONS = new Set([
  'critical_auditor_receipt_missing',
  'critical_auditor_less_than_three_no_new_gap_rounds',
  'author_claim_lacks_critic_disposition',
]);

const CRITICAL_AUDITOR_REPAIR_ACTION_TYPE_SET = new Set<string>(
  CRITICAL_AUDITOR_REPAIR_ACTION_TYPES
);

const CRITICAL_AUDITOR_REPAIR_ACTION_REQUIRED_FIELDS = [
  'sourceSpan',
  'sourceText',
  'targetField',
  'newValue',
  'reason',
  'mustRefs',
  'requirementIds',
];

function validateCriticalAuditorRepairActions(input: {
  gaps: Record<string, unknown>[];
  sourceText: string;
  confirmation: Record<string, unknown>;
}): {
  gaps: Array<Record<string, unknown> & { repairActions: CriticalAuditorRepairAction[] }>;
  issues: PreConfirmationDrilldownIssue[];
} {
  const issues: PreConfirmationDrilldownIssue[] = [];
  const sourceLines = input.sourceText.replace(/\r\n/gu, '\n').split('\n');
  const mustRows = asRecordArray(input.confirmation.must);
  const mustIds = new Set(mustRows.map((row) => normalizeText(row.id)).filter(Boolean));
  const requirementIds = new Set<string>();
  for (const row of mustRows) {
    for (const requirementId of uniqueNonEmpty([
      normalizeText(row.sourceRequirementId),
      ...asStringArray(row.sourceRequirementIds),
    ])) {
      requirementIds.add(requirementId);
    }
  }
  const existingIdsByField = new Map<string, Set<string>>();
  for (const field of new Set(Object.values(CRITICAL_AUDITOR_REPAIR_ACTION_TARGET_FIELDS).flat())) {
    const normalizedField = field.replace(/^implementationConfirmation\./u, '');
    if (!existingIdsByField.has(normalizedField)) {
      existingIdsByField.set(
        normalizedField,
        new Set(
          asRecordArray(input.confirmation[normalizedField])
            .map((row) => normalizeText(row.id ?? row.commandId))
            .filter(Boolean)
        )
      );
    }
  }
  const seenActionIds = new Set<string>();
  const reservedNewValueFields = new Set([
    'sourceSpan',
    'sourceText',
    'sourcePath',
    'sourceDocumentHash',
    'sourceRequirementId',
    'sourceRequirementIds',
    'repairActionId',
    'repairReason',
    'derivedFromMustRef',
    'projectionStatus',
  ]);
  const addIssue = (
    code: string,
    message: string,
    refs: string[]
  ): void => {
    issues.push(preConfirmationIssue(code, message, refs, 'critical_auditor'));
  };
  const normalizedGaps = input.gaps.map((gap, gapIndex) => {
    const gapId = normalizeText(gap.id ?? gap.code ?? `validated-gap-${gapIndex + 1}`);
    const actions = asRecordArray(gap.repairActions);
    if (actions.length === 0) {
      addIssue(
        'critical_auditor_validated_gap_repair_actions_missing',
        `Validated gap ${gapId} must include non-empty repairActions[]`,
        [`${gapId}.repairActions`]
      );
    }
    const normalizedActions = actions.map((action, actionIndex) => {
      const actionId =
        normalizeText(action.actionId ?? action.id) || `${gapId}-ACTION-${actionIndex + 1}`;
      const type = normalizeText(action.type ?? action.actionType);
      if (seenActionIds.has(actionId)) {
        addIssue(
          'critical_auditor_repair_action_id_duplicate',
          `Critical Auditor repair action ID ${actionId} is duplicated.`,
          [actionId]
        );
      }
      seenActionIds.add(actionId);
      if (!CRITICAL_AUDITOR_REPAIR_ACTION_TYPE_SET.has(type)) {
        addIssue(
          'critical_auditor_repair_action_type_unknown',
          `Critical Auditor repair action ${actionId} uses unknown action type ${type || '<missing>'}`,
          [type || '<missing>']
        );
      }
      for (const field of CRITICAL_AUDITOR_REPAIR_ACTION_REQUIRED_FIELDS) {
        const value = action[field];
        const missing =
          value === undefined ||
          value === null ||
          (typeof value === 'string' && !normalizeText(value)) ||
          (Array.isArray(value) && value.length === 0) ||
            (field === 'sourceSpan' &&
              (typeof value !== 'object' || value === null || Array.isArray(value)));
        if (missing) {
          addIssue(
            'critical_auditor_repair_action_field_missing',
            `Critical Auditor repair action ${actionId} is missing required field ${field}`,
            [field]
          );
        }
      }
      const sourceSpan = recordObject(action.sourceSpan);
      const startLine = Number(sourceSpan.startLine);
      const endLine = Number(sourceSpan.endLine);
      const sourceText = normalizeText(action.sourceText);
      if (
        !Number.isInteger(startLine) ||
        !Number.isInteger(endLine) ||
        startLine < 1 ||
        endLine < startLine ||
        endLine > sourceLines.length
      ) {
        addIssue(
          'critical_auditor_repair_action_source_span_invalid',
          `Critical Auditor repair action ${actionId} has an invalid sourceSpan.`,
          [actionId, String(startLine), String(endLine)]
        );
      } else {
        const actualSourceText = sourceLines.slice(startLine - 1, endLine).join('\n').trim();
        if (actualSourceText !== sourceText) {
          addIssue(
            'critical_auditor_repair_action_source_text_mismatch',
            `Critical Auditor repair action ${actionId} sourceText does not match the current source bytes at sourceSpan.`,
            [actionId, `${startLine}:${endLine}`]
          );
        }
      }
      const mustRefs = asStringArray(action.mustRefs);
      const actionRequirementIds = asStringArray(action.requirementIds);
      for (const mustRef of mustRefs) {
        if (!mustIds.has(mustRef)) {
          addIssue(
            'critical_auditor_repair_action_must_ref_unknown',
            `Critical Auditor repair action ${actionId} references unknown MUST ${mustRef}.`,
            [actionId, mustRef]
          );
        }
      }
      for (const requirementId of actionRequirementIds) {
        if (!requirementIds.has(requirementId)) {
          addIssue(
            'critical_auditor_repair_action_requirement_id_unknown',
            `Critical Auditor repair action ${actionId} references unknown requirement ${requirementId}.`,
            [actionId, requirementId]
          );
        }
      }
      const targetField = normalizeText(action.targetField).replace(
        /^implementationConfirmation\./u,
        ''
      );
      const value = recordObject(action.newValue);
      if (
        !action.newValue ||
        typeof action.newValue !== 'object' ||
        Array.isArray(action.newValue) ||
        Object.keys(value).length === 0
      ) {
        addIssue(
          'critical_auditor_repair_action_new_value_invalid',
          `Critical Auditor repair action ${actionId} must provide a non-empty typed newValue object.`,
          [actionId]
        );
      }
      for (const field of Object.keys(value)) {
        if (reservedNewValueFields.has(field)) {
          addIssue(
            'critical_auditor_repair_action_provenance_field_forbidden',
            `Critical Auditor repair action ${actionId} may not author controlled provenance field ${field}.`,
            [actionId, field]
          );
        }
      }
      if (type === 'split_must') {
        const sourceMustRef = normalizeText(value.sourceMustRef);
        const replacements = asRecordArray(value.replacements);
        const replacementIds = replacements.map((row) => normalizeText(row.id));
        if (
          mustRefs.length !== 1 ||
          sourceMustRef !== mustRefs[0] ||
          replacements.length < 2 ||
          replacementIds.some((id) => !id) ||
          new Set(replacementIds).size !== replacementIds.length ||
          replacementIds.filter((id) => id === sourceMustRef).length !== 1 ||
          replacements.some((row) => !normalizeText(row.text))
        ) {
          addIssue(
            'critical_auditor_split_must_contract_invalid',
            `Critical Auditor split_must action ${actionId} must identify one existing MUST and at least two unique replacement rows, retaining the original MUST ID exactly once.`,
            [actionId, sourceMustRef, ...replacementIds].filter(Boolean)
          );
        }
        const conflictingId = replacementIds.find(
          (id) => id !== sourceMustRef && mustIds.has(id)
        );
        if (conflictingId) {
          addIssue(
            'critical_auditor_repair_action_materialized_id_conflict',
            `Critical Auditor split_must action ${actionId} replacement ID ${conflictingId} already exists.`,
            [actionId, conflictingId]
          );
        }
      } else {
        const id = normalizeText(value.id ?? value.commandId);
        const requiredValuePresent =
          type === 'replace_target_path'
            ? Boolean(normalizeText(value.path))
            : type === 'replace_validation_command'
              ? Boolean(normalizeText(value.command))
              : Boolean(id && normalizeText(value.text));
        if (!requiredValuePresent) {
          addIssue(
            'critical_auditor_repair_action_new_value_shape_invalid',
            `Critical Auditor repair action ${actionId} newValue does not satisfy the ${type} contract.`,
            [actionId, type]
          );
        }
        if (
          id &&
          !['upsert_trace', 'upsert_failure_path', 'upsert_edge_case'].includes(type) &&
          existingIdsByField.get(targetField)?.has(id)
        ) {
          addIssue(
            'critical_auditor_repair_action_materialized_id_conflict',
            `Critical Auditor repair action ${actionId} would duplicate ID ${id} in ${targetField}.`,
            [actionId, targetField, id]
          );
        }
      }
      return {
        actionId,
        type: type as CriticalAuditorRepairActionType,
        sourceSpan,
        sourceText,
        targetField,
        newValue: action.newValue,
        reason: normalizeText(action.reason),
        mustRefs,
        requirementIds: actionRequirementIds,
      };
    });
    return {
      ...gap,
      repairActions: normalizedActions,
    };
  });
  return { gaps: normalizedGaps, issues };
}

function criticalAuditorRoundPerspective(roundIndex: number): Record<string, unknown> {
  const normalizedRound = ((Math.max(roundIndex, 1) - 1) % 3) + 1;
  if (normalizedRound === 1) {
    return {
      id: 'round_1_must_atomicity',
      focus: 'MUST atomicity, over-broad tasks, and missing decomposition',
      requiredAttackSurface: [
        'under_split_must',
        'over_broad_atomic_task',
        'missing_atomicity_driver',
        'missing_question_coverage',
      ],
    };
  }
  if (normalizedRound === 2) {
    return {
      id: 'round_2_projection_materialization',
      focus:
        'EVD / TRACE / ACC / E2E / FAIL / EDGE / artifact / command / AI-TDD projection materialization and per-MUST projection quality',
      requiredAttackSurface: [
        'missing_evidence_projection',
        'missing_trace_projection',
        'missing_acceptance_or_e2e_projection',
        'missing_failure_edge_projection',
        'missing_artifact_or_command_projection',
        'missing_ai_tdd_manifest_projection',
        'source_row_independently_invented',
        ...PROJECTION_QUALITY_RULE_CODES,
      ],
    };
  }
  return {
    id: 'round_3_authority_boundary_hash_delivery_confusion',
    focus:
      'stale hash, authority bypass, negative boundary, reconfirmation, and delivery-vs-confirmation confusion',
    requiredAttackSurface: [
      'stale_source_or_packet_hash',
      'authority_bypass',
      'negative_boundary_gap',
      'reconfirmation_required_gap',
      'delivery_readiness_confused_with_confirmation',
    ],
  };
}

function projectionRefsFromPacket(packet: Record<string, unknown>): string[] {
  const refs = new Set<string>();
  for (const mustPacket of asRecordArray(packet.mustPackets)) {
    const mustRef = normalizeText(mustPacket.mustRef);
    for (const key of CRITICAL_AUDITOR_PROJECTION_GROUPS) {
      for (const row of asRecordArray(mustPacket[key])) {
        const id = normalizeText(row.id);
        if (!id) continue;
        refs.add(id);
        if (mustRef) refs.add(`${mustRef}:${id}`);
        refs.add(`${key}:${id}`);
      }
    }
  }
  return [...refs].sort();
}

function projectionIdentityIds(value: unknown): string[] {
  const ids = new Set<string>();
  const visit = (candidate: unknown): void => {
    if (Array.isArray(candidate)) {
      for (const item of candidate) visit(item);
      return;
    }
    const row = recordObject(candidate);
    if (Object.keys(row).length === 0) return;
    const id = normalizeText(row.id);
    if (id) ids.add(id);
    for (const child of Object.values(row)) visit(child);
  };
  visit(value);
  return [...ids].sort();
}

function projectionInventoryFromConfirmation(
  confirmation: Record<string, unknown>
): {
  projectionGroups: string[];
  projectionRefs: string[];
} {
  const projectionGroups = new Set<string>();
  const projectionRefs = new Set<string>();
  for (const [group, value] of Object.entries(confirmation).sort(([left], [right]) =>
    left.localeCompare(right)
  )) {
    const ids = projectionIdentityIds(value);
    if (ids.length === 0) continue;
    projectionGroups.add(group);
    for (const id of ids) {
      projectionRefs.add(id);
      projectionRefs.add(`${group}:${id}`);
    }
  }
  return {
    projectionGroups: [...projectionGroups].sort(),
    projectionRefs: [...projectionRefs].sort(),
  };
}

function compiledModelPacketProjectionIdentity(row: Record<string, unknown>): string {
  return normalizeText(
    row.id ??
      row.taskId ??
      row.traceId ??
      row.commandId ??
      row.acceptanceId ??
      row.e2eId ??
      row.artifactId
  );
}

function compiledModelPacketProjectionInventory(packet: Record<string, unknown>): {
  projectionGroups: string[];
  projectionRefs: string[];
} {
  const projectionGroups = new Set<string>();
  const projectionRefs = new Set<string>();
  const visit = (value: unknown, pathSegments: string[]): void => {
    if (Array.isArray(value)) {
      const group = pathSegments.join('.');
      for (const item of value) {
        const row = recordObject(item);
        const identity = compiledModelPacketProjectionIdentity(row);
        if (identity && group) {
          projectionGroups.add(group);
          projectionRefs.add(identity);
          projectionRefs.add(`${group}:${identity}`);
        }
        if (Object.keys(row).length > 0) visit(row, pathSegments);
      }
      return;
    }
    const row = recordObject(value);
    for (const [key, child] of Object.entries(row)) {
      visit(child, [...pathSegments, key]);
    }
  };
  visit(packet, []);
  return {
    projectionGroups: [...projectionGroups].sort(),
    projectionRefs: [...projectionRefs].sort(),
  };
}

function compiledModelPacketMustAuthority(packet: Record<string, unknown>): {
  mustRefs: string[];
  sourceRequirementTexts: string[];
} {
  const requirements = recordObject(packet.requirements);
  const authorityByMustRef = new Map<string, string>();
  for (const row of asRecordArray(requirements.must)) {
    const mustRef = normalizeText(row.id);
    const sourceRequirementText = normalizeText(row.text);
    if (!mustRef || !sourceRequirementText) continue;
    authorityByMustRef.set(mustRef, sourceRequirementText);
  }
  return {
    mustRefs: [...authorityByMustRef.keys()],
    sourceRequirementTexts: [...authorityByMustRef.values()],
  };
}

export function resolveAuditJudgeRequestAuthorityBinding(input: {
  projectRoot: string;
  modelPacketPath: string;
  modelPacketHash: string;
  sourceDocumentHash: string;
  projectionSetHash: string;
}): {
  sourceDocument: string;
  sourceBytesHash: string;
  mustRefs: string[];
  sourceRequirementTexts: string[];
  packetProjectionSummary: {
    mustPacketCount: number;
    projectionGroups: string[];
    projectionRefs: string[];
  };
} {
  const projectRoot = path.resolve(input.projectRoot);
  const modelPacketPath = resolveRootRelativePath(projectRoot, input.modelPacketPath);
  const relativeModelPacketPath = path.relative(projectRoot, modelPacketPath);
  if (
    !input.modelPacketPath ||
    relativeModelPacketPath.startsWith('..') ||
    path.isAbsolute(relativeModelPacketPath)
  ) {
    throw new Error('audit_judge_model_packet_path_invalid');
  }
  if (!fs.existsSync(modelPacketPath) || !fs.statSync(modelPacketPath).isFile()) {
    throw new Error('audit_judge_model_packet_missing');
  }
  if (
    !/^sha256:[a-f0-9]{64}$/u.test(input.modelPacketHash) ||
    sha256File(modelPacketPath) !== input.modelPacketHash
  ) {
    throw new Error('audit_judge_model_packet_hash_mismatch');
  }
  const packet = readJsonIfExists(modelPacketPath);
  if (
    !packet ||
    normalizeText(packet.schemaVersion) !== 'req-trace-ai-tdd-model-packet/v1'
  ) {
    throw new Error('audit_judge_model_packet_schema_invalid');
  }
  const sourceDocument = normalizeText(packet.sourceDocument);
  if (!sourceDocument) {
    throw new Error('audit_judge_source_document_missing');
  }
  if (
    !/^sha256:[a-f0-9]{64}$/u.test(input.sourceDocumentHash) ||
    normalizeText(packet.sourceDocumentHash) !== input.sourceDocumentHash
  ) {
    throw new Error('audit_judge_source_document_hash_mismatch');
  }
  const sourcePath = path.resolve(projectRoot, sourceDocument);
  const relativeSourcePath = path.relative(projectRoot, sourcePath);
  if (
    path.isAbsolute(sourceDocument) ||
    relativeSourcePath.startsWith('..') ||
    path.isAbsolute(relativeSourcePath)
  ) {
    throw new Error('audit_judge_source_document_path_invalid');
  }
  if (!fs.existsSync(sourcePath) || !fs.statSync(sourcePath).isFile()) {
    throw new Error('audit_judge_source_document_missing');
  }
  const projectRealPath = fs.realpathSync(projectRoot);
  const sourceRealPath = fs.realpathSync(sourcePath);
  const relativeRealSourcePath = path.relative(projectRealPath, sourceRealPath);
  if (
    relativeRealSourcePath.startsWith('..') ||
    path.isAbsolute(relativeRealSourcePath)
  ) {
    throw new Error('audit_judge_source_document_realpath_escape');
  }
  const sourceText = fs.readFileSync(sourcePath, 'utf8');
  const extracted = extractRequirementsContractImplementationConfirmation(sourceText);
  if (
    sourceDocumentHashForContract(
      sourceText,
      extracted.blockText,
      extracted.value
    ) !== input.sourceDocumentHash
  ) {
    throw new Error('audit_judge_source_document_hash_mismatch');
  }
  const mustAuthority = compiledModelPacketMustAuthority(packet);
  if (mustAuthority.mustRefs.length === 0) {
    throw new Error('audit_judge_must_refs_missing');
  }
  const projectionInventory = compiledModelPacketProjectionInventory(packet);
  if (
    projectionInventory.projectionGroups.length === 0 ||
    projectionInventory.projectionRefs.length === 0
  ) {
    throw new Error('audit_judge_projection_inventory_missing');
  }
  const derivedProjectionSetHash = projectionSetHashForContract(
    projectionInventory.projectionRefs
  );
  if (derivedProjectionSetHash !== input.projectionSetHash) {
    throw new Error('audit_judge_projection_set_hash_mismatch');
  }
  return {
    sourceDocument: relativeSourcePath.replace(/\\/gu, '/'),
    sourceBytesHash: sha256File(sourcePath),
    mustRefs: mustAuthority.mustRefs,
    sourceRequirementTexts: mustAuthority.sourceRequirementTexts,
    packetProjectionSummary: {
      mustPacketCount: mustAuthority.mustRefs.length,
      projectionGroups: projectionInventory.projectionGroups,
      projectionRefs: projectionInventory.projectionRefs,
    },
  };
}

function packetTopLevelProjectionInventoryMatches(
  packet: Record<string, unknown>,
  confirmation: Record<string, unknown>
): boolean {
  const stored = recordObject(packet.topLevelProjectionInventory);
  return (
    sha256Json({
      projectionGroups: uniqueStrings(asStringArray(stored.projectionGroups)).sort(),
      projectionRefs: uniqueStrings(asStringArray(stored.projectionRefs)).sort(),
    }) === sha256Json(projectionInventoryFromConfirmation(confirmation))
  );
}

function criticalAuditorProjectionInventory(
  packet: Record<string, unknown>,
  confirmation?: Record<string, unknown>
): {
  projectionGroups: string[];
  projectionRefs: string[];
} {
  if (
    normalizeText(packet.schemaVersion) === 'req-trace-ai-tdd-model-packet/v1'
  ) {
    return compiledModelPacketProjectionInventory(packet);
  }
  const projectionGroups = new Set<string>(CRITICAL_AUDITOR_PROJECTION_GROUPS);
  const projectionRefs = new Set<string>(projectionRefsFromPacket(packet));
  const storedTopLevelInventory = recordObject(packet.topLevelProjectionInventory);
  const topLevelInventory = confirmation
    ? projectionInventoryFromConfirmation(confirmation)
    : {
        projectionGroups: asStringArray(storedTopLevelInventory.projectionGroups),
        projectionRefs: asStringArray(storedTopLevelInventory.projectionRefs),
      };
  for (const group of topLevelInventory.projectionGroups) {
    projectionGroups.add(group);
  }
  for (const ref of topLevelInventory.projectionRefs) {
    projectionRefs.add(ref);
  }
  return {
    projectionGroups: [...projectionGroups].sort(),
    projectionRefs: [...projectionRefs].sort(),
  };
}

function criticalAuditorProjectionSetHash(
  packet: Record<string, unknown>,
  confirmation?: Record<string, unknown>
): string {
  return projectionSetHashForContract(
    criticalAuditorProjectionInventory(packet, confirmation).projectionRefs
  );
}

function criticalAuditorAuditAttemptId(input: {
  transactionId: string;
  auditInputHash: string;
}): string {
  return `critical-auditor-attempt/${sha256Json(input).slice(
    'sha256:'.length,
    'sha256:'.length + 24
  )}`;
}

function criticalAuditorIndependentProviderExpectationFromRequest(
  request: Record<string, unknown>
): {
  expectation: CriticalAuditorIndependentProviderExpectation | null;
  issueCodes: string[];
} {
  const binding = recordObject(request.independentProviderBinding);
  const issueCodes = asStringArray(request.independentProviderBindingIssueCodes);
  if (Object.keys(binding).length === 0) {
    issueCodes.push('critical_auditor_judge_provider_registry_required');
  }
  const configuredModel = normalizeConfiguredModel(binding.model);
  if (!Object.hasOwn(binding, 'model') || configuredModel === undefined) {
    issueCodes.push('critical_auditor_model_missing');
  }
  const required = {
    providerId: normalizeText(binding.providerId),
    transport: normalizeText(binding.transport),
    adapterRef: normalizeText(binding.adapterRef),
    apiStyle: normalizeText(binding.apiStyle),
    configuredBaseUrlHash: normalizeText(binding.configuredBaseUrlHash),
    independenceClass: normalizeText(binding.independenceClass),
    providerRegistryHash: normalizeText(binding.providerRegistryHash),
    providerConfigurationHash: normalizeText(binding.providerConfigurationHash),
    requestHash: normalizeText(request.requestHash),
    sourceDocumentHash: normalizeText(request.sourceDocumentHash),
    sourceBytesHash: normalizeText(request.sourceBytesHash),
    semanticModelHash: normalizeText(request.semanticModelHash),
    projectionSetHash: normalizeText(request.projectionSetHash),
  };
  for (const [field, value] of Object.entries(required)) {
    if (!value) {
      issueCodes.push(
        `critical_auditor_${field.replace(/[A-Z]/gu, (char) => `_${char.toLowerCase()}`)}_missing`
      );
    }
  }
  if (
    required.sourceBytesHash &&
    !/^sha256:[a-f0-9]{64}$/u.test(required.sourceBytesHash)
  ) {
    issueCodes.push('critical_auditor_source_bytes_hash_invalid');
  }
  if (issueCodes.length > 0) {
    return { expectation: null, issueCodes: [...new Set(issueCodes)] };
  }
  return {
    expectation: {
      transactionId: normalizeText(request.transactionId) || undefined,
      auditAttemptId: normalizeText(request.auditAttemptId) || undefined,
      providerId: required.providerId,
      model: configuredModel ?? null,
      transport: required.transport,
      adapterRef: required.adapterRef,
      apiStyle: required.apiStyle,
      configuredBaseUrlHash: required.configuredBaseUrlHash,
      independenceClass: required.independenceClass,
      providerRegistryHash: required.providerRegistryHash,
      providerConfigurationHash: required.providerConfigurationHash,
      requestHash: required.requestHash,
      sourceDocumentHash: required.sourceDocumentHash,
      semanticModelHash: required.semanticModelHash,
      projectionSetHash: required.projectionSetHash,
    },
    issueCodes: [],
  };
}

function actionableDryRunIssues(
  report: Record<string, unknown> | null
): PreConfirmationDrilldownIssue[] {
  return collectBlockingIssuesFromReports(report).filter(
    (issue) => !CRITICAL_AUDITOR_ACTIONABLE_DRY_RUN_EXCLUSIONS.has(issue.code)
  );
}

function buildCriticalAuditorGateDryRunSummary(input: {
  root: string;
  sourcePath: string;
  paths: PreConfirmationPaths;
  roundIndex: number;
}): CriticalAuditorGateDryRunSummary {
  const dryRunBase = path.join(
    input.paths.authoringDir,
    `pre-render-must-decomposition-gate-dry-run-round-${input.roundIndex}`
  );
  const reportPath = `${dryRunBase}.json`;
  const receiptPath = `${dryRunBase}-receipt.json`;
  const reconciliationReportPath = `${dryRunBase}-reconciliation.json`;
  const mustGateScript = resolveSkillScript(input.root, 'pre_render_must_decomposition_gate.js');
  const dryRun = runNodeJson(
    mustGateScript,
    [
      '--source',
      input.sourcePath,
      '--authoring-dir',
      input.paths.authoringDir,
      '--semantic-kernel',
      input.paths.semanticKernel,
      '--must-decomposition-packet',
      input.paths.mustDecompositionPacket,
      '--out',
      reportPath,
      '--receipt',
      receiptPath,
      '--reconciliation-report',
      reconciliationReportPath,
      '--json',
    ],
    input.root
  );
  const report = dryRun.json ?? readJsonIfExists(reportPath);
  const reconciliation = readJsonIfExists(reconciliationReportPath);
  const blockingIssues = report
    ? collectBlockingIssuesFromReports(report)
    : [commandFailureIssue('critical_auditor_gate_dry_run_report_missing', mustGateScript, dryRun)];
  const actionableBlockingIssues = actionableDryRunIssues(report).concat(
    report
      ? []
      : [
          commandFailureIssue(
            'critical_auditor_gate_dry_run_report_missing',
            mustGateScript,
            dryRun
          ),
        ]
  );
  const summary = {
    reportPath,
    receiptPath,
    reconciliationReportPath,
    verdict: normalizeText(report?.verdict) || (dryRun.status === 0 ? 'PASS' : 'FAIL'),
    failedChecks: asStringArray(report?.failedChecks),
    blockingIssues,
    actionableBlockingIssues,
    actionableBlockingIssueCount: actionableBlockingIssues.length,
    reconciliation: {
      verdict: normalizeText(
        reconciliation?.verdict ?? recordObject(report?.packetSourceReconciliation).verdict
      ),
      issueCount: Number(reconciliation?.issueCount ?? 0),
      checkedGroups: asStringArray(reconciliation?.checkedGroups),
    },
  };
  return {
    ...summary,
    hash: sha256Json({
      schemaVersion: 'critical-auditor-gate-dry-run-summary/v1',
      roundIndex: input.roundIndex,
      verdict: summary.verdict,
      failedChecks: summary.failedChecks,
      actionableBlockingIssues: summary.actionableBlockingIssues.map((issue) => ({
        code: issue.code,
        message: issue.message,
        refs: issue.refs,
      })),
      reconciliation: summary.reconciliation,
    }),
  };
}

function runCriticalAuditorReceiptLoop(input: {
  root: string;
  sourcePath: string;
  paths: PreConfirmationPaths;
  transaction: CriticalAuditorStagingTransaction;
  auditInputHash: string;
  recordId: string;
  requirementSetId: string;
  implementationAttemptId: string;
  sourceDocumentHash: string;
  semanticModelHash: string;
  implementationConfirmationHash: string;
  packetHash: string;
  mustRefs: string[];
  sourceRequirementTexts: string[];
  mustPacketCount: number;
  packet: Record<string, unknown>;
  createdAt: string;
  roundProvider?: (round: CriticalAuditorRoundInput) => CriticalAuditorRoundResult;
  maxRounds?: number;
}): {
  latestReceiptHash: string | null;
  consecutiveNoNewGapRounds: number;
  receipts: Record<string, unknown>[];
  requestPath?: string | null;
  continuation?: Record<string, unknown> | null;
  issues: PreConfirmationDrilldownIssue[];
} {
  const sourceText = fs.readFileSync(input.sourcePath, 'utf8');
  const currentSourceBytesHash = sha256File(input.sourcePath);
  const sourceExtraction = extractImplementationConfirmationBlock(sourceText);
  if (!sourceExtraction) {
    return {
      latestReceiptHash: null,
      consecutiveNoNewGapRounds: 0,
      receipts: [],
      issues: [
        preConfirmationIssue(
          'critical_auditor_source_confirmation_missing',
          'Critical Auditor production loop requires the current staging source implementationConfirmation.',
          [toRootRelativePath(input.root, input.sourcePath)],
          'critical_auditor'
        ),
      ],
    };
  }
  const projectionInventory = criticalAuditorProjectionInventory(
    input.packet,
    sourceExtraction.confirmation
  );
  const projectionSetHash = projectionSetHashForContract(
    projectionInventory.projectionRefs
  );
  const auditAttemptId = criticalAuditorAuditAttemptId({
    transactionId: input.transaction.transactionId,
    auditInputHash: input.auditInputHash,
  });
  const preflight = runCriticalAuditorPreflightCheckpoints({
    root: input.root,
    sourcePath: input.sourcePath,
    paths: input.paths,
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    implementationAttemptId: input.implementationAttemptId,
    sourceDocumentHash: input.sourceDocumentHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    createdAt: input.createdAt,
  });
  if (!preflight.ok) {
    return {
      latestReceiptHash: null,
      consecutiveNoNewGapRounds: 0,
      receipts: [],
      issues: [preflight.issue],
    };
  }
  const providerBinding = buildCriticalAuditorJudgeRuntimeBinding(
    readGovernanceRemediationConfig(input.root).judgeRuntime
  );
  const receipts: Record<string, unknown>[] = [];
  const bindingRounds: CriticalAuditorReceiptBindingRound[] = [];
  const issues: PreConfirmationDrilldownIssue[] = [];
  let latestReceiptHash: string | null = null;
  let consecutiveNoNewGapRounds = 0;
  if (!input.roundProvider) {
    const roundIndex = 1;
    const gateDryRun = buildCriticalAuditorGateDryRunSummary({
      root: input.root,
      sourcePath: input.sourcePath,
      paths: input.paths,
      roundIndex,
    });
    const candidateRequest = buildCriticalAuditorRoundRequest({
      root: input.root,
      sourcePath: input.sourcePath,
      recordId: input.recordId,
      roundIndex,
      transactionId: input.transaction.transactionId,
      namespaceVersion: input.transaction.namespaceVersion,
      sourceDocumentHash: input.sourceDocumentHash,
      semanticModelHash: input.semanticModelHash,
      implementationConfirmationHash: input.implementationConfirmationHash,
      packetHash: input.packetHash,
      projectionSetHash,
      auditAttemptId,
      independentProviderBinding: providerBinding.binding,
      independentProviderBindingIssueCodes: providerBinding.issueCodes,
      auditInputHash: input.auditInputHash,
      mustRequirements: input.mustRefs.map((id, index) => ({
        id,
        text: input.sourceRequirementTexts[index] ?? id,
        sourceLine: index + 1,
      })),
      packet: input.packet,
      confirmation: sourceExtraction.confirmation,
      previousReceipts: [],
      gateDryRun,
      createdAt: input.createdAt,
    });
    const requestPath = criticalAuditorRequestPath(input.transaction, roundIndex);
    writeOrReuseCriticalAuditorRoundRequest({
      requestPath,
      candidate: candidateRequest,
    });
    const providerIssue = preConfirmationIssue(
      'critical_auditor_provider_mode_required',
      'A real Critical Auditor round provider is required; synthetic clean receipts are not allowed',
      ['critical_auditor_receipt_loop'],
      'critical_auditor'
    );
    const outcomeCommit = commitCriticalAuditorCheckpointOutcome({
      root: input.root,
      sourcePath: input.sourcePath,
      paths: input.paths,
      transaction: input.transaction,
      recordId: input.recordId,
      requirementSetId: input.requirementSetId,
      implementationAttemptId: input.implementationAttemptId,
      auditInputHash: input.auditInputHash,
      sourceDocumentHash: input.sourceDocumentHash,
      semanticModelHash: input.semanticModelHash,
      implementationConfirmationHash: input.implementationConfirmationHash,
      packetHash: input.packetHash,
      projectionSetHash,
      roundIndex,
      requestPath,
      bindingRounds,
      blockingIssues: [providerIssue],
      createdAt: input.createdAt,
    });
    return {
      latestReceiptHash: null,
      consecutiveNoNewGapRounds: 0,
      receipts: [],
      requestPath,
      continuation: {
        providerMode: 'main_session_inline',
        transactionId: input.transaction.transactionId,
        namespaceVersion: input.transaction.namespaceVersion,
        roundIndex,
        requestPath: toRootRelativePath(input.root, requestPath),
        responsePath: toRootRelativePath(
          input.root,
          criticalAuditorResponsePath(input.transaction, roundIndex)
        ),
        nextRequiredAction: 'run_main_session_critical_auditor_round',
      },
      issues: [
        providerIssue,
        ...(outcomeCommit.ok ? [] : [outcomeCommit.issue]),
      ],
    };
  }
  const provider = input.roundProvider;
  const maxRounds = input.maxRounds && input.maxRounds > 0 ? input.maxRounds : 12;

  for (
    let roundIndex = 1;
    roundIndex <= maxRounds && consecutiveNoNewGapRounds < 3;
    roundIndex += 1
  ) {
    const gateDryRun = buildCriticalAuditorGateDryRunSummary({
      root: input.root,
      sourcePath: input.sourcePath,
      paths: input.paths,
      roundIndex,
    });
    const roundPerspective = criticalAuditorRoundPerspective(roundIndex);
    const candidateRequest = buildCriticalAuditorRoundRequest({
      root: input.root,
      sourcePath: input.sourcePath,
      recordId: input.recordId,
      roundIndex,
      transactionId: input.transaction.transactionId,
      namespaceVersion: input.transaction.namespaceVersion,
      sourceDocumentHash: input.sourceDocumentHash,
      semanticModelHash: input.semanticModelHash,
      implementationConfirmationHash: input.implementationConfirmationHash,
      packetHash: input.packetHash,
      projectionSetHash,
      auditAttemptId,
      independentProviderBinding: providerBinding.binding,
      independentProviderBindingIssueCodes: providerBinding.issueCodes,
      auditInputHash: input.auditInputHash,
      mustRequirements: input.mustRefs.map((id, index) => ({
        id,
        text: input.sourceRequirementTexts[index] ?? id,
        sourceLine: index + 1,
      })),
      packet: input.packet,
      confirmation: sourceExtraction.confirmation,
      previousReceipts: receipts,
      gateDryRun,
      createdAt: input.createdAt,
    });
    const requestPath = criticalAuditorRequestPath(input.transaction, roundIndex);
    const responsePath = criticalAuditorResponsePath(input.transaction, roundIndex);
    const receiptPath = criticalAuditorReceiptPath(input.transaction, roundIndex);
    const mirrorPath = path.join(
      input.paths.authoringDir,
      `critical-auditor-receipt-round-${roundIndex}.json`
    );
    const commitRoundOutcome = (outcomeInput: {
      receipt?: Record<string, unknown> | null;
      includeResponse?: boolean;
      blockingIssues: PreConfirmationDrilldownIssue[];
    }) =>
      commitCriticalAuditorCheckpointOutcome({
        root: input.root,
        sourcePath: input.sourcePath,
        paths: input.paths,
        transaction: input.transaction,
        recordId: input.recordId,
        requirementSetId: input.requirementSetId,
        implementationAttemptId: input.implementationAttemptId,
        auditInputHash: input.auditInputHash,
        sourceDocumentHash: input.sourceDocumentHash,
        semanticModelHash: input.semanticModelHash,
        implementationConfirmationHash: input.implementationConfirmationHash,
        packetHash: input.packetHash,
        projectionSetHash,
        roundIndex,
        requestPath,
        responsePath: outcomeInput.includeResponse ? responsePath : null,
        receiptPath: outcomeInput.receipt ? receiptPath : null,
        receipt: outcomeInput.receipt,
        bindingRounds,
        blockingIssues: outcomeInput.blockingIssues,
        createdAt: input.createdAt,
      });
    const existingRequest = readJsonIfExists(requestPath);
    const existingResponse = readJsonIfExists(responsePath);
    const existingReceipt = unwrapCriticalAuditorReceipt(readJsonIfExists(receiptPath));
    const existingFrozenGateDryRun = existingRequest
      ? criticalAuditorGateDryRunSummaryFromRequest(existingRequest, gateDryRun)
      : null;
    const reusablePublishedRequest =
      existingRequest &&
      existingFrozenGateDryRun &&
      criticalAuditorPublishedRoundRequestCanReuseReceipt({
        existingRequest,
        candidateRequest,
        existingGateDryRun: existingFrozenGateDryRun,
        currentGateDryRun: gateDryRun,
      })
        ? existingRequest
        : null;
    const reusablePublishedReceipt =
      reusablePublishedRequest &&
      existingFrozenGateDryRun &&
      criticalAuditorReceiptMatchesCurrent({
        projectRoot: input.root,
        receipt: existingReceipt,
        response: existingResponse,
        roundIndex,
        transaction: input.transaction,
        auditInputHash: input.auditInputHash,
        recordId: input.recordId,
        sourceDocumentHash: input.sourceDocumentHash,
        sourceBytesHash: currentSourceBytesHash,
        semanticModelHash: input.semanticModelHash,
        implementationConfirmationHash: input.implementationConfirmationHash,
        packetHash: input.packetHash,
        projectionSetHash,
        requestHash: normalizeText(reusablePublishedRequest.requestHash),
        gateDryRunHash: existingFrozenGateDryRun.hash,
      })
        ? existingReceipt
        : null;
    const request =
      reusablePublishedRequest
        ? reusablePublishedRequest
        : writeOrReuseCriticalAuditorRoundRequest({
            requestPath,
            candidate: candidateRequest,
          });
    const frozenGateDryRun =
      reusablePublishedRequest && existingFrozenGateDryRun
        ? existingFrozenGateDryRun
        : criticalAuditorGateDryRunSummaryFromRequest(request, gateDryRun);
    const requestSourceBytesHash = normalizeText(request.sourceBytesHash);
    if (!/^sha256:[a-f0-9]{64}$/u.test(requestSourceBytesHash)) {
      const sourceBindingIssue = preConfirmationIssue(
        'critical_auditor_request_source_bytes_hash_invalid',
        `Critical Auditor request round ${roundIndex} lacks a valid frozen sourceBytesHash.`,
        [requestPath, 'sourceBytesHash'],
        'critical_auditor'
      );
      issues.push(sourceBindingIssue);
      const outcomeCommit = commitRoundOutcome({
        blockingIssues: [sourceBindingIssue],
      });
      if (!outcomeCommit.ok) {
        issues.push(outcomeCommit.issue);
      }
      break;
    }
    let receipt: Record<string, unknown> | null = reusablePublishedReceipt;
    if (
      !receipt &&
      criticalAuditorReceiptMatchesCurrent({
        projectRoot: input.root,
        receipt: existingReceipt,
        response: existingResponse,
        roundIndex,
        transaction: input.transaction,
        auditInputHash: input.auditInputHash,
        recordId: input.recordId,
        sourceDocumentHash: input.sourceDocumentHash,
        sourceBytesHash: requestSourceBytesHash,
        semanticModelHash: input.semanticModelHash,
        implementationConfirmationHash: input.implementationConfirmationHash,
        packetHash: input.packetHash,
        projectionSetHash,
        requestHash: normalizeText(request.requestHash),
        gateDryRunHash: frozenGateDryRun.hash,
      })
    ) {
      receipt = existingReceipt;
    }
    let acceptedResponse = receipt ? existingResponse : null;
    if (!receipt) {
      if (!providerBinding.binding) {
        const bindingFailureIssues = providerBinding.issueCodes.map((code) =>
          preConfirmationIssue(
            code,
            `Critical Auditor Judge runtime binding is invalid: ${code}`,
            ['judgeRuntime'],
            'critical_auditor'
          )
        );
        issues.push(...bindingFailureIssues);
        const outcomeCommit = commitRoundOutcome({
          blockingIssues: bindingFailureIssues,
        });
        if (!outcomeCommit.ok) {
          issues.push(outcomeCommit.issue);
        }
        break;
      }
      const independentProviderExpectation: CriticalAuditorIndependentProviderExpectation = {
        ...providerBinding.binding,
        transactionId: input.transaction.transactionId,
        auditAttemptId,
        requestHash: normalizeText(request.requestHash),
        sourceDocumentHash: input.sourceDocumentHash,
        semanticModelHash: input.semanticModelHash,
        projectionSetHash,
      };
      let auditResult: CriticalAuditorRoundResult;
      try {
        auditResult = provider({
          roundIndex,
          transactionId: input.transaction.transactionId,
          namespaceVersion: input.transaction.namespaceVersion,
          auditInputHash: input.auditInputHash,
          recordId: input.recordId,
          requirementSetId: input.requirementSetId,
          implementationAttemptId: input.implementationAttemptId,
          sourceDocumentHash: input.sourceDocumentHash,
          sourceBytesHash: requestSourceBytesHash,
          semanticModelHash: input.semanticModelHash,
          implementationConfirmationHash: input.implementationConfirmationHash,
          packetHash: input.packetHash,
          projectionSetHash,
          independentProviderExpectation,
          roundPerspective,
          gateDryRun: frozenGateDryRun,
          packetProjectionSummary: {
            projectionGroups: projectionInventory.projectionGroups,
            projectionRefs: projectionInventory.projectionRefs,
          },
          mustRefs: input.mustRefs,
          sourceRequirementTexts: input.sourceRequirementTexts,
          mustPacketCount: input.mustPacketCount,
          consecutiveNoNewGapRounds,
          previousReceipts: receipts,
        });
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        const code = normalizeText(message.split(':')[0]) || 'critical_auditor_provider_failed';
        const providerFailureIssue = preConfirmationIssue(
          code,
          message,
          [`round-${roundIndex}`],
          'critical_auditor'
        );
        issues.push(providerFailureIssue);
        const outcomeCommit = commitRoundOutcome({
          blockingIssues: [providerFailureIssue],
        });
        if (!outcomeCommit.ok) {
          issues.push(outcomeCommit.issue);
        }
        break;
      }
      const bindingIssues = validateCriticalAuditorRoundResultBinding({
        projectRoot: input.root,
        roundIndex,
        auditResult,
        gateDryRun: frozenGateDryRun,
        previousReceipts: receipts,
        packet: input.packet,
        sourceText,
        confirmation: sourceExtraction.confirmation,
        independentProviderExpectation,
        sourceBytesHash: requestSourceBytesHash,
      });
      if (bindingIssues.length > 0) {
        const judgeAdapterHostExecution = recordObject(
          auditResult.judgeAdapterHostExecution
        );
        const productionJudgeAdapterResult = [
          'package_cli_external_adapter',
          'committed_provider_invocation_recovery',
        ].includes(normalizeText(judgeAdapterHostExecution.adapterKind));
        let rejectionRecordingIssue: PreConfirmationDrilldownIssue | null = null;
        let providerContractBlockedIssue: PreConfirmationDrilldownIssue | null = null;
        if (productionJudgeAdapterResult) {
          const outputDir = criticalAuditorJudgeInvocationOutputDir({
            stagingDir: input.transaction.stagingDir,
            roundIndex,
            requestHash: normalizeText(request.requestHash),
          });
          try {
            const rejectionDisposition =
              rejectCommittedRequirementsContractCriticalAuditorJudgeInvocation({
              projectRoot: input.root,
              request: requestPath,
              outputDir,
              round: roundIndex,
              semanticIssueCodes: bindingIssues.map((issue) => issue.code),
            });
            if (
              normalizeText(rejectionDisposition.decision) ===
              'provider_contract_blocked'
            ) {
              providerContractBlockedIssue = preConfirmationIssue(
                'critical_auditor_judge_provider_contract_blocked',
                `Judge provider contract repeated the same invalid semantic response (${normalizeText(
                  rejectionDisposition.semanticIssueFingerprint
                )}); repair of Source authority is not permitted for this failure domain.`,
                [
                  normalizeText(rejectionDisposition.providerContractBlockedPath),
                  normalizeText(rejectionDisposition.semanticRejectionPath),
                ].filter(Boolean),
                'critical_auditor'
              );
            }
          } catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            rejectionRecordingIssue = preConfirmationIssue(
              'critical_auditor_judge_semantic_rejection_record_failed',
              message,
              [requestPath, outputDir],
              'critical_auditor'
            );
          }
        }
        const blockingIssues = [
          ...bindingIssues,
          ...(providerContractBlockedIssue ? [providerContractBlockedIssue] : []),
          ...(rejectionRecordingIssue ? [rejectionRecordingIssue] : []),
        ];
        issues.push(...blockingIssues);
        const outcomeCommit = commitRoundOutcome({
          blockingIssues,
        });
        if (!outcomeCommit.ok) {
          issues.push(outcomeCommit.issue);
        }
        break;
      }
      const responseExpectation = {
        roundIndex,
        transactionId: input.transaction.transactionId,
        namespaceVersion: input.transaction.namespaceVersion,
        sourceDocumentHash: input.sourceDocumentHash,
        sourceBytesHash: requestSourceBytesHash,
        semanticModelHash: input.semanticModelHash,
        implementationConfirmationHash: input.implementationConfirmationHash,
        packetHash: input.packetHash,
        projectionSetHash,
        requestHash: normalizeText(request.requestHash),
        gateDryRunHash: frozenGateDryRun.hash,
      };
      const canonicalResponse = buildCriticalAuditorResponseArtifact({
        roundIndex,
        transaction: input.transaction,
        requestHash: responseExpectation.requestHash,
        sourceDocumentHash: input.sourceDocumentHash,
        sourceBytesHash: requestSourceBytesHash,
        semanticModelHash: input.semanticModelHash,
        implementationConfirmationHash: input.implementationConfirmationHash,
        packetHash: input.packetHash,
        projectionSetHash,
        gateDryRunHash: frozenGateDryRun.hash,
        auditResult,
      });
      let persistedResponse = readJsonIfExists(responsePath);
      const persistedResponseConflicts = () =>
        Boolean(
          persistedResponse &&
            (!criticalAuditorResponseArtifactMatchesExpectation(
              persistedResponse,
              responseExpectation
            ) ||
              sha256Json(persistedResponse) !== sha256Json(canonicalResponse))
        );
      const staleReceiptRequestHash = normalizeText(existingReceipt?.requestHash);
      const staleReceiptGateDryRunHash = normalizeText(existingReceipt?.gateDryRunHash);
      if (
        persistedResponseConflicts() &&
        staleReceiptRequestHash &&
        staleReceiptRequestHash !== responseExpectation.requestHash &&
        staleReceiptGateDryRunHash &&
        criticalAuditorReceiptMatchesCurrent({
          projectRoot: input.root,
          receipt: existingReceipt,
          response: persistedResponse,
          roundIndex,
          transaction: input.transaction,
          auditInputHash: input.auditInputHash,
          recordId: input.recordId,
          sourceDocumentHash: input.sourceDocumentHash,
          sourceBytesHash: requestSourceBytesHash,
          semanticModelHash: input.semanticModelHash,
          implementationConfirmationHash: input.implementationConfirmationHash,
          packetHash: input.packetHash,
          projectionSetHash,
          requestHash: staleReceiptRequestHash,
          gateDryRunHash: staleReceiptGateDryRunHash,
        })
      ) {
        archiveSupersededCriticalAuditorRoundArtifacts({
          root: input.root,
          transaction: input.transaction,
          roundIndex,
          currentRequestHash: responseExpectation.requestHash,
          staleReceipt: existingReceipt!,
          responsePath,
          receiptPath,
          mirrorPath,
        });
        persistedResponse = null;
      }
      if (
        persistedResponseConflicts()
      ) {
        const responseConflictIssue = preConfirmationIssue(
          'critical_auditor_response_conflicts_with_provider_result',
          'A pre-existing Critical Auditor response differs from the canonical response produced by the current real provider invocation.',
          [responsePath],
          'critical_auditor'
        );
        issues.push(responseConflictIssue);
        const outcomeCommit = commitRoundOutcome({
          includeResponse: true,
          blockingIssues: [responseConflictIssue],
        });
        if (!outcomeCommit.ok) {
          issues.push(outcomeCommit.issue);
        }
        break;
      }
      acceptedResponse = persistedResponse ?? canonicalResponse;
      if (!persistedResponse) {
        writeJsonUtf8(responsePath, canonicalResponse);
      }
      const candidateReceipt = buildCriticalAuditorReceipt({
        roundIndex,
        transactionId: input.transaction.transactionId,
        namespaceVersion: input.transaction.namespaceVersion,
        requestHash: normalizeText(request.requestHash),
        gateDryRunHash: frozenGateDryRun.hash,
        responseHash: sha256Json(acceptedResponse),
        auditInputHash: input.auditInputHash,
        recordId: input.recordId,
        sourceDocumentHash: input.sourceDocumentHash,
        sourceBytesHash: requestSourceBytesHash,
        semanticModelHash: input.semanticModelHash,
        implementationConfirmationHash: input.implementationConfirmationHash,
        packetHash: input.packetHash,
        projectionSetHash,
        independentProviderExpectation,
        createdAt: input.createdAt,
        auditResult,
      });
      const bindingValidation = validateCriticalAuditorReceiptBinding({
        receipt: candidateReceipt,
        response: acceptedResponse,
        expectation: {
          roundIndex,
          transactionId: input.transaction.transactionId,
          namespaceVersion: input.transaction.namespaceVersion,
          auditInputHash: input.auditInputHash,
          recordId: input.recordId,
          sourceDocumentHash: input.sourceDocumentHash,
          sourceBytesHash: requestSourceBytesHash,
          semanticModelHash: input.semanticModelHash,
          implementationConfirmationHash: input.implementationConfirmationHash,
          packetHash: input.packetHash,
          projectionSetHash,
          requestHash: normalizeText(request.requestHash),
          gateDryRunHash: frozenGateDryRun.hash,
        },
      });
      if (!bindingValidation.ok) {
        const receiptBindingIssues = bindingValidation.issueCodes.map((code) =>
          preConfirmationIssue(
            code,
            `Critical Auditor receipt binding is invalid: ${code}`,
            [responsePath, receiptPath],
            'critical_auditor'
          )
        );
        issues.push(...receiptBindingIssues);
        const outcomeCommit = commitRoundOutcome({
          includeResponse: true,
          blockingIssues: receiptBindingIssues,
        });
        if (!outcomeCommit.ok) {
          issues.push(outcomeCommit.issue);
        }
        break;
      }
      receipt = candidateReceipt;
    }
    if (!receipt || !acceptedResponse) {
      break;
    }
    latestReceiptHash = normalizeText(receipt.receiptHash);
    receipts.push(receipt);
    bindingRounds.push({
      receipt,
      response: acceptedResponse,
      expectation: {
        roundIndex,
        transactionId: input.transaction.transactionId,
        namespaceVersion: input.transaction.namespaceVersion,
        auditInputHash: input.auditInputHash,
        recordId: input.recordId,
        sourceDocumentHash: input.sourceDocumentHash,
        sourceBytesHash: requestSourceBytesHash,
        semanticModelHash: input.semanticModelHash,
        implementationConfirmationHash: input.implementationConfirmationHash,
        packetHash: input.packetHash,
        projectionSetHash,
        requestHash: normalizeText(request.requestHash),
        gateDryRunHash: frozenGateDryRun.hash,
      },
    });
    writeCriticalAuditorReceiptMirror({
      rootReceiptPath: receiptPath,
      mirrorPath,
      transaction: input.transaction,
      authoringDir: input.paths.authoringDir,
      receipt,
    });

    const verdict = normalizeCriticalAuditorVerdict(
      recordObject(receipt.convergenceDecision).verdict
    );
    const roundBlockingIssues: PreConfirmationDrilldownIssue[] = [];
    if (verdict === 'blocked' || verdict === 'insufficient_audit') {
      roundBlockingIssues.push(
        preConfirmationIssue(
          `critical_auditor_${verdict}`,
          `Critical Auditor round ${roundIndex} returned ${verdict}`,
          [`critical-auditor-receipt-round-${roundIndex}.json`],
          'critical_auditor'
        )
      );
    }

    const unresolvedGaps = asRecordArray(receipt.validatedGaps).filter((gap) => {
      const status = normalizeText(gap.status ?? gap.resolutionStatus);
      return ![
        'resolved',
        'converted_to_out_boundary',
        'converted_to_open_question',
        'rejected',
      ].includes(status);
    });
    if (unresolvedGaps.length > 0) {
      roundBlockingIssues.push(
        preConfirmationIssue(
          'critical_auditor_unresolved_validated_gap',
          `Critical Auditor round ${roundIndex} returned unresolved validated gaps`,
          unresolvedGaps.map((gap) => normalizeText(gap.id ?? gap.code ?? 'gap')),
          'critical_auditor'
        )
      );
    }
    if (verdict === 'new_valid_gap' && unresolvedGaps.length === 0) {
      roundBlockingIssues.push(
        preConfirmationIssue(
          'critical_auditor_new_valid_gap_requires_repair',
          `Critical Auditor round ${roundIndex} returned a new valid gap that requires a new staging repair transaction.`,
          asRecordArray(receipt.validatedGaps).map((gap) =>
            normalizeText(gap.id ?? gap.code ?? 'gap')
          ),
          'critical_auditor'
        )
      );
    }
    consecutiveNoNewGapRounds = isNoNewGapVerdict(verdict) ? consecutiveNoNewGapRounds + 1 : 0;
    const outcomeCommit = commitRoundOutcome({
      receipt,
      includeResponse: true,
      blockingIssues: roundBlockingIssues,
    });
    if (!outcomeCommit.ok) {
      issues.push(outcomeCommit.issue);
      break;
    }
    if (roundBlockingIssues.length > 0) {
      issues.push(...roundBlockingIssues);
      break;
    }
  }

  const derivedConvergence = evaluateCriticalAuditorReceiptBindingSequence(bindingRounds);
  if (!derivedConvergence.ok) {
    issues.push(
      ...derivedConvergence.issueCodes.map((code) =>
        preConfirmationIssue(
          code,
          `Critical Auditor convergence binding is invalid: ${code}`,
          ['critical_auditor_receipt_loop'],
          'critical_auditor'
        )
      )
    );
    consecutiveNoNewGapRounds = 0;
    latestReceiptHash = null;
  } else {
    consecutiveNoNewGapRounds = derivedConvergence.consecutiveValidNoNewGapRounds;
    latestReceiptHash = derivedConvergence.latestReceiptHash;
  }

  if (consecutiveNoNewGapRounds < 3 && issues.length === 0) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_no_new_gap_convergence_not_reached',
        `Critical Auditor did not reach three consecutive no-new-gap rounds within ${maxRounds} rounds`,
        ['critical_auditor_receipt_loop'],
        'critical_auditor'
      )
    );
  }

  return { latestReceiptHash, consecutiveNoNewGapRounds, receipts, issues };
}

function readCriticalAuditorReceipts(authoringDir: string): Record<string, unknown>[] {
  if (!fs.existsSync(authoringDir)) {
    return [];
  }
  return fs
    .readdirSync(authoringDir)
    .filter((fileName) => /^critical-auditor-receipt-round-\d+\.json$/u.test(fileName))
    .map((fileName) => path.join(authoringDir, fileName))
    .map((filePath) => readJsonIfExists(filePath))
    .filter((item): item is Record<string, unknown> => Boolean(item))
    .map((item) => recordObject(item.criticalAuditorReceipt ?? item))
    .sort((left, right) => Number(left.roundIndex ?? 0) - Number(right.roundIndex ?? 0));
}

function unwrapCriticalAuditorReceipt(
  value: Record<string, unknown> | null
): Record<string, unknown> | null {
  const receipt = value?.criticalAuditorReceipt ?? value;
  return receipt && typeof receipt === 'object' && !Array.isArray(receipt)
    ? (receipt as Record<string, unknown>)
    : null;
}

function authoringRepairPaths(root: string, paths: PreConfirmationPaths): Record<string, string> {
  return {
    authoringDir: toRootRelativePath(root, paths.authoringDir),
    semanticKernel: toRootRelativePath(root, paths.semanticKernel),
    mustDecompositionPacket: toRootRelativePath(root, paths.mustDecompositionPacket),
    promotionReceipt: toRootRelativePath(root, paths.promotionReceipt),
    sourceMaterializationReceipt: toRootRelativePath(root, paths.sourceMaterializationReceipt),
    packetSourceReconciliation: toRootRelativePath(root, paths.reconciliationReport),
    semanticCheckpointProgress: toRootRelativePath(root, paths.progress),
    semanticCheckpointReceiptGlob: `${toRootRelativePath(root, paths.authoringDir)}/checkpoint-receipt-cp-*.json`,
    preRenderMustDecompositionGate: toRootRelativePath(root, paths.preRenderMustGate),
  };
}

function authoringRepairCommand(sourcePath: string, _responsePath?: string): string {
  return `main-agent-orchestration --action authoring-repair --mode preserve-existing --source ${sourcePath} --json`;
}

function buildAuthoringRepairResult(input: {
  root: string;
  sourcePath: string;
  recordId: string;
  requirementSetId: string;
  paths: PreConfirmationPaths;
  status: 'blocked' | 'pre_render_ready';
  blockingStage: string | null;
  nextRequiredAction: string;
  repairCommand?: string;
  artifacts?: string[];
  issues?: PreConfirmationDrilldownIssue[];
  warnings?: Array<Record<string, string>>;
  sourceDocumentHash?: string | null;
  implementationConfirmationHash?: string | null;
  packetHash?: string | null;
  consecutiveNoNewGapRounds?: number;
}): MainAgentAuthoringRepairResult {
  return {
    ok: input.status === 'pre_render_ready' && !input.blockingStage,
    status: input.status,
    mode: 'preserve-existing',
    purpose: 'post_materialization_deep_audit',
    purposeGuard: {
      purpose: 'post_materialization_deep_audit',
      requiredEvidence: [
        'current_source_hash',
        'inline_implementationConfirmation',
        'promotion_receipt',
      ],
      blockingStage:
        input.blockingStage === 'promotion_receipt_required_before_audit'
          ? 'promotion_receipt_required_before_deep_audit'
          : input.blockingStage,
      notAllowedBeforeMaterialization: [
        'critical_auditor_round_request_generation',
        'post_materialization_deep_audit',
        'grill_with_docs',
        'docs_review',
      ],
    },
    sourcePath: toRootRelativePath(input.root, input.sourcePath),
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    sourceDocumentHash: input.sourceDocumentHash ?? null,
    implementationConfirmationHash: input.implementationConfirmationHash ?? null,
    packetHash: input.packetHash ?? null,
    blockingStage: input.blockingStage,
    nextRequiredAction: input.nextRequiredAction,
    repairCommand:
      input.repairCommand ??
      authoringRepairCommand(toRootRelativePath(input.root, input.sourcePath)),
    artifacts: (input.artifacts ?? []).map((filePath) => toRootRelativePath(input.root, filePath)),
    paths: authoringRepairPaths(input.root, input.paths),
    blockingIssues: input.issues ?? [],
    warnings: input.warnings ?? [],
    consecutiveNoNewGapRounds: input.consecutiveNoNewGapRounds ?? 0,
  };
}

function buildCriticalAuditorRoundRequest(input: {
  root: string;
  sourcePath: string;
  recordId: string;
  roundIndex: number;
  transactionId?: string;
  namespaceVersion?: string;
  sourceDocumentHash: string;
  semanticModelHash: string;
  implementationConfirmationHash: string;
  packetHash: string;
  projectionSetHash?: string;
  auditAttemptId?: string;
  independentProviderBinding?: CriticalAuditorJudgeRuntimeBinding | null;
  independentProviderBindingIssueCodes?: string[];
  auditInputHash: string;
  mustRequirements: Array<Pick<SourceMustRequirement, 'id' | 'text'>>;
  packet: Record<string, unknown>;
  confirmation: Record<string, unknown>;
  previousReceipts: Record<string, unknown>[];
  gateDryRun: CriticalAuditorGateDryRunSummary;
  createdAt: string;
}): Record<string, unknown> {
  const roundPerspective = criticalAuditorRoundPerspective(input.roundIndex);
  const projectionInventory = criticalAuditorProjectionInventory(
    input.packet,
    input.confirmation
  );
  const semanticModelHash = normalizeText(input.semanticModelHash);
  if (!semanticModelHash.startsWith('sha256:')) {
    throw new Error('critical_auditor_semantic_model_hash_missing');
  }
  const projectionSetHash =
    normalizeText(input.projectionSetHash) ||
    criticalAuditorProjectionSetHash(input.packet, input.confirmation);
  const auditAttemptId =
    normalizeText(input.auditAttemptId) ||
    criticalAuditorAuditAttemptId({
      transactionId: normalizeText(input.transactionId),
      auditInputHash: input.auditInputHash,
    });
  const configuredProviderBinding =
    input.independentProviderBinding !== undefined
      ? {
          binding: input.independentProviderBinding,
          issueCodes: input.independentProviderBindingIssueCodes ?? [],
        }
      : buildCriticalAuditorJudgeRuntimeBinding(
          readGovernanceRemediationConfig(input.root).judgeRuntime
        );
  const request: Record<string, unknown> = {
    schemaVersion: 'critical-auditor-round-request/v1',
    purpose: 'critical_auditor_round',
    purposeGuard: {
      purpose: 'critical_auditor_round',
      parentPurpose: 'staging_transaction_deep_audit',
      requiredEvidence: [
        'gate_dry_run_hash',
        'staging_source_hash',
        'staging_source_bytes_hash',
        'current_implementationConfirmation_hash',
        'current_packet_hash',
      ],
      sourceMaterializationRequiredBeforeDeepAudit: false,
      sourcePromotionForbiddenBeforeConvergence: true,
    },
    recordId: input.recordId,
    roundIndex: input.roundIndex,
    transactionId: input.transactionId,
    namespaceVersion: input.namespaceVersion,
    sourceDocument: toRootRelativePath(input.root, input.sourcePath),
    sourceHash: input.sourceDocumentHash,
    sourceDocumentHash: input.sourceDocumentHash,
    sourceBytesHash: sha256File(input.sourcePath),
    repairActionSourceContract: {
      sourceDocument: toRootRelativePath(input.root, input.sourcePath),
      lineNumbering: 'one_based_inclusive',
      lineEndingNormalization: 'CRLF_to_LF',
      sourceTextNormalization: 'outer_whitespace_trim_only',
      sourceTextRule:
        'sourceText must equal the complete raw source lines selected by sourceSpan, including Markdown delimiters, IDs, and all table cells.',
      unverifiableSourceBehavior: 'return_insufficient_audit_without_repair_action',
    },
    semanticModelHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    packetHash: input.packetHash,
    projectionSetHash,
    auditAttemptId,
    independentProviderBinding: configuredProviderBinding.binding,
    independentProviderBindingIssueCodes: configuredProviderBinding.issueCodes,
    auditInputHash: input.auditInputHash,
    mustRefs: input.mustRequirements.map((requirement) => requirement.id),
    sourceRequirementTexts: input.mustRequirements.map((requirement) => requirement.text),
    packetProjectionSummary: {
      mustPacketCount: asRecordArray(input.packet.mustPackets).length,
      projectionGroups: projectionInventory.projectionGroups,
      projectionRefs: projectionInventory.projectionRefs,
    },
    projectionQualityGate: {
      requiredRuleCodes: PROJECTION_QUALITY_RULE_CODES,
      policy:
        'Every business MUST needs an independent ACC/E2E boundary or explicit per-MUST assertion mapping; shared EVD/CMD/path/currentTarget/business visual rows must declare per-MUST oracle, assertion, or responsibility mappings.',
    },
    previousReceipts: input.previousReceipts,
    roundPerspective,
    gateDryRun: {
      reportPath: toRootRelativePath(input.root, input.gateDryRun.reportPath),
      receiptPath: toRootRelativePath(input.root, input.gateDryRun.receiptPath),
      reconciliationReportPath: toRootRelativePath(
        input.root,
        input.gateDryRun.reconciliationReportPath
      ),
      gateDryRunHash: input.gateDryRun.hash,
      verdict: input.gateDryRun.verdict,
      failedChecks: input.gateDryRun.failedChecks,
      actionableBlockingIssueCount: input.gateDryRun.actionableBlockingIssueCount,
      actionableBlockingIssues: input.gateDryRun.actionableBlockingIssues,
      reconciliation: input.gateDryRun.reconciliation,
    },
    auditStandards: [
      `This round perspective is mandatory: ${normalizeText(roundPerspective.focus)}.`,
      'Consume gateDryRun before giving a verdict; no_new_* is forbidden when actionable gate dry-run blockers exist unless falsePositiveProofs[] provides machine-verifiable proof for every blocker.',
      'Find under-split MUST rows and over-broad atomic tasks.',
      'Find missing packet/source projections for EVD, TRACE, ACC, E2E, failure paths, edge cases, currentTargetMap, AI TDD manifest, commands, and closeout semantics.',
      'Find per-MUST independent acceptance gaps: every business MUST must have a distinct ACC/E2E boundary or explicit per-MUST assertions.',
      'Reject shared EVD, command, target path, currentTargetMap, or business visual rows that cover all MUST rows without per-MUST oracle, assertion, or responsibility mapping.',
      'Every new_valid_gap validated gap must provide non-empty, materializable repairActions[] with source provenance and typed target-field updates.',
      'Every repair action sourceSpan must point into sourceDocument, and sourceText must equal the complete raw source lines at that inclusive span after CRLF-to-LF normalization and outer whitespace trimming.',
      'Read sourceDocument before emitting repairActions; if exact source bytes cannot be verified, return insufficient_audit instead of guessing.',
      'Reject synthetic clean receipts; response must be authored by the main agent or LLM.',
      'Do not write source, packet, receipts, or control state from the response artifact.',
      'Convergence requires three consecutive no-new-valid-gap receipts, deterministic gate PASS, and packet/source reconciliation pass.',
    ],
    requiredResponseSchema: {
      schemaVersion: 'critical-auditor-round-response/v1',
      requestHash: '<copy requestHash>',
      recordId: input.recordId,
      roundIndex: input.roundIndex,
      transactionId: input.transactionId,
      namespaceVersion: input.namespaceVersion,
      sourceHash: input.sourceDocumentHash,
      sourceDocumentHash: input.sourceDocumentHash,
      sourceBytesHash: sha256File(input.sourcePath),
      implementationConfirmationHash: input.implementationConfirmationHash,
      packetHash: input.packetHash,
      semanticModelHash,
      projectionSetHash,
      gateDryRunHash: input.gateDryRun.hash,
      reconciliationIssueCount: input.gateDryRun.reconciliation.issueCount,
      checkedProjectionGroups: projectionInventory.projectionGroups,
      checkedProjectionQualityRuleCodes: PROJECTION_QUALITY_RULE_CODES,
      verdict:
        'no_new_valid_gap | no_new_confirmation_blocking_gap | new_valid_gap | insufficient_audit | blocked',
      reviewedMustRefs: input.mustRequirements.map((requirement) => requirement.id),
      reviewedProjectionRefs: '<non-empty subset of packetProjectionSummary.projectionRefs>',
      priorFindingsDisposition:
        input.previousReceipts.length > 0 ||
        input.gateDryRun.actionableBlockingIssues.length > 0
          ? [
              {
                findingRef: '<previous finding id or dry-run blocker code>',
                disposition: 'new | resolved | unchanged | rejected',
                evidenceRefs: ['<evidence ref>'],
              },
            ]
          : [],
      falsePositiveProofs: [
        {
          blockerCode:
            '<required only when gateDryRun.actionableBlockingIssueCount > 0 and verdict is no_new_*>',
          proofType:
            'current_source_packet_hash_match | source_row_backref_resolves | projection_materialized | reconciliation_count_match',
          evidenceRefs: [],
        },
      ],
      gapCandidates: [],
      validatedGaps: [
        {
          id: '<validated gap id>',
          status: 'validated',
          mustRef: '<affected MUST ref>',
          title: '<concise gap title>',
          rationale: '<why the current semantic projection is insufficient>',
          evidenceRefs: ['<source or projection evidence ref>'],
          blocking: true,
          repairActions: [
            {
              actionId: '<unique repair action id>',
              type:
                'add_must | split_must | add_neg | add_out | add_evidence | add_trace | upsert_trace | upsert_failure_path | upsert_edge_case | add_acc | add_e2e | add_business_view | add_business_visual | replace_target_path | replace_validation_command',
              sourceSpan: {
                startLine: '<1-based source start line>',
                endLine: '<1-based source end line>',
              },
              sourceText:
                '<complete raw source lines from sourceDocument at sourceSpan, including Markdown delimiters and all cells>',
              targetField: '<allowed implementationConfirmation target field>',
              newValue: '<typed semantic row or replacement value>',
              reason: '<why this action resolves the validated gap>',
              mustRefs: ['<affected MUST ref>'],
              requirementIds: ['<source requirement id>'],
            },
          ],
        },
      ],
      rejectedGapCandidates: [],
      independentProviderEvidence: configuredProviderBinding.binding
        ? {
            ...configuredProviderBinding.binding,
            transactionId: input.transactionId,
            auditAttemptId,
            requestHash: '<copy requestHash>',
            sourceDocumentHash: input.sourceDocumentHash,
            semanticModelHash,
            projectionSetHash,
            providerRunId: '<provider run id>',
            responseHash: '<provider response hash>',
            runHash: '<hash of independentProviderEvidence without runHash>',
          }
        : null,
      rationale: '<required>',
    },
    createdBy:
      'main_agent_orchestration.requirement_confirmation.authoring_repair.preserve_existing',
    createdAt: input.createdAt,
  };
  request.requestHash = sha256Json({ ...request, requestHash: null });
  return request;
}

function criticalAuditorRoundRequestMatchesCurrent(
  existing: Record<string, unknown>,
  candidate: Record<string, unknown>
): boolean {
  if (!criticalAuditorRoundRequestAuthorityMatchesCurrent(existing, candidate)) {
    return false;
  }
  const existingGateDryRun = recordObject(existing.gateDryRun);
  const candidateGateDryRun = recordObject(candidate.gateDryRun);
  const existingReconciliation = recordObject(existingGateDryRun.reconciliation);
  const candidateReconciliation = recordObject(candidateGateDryRun.reconciliation);
  if (
    normalizeText(existingGateDryRun.gateDryRunHash) !==
      normalizeText(candidateGateDryRun.gateDryRunHash) ||
    Number(existingGateDryRun.actionableBlockingIssueCount ?? 0) !==
      Number(candidateGateDryRun.actionableBlockingIssueCount ?? 0) ||
    normalizeText(existingReconciliation.verdict) !==
      normalizeText(candidateReconciliation.verdict) ||
    Number(existingReconciliation.issueCount ?? 0) !==
      Number(candidateReconciliation.issueCount ?? 0)
  ) {
    return false;
  }
  return true;
}

function criticalAuditorRoundRequestAuthorityMatchesCurrent(
  existing: Record<string, unknown>,
  candidate: Record<string, unknown>
): boolean {
  const comparableScalarKeys = [
    'schemaVersion',
    'recordId',
    'roundIndex',
    'transactionId',
    'namespaceVersion',
    'sourceHash',
    'sourceDocumentHash',
    'sourceBytesHash',
    'semanticModelHash',
    'implementationConfirmationHash',
    'packetHash',
    'projectionSetHash',
    'auditAttemptId',
    'auditInputHash',
  ];
  for (const key of comparableScalarKeys) {
    if (normalizeText(existing[key]) !== normalizeText(candidate[key])) {
      return false;
    }
  }
  const comparableArrayKeys = ['mustRefs', 'sourceRequirementTexts'];
  for (const key of comparableArrayKeys) {
    if (sha256Json(asStringArray(existing[key])) !== sha256Json(asStringArray(candidate[key]))) {
      return false;
    }
  }
  const existingProjectionSummary = recordObject(existing.packetProjectionSummary);
  const candidateProjectionSummary = recordObject(candidate.packetProjectionSummary);
  if (
    sha256Json(asStringArray(existingProjectionSummary.projectionRefs)) !==
    sha256Json(asStringArray(candidateProjectionSummary.projectionRefs))
  ) {
    return false;
  }
  if (
    sha256Json(asRecordArray(existing.previousReceipts)) !==
    sha256Json(asRecordArray(candidate.previousReceipts))
  ) {
    return false;
  }
  if (
    sha256Json(recordObject(existing.independentProviderBinding)) !==
      sha256Json(recordObject(candidate.independentProviderBinding)) ||
    sha256Json(asStringArray(existing.independentProviderBindingIssueCodes)) !==
      sha256Json(asStringArray(candidate.independentProviderBindingIssueCodes))
  ) {
    return false;
  }
  return Boolean(normalizeText(existing.requestHash));
}

export function criticalAuditorPublishedRoundRequestCanReuseReceipt(input: {
  existingRequest: Record<string, unknown>;
  candidateRequest: Record<string, unknown>;
  existingGateDryRun: CriticalAuditorGateDryRunSummary;
  currentGateDryRun: CriticalAuditorGateDryRunSummary;
}): boolean {
  return (
    criticalAuditorRoundRequestAuthorityMatchesCurrent(
      input.existingRequest,
      input.candidateRequest
    ) &&
    criticalAuditorRoundRequestHashMatchesContent(input.existingRequest) &&
    criticalAuditorRoundRequestHashMatchesContent(input.candidateRequest) &&
    criticalAuditorSubstantiveGateBindingHash(input.existingGateDryRun) ===
      criticalAuditorSubstantiveGateBindingHash(input.currentGateDryRun)
  );
}

function criticalAuditorRoundRequestHashMatchesContent(request: Record<string, unknown>): boolean {
  const requestHash = normalizeText(request.requestHash);
  return Boolean(requestHash) && requestHash === sha256Json({ ...request, requestHash: null });
}

function criticalAuditorSubstantiveGateBindingHash(
  gateDryRun: CriticalAuditorGateDryRunSummary
): string {
  const failedChecks = gateDryRun.failedChecks.filter(
    (code) => !CRITICAL_AUDITOR_ACTIONABLE_DRY_RUN_EXCLUSIONS.has(code)
  );
  const actionableBlockingIssues = gateDryRun.actionableBlockingIssues.map((issue) => ({
    code: issue.code,
    message: issue.message,
    refs: issue.refs,
  }));
  const substantiveVerdict =
    failedChecks.length === 0 &&
    actionableBlockingIssues.length === 0 &&
    normalizeText(gateDryRun.reconciliation.verdict) === 'pass' &&
    gateDryRun.reconciliation.issueCount === 0
      ? 'PASS'
      : gateDryRun.verdict;
  return sha256Json({
    verdict: substantiveVerdict,
    failedChecks,
    actionableBlockingIssues,
    reconciliation: gateDryRun.reconciliation,
  });
}

function writeOrReuseCriticalAuditorRoundRequest(input: {
  requestPath: string;
  candidate: Record<string, unknown>;
}): Record<string, unknown> {
  const existing = readJsonIfExists(input.requestPath);
  if (existing && criticalAuditorRoundRequestMatchesCurrent(existing, input.candidate)) {
    return existing;
  }
  writeJsonUtf8(input.requestPath, input.candidate);
  return input.candidate;
}

function criticalAuditorGateDryRunSummaryFromRequest(
  request: Record<string, unknown>,
  fallback: CriticalAuditorGateDryRunSummary
): CriticalAuditorGateDryRunSummary {
  const gateDryRun = recordObject(request.gateDryRun);
  if (Object.keys(gateDryRun).length === 0) {
    return fallback;
  }
  const reconciliation = recordObject(gateDryRun.reconciliation);
  const parseIssue = (issue: Record<string, unknown>): PreConfirmationDrilldownIssue => ({
    code: normalizeText(issue.code),
    message: normalizeText(issue.message),
    refs: asStringArray(issue.refs),
    severity: normalizeText(issue.severity) === 'warning' ? 'warning' : 'blocker',
    source: normalizeText(issue.source) || normalizeText(issue.category) || 'critical_auditor',
  });
  const actionableBlockingIssues = asRecordArray(gateDryRun.actionableBlockingIssues)
    .map(parseIssue)
    .filter((issue) => issue.code);
  const blockingIssues = asRecordArray(gateDryRun.blockingIssues)
    .map(parseIssue)
    .filter((issue) => issue.code);
  return {
    reportPath: normalizeText(gateDryRun.reportPath) || fallback.reportPath,
    receiptPath: normalizeText(gateDryRun.receiptPath) || fallback.receiptPath,
    reconciliationReportPath:
      normalizeText(gateDryRun.reconciliationReportPath) || fallback.reconciliationReportPath,
    verdict: normalizeText(gateDryRun.verdict) || fallback.verdict,
    failedChecks: asStringArray(gateDryRun.failedChecks),
    blockingIssues: blockingIssues.length > 0 ? blockingIssues : fallback.blockingIssues,
    actionableBlockingIssues,
    actionableBlockingIssueCount: Number(
      gateDryRun.actionableBlockingIssueCount ?? actionableBlockingIssues.length
    ),
    reconciliation: {
      verdict: normalizeText(reconciliation.verdict),
      issueCount: Number(reconciliation.issueCount ?? 0),
      checkedGroups: asStringArray(reconciliation.checkedGroups),
    },
    hash:
      normalizeText(gateDryRun.gateDryRunHash) || normalizeText(gateDryRun.hash) || fallback.hash,
  };
}

function pendingCriticalAuditorDraftText(input: {
  transaction: CriticalAuditorStagingTransaction;
  recordId: string;
  packetHash: string;
}): string | null {
  if (
    !fs.existsSync(input.transaction.draftSource) ||
    safeCurrentSourceDocumentHash(input.transaction.draftSource) !==
      input.transaction.auditSourceHash
  ) {
    return null;
  }
  const request = readJsonIfExists(criticalAuditorRequestPath(input.transaction, 1));
  if (
    !request ||
    !criticalAuditorRoundRequestHashMatchesContent(request) ||
    normalizeText(request.recordId) !== input.recordId ||
    normalizeText(request.transactionId) !== input.transaction.transactionId ||
    normalizeText(request.namespaceVersion) !== input.transaction.namespaceVersion ||
    normalizeText(request.sourceDocumentHash) !== input.transaction.auditSourceHash ||
    normalizeText(request.sourceBytesHash) !== sha256File(input.transaction.draftSource) ||
    normalizeText(request.packetHash) !== input.packetHash
  ) {
    return null;
  }
  return fs.readFileSync(input.transaction.draftSource, 'utf8');
}

function pendingFinalCriticalAuditorDraftText(input: {
  transaction: CriticalAuditorStagingTransaction;
  recordId: string;
  packetHash: string;
}): string | null {
  const finalDraftSource = path.join(input.transaction.stagingDir, 'final-draft-source.md');
  const request = readJsonIfExists(criticalAuditorRequestPath(input.transaction, 1));
  const kernel = recordObject(readJsonIfExists(input.transaction.semanticKernel)?.semanticKernel);
  const packet = recordObject(
    readJsonIfExists(input.transaction.mustDecompositionPacket)?.must_decomposition_packet
  );
  if (
    !fs.existsSync(finalDraftSource) ||
    !request ||
    Object.keys(kernel).length === 0 ||
    Object.keys(packet).length === 0 ||
    !criticalAuditorRoundRequestHashMatchesContent(request)
  ) {
    return null;
  }

  const draftText = fs.readFileSync(finalDraftSource, 'utf8');
  const extraction = extractImplementationConfirmationBlock(draftText);
  if (!extraction) {
    return null;
  }
  const sourceDocumentHash = sourceDocumentHashForPreConfirmation(
    draftText,
    extraction.blockText,
    extraction.confirmation
  );
  const implementationConfirmationHash = implementationConfirmationHashForPreConfirmation(
    extraction.confirmation
  );
  const semanticModelHash = normalizeText(kernel.semanticModelHash);
  const semanticKernelHash = normalizeText(kernel.kernelHash);
  if (
    !semanticModelHash.startsWith('sha256:') ||
    !semanticKernelHash.startsWith('sha256:')
  ) {
    return null;
  }
  const projectionSetHash = criticalAuditorProjectionSetHash(
    packet,
    extraction.confirmation
  );
  const auditInputHash = sha256Json({
    sourceDocumentHash,
    semanticModelHash,
    implementationConfirmationHash,
    semanticKernelHash,
    packetHash: input.packetHash,
  });
  const criticalAuditor = recordObject(
    recordObject(extraction.confirmation.preConfirmationDrilldown).criticalAuditor
  );
  const convergenceIsFinal =
    Number(criticalAuditor.consecutiveNoNewGapRounds ?? 0) >= 3 &&
    normalizeText(criticalAuditor.convergenceVerdict) === 'bounded_no_new_gap';
  const requestMatchesFinalDraft =
    normalizeText(request.schemaVersion) === 'critical-auditor-round-request/v1' &&
    Number(request.roundIndex) === 1 &&
    normalizeText(request.recordId) === input.recordId &&
    normalizeText(request.transactionId) === input.transaction.transactionId &&
    normalizeText(request.namespaceVersion) === input.transaction.namespaceVersion &&
    normalizeText(request.sourceDocumentHash) === sourceDocumentHash &&
    normalizeText(request.sourceBytesHash) === sha256File(finalDraftSource) &&
    normalizeText(request.semanticModelHash) === semanticModelHash &&
    normalizeText(request.implementationConfirmationHash) === implementationConfirmationHash &&
    normalizeText(request.packetHash) === input.packetHash &&
    normalizeText(request.projectionSetHash) === projectionSetHash &&
    normalizeText(request.auditInputHash) === auditInputHash &&
    normalizeText(request.auditAttemptId) ===
      criticalAuditorAuditAttemptId({
        transactionId: input.transaction.transactionId,
        auditInputHash,
      }) &&
    normalizeText(kernel.sourceDocumentHash) === sourceDocumentHash &&
    normalizeText(kernel.implementationConfirmationHash) === implementationConfirmationHash &&
    normalizeText(packet.sourceDocumentHash) === sourceDocumentHash &&
    normalizeText(packet.semanticModelHash) === semanticModelHash &&
    normalizeText(packet.implementationConfirmationHash) === implementationConfirmationHash &&
    normalizeText(packet.semanticKernelHash) === semanticKernelHash;

  return convergenceIsFinal && requestMatchesFinalDraft ? draftText : null;
}

function findCriticalAuditorRequestPath(authoringDir: string, roundIndex: number): string {
  return path.join(authoringDir, `critical-auditor-round-request-${roundIndex}.json`);
}

function findNextCriticalAuditorRound(authoringDir: string): number {
  const receipts = readCriticalAuditorReceipts(authoringDir);
  return receipts.length + 1;
}

function archiveCriticalAuditorArtifacts(input: {
  authoringDir: string;
  stagingDir?: string;
  reason: string;
  auditInputHash: string;
  createdAt: string;
}): string | null {
  if (!fs.existsSync(input.authoringDir)) {
    return null;
  }
  const artifactPattern =
    /^(?:(?:critical-auditor-round-(?:request|response)-\d+)|(?:critical-auditor-receipt-round-\d+)|pre-render-must-decomposition-gate-dry-run-round-\d+(?:-receipt|-reconciliation)?)\.json$/u;
  const artifactEntries: Array<{ absolutePath: string; archiveRelativePath: string }> = [];
  for (const fileName of fs.readdirSync(input.authoringDir)) {
    if (artifactPattern.test(fileName)) {
      artifactEntries.push({
        absolutePath: path.join(input.authoringDir, fileName),
        archiveRelativePath: fileName,
      });
    }
  }
  if (input.stagingDir && fs.existsSync(input.stagingDir)) {
    const stagingName = path.basename(input.stagingDir);
    for (const fileName of fs.readdirSync(input.stagingDir)) {
      if (artifactPattern.test(fileName)) {
        artifactEntries.push({
          absolutePath: path.join(input.stagingDir, fileName),
          archiveRelativePath: path.join('staging', stagingName, fileName),
        });
      }
    }
    const providerInvocationsPath = path.join(
      input.stagingDir,
      CRITICAL_AUDITOR_JUDGE_INVOCATIONS_DIR
    );
    if (fs.existsSync(providerInvocationsPath)) {
      artifactEntries.push({
        absolutePath: providerInvocationsPath,
        archiveRelativePath: path.join(
          'staging',
          stagingName,
          CRITICAL_AUDITOR_JUDGE_INVOCATIONS_DIR
        ),
      });
    }
  }
  if (artifactEntries.length === 0) {
    return null;
  }
  const stamp = input.createdAt.replace(/[^0-9A-Za-z]+/gu, '').slice(0, 15) || 'archive';
  const archiveDir = path.join(
    input.authoringDir,
    'archive',
    `${stamp}-${sha256Text(input.auditInputHash).slice(
      'sha256:'.length,
      'sha256:'.length + 12
    )}-stale-namespace`
  );
  fs.mkdirSync(archiveDir, { recursive: true });
  for (const artifact of artifactEntries) {
    const archivePath = path.join(archiveDir, artifact.archiveRelativePath);
    fs.mkdirSync(path.dirname(archivePath), { recursive: true });
    fs.renameSync(artifact.absolutePath, archivePath);
  }
  writeJsonUtf8(path.join(archiveDir, 'archive-manifest.json'), {
    schemaVersion: 'critical-auditor-stale-archive/v1',
    reason: input.reason,
    auditInputHash: input.auditInputHash,
    archivedAt: input.createdAt,
    artifacts: artifactEntries.map((artifact) => artifact.archiveRelativePath.replace(/\\/g, '/')),
  });
  return archiveDir;
}

function archiveSupersededCriticalAuditorRoundArtifacts(input: {
  root: string;
  transaction: CriticalAuditorStagingTransaction;
  roundIndex: number;
  currentRequestHash: string;
  staleReceipt: Record<string, unknown>;
  responsePath: string;
  receiptPath: string;
  mirrorPath: string;
}): string {
  const staleRequestHash = normalizeText(input.staleReceipt.requestHash);
  const staleReceiptHash = normalizeText(input.staleReceipt.receiptHash);
  if (
    !/^sha256:[a-f0-9]{64}$/u.test(staleRequestHash) ||
    !/^sha256:[a-f0-9]{64}$/u.test(staleReceiptHash) ||
    !/^sha256:[a-f0-9]{64}$/u.test(input.currentRequestHash) ||
    staleRequestHash === input.currentRequestHash
  ) {
    throw new Error('critical_auditor_superseded_round_archive_binding_invalid');
  }
  const archiveDir = path.join(
    input.transaction.stagingDir,
    'archive',
    'superseded-rounds',
    `round-${input.roundIndex}`,
    `request-${staleRequestHash.slice('sha256:'.length, 'sha256:'.length + 24)}`
  );
  const candidates = [
    { role: 'response', sourcePath: path.resolve(input.responsePath) },
    { role: 'receipt', sourcePath: path.resolve(input.receiptPath) },
    { role: 'mirror', sourcePath: path.resolve(input.mirrorPath) },
  ];
  const unique = new Map<string, { role: string; sourcePath: string }>();
  for (const candidate of candidates) {
    const existing = unique.get(candidate.sourcePath);
    if (existing) {
      existing.role = `${existing.role}+${candidate.role}`;
    } else {
      unique.set(candidate.sourcePath, candidate);
    }
  }
  const artifacts = [...unique.values()].map((artifact) => {
    if (!fs.existsSync(artifact.sourcePath)) {
      throw new Error('critical_auditor_superseded_round_archive_source_missing');
    }
    const sourceHash = sha256File(artifact.sourcePath);
    const archivePath = path.join(archiveDir, `${artifact.role}.json`);
    fs.mkdirSync(path.dirname(archivePath), { recursive: true });
    if (fs.existsSync(archivePath)) {
      if (sha256File(archivePath) !== sourceHash) {
        throw new Error('critical_auditor_superseded_round_archive_conflict');
      }
    } else {
      const temporaryPath = `${archivePath}.${process.pid}.${crypto.randomUUID()}.tmp`;
      try {
        fs.copyFileSync(artifact.sourcePath, temporaryPath);
        if (sha256File(temporaryPath) !== sourceHash) {
          throw new Error('critical_auditor_superseded_round_archive_copy_invalid');
        }
        fs.renameSync(temporaryPath, archivePath);
      } finally {
        if (fs.existsSync(temporaryPath)) fs.rmSync(temporaryPath, { force: true });
      }
    }
    return {
      role: artifact.role,
      sourcePath: toRootRelativePath(input.root, artifact.sourcePath),
      sourceHash,
      archivePath: toRootRelativePath(input.root, archivePath),
    };
  });
  writeJsonCreateOnlyOrEqual(
    path.join(archiveDir, 'archive-manifest.json'),
    {
      schemaVersion: 'critical-auditor-superseded-round-archive/v1',
      transactionId: input.transaction.transactionId,
      namespaceVersion: input.transaction.namespaceVersion,
      roundIndex: input.roundIndex,
      staleRequestHash,
      staleReceiptHash,
      currentRequestHash: input.currentRequestHash,
      artifacts,
    },
    'critical_auditor_superseded_round_archive_manifest_conflict'
  );
  for (const artifact of artifacts) {
    const sourcePath = path.resolve(input.root, artifact.sourcePath);
    if (!fs.existsSync(sourcePath)) continue;
    if (sha256File(sourcePath) !== artifact.sourceHash) {
      throw new Error('critical_auditor_superseded_round_archive_source_changed');
    }
    fs.rmSync(sourcePath, { force: true });
  }
  return archiveDir;
}

function collectStaleCriticalAuditorArtifactIssues(input: {
  authoringDir: string;
  auditInputHash: string;
  sourceDocumentHash: string;
  sourceBytesHash: string;
  implementationConfirmationHash: string;
  packetHash: string;
}): PreConfirmationDrilldownIssue[] {
  if (!fs.existsSync(input.authoringDir)) {
    return [];
  }
  const issues: PreConfirmationDrilldownIssue[] = [];
  const staleIfMismatch = (
    artifactName: string,
    artifact: Record<string, unknown> | null,
    hashFields: string[]
  ) => {
    if (!artifact) {
      return;
    }
    for (const field of hashFields) {
      const expected = normalizeText((input as unknown as Record<string, unknown>)[field]);
      const actual = normalizeText(artifact[field]);
      if (
        expected &&
        ((field === 'sourceBytesHash' && actual !== expected) ||
          (field !== 'sourceBytesHash' && actual && actual !== expected))
      ) {
        issues.push(
          preConfirmationIssue(
            `critical_auditor_${artifactName.replace(/\W+/gu, '_')}_${field}_stale`,
            `Critical Auditor artifact ${artifactName} has stale ${field}`,
            [artifactName, field],
            'critical_auditor'
          )
        );
      }
    }
  };
  for (const fileName of fs.readdirSync(input.authoringDir)) {
    const filePath = path.join(input.authoringDir, fileName);
    if (/^critical-auditor-round-request-\d+\.json$/u.test(fileName)) {
      const request = readJsonIfExists(filePath);
      staleIfMismatch(fileName, request, [
        'sourceDocumentHash',
        'sourceBytesHash',
        'implementationConfirmationHash',
        'packetHash',
        'auditInputHash',
      ]);
    }
    if (/^critical-auditor-round-response-\d+\.json$/u.test(fileName)) {
      const response = readJsonIfExists(filePath);
      staleIfMismatch(fileName, response, [
        'sourceDocumentHash',
        'sourceBytesHash',
        'implementationConfirmationHash',
        'packetHash',
      ]);
    }
    if (/^critical-auditor-receipt-round-\d+\.json$/u.test(fileName)) {
      const receipt = unwrapCriticalAuditorReceipt(readJsonIfExists(filePath));
      staleIfMismatch(fileName, receipt, [
        'sourceDocumentHash',
        'sourceBytesHash',
        'implementationConfirmationHash',
        'packetHash',
      ]);
      if (receipt && normalizeText(receipt.inputHash) !== input.auditInputHash) {
        issues.push(
          preConfirmationIssue(
            'critical_auditor_receipt_input_hash_stale',
            `Critical Auditor artifact ${fileName} has stale inputHash`,
            [fileName, 'inputHash'],
            'critical_auditor'
          )
        );
      }
      if (receipt && !normalizeText(receipt.gateDryRunHash)) {
        issues.push(
          preConfirmationIssue(
            'critical_auditor_receipt_gate_dry_run_hash_missing',
            `Critical Auditor artifact ${fileName} lacks gateDryRunHash`,
            [fileName, 'gateDryRunHash'],
            'critical_auditor'
          )
        );
      }
    }
  }
  return issues;
}

function collectConsecutiveNoNewGapFromReceipts(input: {
  receipts: Record<string, unknown>[];
  projectRoot: string;
  auditInputHash: string;
  sourceDocumentHash: string;
  sourceBytesHash: string;
  semanticModelHash: string;
  implementationConfirmationHash: string;
  packetHash: string;
  projectionSetHash: string;
}): {
  consecutive: number;
  issues: PreConfirmationDrilldownIssue[];
  latestReceiptHash: string | null;
} {
  const issues: PreConfirmationDrilldownIssue[] = [];
  const seenProviderRunIds = new Set<string>();
  const seenRequestHashes = new Set<string>();
  const seenReceiptHashes = new Set<string>();
  let consecutive = 0;
  let latestReceiptHash: string | null = null;
  for (const [index, receipt] of input.receipts.entries()) {
    const roundIndex = Number(receipt.roundIndex);
    const receiptHash = normalizeText(receipt.receiptHash);
    const receiptWithoutHash = { ...receipt };
    delete receiptWithoutHash.receiptHash;
    latestReceiptHash = receiptHash || null;
    if (
      roundIndex !== index + 1 ||
      !/^sha256:[a-f0-9]{64}$/u.test(receiptHash) ||
      receiptHash !== sha256Json(receiptWithoutHash)
    ) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_receipt_integrity_invalid',
          `Critical Auditor receipt round ${receipt.roundIndex ?? '?'} failed sequence or self-hash validation`,
          ['roundIndex', 'receiptHash'],
          'critical_auditor'
        )
      );
      consecutive = 0;
      continue;
    }
    if (
      normalizeText(receipt.inputHash) !== input.auditInputHash ||
      normalizeText(receipt.sourceDocumentHash) !== input.sourceDocumentHash ||
      normalizeText(receipt.sourceBytesHash) !== input.sourceBytesHash ||
      normalizeText(receipt.semanticModelHash) !== input.semanticModelHash ||
      normalizeText(receipt.implementationConfirmationHash) !==
        input.implementationConfirmationHash ||
      normalizeText(receipt.packetHash) !== input.packetHash ||
      normalizeText(receipt.projectionSetHash) !== input.projectionSetHash
    ) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_receipt_input_hash_stale',
          `Critical Auditor receipt round ${receipt.roundIndex ?? '?'} is stale for current source/packet hashes`,
          [
            'inputHash',
            'sourceDocumentHash',
            'sourceBytesHash',
            'semanticModelHash',
            'implementationConfirmationHash',
            'packetHash',
            'projectionSetHash',
          ],
          'critical_auditor'
        )
      );
      consecutive = 0;
      continue;
    }
    if (!normalizeText(receipt.gateDryRunHash)) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_receipt_gate_dry_run_hash_missing',
          `Critical Auditor receipt round ${receipt.roundIndex ?? '?'} lacks gateDryRunHash and must be regenerated`,
          ['gateDryRunHash'],
          'critical_auditor'
        )
      );
      consecutive = 0;
      continue;
    }
    try {
      const expectation = recordObject(receipt.independentProviderExpectation);
      const evidence = recordObject(receipt.independentProviderEvidence);
      const requestHash = normalizeText(receipt.requestHash);
      const providerRunId = normalizeText(evidence.providerRunId);
      if (
        !requestHash ||
        normalizeText(expectation.requestHash) !== requestHash ||
        normalizeText(expectation.sourceDocumentHash) !== input.sourceDocumentHash ||
        normalizeText(expectation.semanticModelHash) !== input.semanticModelHash ||
        normalizeText(expectation.projectionSetHash) !== input.projectionSetHash
      ) {
        throw new Error('critical_auditor_provider_expectation_binding_mismatch');
      }
      const providerValidation = validateCriticalAuditorIndependentProviderEvidence({
        expected: expectation as unknown as CriticalAuditorIndependentProviderExpectation,
        evidence,
      });
      if (!providerValidation.ok) {
        throw new Error(
          providerValidation.issueCodes[0] ??
            'critical_auditor_independent_provider_evidence_invalid'
        );
      }
      if (!providerRunId) {
        throw new Error('critical_auditor_provider_run_id_missing');
      }
      if (
        seenProviderRunIds.has(providerRunId) ||
        seenRequestHashes.has(requestHash) ||
        seenReceiptHashes.has(receiptHash)
      ) {
        throw new Error('critical_auditor_cross_round_replay_detected');
      }
      validateCriticalAuditorProviderInvocationReceipt({
        projectRoot: input.projectRoot,
        receiptRef: receipt.providerInvocationReceiptRef,
        requestHash,
        sourceDocumentHash: input.sourceDocumentHash,
        sourceBytesHash: input.sourceBytesHash,
        semanticModelHash: input.semanticModelHash,
        projectionSetHash: input.projectionSetHash,
        providerRunId,
        expectedProviderBinding:
          expectation as unknown as CriticalAuditorJudgeRuntimeBinding,
      });
      validateCriticalAuditorJudgeHostExecution(
        input.projectRoot,
        receipt.judgeAdapterHostExecution,
        receipt.providerInvocationReceiptRef
      );
      seenProviderRunIds.add(providerRunId);
      seenRequestHashes.add(requestHash);
      seenReceiptHashes.add(receiptHash);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const code =
        normalizeText(message.split(':')[0]) ||
        'critical_auditor_judge_invocation_provenance_invalid';
      issues.push(
        preConfirmationIssue(
          code,
          `Critical Auditor receipt provenance is invalid: ${message}`,
          [
            'independentProviderEvidence',
            'providerInvocationReceiptRef',
            'judgeAdapterHostExecution',
          ],
          'critical_auditor'
        )
      );
      consecutive = 0;
      continue;
    }
    const verdict = normalizeText(
      recordObject(receipt.convergenceDecision).verdict
    ) as CriticalAuditorVerdict;
    consecutive = isNoNewGapVerdict(verdict) ? consecutive + 1 : 0;
  }
  return { consecutive, issues, latestReceiptHash };
}

function validateCriticalAuditorResponse(input: {
  responsePath: string;
  request: Record<string, unknown>;
  transaction?: CriticalAuditorStagingTransaction;
  roundIndex?: number;
  sourceDocumentHash: string;
  implementationConfirmationHash: string;
  packetHash: string;
  mustRefs: string[];
  packet: Record<string, unknown>;
  sourceText: string;
  confirmation: Record<string, unknown>;
  gateDryRun: CriticalAuditorGateDryRunSummary;
  independentProviderExpectation: CriticalAuditorIndependentProviderExpectation;
}): { response: CriticalAuditorRoundResult | null; issues: PreConfirmationDrilldownIssue[] } {
  const parsed = readJsonIfExists(input.responsePath);
  const issues: PreConfirmationDrilldownIssue[] = [];
  if (!parsed) {
    return {
      response: null,
      issues: [
        preConfirmationIssue(
          'critical_auditor_response_unreadable',
          'Critical Auditor response is missing or unreadable',
          [input.responsePath],
          'critical_auditor'
        ),
      ],
    };
  }
  const requestHash = normalizeText(input.request.requestHash);
  const sourceBytesHash = normalizeText(input.request.sourceBytesHash);
  if (normalizeText(parsed.requestHash) !== requestHash) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_request_hash_mismatch',
        'Critical Auditor response requestHash does not match the current request',
        ['requestHash'],
        'critical_auditor'
      )
    );
  }
  const expectedRoundIndex = Number(input.roundIndex ?? input.request.roundIndex ?? 0);
  if (expectedRoundIndex > 0 && Number(parsed.roundIndex) !== expectedRoundIndex) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_round_index_mismatch',
        'Critical Auditor response roundIndex does not match the current request',
        ['roundIndex'],
        'critical_auditor'
      )
    );
  }
  if (
    input.transaction &&
    normalizeText(parsed.transactionId) !== input.transaction.transactionId
  ) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_transaction_id_mismatch',
        'Critical Auditor response transactionId does not match the active staging transaction',
        ['transactionId'],
        'critical_auditor'
      )
    );
  }
  if (
    input.transaction &&
    normalizeText(parsed.namespaceVersion) !== input.transaction.namespaceVersion
  ) {
    issues.push(
      preConfirmationIssue(
        'id_namespace_mismatch',
        'Critical Auditor response namespaceVersion does not match the active namespace',
        ['namespaceVersion'],
        'critical_auditor'
      )
    );
  }
  if (
    normalizeText(parsed.sourceHash) &&
    normalizeText(parsed.sourceHash) !== input.sourceDocumentHash
  ) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_source_hash_stale',
        'Critical Auditor response sourceHash is stale',
        ['sourceHash'],
        'critical_auditor'
      )
    );
  }
  if (normalizeText(parsed.sourceDocumentHash) !== input.sourceDocumentHash) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_source_hash_stale',
        'Critical Auditor response sourceDocumentHash is stale',
        ['sourceDocumentHash'],
        'critical_auditor'
      )
    );
  }
  if (
    !/^sha256:[a-f0-9]{64}$/u.test(sourceBytesHash) ||
    normalizeText(parsed.sourceBytesHash) !== sourceBytesHash
  ) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_source_bytes_hash_mismatch',
        'Critical Auditor response sourceBytesHash does not match the frozen request bytes.',
        ['sourceBytesHash'],
        'critical_auditor'
      )
    );
  }
  if (normalizeText(parsed.semanticModelHash) !== normalizeText(input.request.semanticModelHash)) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_semantic_model_hash_stale',
        'Critical Auditor response semanticModelHash is stale',
        ['semanticModelHash'],
        'critical_auditor'
      )
    );
  }
  if (
    normalizeText(parsed.implementationConfirmationHash) !== input.implementationConfirmationHash
  ) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_implementation_hash_stale',
        'Critical Auditor response implementationConfirmationHash is stale',
        ['implementationConfirmationHash'],
        'critical_auditor'
      )
    );
  }
  if (normalizeText(parsed.packetHash) !== input.packetHash) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_packet_hash_stale',
        'Critical Auditor response packetHash is stale',
        ['packetHash'],
        'critical_auditor'
      )
    );
  }
  const verdict = normalizeText(parsed.verdict) as CriticalAuditorVerdict;
  if (!verdict) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_verdict_missing',
        'Critical Auditor response must include verdict',
        ['verdict'],
        'critical_auditor'
      )
    );
  }
  if (
    !isNoNewGapVerdict(verdict) &&
    !['new_valid_gap', 'insufficient_audit', 'blocked'].includes(verdict)
  ) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_verdict_invalid',
        'Critical Auditor response verdict is not an allowed value',
        ['verdict'],
        'critical_auditor'
      )
    );
  }
  if (verdict === 'blocked' && !hasCriticalAuditorBlockedEvidence(parsed)) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_blocked_evidence_missing',
        'Critical Auditor response verdict blocked requires source materialization, missing projection, source/projection invalid proof, or gate dry-run blocker evidence',
        [
          'sourceMaterializationFindings',
          'missingProjectionFindings',
          'invalidProofFindings',
          'gateDryRunBlockers',
        ],
        'critical_auditor'
      )
    );
  }
  if (verdict === 'insufficient_audit' && !hasCriticalAuditorInsufficientAuditEvidence(parsed)) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_insufficient_audit_evidence_missing',
        'Critical Auditor response verdict insufficient_audit requires invalidProofFindings that explicitly describe incomplete audit evidence',
        ['invalidProofFindings'],
        'critical_auditor'
      )
    );
  }
  if (isNoNewGapVerdict(verdict)) {
    const providerValidation = validateCriticalAuditorIndependentProviderEvidence({
      expected: input.independentProviderExpectation,
      evidence: parsed.independentProviderEvidence,
    });
    issues.push(
      ...providerValidation.issueCodes.map((code) =>
        preConfirmationIssue(
          code,
          `Critical Auditor independent provider evidence is invalid: ${code}`,
          ['independentProviderEvidence'],
          'critical_auditor'
        )
      )
    );
  }
  if (normalizeText(parsed.projectionSetHash) !== normalizeText(input.request.projectionSetHash)) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_projection_set_hash_mismatch',
        'Critical Auditor response projectionSetHash does not match the current request',
        ['projectionSetHash'],
        'critical_auditor'
      )
    );
  }
  if (normalizeText(parsed.gateDryRunHash) !== input.gateDryRun.hash) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_gate_dry_run_hash_mismatch',
        'Critical Auditor response gateDryRunHash does not match the current gate dry-run',
        ['gateDryRunHash'],
        'critical_auditor'
      )
    );
  }
  if (Number(parsed.reconciliationIssueCount) !== input.gateDryRun.reconciliation.issueCount) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_reconciliation_issue_count_mismatch',
        'Critical Auditor response reconciliationIssueCount does not match the current gate dry-run',
        ['reconciliationIssueCount'],
        'critical_auditor'
      )
    );
  }
  const checkedProjectionGroups = new Set(asStringArray(parsed.checkedProjectionGroups));
  for (const group of CRITICAL_AUDITOR_PROJECTION_GROUPS) {
    if (!checkedProjectionGroups.has(group)) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_response_checked_projection_group_missing',
          `Critical Auditor response did not check projection group ${group}`,
          [group],
          'critical_auditor'
        )
      );
    }
  }
  const checkedProjectionQualityRuleCodes = new Set(
    asStringArray(parsed.checkedProjectionQualityRuleCodes)
  );
  for (const ruleCode of PROJECTION_QUALITY_RULE_CODES) {
    if (!checkedProjectionQualityRuleCodes.has(ruleCode)) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_response_checked_projection_quality_rule_missing',
          `Critical Auditor response did not check projection quality rule ${ruleCode}`,
          [ruleCode],
          'critical_auditor'
        )
      );
    }
  }
  const priorFindingsDisposition = asRecordArray(parsed.priorFindingsDisposition);
  const priorFindingDispositionRequired =
    asRecordArray(input.request.previousReceipts).length > 0 ||
    asRecordArray(recordObject(input.request.gateDryRun).actionableBlockingIssues).length > 0;
  if (priorFindingDispositionRequired && priorFindingsDisposition.length === 0) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_prior_findings_disposition_missing',
        'Critical Auditor response must classify prior findings as new/resolved/unchanged/rejected',
        ['priorFindingsDisposition'],
        'critical_auditor'
      )
    );
  }
  if (!priorFindingDispositionRequired && priorFindingsDisposition.length > 0) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_prior_findings_disposition_synthetic',
        'Critical Auditor response must not invent prior findings when the request has no previous receipts or actionable blockers',
        ['priorFindingsDisposition'],
        'critical_auditor'
      )
    );
  }
  for (const disposition of priorFindingsDisposition) {
    const value = normalizeText(disposition.disposition);
    if (!['new', 'resolved', 'unchanged', 'rejected'].includes(value)) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_response_prior_findings_disposition_invalid',
          `Critical Auditor response has invalid prior finding disposition ${value || '<missing>'}`,
          ['priorFindingsDisposition.disposition'],
          'critical_auditor'
        )
      );
    }
  }
  const allowedRefs = new Set(input.mustRefs);
  const reviewedRefs = asStringArray(parsed.reviewedMustRefs);
  for (const ref of reviewedRefs) {
    if (!allowedRefs.has(ref)) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_response_unknown_must_ref',
          `Critical Auditor response references unknown MUST ${ref}`,
          [ref],
          'critical_auditor'
        )
      );
    }
  }
  const allowedProjectionRefs = new Set<string>();
  for (const mustPacket of asRecordArray(input.packet.mustPackets)) {
    for (const key of [
      'mustAtomicTasks',
      'mustExecutionDecompositionMatrix',
      'mustEvidenceProjection',
      'mustTraceProjection',
      'mustAcceptanceProjection',
      'mustFailureEdgeProjection',
      'mustTargetPathProjection',
      'mustCurrentTargetProjection',
      'mustAiTddManifestProjection',
      'mustArtifactProjection',
      'mustCommandProjection',
      'mustCloseoutBoundaryProjection',
    ]) {
      for (const row of asRecordArray(mustPacket[key])) {
        const id = normalizeText(row.id);
        if (id) {
          allowedProjectionRefs.add(id);
          allowedProjectionRefs.add(`${normalizeText(mustPacket.mustRef)}:${id}`);
          allowedProjectionRefs.add(`${key}:${id}`);
        }
      }
    }
  }
  const reviewedProjectionRefs = asStringArray(parsed.reviewedProjectionRefs);
  if (reviewedProjectionRefs.length === 0) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_reviewed_projection_refs_missing',
        'Critical Auditor response must include non-empty reviewedProjectionRefs',
        ['reviewedProjectionRefs'],
        'critical_auditor'
      )
    );
  }
  for (const ref of [
    ...reviewedProjectionRefs,
    ...asStringArray(parsed.projectionRefs),
    ...asStringArray(parsed.referencedProjectionRefs),
  ]) {
    if (!allowedProjectionRefs.has(ref)) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_response_unknown_projection_ref',
          `Critical Auditor response references unknown projection ${ref}`,
          [ref],
          'critical_auditor'
        )
      );
    }
  }
  if (isNoNewGapVerdict(verdict) && input.gateDryRun.actionableBlockingIssueCount > 0) {
    const proofs = asRecordArray(parsed.falsePositiveProofs);
    const provenCodes = new Set(
      proofs.map((proof) => normalizeText(proof.blockerCode)).filter(Boolean)
    );
    const missingProofs = input.gateDryRun.actionableBlockingIssues
      .map((issue) => issue.code)
      .filter((code) => !provenCodes.has(code));
    if (missingProofs.length > 0) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_no_new_gap_forbidden_by_gate_dry_run_blockers',
          'Critical Auditor response cannot use no_new_* while gate dry-run has actionable blockers without machine-verifiable falsePositiveProofs',
          missingProofs,
          'critical_auditor'
        )
      );
    }
  }
  const attemptedWrites = [
    ...asStringArray(parsed.writeAttempts),
    ...asStringArray(parsed.sourceWriteAttempts),
    ...asStringArray(parsed.controlWriteAttempts),
  ];
  if (
    attemptedWrites.length > 0 ||
    parsed.mutatesSource === true ||
    parsed.writesControlState === true
  ) {
    issues.push(
      preConfirmationIssue(
        'subagent_write_boundary_violation',
        'Critical Auditor response must not write source, packet, receipt, or control state',
        attemptedWrites,
        'critical_auditor'
      )
    );
  }
  const parsedValidatedGaps = asRecordArray(parsed.validatedGaps);
  const unresolvedGaps = parsedValidatedGaps.filter((gap) => {
    const status = normalizeText(gap.status ?? gap.resolutionStatus);
    return ![
      'resolved',
      'converted_to_out_boundary',
      'converted_to_open_question',
      'rejected',
    ].includes(status);
  });
  if (unresolvedGaps.length > 0 && verdict !== 'new_valid_gap') {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_unresolved_validated_gap',
        'Critical Auditor response contains unresolved validated gaps',
        unresolvedGaps.map((gap) => normalizeText(gap.id ?? gap.code ?? 'gap')),
        'critical_auditor'
      )
    );
  }
  const repairActionValidation =
    verdict === 'new_valid_gap'
      ? unresolvedGaps.length === 0
        ? {
            gaps: [] as Array<
              Record<string, unknown> & { repairActions: CriticalAuditorRepairAction[] }
            >,
            issues: [
              preConfirmationIssue(
                'critical_auditor_new_valid_gap_missing_validated_gap',
                'Critical Auditor response verdict new_valid_gap requires at least one unresolved validated gap',
                ['validatedGaps'],
                'critical_auditor'
              ),
            ],
          }
        : validateCriticalAuditorRepairActions({
            gaps: unresolvedGaps,
            sourceText: input.sourceText,
            confirmation: input.confirmation,
          })
      : {
          gaps: parsedValidatedGaps as Array<
            Record<string, unknown> & { repairActions: CriticalAuditorRepairAction[] }
          >,
          issues: [],
        };
  if (repairActionValidation.issues.length > 0) {
    issues.push(...repairActionValidation.issues);
  }
  if (issues.length > 0) {
    return { response: null, issues };
  }
  return {
    response: {
      verdict,
      transactionId: normalizeText(parsed.transactionId),
      namespaceVersion: normalizeText(parsed.namespaceVersion),
      requestHash,
      sourceHash: normalizeText(parsed.sourceHash) || input.sourceDocumentHash,
      sourceDocumentHash: input.sourceDocumentHash,
      sourceBytesHash,
      semanticModelHash: normalizeText(parsed.semanticModelHash),
      implementationConfirmationHash: input.implementationConfirmationHash,
      packetHash: input.packetHash,
      projectionSetHash: normalizeText(parsed.projectionSetHash),
      gapCandidates: asRecordArray(parsed.gapCandidates),
      validatedGaps: isNoNewGapVerdict(verdict) ? parsedValidatedGaps : repairActionValidation.gaps,
      rejectedGapCandidates: asRecordArray(parsed.rejectedGapCandidates),
      mutationPressureFindings: asRecordArray(parsed.mutationPressureFindings),
      overBroadTaskFindings: asRecordArray(parsed.overBroadTaskFindings),
      missingProjectionFindings: asRecordArray(parsed.missingProjectionFindings),
      invalidProofFindings: asRecordArray(parsed.invalidProofFindings),
      legacyBypassFindings: asRecordArray(parsed.legacyBypassFindings),
      sourceMaterializationFindings: asRecordArray(parsed.sourceMaterializationFindings),
      reviewedMustRefs: reviewedRefs,
      reviewedProjectionRefs,
      gateDryRunHash: normalizeText(parsed.gateDryRunHash),
      reconciliationIssueCount: Number(parsed.reconciliationIssueCount),
      checkedProjectionGroups: asStringArray(parsed.checkedProjectionGroups),
      checkedProjectionQualityRuleCodes: asStringArray(parsed.checkedProjectionQualityRuleCodes),
      priorFindingsDisposition,
      falsePositiveProofs: asRecordArray(parsed.falsePositiveProofs),
      independentProviderEvidence: isNoNewGapVerdict(verdict)
        ? (parsed.independentProviderEvidence as CriticalAuditorIndependentProviderEvidence)
        : undefined,
      rationale: normalizeText(parsed.rationale),
    },
    issues: [],
  };
}

function validateCriticalAuditorRoundResultBinding(input: {
  projectRoot: string;
  roundIndex: number;
  auditResult: CriticalAuditorRoundResult;
  gateDryRun: CriticalAuditorGateDryRunSummary;
  previousReceipts: Record<string, unknown>[];
  packet: Record<string, unknown>;
  sourceText: string;
  confirmation: Record<string, unknown>;
  independentProviderExpectation: CriticalAuditorIndependentProviderExpectation;
  sourceBytesHash: string;
}): PreConfirmationDrilldownIssue[] {
  const issues: PreConfirmationDrilldownIssue[] = [];
  const result = input.auditResult;
  const providerValidation = validateCriticalAuditorIndependentProviderEvidence({
    expected: input.independentProviderExpectation,
    evidence: result.independentProviderEvidence,
  });
  issues.push(
    ...providerValidation.issueCodes.map((code) =>
      preConfirmationIssue(
        code,
        `Critical Auditor independent provider evidence is invalid: ${code}`,
        ['independentProviderEvidence'],
        'critical_auditor'
      )
    )
  );
  if (providerValidation.ok) {
    try {
      const providerRunId = normalizeText(
        recordObject(result.independentProviderEvidence).providerRunId
      );
      if (!providerRunId) {
        throw new Error('critical_auditor_provider_run_id_missing');
      }
      validateCriticalAuditorProviderInvocationReceipt({
        projectRoot: input.projectRoot,
        receiptRef: result.providerInvocationReceiptRef,
        requestHash: input.independentProviderExpectation.requestHash,
        sourceDocumentHash: input.independentProviderExpectation.sourceDocumentHash,
        sourceBytesHash: input.sourceBytesHash,
        semanticModelHash: input.independentProviderExpectation.semanticModelHash,
        projectionSetHash: input.independentProviderExpectation.projectionSetHash,
        providerRunId,
        expectedProviderBinding: input.independentProviderExpectation,
      });
      validateCriticalAuditorJudgeHostExecution(
        input.projectRoot,
        result.judgeAdapterHostExecution,
        result.providerInvocationReceiptRef
      );
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const code =
        normalizeText(message.split(':')[0]) ||
        'critical_auditor_judge_invocation_provenance_invalid';
      issues.push(
        preConfirmationIssue(
          code,
          `Critical Auditor Judge invocation provenance is invalid: ${message}`,
          ['providerInvocationReceiptRef', 'judgeAdapterHostExecution'],
          'critical_auditor'
        )
      );
    }
  }
  if (normalizeText(result.sourceBytesHash) !== input.sourceBytesHash) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_source_bytes_hash_mismatch',
        `Critical Auditor provider round ${input.roundIndex} did not bind the frozen source bytes hash.`,
        ['sourceBytesHash'],
        'critical_auditor'
      )
    );
  }
  if (normalizeText(result.gateDryRunHash) !== input.gateDryRun.hash) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_gate_dry_run_hash_mismatch',
        `Critical Auditor provider round ${input.roundIndex} did not bind the current gate dry-run hash`,
        ['gateDryRunHash'],
        'critical_auditor'
      )
    );
  }
  if (Number(result.reconciliationIssueCount) !== input.gateDryRun.reconciliation.issueCount) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_reconciliation_issue_count_mismatch',
        `Critical Auditor provider round ${input.roundIndex} did not bind reconciliationIssueCount`,
        ['reconciliationIssueCount'],
        'critical_auditor'
      )
    );
  }
  const reviewedProjectionRefs = new Set(result.reviewedProjectionRefs ?? []);
  if (reviewedProjectionRefs.size === 0) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_reviewed_projection_refs_missing',
        `Critical Auditor provider round ${input.roundIndex} must include reviewedProjectionRefs`,
        ['reviewedProjectionRefs'],
        'critical_auditor'
      )
    );
  }
  const projectionInventory = criticalAuditorProjectionInventory(
    input.packet,
    input.confirmation
  );
  const allowedProjectionRefs = new Set(projectionInventory.projectionRefs);
  for (const ref of reviewedProjectionRefs) {
    if (!allowedProjectionRefs.has(ref)) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_response_unknown_projection_ref',
          `Critical Auditor provider round ${input.roundIndex} references unknown projection ${ref}`,
          [ref],
          'critical_auditor'
        )
      );
    }
  }
  const checkedGroups = new Set(result.checkedProjectionGroups ?? []);
  for (const group of projectionInventory.projectionGroups) {
    if (!checkedGroups.has(group)) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_response_checked_projection_group_missing',
          `Critical Auditor provider round ${input.roundIndex} did not check projection group ${group}`,
          [group],
          'critical_auditor'
        )
      );
    }
  }
  const checkedProjectionQualityRuleCodes = new Set(result.checkedProjectionQualityRuleCodes ?? []);
  for (const ruleCode of PROJECTION_QUALITY_RULE_CODES) {
    if (!checkedProjectionQualityRuleCodes.has(ruleCode)) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_response_checked_projection_quality_rule_missing',
          `Critical Auditor provider round ${input.roundIndex} did not check projection quality rule ${ruleCode}`,
          [ruleCode],
          'critical_auditor'
        )
      );
    }
  }
  const dispositions = result.priorFindingsDisposition ?? [];
  const priorFindingDispositionRequired =
    input.previousReceipts.length > 0 || input.gateDryRun.actionableBlockingIssues.length > 0;
  if (priorFindingDispositionRequired && dispositions.length === 0) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_prior_findings_disposition_missing',
        `Critical Auditor provider round ${input.roundIndex} must classify prior findings`,
        ['priorFindingsDisposition'],
        'critical_auditor'
      )
    );
  }
  if (!priorFindingDispositionRequired && dispositions.length > 0) {
    issues.push(
      preConfirmationIssue(
        'critical_auditor_response_prior_findings_disposition_synthetic',
        `Critical Auditor provider round ${input.roundIndex} must not invent prior findings`,
        ['priorFindingsDisposition'],
        'critical_auditor'
      )
    );
  }
  for (const disposition of dispositions) {
    const value = normalizeText(disposition.disposition);
    if (!['new', 'resolved', 'unchanged', 'rejected'].includes(value)) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_response_prior_findings_disposition_invalid',
          `Critical Auditor provider round ${input.roundIndex} has invalid disposition ${value || '<missing>'}`,
          ['priorFindingsDisposition.disposition'],
          'critical_auditor'
        )
      );
    }
  }
  if (
    isNoNewGapVerdict(normalizeCriticalAuditorVerdict(result.verdict)) &&
    input.gateDryRun.actionableBlockingIssueCount > 0
  ) {
    const proofs = result.falsePositiveProofs ?? [];
    const provenCodes = new Set(
      proofs.map((proof) => normalizeText(proof.blockerCode)).filter(Boolean)
    );
    const missingProofs = input.gateDryRun.actionableBlockingIssues
      .map((issue) => issue.code)
      .filter((code) => !provenCodes.has(code));
    if (missingProofs.length > 0) {
      issues.push(
        preConfirmationIssue(
          'critical_auditor_no_new_gap_forbidden_by_gate_dry_run_blockers',
          `Critical Auditor provider round ${input.roundIndex} cannot return no_new_* while gate dry-run has actionable blockers`,
          missingProofs,
          'critical_auditor'
        )
      );
    }
  }
  if (normalizeCriticalAuditorVerdict(result.verdict) === 'new_valid_gap') {
    issues.push(
      ...validateCriticalAuditorRepairActions({
        gaps: result.validatedGaps ?? [],
        sourceText: input.sourceText,
        confirmation: input.confirmation,
      }).issues
    );
  }
  return issues;
}

function criticalAuditorFindingText(value: Record<string, unknown>): string {
  return [
    normalizeText(value.code),
    normalizeText(value.issueCode),
    normalizeText(value.findingCode),
    normalizeText(value.category),
    normalizeText(value.type),
    normalizeText(value.message),
    normalizeText(value.reason),
    normalizeText(value.description),
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
}

function isAuditInsufficiencyFinding(value: Record<string, unknown>): boolean {
  const text = criticalAuditorFindingText(value);
  const hasAuditContext =
    text.includes('audit') ||
    text.includes('reviewed') ||
    text.includes('rationale') ||
    text.includes('evidence');
  const hasInsufficiencySignal =
    text.includes('insufficient') ||
    text.includes('incomplete') ||
    text.includes('missing') ||
    text.includes('lacks') ||
    text.includes('lack ') ||
    text.includes('without');
  return hasAuditContext && hasInsufficiencySignal;
}

function hasCriticalAuditorBlockedEvidence(parsed: Record<string, unknown>): boolean {
  const sourceMaterializationFindings = asRecordArray(parsed.sourceMaterializationFindings);
  const missingProjectionFindings = asRecordArray(parsed.missingProjectionFindings);
  const gateDryRunBlockers = [
    ...asRecordArray(parsed.gateDryRunBlockers),
    ...asRecordArray(parsed.gateDryRunFindings),
  ];
  const invalidSourceOrProjectionProofFindings = asRecordArray(parsed.invalidProofFindings).filter(
    (finding) => !isAuditInsufficiencyFinding(finding)
  );
  return (
    sourceMaterializationFindings.length > 0 ||
    missingProjectionFindings.length > 0 ||
    gateDryRunBlockers.length > 0 ||
    invalidSourceOrProjectionProofFindings.length > 0
  );
}

function hasCriticalAuditorInsufficientAuditEvidence(parsed: Record<string, unknown>): boolean {
  return asRecordArray(parsed.invalidProofFindings).some(isAuditInsufficiencyFinding);
}

function isPacketSourceProjectionMetadataDrift(response: CriticalAuditorRoundResult): boolean {
  const findings = [
    ...(response.sourceMaterializationFindings ?? []),
    ...(response.missingProjectionFindings ?? []),
    ...(response.invalidProofFindings ?? []),
    ...(response.gapCandidates ?? []),
    ...(response.rejectedGapCandidates ?? []),
  ];
  return findings.some((finding) => {
    const text = criticalAuditorFindingText(finding);
    return (
      (text.includes('source') && text.includes('packet') && text.includes('projection')) ||
      (text.includes('metadata') && text.includes('drift')) ||
      text.includes('packet_source_projection') ||
      text.includes('source_packet_projection')
    );
  });
}

function detectIgnoredRequirementSource(
  root: string,
  sourcePath: string
): Array<Record<string, string>> {
  const relative = toRootRelativePath(root, sourcePath);
  if (!relative.startsWith('docs/requirements/')) {
    return [];
  }
  const gitignorePath = path.join(root, '.gitignore');
  if (!fs.existsSync(gitignorePath)) {
    return [];
  }
  const gitignoreText = fs.readFileSync(gitignorePath, 'utf8');
  if (!/^docs\/requirements\/\s*$/mu.test(gitignoreText)) {
    return [];
  }
  return [
    {
      warning: 'source_document_ignored_by_git',
      recommendedAction: `git add -f ${relative}`,
    },
  ];
}

function resumePendingCriticalAuditorGapPromotion(input: {
  root: string;
  sourcePath: string;
  paths: PreConfirmationPaths;
  recordId: string;
  requirementSetId: string;
  implementationAttemptId: string;
  responsePath: string;
  currentSourceDocumentHash: string;
  currentImplementationConfirmationHash: string;
}):
  | { status: 'none' }
  | {
      status: 'blocked';
      issue: PreConfirmationDrilldownIssue;
      artifacts: string[];
    }
  | {
      status: 'resumed';
      materialized: ReturnType<typeof readMaterializedConfirmation>;
      artifacts: string[];
    } {
  const repairDraftPath = path.join(input.paths.authoringDir, 'authoring-repair-draft-source.md');
  const decision = readJsonIfExists(input.paths.sourceMutationDecision);
  if (
    !decision ||
    !fs.existsSync(repairDraftPath) ||
    normalizeText(decision.finalDecision) !== 'allow_source_materialization' ||
    decision.sourceMutationPerformed === true
  ) {
    return { status: 'none' };
  }

  const currentRawHash = sha256File(input.sourcePath);
  const rawHashBefore =
    normalizeText(decision.targetRawHashBefore) || normalizeText(decision.sourceDocumentHashBefore);
  const rawHashAfter =
    normalizeText(decision.targetRawHashAfter) || normalizeText(decision.sourceDocumentHashAfter);
  if (currentRawHash === rawHashAfter) {
    return { status: 'none' };
  }

  const artifacts = [
    input.paths.sourceMutationDecision,
    repairDraftPath,
    input.responsePath,
  ].filter(Boolean);
  const blocked = (
    code: string,
    message: string,
    refs: string[]
  ): {
    status: 'blocked';
    issue: PreConfirmationDrilldownIssue;
    artifacts: string[];
  } => ({
    status: 'blocked',
    issue: sourceMaterializationGateIssue(code, message, refs),
    artifacts,
  });

  if (
    normalizeText(decision.schemaVersion) !==
      'requirements-authoring-source-mutation-decision/v1' ||
    normalizeText(decision.sourcePath) !== toRootRelativePath(input.root, input.sourcePath) ||
    normalizeText(decision.recordId) !== input.recordId ||
    normalizeText(decision.requirementSetId) !== input.requirementSetId
  ) {
    return blocked(
      'pending_source_gap_promotion_decision_binding_invalid',
      'Pending validated-gap source promotion decision does not bind the current source and requirement identity.',
      [
        normalizeText(decision.sourcePath),
        normalizeText(decision.recordId),
        normalizeText(decision.requirementSetId),
      ]
    );
  }
  if (
    currentRawHash !== rawHashBefore ||
    sha256File(repairDraftPath) !== rawHashAfter ||
    normalizeText(decision.semanticSourceHashBefore) !== input.currentSourceDocumentHash ||
    normalizeText(decision.semanticSourceHashAfter) === input.currentSourceDocumentHash
  ) {
    return blocked(
      'pending_source_gap_promotion_hash_binding_invalid',
      'Pending validated-gap source promotion hashes do not match the current source and durable repair draft.',
      [
        currentRawHash,
        rawHashBefore,
        sha256File(repairDraftPath),
        rawHashAfter,
        input.currentSourceDocumentHash,
        normalizeText(decision.semanticSourceHashBefore),
        normalizeText(decision.semanticSourceHashAfter),
      ]
    );
  }
  const repairDraft = readMaterializedConfirmation(repairDraftPath);
  if (
    repairDraft.sourceDocumentHash !== normalizeText(decision.semanticSourceHashAfter) ||
    repairDraft.implementationConfirmationHash === input.currentImplementationConfirmationHash
  ) {
    return blocked(
      'pending_source_gap_promotion_semantic_binding_invalid',
      'Pending validated-gap repair draft does not match the semantic hashes authorized by the source mutation decision.',
      [
        repairDraft.sourceDocumentHash,
        repairDraft.implementationConfirmationHash,
        normalizeText(decision.semanticSourceHashAfter),
        input.currentImplementationConfirmationHash,
      ]
    );
  }
  if (!input.responsePath || !fs.existsSync(input.responsePath)) {
    return blocked(
      'pending_source_gap_promotion_response_missing',
      'Pending validated-gap source promotion requires the already accepted Critical Auditor response.',
      [input.responsePath || 'critical-auditor-round-response-<round>.json']
    );
  }

  const response = readJsonIfExists(input.responsePath);
  const roundIndex = Number(response?.roundIndex ?? 0);
  const requestPath = findCriticalAuditorRequestPath(input.paths.authoringDir, roundIndex);
  const receiptPath = path.join(
    input.paths.authoringDir,
    `critical-auditor-receipt-round-${roundIndex}.json`
  );
  const request = readJsonIfExists(requestPath);
  const receiptEnvelope = readJsonIfExists(receiptPath);
  const receipt = recordObject(receiptEnvelope?.criticalAuditorReceipt);
  artifacts.push(requestPath, receiptPath);
  if (!roundIndex || !response || !request || Object.keys(receipt).length === 0) {
    return blocked(
      'pending_source_gap_promotion_audit_evidence_missing',
      'Pending validated-gap source promotion requires its original request, response, and accepted receipt.',
      [requestPath, input.responsePath, receiptPath]
    );
  }
  const receiptForHash = { ...receipt };
  const receiptHash = normalizeText(receiptForHash.receiptHash);
  delete receiptForHash.receiptHash;
  const receiptHashCandidates = new Set([
    sha256Json(receiptForHash),
    sha256Json({
      ...receiptForHash,
      transactionId: receiptForHash.transactionId,
      namespaceVersion: receiptForHash.namespaceVersion,
    }),
  ]);
  const requestGateDryRun = recordObject(request.gateDryRun);
  const requestGateDryRunHash =
    normalizeText(requestGateDryRun.gateDryRunHash) || normalizeText(requestGateDryRun.hash);
  const auditBindingsMatch =
    receiptHashCandidates.has(receiptHash) &&
    normalizeText(response.verdict) === 'new_valid_gap' &&
    normalizeText(recordObject(receipt.convergenceDecision).verdict) === 'new_valid_gap' &&
    normalizeText(response.requestHash) === normalizeText(request.requestHash) &&
    normalizeText(receipt.requestHash) === normalizeText(request.requestHash) &&
    normalizeText(response.gateDryRunHash) === requestGateDryRunHash &&
    normalizeText(receipt.gateDryRunHash) === requestGateDryRunHash &&
    normalizeText(response.sourceDocumentHash) === input.currentSourceDocumentHash &&
    normalizeText(request.sourceDocumentHash) === input.currentSourceDocumentHash &&
    normalizeText(receipt.sourceDocumentHash) === input.currentSourceDocumentHash &&
    normalizeText(response.implementationConfirmationHash) ===
      input.currentImplementationConfirmationHash &&
    normalizeText(request.implementationConfirmationHash) ===
      input.currentImplementationConfirmationHash &&
    normalizeText(receipt.implementationConfirmationHash) ===
      input.currentImplementationConfirmationHash &&
    normalizeText(response.packetHash) === normalizeText(request.packetHash) &&
    normalizeText(receipt.packetHash) === normalizeText(request.packetHash) &&
    sha256Json(asRecordArray(receipt.validatedGaps)) ===
      sha256Json(asRecordArray(response.validatedGaps));
  if (!auditBindingsMatch) {
    return blocked(
      'pending_source_gap_promotion_audit_binding_invalid',
      'Pending validated-gap source promotion audit evidence is stale or does not bind the original frozen gate dry-run.',
      [
        normalizeText(request.requestHash),
        normalizeText(response.requestHash),
        normalizeText(receipt.requestHash),
        requestGateDryRunHash,
        normalizeText(response.gateDryRunHash),
        normalizeText(receipt.gateDryRunHash),
      ]
    );
  }

  const current = readMaterializedConfirmation(input.sourcePath);
  const repairActionValidation = validateCriticalAuditorRepairActions({
    gaps: asRecordArray(response.validatedGaps),
    sourceText: fs.readFileSync(input.sourcePath, 'utf8'),
    confirmation: current.extraction.confirmation,
  });
  if (repairActionValidation.issues.length > 0) {
    return {
      status: 'blocked',
      issue: repairActionValidation.issues[0],
      artifacts,
    };
  }
  const gapFix = materializeCriticalAuditorGapFix({
    root: input.root,
    sourcePath: input.sourcePath,
    paths: input.paths,
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    implementationAttemptId: input.implementationAttemptId,
    confirmation: current.extraction.confirmation,
    previousSourceDocumentHash: input.currentSourceDocumentHash,
    response: {
      verdict: 'new_valid_gap',
      validatedGaps: repairActionValidation.gaps,
    },
    createdAt: new Date().toISOString(),
  });
  if (gapFix.ok === false) {
    return {
      status: 'blocked',
      issue: gapFix.issue,
      artifacts,
    };
  }
  artifacts.push(gapFix.receiptPath, input.paths.checkpointPersistenceEvidence);
  const materialized = gapFix.materialized;
  if (materialized.sourceDocumentHash === input.currentSourceDocumentHash) {
    return blocked(
      'pending_source_gap_promotion_result_hash_mismatch',
      'Recovered validated-gap source promotion did not change the current semantic source hash.',
      [materialized.sourceDocumentHash, input.currentSourceDocumentHash]
    );
  }
  return {
    status: 'resumed',
    materialized,
    artifacts: uniqueStrings(artifacts),
  };
}

export function runMainAgentAuthoringRepair(
  root: string,
  options: MainAgentAuthoringRepairOptions
): MainAgentAuthoringRepairResult {
  if (normalizeText(options.criticalAuditorResponse)) {
    throw new Error('critical_auditor_response_injection_forbidden');
  }
  const sourceArg = normalizeText(options.source);
  if (!sourceArg) {
    throw new Error('authoring-repair requires --source <source-document.md>');
  }
  if (normalizeText(options.mode) !== 'preserve-existing') {
    throw new Error('authoring-repair currently requires --mode preserve-existing');
  }
  const sourcePath = resolveRootRelativePath(root, sourceArg);
  if (!fs.existsSync(sourcePath)) {
    throw new Error(`source document not found: ${sourcePath}`);
  }
  const identity = derivePreConfirmationIdentity(root, sourcePath, options);
  const implementationAttemptId = normalizeText(options.implementationAttemptId);
  const paths = preConfirmationPaths(root, identity.recordId, identity.requirementSetId);
  const createdAt = new Date().toISOString();
  const sourceText = fs.readFileSync(sourcePath, 'utf8');
  const extraction = extractImplementationConfirmationBlock(sourceText);
  const initialSourceDocumentHash = semanticSourceDocumentHashForText(sourceText);
  const initialWarnings = detectIgnoredRequirementSource(root, sourcePath);
  const activeStagingTransaction = resolveActiveCriticalAuditorStagingTransaction({
    root,
    paths,
    recordId: identity.recordId,
    sourceStartHash: initialSourceDocumentHash,
  });
  const committedGapRound = latestCommittedCriticalAuditorGapRound({
    root,
    transaction: activeStagingTransaction,
  });
  if (committedGapRound) {
    if (!fs.existsSync(activeStagingTransaction.draftSource)) {
      throw new Error('critical_auditor_staging_repair_draft_missing');
    }
    const activeDraft = readMaterializedConfirmation(activeStagingTransaction.draftSource);
    if (activeDraft.sourceDocumentHash !== activeStagingTransaction.auditSourceHash) {
      throw new Error('critical_auditor_staging_repair_draft_hash_mismatch');
    }
    const repairActionValidation = validateCriticalAuditorRepairActions({
      gaps: asRecordArray(committedGapRound.response.validatedGaps),
      sourceText: fs.readFileSync(activeStagingTransaction.draftSource, 'utf8'),
      confirmation: activeDraft.extraction.confirmation,
    });
    if (repairActionValidation.issues.length > 0) {
      return buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage: 'source_gap_fix_materialization_required',
        nextRequiredAction: 'repair_invalid_judge_repair_actions',
        sourceDocumentHash: activeDraft.sourceDocumentHash,
        implementationConfirmationHash: activeDraft.implementationConfirmationHash,
        warnings: initialWarnings,
        issues: repairActionValidation.issues,
        artifacts: [committedGapRound.responsePath, committedGapRound.receiptPath],
      });
    }
    const repairWorkspaceDir = path.join(
      activeStagingTransaction.stagingDir,
      `repair-work-round-${committedGapRound.roundIndex}`
    );
    const repairWorkspace: CriticalAuditorStagingTransaction = {
      ...activeStagingTransaction,
      stagingDir: repairWorkspaceDir,
      draftSource: path.join(repairWorkspaceDir, 'draft-source.md'),
      semanticKernel: path.join(repairWorkspaceDir, 'semantic-kernel.json'),
      mustDecompositionPacket: path.join(repairWorkspaceDir, 'must_decomposition_packet.json'),
      sourcePromotionDecision: path.join(repairWorkspaceDir, 'source-promotion-decision.json'),
      auditSourceTransition: path.join(repairWorkspaceDir, 'audit-source-transition.json'),
      repairCommit: path.join(repairWorkspaceDir, 'staging-repair-commit.json'),
    };
    const repairWorkspacePaths = criticalAuditorStagingPaths(paths, repairWorkspace);
    fs.mkdirSync(repairWorkspaceDir, { recursive: true });
    const candidatePath = repairWorkspace.draftSource;
    fs.copyFileSync(activeStagingTransaction.draftSource, candidatePath);
    const stagingPromotionReceiptPath = path.join(
      repairWorkspaceDir,
      `staging-repair-promotion-receipt-round-${committedGapRound.roundIndex}.json`
    );
    const gapFix = materializeCriticalAuditorGapFix({
      root,
      sourcePath: candidatePath,
      paths: repairWorkspacePaths,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      implementationAttemptId,
      confirmation: activeDraft.extraction.confirmation,
      previousSourceDocumentHash: activeDraft.sourceDocumentHash,
      response: {
        ...committedGapRound.response,
        verdict: 'new_valid_gap',
        validatedGaps: repairActionValidation.gaps,
      },
      createdAt,
      promotionReceiptPath: stagingPromotionReceiptPath,
    });
    if (!gapFix.ok) {
      return buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage: 'source_gap_fix_materialization_required',
        nextRequiredAction: 'repair_judge_action_materialization',
        sourceDocumentHash: activeDraft.sourceDocumentHash,
        implementationConfirmationHash: activeDraft.implementationConfirmationHash,
        warnings: initialWarnings,
        issues: [gapFix.issue],
        artifacts: [committedGapRound.responsePath, committedGapRound.receiptPath],
      });
    }
    const nextTransaction = createCriticalAuditorStagingTransaction({
      paths,
      recordId: identity.recordId,
      sourceStartHash: initialSourceDocumentHash,
      auditSourceHash: gapFix.materialized.sourceDocumentHash,
    });
    fs.mkdirSync(nextTransaction.stagingDir, { recursive: true });
    if (
      fs.existsSync(nextTransaction.draftSource) &&
      sha256File(nextTransaction.draftSource) !== sha256File(candidatePath)
    ) {
      throw new Error('critical_auditor_staging_repair_next_draft_conflict');
    }
    if (!fs.existsSync(nextTransaction.draftSource)) {
      fs.copyFileSync(candidatePath, nextTransaction.draftSource);
    }
    const nextArtifactPaths = uniqueNonEmpty([
      repairWorkspacePaths.semanticKernel,
      repairWorkspacePaths.mustDecompositionPacket,
      repairWorkspacePaths.semanticIr,
      repairWorkspacePaths.semanticConservationManifest,
      repairWorkspacePaths.requirementContractModel,
      repairWorkspacePaths.compilerClosureReport,
      repairWorkspacePaths.mustDecompositionReceipt,
      repairWorkspacePaths.preRenderMustGate,
      repairWorkspacePaths.preRenderGlobalConsistency,
      repairWorkspacePaths.reconciliationReport,
      repairWorkspacePaths.scaleAssessmentInitial,
      repairWorkspacePaths.scaleAssessmentPostPacket,
      repairWorkspacePaths.scaleAssessmentPostMaterialization,
      repairWorkspacePaths.scaleRoutingDecision,
      ...repairWorkspacePaths.checkpointReceiptPaths.filter((artifactPath) =>
        fs.existsSync(artifactPath)
      ),
      repairWorkspacePaths.checkpointPersistenceEvidence,
      repairWorkspacePaths.progress,
      gapFix.receiptPath,
    ]);
    for (const artifactPath of nextArtifactPaths) {
      if (!fs.existsSync(artifactPath)) {
        throw new Error('critical_auditor_staging_repair_rebuilt_artifact_missing');
      }
    }
    const providerInvocationReceiptRef = recordObject(
      committedGapRound.receipt.providerInvocationReceiptRef
    );
    if (
      !normalizeText(providerInvocationReceiptRef.path) ||
      !normalizeText(providerInvocationReceiptRef.contentHash)
    ) {
      throw new Error('critical_auditor_staging_repair_provider_receipt_ref_missing');
    }
    writeCriticalAuditorStagingRepairCommit({
      root,
      previous: activeStagingTransaction,
      next: nextTransaction,
      requestPath: committedGapRound.requestPath,
      responsePath: committedGapRound.responsePath,
      receiptPath: committedGapRound.receiptPath,
      providerInvocationReceiptRef,
      nextArtifactPaths,
      materialized: gapFix.materialized,
      createdAt,
    });
    return {
      ...buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage: 'critical_auditor_round_required',
        nextRequiredAction: 'rerun_pre_confirmation_from_committed_staging_repair',
        sourceDocumentHash: gapFix.materialized.sourceDocumentHash,
        implementationConfirmationHash: gapFix.materialized.implementationConfirmationHash,
        warnings: initialWarnings,
        issues: [
          preConfirmationIssue(
            'semantic_repair_transaction_restarted',
            'The real Judge gap was applied only to a new staging transaction; the authoritative Source remains unchanged until renewed convergence.',
            [
              toRootRelativePath(root, nextTransaction.draftSource),
              toRootRelativePath(root, activeStagingTransaction.repairCommit),
            ],
            'critical_auditor'
          ),
        ],
        artifacts: [
          committedGapRound.responsePath,
          committedGapRound.receiptPath,
          gapFix.receiptPath,
          activeStagingTransaction.repairCommit,
          nextTransaction.draftSource,
          ...nextArtifactPaths,
        ],
      }),
    };
  }
  if (activeStagingTransaction.auditSourceHash !== initialSourceDocumentHash) {
    return buildAuthoringRepairResult({
      root,
      sourcePath,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      paths,
      status: 'blocked',
      blockingStage: 'critical_auditor_round_required',
      nextRequiredAction: 'rerun_pre_confirmation_from_committed_staging_repair',
      sourceDocumentHash: activeStagingTransaction.auditSourceHash,
      implementationConfirmationHash: null,
      warnings: initialWarnings,
      artifacts: [activeStagingTransaction.draftSource],
      issues: [
        preConfirmationIssue(
          'critical_auditor_staging_repair_resume_required',
          'A committed staging repair is awaiting a fresh Critical Auditor transaction.',
          [toRootRelativePath(root, activeStagingTransaction.draftSource)],
          'critical_auditor'
        ),
      ],
    });
  }
  if (!extraction) {
    return buildAuthoringRepairResult({
      root,
      sourcePath,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      paths,
      status: 'blocked',
      blockingStage: 'implementation_confirmation_missing',
      nextRequiredAction: 'run_author_confirmation_ready_source_before_preserve_existing_repair',
      issues: [
        preConfirmationIssue(
          'implementation_confirmation_missing',
          'preserve-existing authoring repair requires an existing inline implementationConfirmation block unless a committed real-Judge gap is recoverable from staging',
          [toRootRelativePath(root, sourcePath)],
          'authoring_repair'
        ),
      ],
    });
  }
  const initialImplementationConfirmationHash = implementationConfirmationHashForPreConfirmation(
    extraction.confirmation
  );
  const mustRequirements = extractInlineMustRequirements(extraction.confirmation, {
    extraction,
    sourcePath: toRootRelativePath(root, sourcePath),
    sourceDocumentHash: sha256Text(sourceText),
  });
  if (mustRequirements.length === 0) {
    return buildAuthoringRepairResult({
      root,
      sourcePath,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      paths,
      status: 'blocked',
      blockingStage: 'semantic_kernel_required',
      nextRequiredAction: 'author_controlled_must_candidates',
      sourceDocumentHash: initialSourceDocumentHash,
      implementationConfirmationHash: initialImplementationConfirmationHash,
      warnings: initialWarnings,
      issues: [
        preConfirmationIssue(
          'controlled_must_candidates_missing',
          'No inline implementationConfirmation.must[] entries were found; preserve-existing repair does not fall back to default MUST candidates.',
          ['implementationConfirmation.must'],
          'semantic_kernel_authoring'
        ),
      ],
    });
  }
  const responsePath = '';
  const initialMaterializationGate = verifySourceMaterializationBeforeAudit({
    root,
    sourcePath,
    paths,
    requirementSetId: identity.requirementSetId,
    expectedSourceDocumentHash: initialSourceDocumentHash,
    expectedImplementationConfirmationHash: initialImplementationConfirmationHash,
  });
  if (initialMaterializationGate.ok === false) {
    if (shouldAttemptCurrentSourcePromotionReceiptRefresh(initialMaterializationGate.issues)) {
      const refresh = runSkillLocalCurrentSourcePromotionRefresh({
        root,
        sourcePath,
        paths,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        implementationAttemptId,
      });
      if (refresh.ok === false) {
        return buildCurrentSourcePromotionRefreshFailedResult({
          root,
          sourcePath,
          recordId: identity.recordId,
          requirementSetId: identity.requirementSetId,
          paths,
          sourceDocumentHash: initialSourceDocumentHash,
          implementationConfirmationHash: initialImplementationConfirmationHash,
          warnings: initialWarnings,
          staleReceiptIssues: initialMaterializationGate.issues,
          refreshIssues: refresh.issues,
          artifacts: refresh.artifacts,
        });
      }
      const refreshedGate = verifySourceMaterializationBeforeAudit({
        root,
        sourcePath,
        paths,
        requirementSetId: identity.requirementSetId,
        expectedSourceDocumentHash: initialSourceDocumentHash,
        expectedImplementationConfirmationHash: initialImplementationConfirmationHash,
      });
      if (refreshedGate.ok === false) {
        return buildCurrentSourcePromotionRefreshFailedResult({
          root,
          sourcePath,
          recordId: identity.recordId,
          requirementSetId: identity.requirementSetId,
          paths,
          sourceDocumentHash: initialSourceDocumentHash,
          implementationConfirmationHash: initialImplementationConfirmationHash,
          warnings: initialWarnings,
          staleReceiptIssues: initialMaterializationGate.issues,
          refreshIssues: refreshedGate.issues,
          artifacts: refresh.artifacts,
        });
      }
    } else {
      return buildSourceMaterializationRequiredResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        sourceDocumentHash: initialSourceDocumentHash,
        implementationConfirmationHash: initialImplementationConfirmationHash,
        warnings: initialWarnings,
        issues: initialMaterializationGate.issues,
      });
    }
  }
  const visualProofResync =
    normalizeText(extraction.confirmation.status) === 'user_confirmed'
      ? { ok: true as const, changed: false, artifacts: [], changedViewIds: [] }
      : materializePreserveExistingBusinessVisualProofResync({
          root,
          sourcePath,
          paths,
          recordId: identity.recordId,
          requirementSetId: identity.requirementSetId,
          implementationAttemptId,
          createdAt,
          sourceText,
          confirmation: extraction.confirmation,
          previousSourceDocumentHash: initialSourceDocumentHash,
        });
  if (!visualProofResync.ok) {
    return buildAuthoringRepairResult({
      root,
      sourcePath,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      paths,
      status: 'blocked',
      blockingStage: 'business_visual_proof_resync_required',
      nextRequiredAction: 'repair_business_visual_proof_resync_materialization',
      artifacts: visualProofResync.artifacts,
      sourceDocumentHash: initialSourceDocumentHash,
      implementationConfirmationHash: implementationConfirmationHashForPreConfirmation(
        extraction.confirmation
      ),
      warnings: initialWarnings,
      issues: visualProofResync.issues,
    });
  }
  if (visualProofResync.changed) {
    const resumed = runMainAgentAuthoringRepair(root, {
      ...options,
      source: sourceArg,
      mode: 'preserve-existing',
      criticalAuditorResponse: undefined,
    });
    return {
      ...resumed,
      artifacts: uniqueStrings([...visualProofResync.artifacts, ...resumed.artifacts]),
      blockingIssues: [
        preConfirmationIssue(
          'business_visual_proof_resync_materialized',
          'Existing business visual views were resynchronized with explicit trace, evidence, acceptance, failure, and edge proof refs; Critical Auditor must restart on the new source hashes.',
          visualProofResync.changedViewIds,
          'authoring_repair'
        ),
        ...resumed.blockingIssues,
      ],
    };
  }
  const sourceDocumentHash = sourceDocumentHashForPreConfirmation(
    sourceText,
    extraction.blockText,
    extraction.confirmation
  );
  const implementationConfirmationHash = implementationConfirmationHashForPreConfirmation(
    extraction.confirmation
  );
  const rebuiltArtifacts = buildPreserveExistingAuthoringArtifacts({
    root,
    sourcePath,
    paths,
    recordId: identity.recordId,
    requirementSetId: identity.requirementSetId,
    createdAt,
    sourceText,
    extraction,
    consecutiveNoNewGapRounds: 0,
  });
  if (!rebuiltArtifacts.ok) {
    return buildAuthoringRepairResult({
      root,
      sourcePath,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      paths,
      status: 'blocked',
      blockingStage: 'semantic_kernel_required',
      nextRequiredAction: 'author_controlled_must_candidates',
      sourceDocumentHash,
      implementationConfirmationHash,
      warnings: initialWarnings,
      issues: [rebuiltArtifacts.issue],
    });
  }
  const semanticModelHash = rebuiltArtifacts.semanticModelHash;
  const semanticKernelHash = rebuiltArtifacts.semanticKernelHash;
  const packetHash = rebuiltArtifacts.packetHash;
  const previousReceiptsBeforePacket = readCriticalAuditorReceipts(paths.authoringDir);
  const previousConvergence = collectConsecutiveNoNewGapFromReceipts({
    receipts: previousReceiptsBeforePacket,
    projectRoot: root,
    auditInputHash: rebuiltArtifacts.auditInputHash,
    sourceDocumentHash,
    sourceBytesHash: sha256File(sourcePath),
    semanticModelHash,
    implementationConfirmationHash,
    packetHash,
    projectionSetHash: criticalAuditorProjectionSetHash(
      rebuiltArtifacts.packet,
      extraction.confirmation
    ),
  });
  const packet =
    previousConvergence.consecutive === 0
      ? rebuiltArtifacts.packet
      : buildPreserveExistingMustDecompositionPacket({
          root,
          sourcePath,
          paths,
          recordId: identity.recordId,
          sourceDocumentHash,
          semanticModelHash,
          implementationConfirmationHash,
          semanticKernelHash,
          packetHash,
          createdAt,
          mustRequirements,
          confirmation: extraction.confirmation,
          consecutiveNoNewGapRounds: previousConvergence.consecutive,
        });
  writeJsonUtf8(paths.mustDecompositionPacket, { must_decomposition_packet: packet });
  const packetProjectionMetadataResync = materializePreserveExistingPacketProjectionMetadataResync({
    root,
    sourcePath,
    paths,
    recordId: identity.recordId,
    requirementSetId: identity.requirementSetId,
    implementationAttemptId,
    createdAt,
    sourceText,
    confirmation: extraction.confirmation,
    sourceDocumentHash,
    implementationConfirmationHash,
    packetHash,
  });
  if (!packetProjectionMetadataResync.ok) {
    return buildAuthoringRepairResult({
      root,
      sourcePath,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      paths,
      status: 'blocked',
      blockingStage: 'packet_source_projection_resynchronization_required',
      nextRequiredAction: 'repair_packet_source_projection_resynchronization',
      sourceDocumentHash,
      implementationConfirmationHash,
      packetHash,
      artifacts: packetProjectionMetadataResync.artifacts,
      warnings: initialWarnings,
      issues: packetProjectionMetadataResync.issues,
    });
  }
  if (packetProjectionMetadataResync.changed) {
    const resumed = runMainAgentAuthoringRepair(root, {
      ...options,
      source: sourceArg,
      mode: 'preserve-existing',
      criticalAuditorResponse: undefined,
    });
    return {
      ...resumed,
      artifacts: uniqueStrings([...packetProjectionMetadataResync.artifacts, ...resumed.artifacts]),
      warnings: [
        ...resumed.warnings,
        {
          warning: 'packet_source_projection_metadata_resynchronized',
          changedRowCount: String(packetProjectionMetadataResync.changedRowCount),
          previousPacketHashes: packetProjectionMetadataResync.previousPacketHashes.join(','),
          packetHash,
        },
      ],
    };
  }
  const auditInputHash = rebuiltArtifacts.auditInputHash;
  const effectivePacket = {
    ...packet,
    consecutiveNoNewValidGapRounds: previousConvergence.consecutive,
    authorClaims: asRecordArray(packet.authorClaims).map((claim) => ({
      ...claim,
      criticDisposition:
        previousConvergence.consecutive >= 3
          ? 'accepted_no_new_valid_gap'
          : 'pending_critical_auditor_response',
    })),
    mustPackets: asRecordArray(packet.mustPackets).map((mustPacket) => ({
      ...mustPacket,
      authorClaims: asRecordArray(mustPacket.authorClaims).map((claim) => ({
        ...claim,
        criticDisposition:
          previousConvergence.consecutive >= 3
            ? 'accepted_no_new_valid_gap'
            : 'pending_critical_auditor_response',
      })),
    })),
  };
  const warnings = detectIgnoredRequirementSource(root, sourcePath);
  const materializationGate = verifySourceMaterializationBeforeAudit({
    root,
    sourcePath,
    paths,
    requirementSetId: identity.requirementSetId,
    expectedSourceDocumentHash: sourceDocumentHash,
    expectedImplementationConfirmationHash: implementationConfirmationHash,
  });
  if (materializationGate.ok === false) {
    if (shouldAttemptCurrentSourcePromotionReceiptRefresh(materializationGate.issues)) {
      const refresh = runSkillLocalCurrentSourcePromotionRefresh({
        root,
        sourcePath,
        paths,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        implementationAttemptId,
      });
      if (refresh.ok === false) {
        return buildCurrentSourcePromotionRefreshFailedResult({
          root,
          sourcePath,
          recordId: identity.recordId,
          requirementSetId: identity.requirementSetId,
          paths,
          sourceDocumentHash,
          implementationConfirmationHash,
          packetHash,
          warnings,
          staleReceiptIssues: materializationGate.issues,
          refreshIssues: refresh.issues,
          artifacts: refresh.artifacts,
        });
      }
      const refreshedGate = verifySourceMaterializationBeforeAudit({
        root,
        sourcePath,
        paths,
        requirementSetId: identity.requirementSetId,
        expectedSourceDocumentHash: sourceDocumentHash,
        expectedImplementationConfirmationHash: implementationConfirmationHash,
      });
      if (refreshedGate.ok === false) {
        return buildCurrentSourcePromotionRefreshFailedResult({
          root,
          sourcePath,
          recordId: identity.recordId,
          requirementSetId: identity.requirementSetId,
          paths,
          sourceDocumentHash,
          implementationConfirmationHash,
          packetHash,
          warnings,
          staleReceiptIssues: materializationGate.issues,
          refreshIssues: refreshedGate.issues,
          artifacts: refresh.artifacts,
        });
      }
    } else {
      return buildSourceMaterializationRequiredResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        sourceDocumentHash,
        implementationConfirmationHash,
        packetHash,
        warnings,
        issues: materializationGate.issues,
      });
    }
  }
  if (
    hasAnyAuthoringCheckpointReceipt(paths) &&
    !areAuthoringCheckpointReceiptsCurrent({
      root,
      draftSourcePath: sourcePath,
      paths,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      implementationAttemptId,
      sourceDocumentHash,
      implementationConfirmationHash,
    })
  ) {
    const checkpointRouteDecision = authoringCheckpointRouteDecisionForPersistence(
      readJsonIfExists(paths.scaleRoutingDecision),
      paths
    );
    const checkpointPersistence = refreshCurrentSourceCheckpointPersistence(root, {
      source: sourcePath,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      implementationAttemptId,
      sourceDocumentHash,
      implementationConfirmationHash,
      createdAt,
      routeDecision: checkpointRouteDecision,
      forceRefresh: true,
    });
    if (checkpointPersistence.ok === false) {
      return buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage: 'checkpoint_persistence_required_before_audit',
        nextRequiredAction: 'rerun_semantic_checkpoints_before_critical_auditor_round',
        sourceDocumentHash,
        implementationConfirmationHash,
        packetHash,
        warnings,
        issues: [checkpointPersistence.issue],
      });
    }
  }
  const staleArtifactIssues = collectStaleCriticalAuditorArtifactIssues({
    authoringDir: paths.authoringDir,
    auditInputHash,
    sourceDocumentHash,
    sourceBytesHash: sha256File(sourcePath),
    implementationConfirmationHash,
    packetHash,
  });
  const staleArchiveDir = staleArtifactIssues.length
    ? archiveCriticalAuditorArtifacts({
        authoringDir: paths.authoringDir,
        reason: 'stale_or_unbound_critical_auditor_artifacts',
        auditInputHash,
        createdAt,
      })
    : null;

  if (responsePath && !staleArtifactIssues.length) {
    const response = readJsonIfExists(responsePath);
    const roundIndex = Number(response?.roundIndex ?? 0);
    const requestPath = findCriticalAuditorRequestPath(paths.authoringDir, roundIndex);
    const request = readJsonIfExists(requestPath);
    if (!roundIndex || !request) {
      return buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage: 'critical_auditor_response_invalid',
        nextRequiredAction: 'regenerate_critical_auditor_round_request',
        sourceDocumentHash,
        implementationConfirmationHash,
        packetHash,
        warnings,
        issues: [
          preConfirmationIssue(
            'critical_auditor_request_missing_for_response',
            'Critical Auditor response does not match an existing round request',
            [responsePath],
            'critical_auditor'
          ),
        ],
      });
    }
    const responseGateDryRun = buildCriticalAuditorGateDryRunSummary({
      root,
      sourcePath,
      paths,
      roundIndex,
    });
    const providerExpectation = criticalAuditorIndependentProviderExpectationFromRequest(request);
    const validation = providerExpectation.expectation
      ? validateCriticalAuditorResponse({
          responsePath,
          request,
          sourceDocumentHash,
          implementationConfirmationHash,
          packetHash,
          mustRefs: mustRequirements.map((requirement) => requirement.id),
          packet: effectivePacket,
          sourceText,
          confirmation: extraction.confirmation,
          gateDryRun: responseGateDryRun,
          independentProviderExpectation: providerExpectation.expectation,
        })
      : {
          response: null,
          issues: providerExpectation.issueCodes.map((code) =>
            preConfirmationIssue(
              code,
              `Critical Auditor Judge runtime binding is invalid: ${code}`,
              ['independentProviderBinding'],
              'critical_auditor'
            )
          ),
        };
    if (!validation.response) {
      const validationCodes = new Set(validation.issues.map((issue) => issue.code));
      const gateBindingChanged =
        validationCodes.has('critical_auditor_response_gate_dry_run_hash_mismatch') ||
        validationCodes.has('critical_auditor_response_reconciliation_issue_count_mismatch');
      const refreshedRequestPath = gateBindingChanged ? requestPath : null;
      if (refreshedRequestPath) {
        const refreshedRequest = buildCriticalAuditorRoundRequest({
          root,
          sourcePath,
          recordId: identity.recordId,
          roundIndex,
          transactionId: normalizeText(request.transactionId) || undefined,
          namespaceVersion: normalizeText(request.namespaceVersion) || undefined,
          sourceDocumentHash,
          semanticModelHash,
          implementationConfirmationHash,
          packetHash,
          projectionSetHash: criticalAuditorProjectionSetHash(
            effectivePacket,
            extraction.confirmation
          ),
          auditInputHash,
          mustRequirements,
          packet: effectivePacket,
          confirmation: extraction.confirmation,
          previousReceipts: asRecordArray(request.previousReceipts),
          gateDryRun: responseGateDryRun,
          createdAt,
        });
        writeOrReuseCriticalAuditorRoundRequest({
          requestPath: refreshedRequestPath,
          candidate: refreshedRequest,
        });
      }
      return buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage: 'critical_auditor_response_invalid',
        nextRequiredAction: 'write_current_critical_auditor_round_response',
        sourceDocumentHash,
        implementationConfirmationHash,
        packetHash,
        artifacts: refreshedRequestPath ? [refreshedRequestPath] : [],
        warnings,
        issues: validation.issues,
      });
    }
    if (!response) {
      return buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage: 'critical_auditor_response_invalid',
        nextRequiredAction: 'write_current_critical_auditor_round_response',
        sourceDocumentHash,
        implementationConfirmationHash,
        packetHash,
        warnings,
        issues: [
          preConfirmationIssue(
            'critical_auditor_response_unreadable',
            'Critical Auditor response is missing or unreadable',
            [responsePath],
            'critical_auditor'
          ),
        ],
      });
    }
    const receipt = buildCriticalAuditorReceipt({
      roundIndex,
      transactionId: normalizeText(request.transactionId),
      namespaceVersion: normalizeText(request.namespaceVersion),
      requestHash: normalizeText(request.requestHash),
      gateDryRunHash: responseGateDryRun.hash,
      responseHash: sha256Json(response),
      auditInputHash,
      recordId: identity.recordId,
      sourceDocumentHash,
      sourceBytesHash: normalizeText(request.sourceBytesHash),
      semanticModelHash,
      implementationConfirmationHash,
      packetHash,
      projectionSetHash: criticalAuditorProjectionSetHash(
        effectivePacket,
        extraction.confirmation
      ),
      independentProviderExpectation: providerExpectation.expectation ?? undefined,
      createdAt,
      auditResult: validation.response,
    });
    const receiptBinding = validateCriticalAuditorReceiptBinding({
      receipt,
      response,
      expectation: {
        roundIndex,
        transactionId: normalizeText(request.transactionId),
        namespaceVersion: normalizeText(request.namespaceVersion),
        auditInputHash,
        recordId: identity.recordId,
        sourceDocumentHash,
        sourceBytesHash: normalizeText(request.sourceBytesHash),
        semanticModelHash,
        implementationConfirmationHash,
        packetHash,
        projectionSetHash: criticalAuditorProjectionSetHash(
          effectivePacket,
          extraction.confirmation
        ),
        requestHash: normalizeText(request.requestHash),
        gateDryRunHash: responseGateDryRun.hash,
      },
    });
    if (!receiptBinding.ok) {
      return buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage: 'critical_auditor_receipt_binding_invalid',
        nextRequiredAction: 'write_current_critical_auditor_round_response',
        sourceDocumentHash,
        implementationConfirmationHash,
        packetHash,
        warnings,
        issues: receiptBinding.issueCodes.map((code) =>
          preConfirmationIssue(
            code,
            `Critical Auditor receipt binding is invalid: ${code}`,
            [responsePath],
            'critical_auditor'
          )
        ),
      });
    }
    writeJsonUtf8(
      path.join(paths.authoringDir, `critical-auditor-receipt-round-${roundIndex}.json`),
      {
        criticalAuditorReceipt: receipt,
      }
    );
    if (validation.response.verdict === 'blocked') {
      const metadataDrift = isPacketSourceProjectionMetadataDrift(validation.response);
      const blockingStage = metadataDrift
        ? 'packet_source_projection_resynchronization_required'
        : 'critical_auditor_blocked';
      const nextRequiredAction = metadataDrift
        ? 'run_packet_source_projection_resynchronization'
        : 'resolve_critical_auditor_blocker';
      return buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage,
        nextRequiredAction,
        sourceDocumentHash,
        implementationConfirmationHash,
        packetHash,
        artifacts: [
          path.join(paths.authoringDir, `critical-auditor-receipt-round-${roundIndex}.json`),
        ],
        warnings,
        issues: [
          preConfirmationIssue(
            blockingStage,
            metadataDrift
              ? 'Critical Auditor blocked on source and packet projection metadata drift; controlled resynchronization is required.'
              : 'Critical Auditor returned blocked; resolve the audit blocker before continuing authoring repair.',
            [responsePath],
            'critical_auditor'
          ),
        ],
        consecutiveNoNewGapRounds: 0,
      });
    }
    if (validation.response.verdict === 'insufficient_audit') {
      return buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage: 'critical_auditor_insufficient_audit',
        nextRequiredAction: 'rewrite_current_critical_auditor_round_response',
        sourceDocumentHash,
        implementationConfirmationHash,
        packetHash,
        artifacts: [
          path.join(paths.authoringDir, `critical-auditor-receipt-round-${roundIndex}.json`),
        ],
        warnings,
        issues: [
          preConfirmationIssue(
            'critical_auditor_insufficient_audit',
            'Critical Auditor response is insufficient for convergence; rewrite the current round response with complete audit evidence.',
            [responsePath],
            'critical_auditor'
          ),
        ],
        consecutiveNoNewGapRounds: 0,
      });
    }
    if (validation.response.verdict === 'new_valid_gap') {
      const gapFix = materializeCriticalAuditorGapFix({
        root,
        sourcePath,
        paths,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        implementationAttemptId,
        confirmation: extraction.confirmation,
        previousSourceDocumentHash: sourceDocumentHash,
        response: validation.response,
        createdAt,
      });
      if (gapFix.ok === false) {
        return buildAuthoringRepairResult({
          root,
          sourcePath,
          recordId: identity.recordId,
          requirementSetId: identity.requirementSetId,
          paths,
          status: 'blocked',
          blockingStage: 'source_gap_fix_materialization_required',
          nextRequiredAction: 'write_source_gap_fix_before_next_audit_round',
          sourceDocumentHash,
          implementationConfirmationHash,
          packetHash,
          artifacts: [
            path.join(paths.authoringDir, `critical-auditor-receipt-round-${roundIndex}.json`),
          ],
          warnings,
          issues: [
            sourceMaterializationGateIssue(
              'source_gap_fix_materialization_required',
              'Critical Auditor new_valid_gap repair actions could not be materialized into the source contract.',
              gapFix.issue.refs
            ),
            gapFix.issue,
          ],
          consecutiveNoNewGapRounds: 0,
        });
      }
      const repaired = readMaterializedConfirmation(sourcePath);
      const rebuilt = buildPreserveExistingAuthoringArtifacts({
        root,
        sourcePath,
        paths,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        createdAt,
        sourceText: repaired.sourceText,
        extraction: repaired.extraction,
        consecutiveNoNewGapRounds: 0,
      });
      if (!rebuilt.ok) {
        return buildAuthoringRepairResult({
          root,
          sourcePath,
          recordId: identity.recordId,
          requirementSetId: identity.requirementSetId,
          paths,
          status: 'blocked',
          blockingStage: 'source_gap_fix_materialization_required',
          nextRequiredAction: 'write_source_gap_fix_before_next_audit_round',
          sourceDocumentHash: repaired.sourceDocumentHash,
          implementationConfirmationHash: repaired.implementationConfirmationHash,
          packetHash,
          warnings,
          issues: [rebuilt.issue],
          consecutiveNoNewGapRounds: 0,
        });
      }
      const archiveDir = archiveCriticalAuditorArtifacts({
        authoringDir: paths.authoringDir,
        reason: 'semantic_repair_transaction_restart',
        auditInputHash: rebuilt.auditInputHash,
        createdAt,
      });
      const freshGateDryRun = buildCriticalAuditorGateDryRunSummary({
        root,
        sourcePath,
        paths,
        roundIndex: 1,
      });
      const freshRequest = buildCriticalAuditorRoundRequest({
        root,
        sourcePath,
        recordId: identity.recordId,
        roundIndex: 1,
        sourceDocumentHash: rebuilt.sourceDocumentHash,
        semanticModelHash: rebuilt.semanticModelHash,
        implementationConfirmationHash: rebuilt.implementationConfirmationHash,
        packetHash: rebuilt.packetHash,
        projectionSetHash: criticalAuditorProjectionSetHash(
          rebuilt.effectivePacket,
          repaired.extraction.confirmation
        ),
        auditInputHash: rebuilt.auditInputHash,
        mustRequirements: rebuilt.mustRequirements,
        packet: rebuilt.effectivePacket,
        confirmation: repaired.extraction.confirmation,
        previousReceipts: [],
        gateDryRun: freshGateDryRun,
        createdAt,
      });
      const freshRequestPath = findCriticalAuditorRequestPath(paths.authoringDir, 1);
      writeOrReuseCriticalAuditorRoundRequest({
        requestPath: freshRequestPath,
        candidate: freshRequest,
      });
      return buildAuthoringRepairResult({
        root,
        sourcePath,
        recordId: identity.recordId,
        requirementSetId: identity.requirementSetId,
        paths,
        status: 'blocked',
        blockingStage: 'critical_auditor_round_required',
        nextRequiredAction: 'write_critical_auditor_round_response',
        repairCommand: authoringRepairCommand(
          toRootRelativePath(root, sourcePath),
          toRootRelativePath(
            root,
            path.join(paths.authoringDir, 'critical-auditor-round-response-1.json')
          )
        ),
        sourceDocumentHash: rebuilt.sourceDocumentHash,
        implementationConfirmationHash: rebuilt.implementationConfirmationHash,
        packetHash: rebuilt.packetHash,
        artifacts: uniqueNonEmpty([freshRequestPath, archiveDir, gapFix.receiptPath]),
        warnings,
        issues: [
          preConfirmationIssue(
            'semantic_repair_transaction_restarted',
            'Critical Auditor validated gap was materialized into semantic fields; stale audit artifacts were archived and round 1 restarted on the repaired packet.',
            uniqueNonEmpty([freshRequestPath, archiveDir]),
            'critical_auditor'
          ),
        ],
        consecutiveNoNewGapRounds: 0,
      });
    }
  } else if (responsePath && staleArtifactIssues.length) {
    try {
      if (fs.existsSync(responsePath) && path.dirname(responsePath) !== path.dirname(sourcePath)) {
        const archivedResponsePath = path.join(
          staleArchiveDir ?? paths.authoringDir,
          path.basename(responsePath)
        );
        if (!fs.existsSync(archivedResponsePath)) {
          fs.renameSync(responsePath, archivedResponsePath);
        }
      }
    } catch {
      // Stale external responses are best-effort archived; restart remains fail-closed.
    }
  }

  const receipts = readCriticalAuditorReceipts(paths.authoringDir);
  const convergence = collectConsecutiveNoNewGapFromReceipts({
    receipts,
    projectRoot: root,
    auditInputHash,
    sourceDocumentHash,
    sourceBytesHash: sha256File(sourcePath),
    semanticModelHash,
    implementationConfirmationHash,
    packetHash,
    projectionSetHash: criticalAuditorProjectionSetHash(
      effectivePacket,
      extraction.confirmation
    ),
  });
  const restartIssues = [...staleArtifactIssues, ...convergence.issues];
  if (restartIssues.length > 0) {
    const archiveDir =
      staleArchiveDir ??
      archiveCriticalAuditorArtifacts({
        authoringDir: paths.authoringDir,
        reason: 'stale_or_unbound_critical_auditor_artifacts',
        auditInputHash,
        createdAt,
      });
    const freshRequestGateDryRun = buildCriticalAuditorGateDryRunSummary({
      root,
      sourcePath,
      paths,
      roundIndex: 1,
    });
    const request = buildCriticalAuditorRoundRequest({
      root,
      sourcePath,
      recordId: identity.recordId,
      roundIndex: 1,
      sourceDocumentHash,
      semanticModelHash,
      implementationConfirmationHash,
      packetHash,
      projectionSetHash: criticalAuditorProjectionSetHash(
        effectivePacket,
        extraction.confirmation
      ),
      auditInputHash,
      mustRequirements,
      packet: effectivePacket,
      confirmation: extraction.confirmation,
      previousReceipts: [],
      gateDryRun: freshRequestGateDryRun,
      createdAt,
    });
    const requestPath = findCriticalAuditorRequestPath(paths.authoringDir, 1);
    writeOrReuseCriticalAuditorRoundRequest({ requestPath, candidate: request });
    return buildAuthoringRepairResult({
      root,
      sourcePath,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      paths,
      status: 'blocked',
      blockingStage: 'critical_auditor_round_required',
      nextRequiredAction: 'write_critical_auditor_round_response',
      repairCommand: authoringRepairCommand(
        toRootRelativePath(root, sourcePath),
        toRootRelativePath(
          root,
          path.join(paths.authoringDir, 'critical-auditor-round-response-1.json')
        )
      ),
      sourceDocumentHash,
      implementationConfirmationHash,
      packetHash,
      warnings,
      issues: restartIssues,
      artifacts: [requestPath, ...(archiveDir ? [archiveDir] : [])],
      consecutiveNoNewGapRounds: convergence.consecutive,
    });
  }

  if (convergence.consecutive < 3) {
    const roundIndex = findNextCriticalAuditorRound(paths.authoringDir);
    const request = buildCriticalAuditorRoundRequest({
      root,
      sourcePath,
      recordId: identity.recordId,
      roundIndex,
      sourceDocumentHash,
      semanticModelHash,
      implementationConfirmationHash,
      packetHash,
      projectionSetHash: criticalAuditorProjectionSetHash(
        effectivePacket,
        extraction.confirmation
      ),
      auditInputHash,
      mustRequirements,
      packet: effectivePacket,
      confirmation: extraction.confirmation,
      previousReceipts: receipts,
      gateDryRun: buildCriticalAuditorGateDryRunSummary({
        root,
        sourcePath,
        paths,
        roundIndex,
      }),
      createdAt,
    });
    const requestPath = findCriticalAuditorRequestPath(paths.authoringDir, roundIndex);
    writeOrReuseCriticalAuditorRoundRequest({ requestPath, candidate: request });
    return buildAuthoringRepairResult({
      root,
      sourcePath,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      paths,
      status: 'blocked',
      blockingStage: 'critical_auditor_round_required',
      nextRequiredAction: 'write_critical_auditor_round_response',
      repairCommand: authoringRepairCommand(
        toRootRelativePath(root, sourcePath),
        toRootRelativePath(
          root,
          path.join(paths.authoringDir, `critical-auditor-round-response-${roundIndex}.json`)
        )
      ),
      artifacts: [requestPath],
      sourceDocumentHash,
      implementationConfirmationHash,
      packetHash,
      warnings,
      consecutiveNoNewGapRounds: convergence.consecutive,
    });
  }

  const finalPacket = {
    ...effectivePacket,
    consecutiveNoNewValidGapRounds: convergence.consecutive,
  };
  writeJsonUtf8(paths.mustDecompositionPacket, { must_decomposition_packet: finalPacket });

  const mustGateScript = resolveSkillScript(root, 'pre_render_must_decomposition_gate.js');
  const mustGate = runNodeJson(
    mustGateScript,
    [
      '--source',
      sourcePath,
      '--authoring-dir',
      paths.authoringDir,
      '--semantic-kernel',
      paths.semanticKernel,
      '--must-decomposition-packet',
      paths.mustDecompositionPacket,
      '--out',
      paths.preRenderMustGate,
      '--receipt',
      paths.mustDecompositionReceipt,
      '--reconciliation-report',
      paths.reconciliationReport,
      '--json',
    ],
    root
  );
  const mustGateReport = mustGate.json ?? readJsonIfExists(paths.preRenderMustGate);
  const reconciliationReport = readJsonIfExists(paths.reconciliationReport);
  if (mustGateReport?.verdict !== 'PASS' || reconciliationReport?.verdict !== 'pass') {
    return buildAuthoringRepairResult({
      root,
      sourcePath,
      recordId: identity.recordId,
      requirementSetId: identity.requirementSetId,
      paths,
      status: 'blocked',
      blockingStage: 'pre_render_must_gate_required',
      nextRequiredAction: 'repair_pre_render_must_gate',
      artifacts: [paths.preRenderMustGate, paths.reconciliationReport],
      sourceDocumentHash,
      implementationConfirmationHash,
      packetHash,
      warnings,
      issues: mustGateReport
        ? collectBlockingIssuesFromReports(mustGateReport, reconciliationReport)
        : [
            commandFailureIssue(
              'pre_render_must_decomposition_gate_report_missing',
              mustGateScript,
              mustGate
            ),
          ],
      consecutiveNoNewGapRounds: convergence.consecutive,
    });
  }

  writeJsonUtf8(paths.progress, {
    schemaVersion: 'semantic-checkpoint-progress/v1',
    recordId: identity.recordId,
    status: 'pre_render_ready',
    mode: 'preserve-existing',
    sourceDocumentHash,
    implementationConfirmationHash,
    packetHash,
    consecutiveNoNewGapRounds: convergence.consecutive,
    currentStage: 'pre_render_ready',
    createdBy:
      'main_agent_orchestration.requirement_confirmation.authoring_repair.preserve_existing',
    createdAt,
    inputRefs: [
      toRootRelativePath(root, sourcePath),
      toRootRelativePath(root, paths.semanticKernel),
      toRootRelativePath(root, paths.mustDecompositionPacket),
      toRootRelativePath(root, paths.preRenderMustGate),
    ],
  });

  return buildAuthoringRepairResult({
    root,
    sourcePath,
    recordId: identity.recordId,
    requirementSetId: identity.requirementSetId,
    paths,
    status: 'pre_render_ready',
    blockingStage: null,
    nextRequiredAction: 'render_confirmation_allowed',
    repairCommand: authoringRepairCommand(toRootRelativePath(root, sourcePath)),
    artifacts: [
      paths.semanticKernel,
      paths.mustDecompositionPacket,
      paths.reconciliationReport,
      paths.preRenderMustGate,
      paths.progress,
    ],
    sourceDocumentHash,
    implementationConfirmationHash,
    packetHash,
    warnings,
    consecutiveNoNewGapRounds: convergence.consecutive,
  });
}

function enhanceArtifactMetadata(
  filePath: string,
  input: {
    schemaVersion?: string;
    recordId: string;
    sourceDocumentHash: string | null;
    implementationConfirmationHash: string | null;
    createdBy: string;
    createdAt: string;
    inputRefs: string[];
  }
): Record<string, unknown> | null {
  const existing = readJsonIfExists(filePath);
  if (!existing) {
    return null;
  }
  const enhanced = {
    ...existing,
    schemaVersion: normalizeText(existing.schemaVersion) || input.schemaVersion || null,
    recordId: normalizeText(existing.recordId) || input.recordId,
    sourceDocumentHash: normalizeText(existing.sourceDocumentHash) || input.sourceDocumentHash,
    implementationConfirmationHash:
      normalizeText(existing.implementationConfirmationHash) ||
      input.implementationConfirmationHash,
    createdBy: normalizeText(existing.createdBy) || input.createdBy,
    createdAt: normalizeText(existing.createdAt) || input.createdAt,
    inputRefs: Array.isArray(existing.inputRefs) ? existing.inputRefs : input.inputRefs,
  };
  const hashKey = normalizeText((enhanced as Record<string, unknown>).receiptHash)
    ? 'receiptHash'
    : 'contentHash';
  (enhanced as Record<string, unknown>)[hashKey] = sha256Json({
    ...enhanced,
    contentHash: null,
    confirmationPageHash: null,
    renderReportHash: null,
    receiptHash: null,
  });
  writeJsonUtf8(filePath, enhanced);
  return enhanced;
}

function writePreConfirmationRequirementRecord(input: {
  root: string;
  sourcePath: string;
  recordId: string;
  requirementSetId: string;
  paths: PreConfirmationPaths;
  laneState: PreConfirmationDrilldownSubstate;
  sourceDocumentHash: string | null;
  implementationConfirmationHash: string | null;
  confirmationPageHash: string | null;
  renderReportPath: string | null;
  createdAt: string;
}): void {
  const record = {
    recordId: input.recordId,
    requirementSetId: input.requirementSetId,
    status: 'draft',
    flow: 'standalone_tasks',
    stage: 'implement',
    entryFlow: 'standalone_tasks',
    entryFlowClass: 'task_packet_entry',
    workflowAdapter: 'direct',
    sourcePath: toRootRelativePath(input.root, input.sourcePath),
    sourceDocumentHash: input.sourceDocumentHash,
    implementationConfirmationHash: input.implementationConfirmationHash,
    confirmationPageHash: input.confirmationPageHash,
    lastEventType: 'pre_confirmation_drilldown_user_confirmable',
    updatedAt: input.createdAt,
    preConfirmationDrilldownLane: {
      currentMentalModel: 'requirement_confirmation',
      lane: 'pre_confirmation_drilldown',
      substate: input.laneState,
      nextMentalModel: null,
      controlledIngestRequiredBeforeProgression: true,
      confirmationRenderReportPath: input.renderReportPath
        ? toRootRelativePath(input.root, input.renderReportPath)
        : null,
    },
    architectureConfirmationState: {
      status: 'missing',
      reasonCode: 'blocked_until_controlled_requirement_confirmation_ingest',
      updatedAt: input.createdAt,
    },
    runtimePolicySnapshotRef: {
      path: toRootRelativePath(
        input.root,
        path.join(input.paths.recordRoot, 'recovery', 'runtime-policy-snapshot.json')
      ),
    },
    recoveryContextRef: {
      path: toRootRelativePath(
        input.root,
        path.join(input.paths.recordRoot, 'recovery', 'recovery-context.json')
      ),
    },
  };
  const recoveryDir = path.join(input.paths.recordRoot, 'recovery');
  writeJsonUtf8(path.join(recoveryDir, 'runtime-policy-snapshot.json'), {
    kind: 'runtime-policy-snapshot',
    flow: 'standalone_tasks',
    stage: 'implement',
    policy: { flow: 'standalone_tasks', stage: 'implement' },
  });
  writeJsonUtf8(path.join(recoveryDir, 'recovery-context.json'), {
    kind: 'recovery-context',
    currentMentalModel: 'requirement_confirmation',
    lane: 'pre_confirmation_drilldown',
  });
  writeJsonUtf8(input.paths.recordPath, record);
  writeJsonUtf8(input.paths.indexPath, {
    version: 1,
    active: {
      recordId: input.recordId,
      requirementSetId: input.requirementSetId,
      recordPath: toRootRelativePath(input.root, input.paths.recordPath),
    },
    records: [
      {
        recordId: input.recordId,
        requirementSetId: input.requirementSetId,
        recordPath: toRootRelativePath(input.root, input.paths.recordPath),
      },
    ],
  });
}

function resolveSkillScript(root: string, relativeScript: string): string {
  const home = process.env.USERPROFILE || process.env.HOME || '';
  const packageRoot = path.resolve(__dirname, '..', '..', '..', '..');
  const repoRoot = path.resolve(__dirname, '..', '..', '..', '..', '..', '..');
  const candidates = [
    path.join(root, '_bmad', 'skills', 'requirements-contract-authoring'),
    path.join(root, '.codex', 'skills', 'requirements-contract-authoring'),
    path.join(root, '.cursor', 'skills', 'requirements-contract-authoring'),
    path.join(root, '.claude', 'skills', 'requirements-contract-authoring'),
    path.join(root, '.agents', 'skills', 'requirements-contract-authoring'),
    path.join(repoRoot, '_bmad', 'skills', 'requirements-contract-authoring'),
    path.join(repoRoot, '.codex', 'skills', 'requirements-contract-authoring'),
    path.join(repoRoot, '.cursor', 'skills', 'requirements-contract-authoring'),
    path.join(repoRoot, '.claude', 'skills', 'requirements-contract-authoring'),
    path.join(packageRoot, '_bmad', 'skills', 'requirements-contract-authoring'),
    path.resolve(__dirname, '..', '_bmad', 'skills', 'requirements-contract-authoring'),
    path.resolve(__dirname, '..', '.codex', 'skills', 'requirements-contract-authoring'),
    path.resolve(__dirname, '..', '.cursor', 'skills', 'requirements-contract-authoring'),
    path.resolve(__dirname, '..', '.claude', 'skills', 'requirements-contract-authoring'),
    ...(home
      ? [
          path.join(home, '.codex', 'skills', 'requirements-contract-authoring'),
          path.join(home, '.cursor', 'skills', 'requirements-contract-authoring'),
          path.join(home, '.claude', 'skills', 'requirements-contract-authoring'),
          path.join(home, '.agents', 'skills', 'requirements-contract-authoring'),
        ]
      : []),
  ];
  for (const skillDir of candidates) {
    if (!fs.existsSync(path.join(skillDir, 'SKILL.md'))) continue;
    const scriptPath = path.join(skillDir, 'scripts', relativeScript);
    if (fs.existsSync(scriptPath)) return scriptPath;
  }
  return path.join(candidates[0], 'scripts', relativeScript);
}

function resolveEncodingIntegrityScript(root: string): string {
  const home = process.env.USERPROFILE || process.env.HOME || '';
  const packageRoot = path.resolve(__dirname, '..', '..', '..', '..');
  const repoRoot = path.resolve(__dirname, '..', '..', '..', '..', '..', '..');
  const candidates = [
    path.join(root, '_bmad', 'skills', 'encoding-integrity-guardian'),
    path.join(root, '.codex', 'skills', 'encoding-integrity-guardian'),
    path.join(root, '.cursor', 'skills', 'encoding-integrity-guardian'),
    path.join(root, '.claude', 'skills', 'encoding-integrity-guardian'),
    path.join(packageRoot, '_bmad', 'skills', 'encoding-integrity-guardian'),
    path.join(repoRoot, '_bmad', 'skills', 'encoding-integrity-guardian'),
    path.join(repoRoot, '.codex', 'skills', 'encoding-integrity-guardian'),
    ...(home ? [path.join(home, '.codex', 'skills', 'encoding-integrity-guardian')] : []),
  ];
  for (const skillDir of candidates) {
    const scriptPath = path.join(skillDir, 'scripts', 'check-encoding-integrity.js');
    if (fs.existsSync(scriptPath)) return scriptPath;
  }
  return path.join(candidates[0], 'scripts', 'check-encoding-integrity.js');
}

function runNodeJson(
  scriptPath: string,
  args: string[],
  cwd: string
): {
  status: number;
  stdout: string;
  stderr: string;
  json: Record<string, unknown> | null;
} {
  const packageRoot = path.resolve(__dirname, '..');
  const packageNodeModules = path.join(packageRoot, 'node_modules');
  const nodePath = [packageNodeModules, process.env.NODE_PATH].filter(Boolean).join(path.delimiter);
  const result = spawnSync(process.execPath, [scriptPath, ...args], {
    cwd,
    encoding: 'utf8',
    env: {
      ...process.env,
      BMAD_SPECKIT_PACKAGE_ROOT: packageRoot,
      NODE_PATH: nodePath,
    },
  });
  let json: Record<string, unknown> | null = null;
  const candidate = result.stdout.trim() || result.stderr.trim();
  if (candidate) {
    try {
      const parsed = JSON.parse(candidate) as unknown;
      json =
        parsed && typeof parsed === 'object' && !Array.isArray(parsed)
          ? (parsed as Record<string, unknown>)
          : null;
    } catch {
      json = null;
    }
  }
  return {
    status: result.status ?? 1,
    stdout: result.stdout,
    stderr: result.stderr,
    json,
  };
}

function runEncodingIntegrityGate(input: {
  root: string;
  paths: PreConfirmationPaths;
  targetPaths?: string[];
}): {
  report: Record<string, unknown> | null;
  issues: PreConfirmationDrilldownIssue[];
} {
  const script = resolveEncodingIntegrityScript(input.root);
  const pathArgs = (input.targetPaths ?? [])
    .filter((item) => normalizeText(item))
    .flatMap((item) => ['--paths', toRootRelativePath(input.root, item)]);
  const command = runNodeJson(script, ['--json', ...pathArgs], input.root);
  const report = command.json;
  const issues: PreConfirmationDrilldownIssue[] = [];
  if (command.status !== 0 || !report) {
    issues.push(
      preConfirmationIssue(
        'encoding_gate_report_missing',
        `Encoding integrity gate failed or did not emit JSON: ${command.stderr || command.stdout || script}.`,
        [script],
        'encoding_integrity_gate'
      )
    );
  } else {
    writeJsonUtf8(input.paths.encodingReport, report);
    const findings = Array.isArray(report.findings) ? report.findings : [];
    if (findings.length > 0) {
      issues.push(
        preConfirmationIssue(
          'encoding_gate_findings_present',
          `Encoding integrity gate reported ${findings.length} finding(s).`,
          [toRootRelativePath(input.root, input.paths.encodingReport)],
          'encoding_integrity_gate'
        )
      );
    }
  }
  return { report, issues };
}

export function validateWrittenDeepReviewInput(input: {
  root: string;
  skillName: 'grill-with-docs' | 'docs-review';
  documentPath?: string | null;
  inputHash?: string | null;
}): {
  ok: boolean;
  status:
    | 'ready'
    | 'written_document_path_required'
    | 'written_document_missing'
    | 'input_hash_mismatch';
  skillName: 'grill-with-docs' | 'docs-review';
  documentPath: string | null;
  writtenFileHash: string | null;
  inputHash: string | null;
} {
  const documentArg = normalizeText(input.documentPath);
  if (!documentArg) {
    return {
      ok: false,
      status: 'written_document_path_required',
      skillName: input.skillName,
      documentPath: null,
      writtenFileHash: null,
      inputHash: normalizeText(input.inputHash) || null,
    };
  }
  const absoluteDocumentPath = resolveRootRelativePath(input.root, documentArg);
  const relativeDocumentPath = toRootRelativePath(input.root, absoluteDocumentPath);
  if (!fs.existsSync(absoluteDocumentPath)) {
    return {
      ok: false,
      status: 'written_document_missing',
      skillName: input.skillName,
      documentPath: relativeDocumentPath,
      writtenFileHash: null,
      inputHash: normalizeText(input.inputHash) || null,
    };
  }
  const writtenFileHash = sha256File(absoluteDocumentPath);
  const inputHash = normalizeText(input.inputHash) || writtenFileHash;
  if (inputHash !== writtenFileHash) {
    return {
      ok: false,
      status: 'input_hash_mismatch',
      skillName: input.skillName,
      documentPath: relativeDocumentPath,
      writtenFileHash,
      inputHash,
    };
  }
  return {
    ok: true,
    status: 'ready',
    skillName: input.skillName,
    documentPath: relativeDocumentPath,
    writtenFileHash,
    inputHash,
  };
}

function commandFailureIssue(
  code: string,
  scriptPath: string,
  command: ReturnType<typeof runNodeJson>
): PreConfirmationDrilldownIssue {
  const output = (command.stderr.trim() || command.stdout.trim()).slice(0, 600);
  return preConfirmationIssue(
    code,
    `Skill-local script failed or did not emit its required report: ${scriptPath}${output ? `; output: ${output}` : ''}`,
    [scriptPath],
    'skill_script_resolution'
  );
}

function runPreConfirmationScaleAssessment(input: {
  root: string;
  sourcePath: string;
  paths: PreConfirmationPaths;
  phase: 'initial_assessment' | 'post_packet_assessment' | 'post_materialization_assessment';
  checkpointPersistenceEvidencePath?: string;
  semanticBinding?: {
    semanticModelHash: string;
    semanticConservationManifestHash: string;
  };
}): {
  assessment: Record<string, unknown> | null;
  routingDecision: Record<string, unknown> | null;
  issues: PreConfirmationDrilldownIssue[];
} {
  const script = resolveSkillScript(input.root, 'assess_contract_authoring_scale.js');
  const outByPhase = {
    initial_assessment: input.paths.scaleAssessmentInitial,
    post_packet_assessment: input.paths.scaleAssessmentPostPacket,
    post_materialization_assessment: input.paths.scaleAssessmentPostMaterialization,
  };
  const args = [
    '--source',
    input.sourcePath,
    '--phase',
    input.phase,
    '--out',
    outByPhase[input.phase],
    '--routing-decision-out',
    input.paths.scaleRoutingDecision,
    '--json',
  ];
  if (input.semanticBinding) {
    args.push('--semantic-model-hash', input.semanticBinding.semanticModelHash);
    args.push(
      '--semantic-conservation-manifest-hash',
      input.semanticBinding.semanticConservationManifestHash
    );
  }
  if (input.phase !== 'initial_assessment') {
    args.push('--semantic-kernel', input.paths.semanticKernel);
    args.push('--packet', input.paths.mustDecompositionPacket);
    args.push('--initial-assessment', input.paths.scaleAssessmentInitial);
  }
  if (input.phase === 'post_materialization_assessment') {
    args.push('--post-packet-assessment', input.paths.scaleAssessmentPostPacket);
    args.push('--packet-source-reconciliation', input.paths.reconciliationReport);
    if (input.checkpointPersistenceEvidencePath) {
      args.push('--checkpoint-persistence-evidence', input.checkpointPersistenceEvidencePath);
    }
  }
  const command = runNodeJson(script, args, input.root);
  if (command.stderr) {
    process.stderr.write(command.stderr);
  }
  const assessment = command.json ?? readJsonIfExists(outByPhase[input.phase]);
  const routingDecision = readJsonIfExists(input.paths.scaleRoutingDecision);
  const issues: PreConfirmationDrilldownIssue[] = [];
  if (!assessment) {
    issues.push(commandFailureIssue('scale_assessment_report_missing', script, command));
  }
  if (!routingDecision) {
    issues.push(commandFailureIssue('scale_routing_decision_missing', script, command));
  }
  return { assessment, routingDecision, issues };
}

function validateCheckpointPersistenceEvidence(input: {
  root: string;
  sourcePath: string;
  paths: PreConfirmationPaths;
  evidencePath: string;
  routeDecision: Record<string, unknown> | null;
  recordId: string;
  requirementSetId: string;
  implementationAttemptId: string;
  sourceDocumentHash: string;
  implementationConfirmationHash: string;
  allowDeferredCriticalAuditorBlockers?: boolean;
}): PreConfirmationDrilldownIssue[] {
  const evidence = readJsonIfExists(input.evidencePath);
  const issues: PreConfirmationDrilldownIssue[] = [];
  const semanticBinding = semanticCheckpointBindingFromPaths(input.paths);
  const ref =
    evidence?.checkpointPersistenceRef &&
    typeof evidence.checkpointPersistenceRef === 'object' &&
    !Array.isArray(evidence.checkpointPersistenceRef)
      ? (evidence.checkpointPersistenceRef as Record<string, unknown>)
      : null;
  const expected = {
    routeDecisionHash: normalizeText(input.routeDecision?.routeDecisionHash),
    requirementSetId: input.requirementSetId,
    implementationAttemptId: input.implementationAttemptId,
    semanticModelHash: semanticBinding?.semanticModelHash ?? '',
    semanticConservationManifestHash: semanticBinding?.semanticConservationManifestHash ?? '',
    progressHash: fs.existsSync(input.paths.progress) ? sha256File(input.paths.progress) : '',
    preRenderMustDecompositionGateHash: fs.existsSync(input.paths.preRenderMustGate)
      ? sha256File(input.paths.preRenderMustGate)
      : '',
    preRenderGlobalConsistencyHash: fs.existsSync(input.paths.preRenderGlobalConsistency)
      ? sha256File(input.paths.preRenderGlobalConsistency)
      : '',
    packetSourceReconciliationHash: fs.existsSync(input.paths.reconciliationReport)
      ? sha256File(input.paths.reconciliationReport)
      : '',
  };
  const addIssue = (detail: string) => {
    issues.push(
      preConfirmationIssue(
        'checkpoint_persistence_evidence_invalid',
        `Checkpoint persistence evidence is not bound to the current transaction: ${detail}.`,
        [toRootRelativePath(input.root, input.evidencePath)],
        'requirements_contract_authoring_scale_routing'
      )
    );
  };
  if (!evidence) {
    addIssue('evidence file is missing or invalid JSON');
    return issues;
  }
  if (!semanticBinding) {
    addIssue('semantic checkpoint binding is missing');
    return issues;
  }
  if (
    normalizeText(evidence.recordId) !== input.recordId ||
    normalizeText(evidence.requirementSetId) !== input.requirementSetId ||
    normalizeText(evidence.implementationAttemptId) !== input.implementationAttemptId
  ) {
    addIssue('record, requirement set, or implementation attempt identity mismatch');
  }
  if (
    normalizeText(evidence.sourceDocumentHash) !== input.sourceDocumentHash ||
    normalizeText(evidence.implementationConfirmationHash) !== input.implementationConfirmationHash
  ) {
    addIssue('source or implementationConfirmation hash mismatch');
  }
  if (
    normalizeText(evidence.semanticModelHash) !== semanticBinding.semanticModelHash ||
    normalizeText(evidence.semanticConservationManifestHash) !==
      semanticBinding.semanticConservationManifestHash
  ) {
    addIssue('semantic checkpoint binding mismatch');
  }
  const preRenderGatePolicy = recordObject(ref?.preRenderGatePolicy);
  const deferredCriticalAuditorBlockers = asRecordArray(
    preRenderGatePolicy.deferredCriticalAuditorBlockers
  );
  const deferredCriticalAuditorOnly =
    input.allowDeferredCriticalAuditorBlockers === true &&
    normalizeText(preRenderGatePolicy.mode) === 'source_gap_fix_materialization' &&
    preRenderGatePolicy.auditorConvergenceDeferredToNextRound === true &&
    deferredCriticalAuditorBlockers.length > 0 &&
    deferredCriticalAuditorBlockers.every((blocker) =>
      CRITICAL_AUDITOR_DEFERRED_CHECKPOINT_BLOCKER_CODES.has(normalizeText(blocker.code))
    );
  if (evidence.checkpointPersistenceSatisfiedCandidate !== true && !deferredCriticalAuditorOnly) {
    addIssue('checkpointPersistenceSatisfiedCandidate is not true');
  }
  if (!ref) {
    addIssue('checkpointPersistenceRef is missing');
    return issues;
  }
  for (const [field, expectedValue] of Object.entries(expected)) {
    const actual = normalizeText(ref[field]);
    if (!expectedValue || actual !== expectedValue) {
      addIssue(`${field} mismatch`);
    }
  }
  const receiptRefs = Array.isArray(ref.checkpointReceiptRefs)
    ? (ref.checkpointReceiptRefs as Record<string, unknown>[])
    : [];
  if (receiptRefs.length !== AUTHORING_REPAIR_CHECKPOINT_IDS.length) {
    addIssue('checkpointReceiptRefs must contain one receipt ref per checkpoint');
  }
  const completedIds = asStringArray(ref.completedCheckpointIds);
  const expectedCompletedIds = deferredCriticalAuditorOnly
    ? PRE_AUDITOR_CHECKPOINT_IDS
    : AUTHORING_REPAIR_CHECKPOINT_IDS;
  if (
    completedIds.length !== expectedCompletedIds.length ||
    expectedCompletedIds.some((checkpointId, index) => completedIds[index] !== checkpointId)
  ) {
    addIssue(`completedCheckpointIds must exactly equal ${expectedCompletedIds.join(', ')}`);
  }
  for (const checkpoint of AUTHORING_REPAIR_CHECKPOINTS) {
    const receiptPath = checkpointReceiptPath(input.paths, checkpoint);
    const refRow = receiptRefs.find((item) => normalizeText(item.checkpointId) === checkpoint.id);
    if (!refRow) {
      addIssue(`checkpoint receipt ref missing ${checkpoint.id}`);
      continue;
    }
    if (normalizeText(refRow.path) !== toRootRelativePath(input.root, receiptPath)) {
      addIssue(`checkpoint receipt path mismatch ${checkpoint.id}`);
    }
    if (
      deferredCriticalAuditorOnly &&
      checkpoint.index > CRITICAL_AUDITOR_DEFERRED_CHECKPOINT.index
    ) {
      if (fs.existsSync(receiptPath)) {
        addIssue(`deferred checkpoint descendant receipt must be absent ${checkpoint.id}`);
      }
      if (
        normalizeText(refRow.hash) ||
        normalizeText(refRow.status) !== 'pending' ||
        normalizeText(refRow.persistenceStatus) !== 'pending' ||
        normalizeText(refRow.semanticValidationStatus) !== 'pending'
      ) {
        addIssue(`deferred checkpoint descendant ref must remain pending ${checkpoint.id}`);
      }
      continue;
    }
    if (!fs.existsSync(receiptPath)) {
      addIssue(`checkpoint receipt file missing ${checkpoint.id}`);
      continue;
    }
    if (normalizeText(refRow.hash) !== sha256File(receiptPath)) {
      addIssue(`checkpoint receipt hash mismatch ${checkpoint.id}`);
    }
    const receipt = readJsonIfExists(receiptPath);
    const currentReceiptInput: CurrentCheckpointReceiptInput = {
      root: input.root,
      receipt,
      checkpoint,
      recordId: input.recordId,
      requirementSetId: input.requirementSetId,
      implementationAttemptId: input.implementationAttemptId,
      sourceDocumentHash: input.sourceDocumentHash,
      implementationConfirmationHash: input.implementationConfirmationHash,
      semanticBinding,
      draftSourcePath: input.sourcePath,
      paths: input.paths,
    };
    if (deferredCriticalAuditorOnly && checkpoint.id === CRITICAL_AUDITOR_DEFERRED_CHECKPOINT.id) {
      if (!isCurrentDeferredCriticalAuditorCheckpointReceipt(currentReceiptInput)) {
        addIssue(`checkpoint receipt is not a current deferred Auditor block ${checkpoint.id}`);
      }
      if (
        normalizeText(refRow.status) !== 'blocked' ||
        normalizeText(refRow.persistenceStatus) !== 'committed' ||
        normalizeText(refRow.semanticValidationStatus) !== 'block'
      ) {
        addIssue(`checkpoint receipt ref is not a deferred Auditor block ${checkpoint.id}`);
      }
      continue;
    }
    if (!isCurrentCheckpointReceipt(currentReceiptInput)) {
      addIssue(`checkpoint receipt stale or invalid ${checkpoint.id}`);
    }
  }
  return issues;
}

function collectBlockingIssuesFromReports(
  ...reports: Array<Record<string, unknown> | null>
): PreConfirmationDrilldownIssue[] {
  return reports.flatMap((report) => {
    if (!report) {
      return [];
    }
    const issueRows = [
      ...(Array.isArray(report.blockingIssues) ? report.blockingIssues : []),
      ...(Array.isArray(report.issues) ? report.issues : []),
    ];
    const normalized = issueRows
      .filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === 'object' && !Array.isArray(item)
      )
      .map((item) =>
        preConfirmationIssue(
          normalizeText(item.code) || 'unknown_pre_confirmation_issue',
          normalizeText(item.message) || normalizeText(item.code) || 'pre-confirmation issue',
          Array.isArray(item.refs) ? item.refs.map(String) : [],
          normalizeText(item.source) || 'pre_confirmation_gate'
        )
      );
    if (normalized.length > 0) {
      return normalized;
    }
    return (Array.isArray(report.failedChecks) ? report.failedChecks : []).map((code) =>
      preConfirmationIssue(
        String(code),
        `pre-confirmation gate failed: ${String(code)}`,
        [String(code)],
        'pre_confirmation_gate'
      )
    );
  });
}

